  "UhhhhhhSourcePath": "UhhhhhhReanim/System/vendor/Uhhhhhh.lua",
  "GelatekSourcePath": "UhhhhhhReanim/System/vendor/Gelatek.lua",
  "DefaultReanimator": 1,
  "UhhhhhhVersion": "1.1.0 DEV (Modded)"
}
