        source = replaceOnce(source, 'Character.Archivable = true',
            '-- The avatar clone callback scopes and restores Archivable.', "scoped avatar clone flags")
        source = replaceOnce(
            source,
            'if IsPermaDeath == true or BreakAccessoryWelds == true then',
            'if BreakAccessoryWelds == true then',
            "PD accessory weld preservation"
        )
        source = replaceOnce(
            source,
            'elseif IsPermaDeath == false then\n\t\t\tlocal Attachment = Joint.Parent and Joint.Parent:FindFirstChildOfClass("Attachment")',
            'elseif false then -- retired selective policy; keeping welds means keeping every accessory\n\t\t\tlocal Attachment = Joint.Parent and Joint.Parent:FindFirstChildOfClass("Attachment")',
            "all-or-nothing accessory weld policy"
