    local function requestInternalStop(preserveController)
        local rig = backend.Rig
        local global = environment()
        if preserveController ~= true and type(Lifecycle.RetireController) == "function" then
            local ok, reason = pcall(Lifecycle.RetireController, rig)
            if not ok then backend.AnimationLifecycleError = tostring(reason) end
        end
        activeFling = nil
        global.UhhhhhhTBZGelatekFlingActive = nil
        restoreGelatekTorsoWriter()
        restoreGelatekRootRepRoot()
        local preserve = preserveController == true and rig and rig.Parent ~= nil
        if not preserve and placeholderActive and rig and rig.Parent then
            updatePoseMirror(rig)
            detachCameraBridge()
            local camera = workspace.CurrentCamera
            local tracker = staticRootPart or ensureStaticRoot(rig:FindFirstChild("HumanoidRootPart"))
            if camera and tracker then
                pcall(function()
                    camera.CameraType = Enum.CameraType.Custom
                    camera.CameraSubject = tracker
                end)
            end
        end
        if preserve then
            local root = rig:FindFirstChild("HumanoidRootPart")
            if root and root:IsA("BasePart") then
                staticRootCFrame = root.CFrame
                global.UhhhhhhTBZGelatekStaticRootCFrame = staticRootCFrame
            end
            global.UhhhhhhTBZGelatekPreservedController = rig
        else
            global.UhhhhhhTBZGelatekPreservedController = nil
        end
        global.UhhhhhhTBZGelatekPreserveController = preserve
        global.UhhhhhhTBZGelatekBridgeStopping = true
        local directStop = global.UhhhhhhTBZGelatekStop
        if type(directStop) == "function" then
            local finished = false
            local stopThread = task.spawn(function()
                pcall(directStop)
                finished = true
            end)
            local deadline = os.clock() + math.max(game:GetService("Players").RespawnTime + 5, 8)
            repeat
                task.wait(0.05)
            until finished or os.clock() >= deadline
            if not finished then
                pcall(task.cancel, stopThread)
            end
        end
        global.UhhhhhhTBZGelatekPreserveController = nil
        global.UhhhhhhTBZGelatekBridgeStopping = nil
        local preserved = preserve and rig and rig.Parent ~= nil
        if preserved then
            global.UhhhhhhTBZGelatekPreservedController = rig
            return true
        end
        global.UhhhhhhTBZGelatekPreservedController = nil
        if rig and rig.Parent then
            local humanoid = rig:FindFirstChildOfClass("Humanoid")
            if humanoid then
                pcall(function() humanoid.BreakJointsOnDeath = true end)
                pcall(function() humanoid.Health = 0 end)
                pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Dead) end)
            end
            local deadline = os.clock() + 4
            repeat
                task.wait(0.05)
            until not rig.Parent or os.clock() >= deadline
        end
        return false
    end

    local function countConnectedBodyJoints(character)
        local count = 0
        if typeof(character) ~= "Instance" or not character:IsA("Model") then
            return count
        end
        for _, instance in ipairs(character:GetDescendants()) do
            if Util.IsCharacterJoint(instance) then
                local part0,part1 = Util.GetCharacterJointParts(instance)
                if part0
                    and part1
                    and instance.Enabled~=false
                    and part0.Parent==character and part1.Parent==character
                    and not (character:FindFirstChild("UpperTorso") and Context.R15Body.KeepJoint(instance,part0,part1))
                then
                    count += 1
                end
            end
        end
        return count
    end

    local function isRetiredJointlessShell(character, humanoid)
        if typeof(character) ~= "Instance"
            or not character:IsA("Model")
            or not character.Parent
            or Player.Character ~= character
        then
            return false
        end
        humanoid = humanoid or character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")
        local head = character:FindFirstChild("Head")
        if not humanoid
            or not root
            or not head
            or humanoid.Health <= 0
        then
            return false
        end
        -- Count links between logical limbs, not retained R15 segment joints or
        -- accessory motors. A fresh R6/R15 body has six of these connections;
        -- a retired follower shell has at most its non-PD Neck.
        return countConnectedBodyJoints(character) <= 1
    end

    local function getPlayableCandidate(character, excluded, secondExcluded)
        if not character
            or character == excluded
            or character == secondExcluded
            or not character.Parent
        then
            return nil
        end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")
        if not humanoid or not root or humanoidIsDead(humanoid) then
            return nil
        end
        -- CharacterAdded can precede the Head, limb parts and their joints.
        -- Do not restore RequiresNeck or run Animate on a partial spawn.
        local required={HumanoidRootPart=true,Head=true}
        if humanoid.RigType==Enum.HumanoidRigType.R15 then
            required.LowerTorso,required.UpperTorso=true,true
            for _,side in ipairs({"Left","Right"}) do
                for _,suffix in ipairs({"UpperArm","LowerArm","Hand","UpperLeg","LowerLeg","Foot"}) do required[side..suffix]=true end
            end
        else
            for _,name in ipairs({"Torso","Left Arm","Right Arm","Left Leg","Right Leg"}) do required[name]=true end
        end
        local reached={[root]=true}
        local joints=character:GetDescendants()
        for _=1,16 do
            local changed=false
            for _,joint in ipairs(joints) do
                if Util.IsCharacterJoint(joint) and joint.Enabled~=false then
                    local p0,p1=Util.GetCharacterJointParts(joint)
                    if p0 and p1 and p0.Parent==character and p1.Parent==character then
                        if reached[p0] and not reached[p1] then reached[p1]=true changed=true end
                        if reached[p1] and not reached[p0] then reached[p0]=true changed=true end
                    end
                end
            end
            if not changed then break end
        end
        for name in pairs(required) do
            local part=character:FindFirstChild(name)
            if not part or not part:IsA("BasePart") or not reached[part] then return nil end
        end
        return character, humanoid
    end

    local function restoreCharacterRuntime(character, humanoid)
        if not character or not humanoid then
            return false
        end
        restoreIsolatedPhysicalCharacter(character)
        pcall(function() Player.Character = character end)
        for _, instance in ipairs(character:GetDescendants()) do
            if instance:IsA("LocalScript") then
                pcall(function() instance.Disabled = false end)
            end
        end
        local animateDeadline = os.clock() + 3
        repeat
            local animate = character:FindFirstChild("Animate")
            if animate and animate:IsA("LocalScript") then
                pcall(function() animate.Disabled = false end)
                break
            end
            task.wait(0.05)
        until os.clock() >= animateDeadline or Player.Character ~= character
        if not humanoid:FindFirstChildOfClass("Animator") then
            pcall(function()
                local animator = Instance.new("Animator")
                animator.Parent = humanoid
            end)
        end
        pcall(function() humanoid.AutoRotate = true end)
        pcall(function() humanoid.PlatformStand = false end)
        pcall(function() humanoid.Sit = false end)
        pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.GettingUp) end)
        pcall(StarterGui.SetCore, StarterGui, "ResetButtonCallback", true)
        pcall(StarterGui.SetCoreGuiEnabled, StarterGui, Enum.CoreGuiType.Health, true)
        Reanimate.Shiftlocked = false
        local camera = workspace.CurrentCamera
        if camera then
            pcall(function()
                camera.CameraType = Enum.CameraType.Custom
                camera.CameraSubject = humanoid
            end)
            if type(Reanimate.Camera) == "table" then
                pcall(function()
                    Reanimate.Camera.CFrame = camera.CFrame
                    Reanimate.Camera.Focus = camera.Focus
                    if type(Reanimate.Camera.OnReset) == "function" then
                        Reanimate.Camera:OnReset()
                    end
                end)
            end
        end
        return true
    end

    local function waitForPlayableCharacter(excluded, timeout, preferred, secondExcluded)
        local latestCharacter = preferred
        local characterAddedConnection = Player.CharacterAdded:Connect(function(character)
            if character ~= excluded and character ~= secondExcluded then
                latestCharacter = character
            end
        end)
        local deadline = os.clock() + timeout
        repeat
            local character, humanoid = getPlayableCandidate(latestCharacter, excluded, secondExcluded)
            if not character then
                character, humanoid = getPlayableCandidate(Player.Character, excluded, secondExcluded)
            end
            if character then
                characterAddedConnection:Disconnect()
                return character, humanoid
            end
            task.wait(0.05)
        until os.clock() >= deadline
        characterAddedConnection:Disconnect()
        return nil
    end

    local function waitForAppearance(character, timeout, expectedAccessoryCount)
        if not character or Player.Character ~= character then
            return false, 0
        end
        expectedAccessoryCount = math.max(math.floor(tonumber(expectedAccessoryCount) or 0), 0)
        local startedAt = os.clock()
        local lastAccessoryChange = startedAt
        local deadline = startedAt + math.max(tonumber(timeout) or 0, 0.1)
        local function accessoryChanged(child)
            if child:IsA("Accessory") then
                lastAccessoryChange = os.clock()
            end
        end
        local addedConnection = character.ChildAdded:Connect(accessoryChanged)
        local removedConnection = character.ChildRemoved:Connect(accessoryChanged)
        local ready = false
        local count = 0
        repeat
            local accessories, allReady = collectReadyAccessories(character)
            count = #accessories
            local now = os.clock()
            local observedLongEnough = now - startedAt >= (expectedAccessoryCount > 0 and 0.35 or 1)
            local stable = now - lastAccessoryChange >= 0.65
            local appearanceLoaded = false
            local loadedOk, loaded = pcall(Player.HasAppearanceLoaded, Player)
            if loadedOk then
                appearanceLoaded = loaded == true
            end
            ready = count >= expectedAccessoryCount
                and allReady
                and observedLongEnough
                and stable
                and (appearanceLoaded or now - startedAt >= 1.25)
            if ready then
                break
            end
            RunService.Heartbeat:Wait()
        until Player.Character ~= character or os.clock() >= deadline
        addedConnection:Disconnect()
        removedConnection:Disconnect()
        return ready and Player.Character == character, count
    end

    local function prepareCharacterAppearance(character, humanoid, isRespawnGeneration)
        local expected = accessorySnapshotCaptured and #accessoryTemplates or 0
        local ready, count = waitForAppearance(
            character,
            isRespawnGeneration and 5 or 3,
            expected
        )
        local restored = 0
        if accessorySnapshotCaptured and count < expected then
            restored = restoreMissingAccessories(character, humanoid)
            if restored > 0 then
                RunService.Heartbeat:Wait()
                RunService.Heartbeat:Wait()
            end
        end
        local accessories = collectReadyAccessories(character)
        local finalCount = #accessories
        if not accessorySnapshotCaptured or finalCount >= expected then
            snapshotAccessoryAppearance(character)
        end
        if isRespawnGeneration then
            warn(
                ("Gelatek respawn appearance: %d/%d accessories ready%s%s"):format(
                    finalCount,
                    expected,
                    restored > 0 and ("; restored " .. tostring(restored) .. " from the prior generation") or "",
                    ready and "" or "; appearance wait reached its deadline"
                )
            )
        end
        return finalCount
    end

    local function findRespawnSignal()
        if type(replicatesignal) ~= "function" then
            return nil
        end
        for _, signalName in ipairs({ "ConnectDiedSignalBackend", "Kill" }) do
            local ok, signal = pcall(function()
                return Player[signalName]
            end)
            if ok and typeof(signal) == "RBXScriptSignal" then
                return signal
            end
        end
        return nil
    end

    local function requestSingleRespawn(excluded, retired)
        local current = Player.Character
        if retired and current and current~=retired and current~=excluded then
            return false -- a newer, possibly incomplete spawn must not be killed
        end
        if current and current ~= excluded then
            local humanoid = current:FindFirstChildOfClass("Humanoid")
            if humanoid and humanoid.Health > 0 then
                pcall(function() humanoid.BreakJointsOnDeath = true end)
                pcall(function() humanoid.Health = 0 end)
                pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Dead) end)
                return true
            end
        end
        local respawnSignal = findRespawnSignal()
        if respawnSignal then
            local ok, result = pcall(replicatesignal, respawnSignal)
            return ok and result ~= false
        end
        return false
    end

    local function uninstallResetBridge()
        backend.AccessoryLifetime.CancelResetHandoff()
        resetRequestSerial += 1
        if resetBindableConnection then
            pcall(function()
                resetBindableConnection:Disconnect()
            end)
            resetBindableConnection = nil
        end
        if resetBindable then
            pcall(function()
                resetBindable:Destroy()
            end)
            resetBindable = nil
        end
        resetInFlight = false
        backend.ResetRequested = false
        backend.ResetPDIntent = false
        backend.ResetPDReadyAt,backend.ResetPDPhysical,backend.ResetPDRequestSerial=nil,nil,nil
        rebindInProgress = false
        pendingPhysicalCharacter = nil
        pcall(StarterGui.SetCore, StarterGui, "ResetButtonCallback", true)
    end

    local function installResetBridge()
        if not findRespawnSignal() then
            -- Executors without a callable respawn signal keep Roblox's default
            -- reset path; controller-death recovery below still preserves place.
            return false
        end
        if not resetBindable then
            resetBindable = Instance.new("BindableEvent")
            resetBindable.Name = "_UhhhhhhGelatekReset"
            resetBindableConnection = resetBindable.Event:Connect(function()
                local rig = backend.Rig
                if resetInFlight
                    or not backend.Running
                    or Reanimate.Stopping
                    or not rig
                    or not rig.Parent
                then
                    return
                end
                backend.AccessoryLifetime.CancelResetHandoff()
                resetRequestSerial += 1
                local requestSerial = resetRequestSerial
                resetInFlight = true
                backend.ResetRequested = true
                backend.ResetPDIntent = options.ResetTurnsPD == true and backend.EffectivePermanentDeath ~= true
                backend.ResetPDReadyAt=nil
                backend.ResetPDPhysical=backend.RealCharacter or originalCharacter
                backend.ResetPDRequestSerial=requestSerial
                backend.ResetPDCompletedSerial, backend.ResetPDLastError = nil, nil
                -- A reset request is not a replacement. Continue animating the
                -- current real head and accessories until CharacterAdded arrives.
                if not requestSingleRespawn(rig) then
                    task.defer(function()
                        if resetRequestSerial ~= requestSerial then
                            return
                        end
                        setRespawnPlaceholderActive(false)
                        uninstallResetBridge()
                        Util.Notify("Gelatek reset bridge unavailable; press Reset again")
                    end)
                else
                    task.delay(math.max(game:GetService("Players").RespawnTime + 2, 3), function()
                        if resetRequestSerial == requestSerial
                            and resetInFlight
                            and backend.Rig == rig
                            and rig.Parent
                        then
                            local physical = backend.RealCharacter or originalCharacter
                            pdHeadFollower.UpdateResetHandoff(physical, physical and physical:FindFirstChild("Head"))
                            resetInFlight = false
                            backend.ResetRequested = false
                            -- Keep Reset -> PD intent for a delayed death/split.
                            -- CharacterAdded is not required to follow the shell
                            -- that Reset has already left dead and jointless.
                            if backend.ResetPDCompletedSerial ~= requestSerial and not backend.ResetPDIntent then
                                Util.Notify("No new character received; Gelatek is still running")
                            elseif backend.ResetPDCompletedSerial ~= requestSerial then
                                backend.ResetPDLastError = "Reset accepted; waiting for physical death or a new character"
                            end
                        end
                    end)
                end
            end)
        end
        return pcall(StarterGui.SetCore, StarterGui, "ResetButtonCallback", resetBindable)
    end

    local function recoverAfterStop(
        excluded,
        preferred,
        awaitAppearance,
        continueRespawn,
        retiredCharacter,
        allowJointlessReuse
    )
        -- After Gelatek stops, its Death function briefly restores the old
        -- physical shell to Player.Character. Never accept that as a normal
        -- CharacterAdded replacement: Gelatek has already removed its body
        -- joints. Wait for a genuinely new server spawn first.
        local retiredExclusion = continueRespawn and retiredCharacter or nil
        local character, humanoid = waitForPlayableCharacter(
            excluded,
            math.max(game:GetService("Players").RespawnTime + 4, 8),
            preferred,
            retiredExclusion
        )
        local permanentDeathFallback = false
        if not character then
            requestSingleRespawn(excluded,retiredCharacter)
            character, humanoid = waitForPlayableCharacter(
                excluded,
                math.max(game:GetService("Players").RespawnTime + 8, 12),
                nil,
                retiredExclusion
            )
        end
        if not character and continueRespawn and allowJointlessReuse == true then
            local retiredHumanoid = retiredCharacter
                and retiredCharacter:FindFirstChildOfClass("Humanoid")
            if isRetiredJointlessShell(retiredCharacter, retiredHumanoid) then
                -- A PD session, or an explicit Reset -> PD request, may reuse
                -- Gelatek's detached shell. Plain non-PD still waits for a real
                -- Roblox spawn instead of quietly turning itself into PD.
                character = retiredCharacter
                humanoid = retiredHumanoid
                permanentDeathFallback = true
            end
        end
        if not character then
            return false, "Roblox did not provide a fresh playable character after Gelatek stopped"
        end
        if continueRespawn then
            rebindInProgress = true
            pendingPhysicalCharacter = character
            -- Complete the same normal-character recovery that a manual
            -- deanimate performs. Gelatek is not started again from inside the
            -- CharacterAdded/reset stack; the outer serialized loop waits for
            -- this fresh character to animate and settle first.
            local recoveryDeadline=os.clock()+math.max(game:GetService("Players").RespawnTime+8,12)
            while character and not Reanimate.Stopping do
                restoreCharacterRuntime(character, humanoid)
                local settleDeadline = os.clock() + 0.35
                repeat RunService.Heartbeat:Wait()
                until Player.Character ~= character or not character.Parent
                    or humanoidIsDead(humanoid) or os.clock() >= settleDeadline or Reanimate.Stopping
                if not Reanimate.Stopping and Player.Character==character
                    and getPlayableCandidate(character,excluded,retiredExclusion) then break end
                character,humanoid=waitForPlayableCharacter(excluded,
                    math.max(0,recoveryDeadline-os.clock()),nil,retiredExclusion)
                if os.clock()>=recoveryDeadline then character=nil end
            end
            if not character or Reanimate.Stopping then
                return false,"no stable complete character received before Gelatek restart deadline"
            end
            if allowJointlessReuse == true
                and isRetiredJointlessShell(character, humanoid)
            then
                permanentDeathFallback = true
            end
        else
            restoreCharacterRuntime(character, humanoid)
            if awaitAppearance then
                waitForAppearance(character, 3, 0)
            end
        end
        return true, nil, character, permanentDeathFallback
    end

    function backend.ModePolicy.DestroyRetiredPhysicalCharacter(retired, active, queued)
        if not retired
            or not retired.Parent
            or retired == active
            or retired == queued
        then
            return false
        end
        return pcall(function()
            retired:Destroy()
        end)
    end

    function backend.ModePolicy.FallbackCleanup(preserveCharacter, continueRespawn, preserveController)
        if backend.Performance.Active then backend.Performance.Stop() end
        if backend.AnimationTemplate then backend.AnimationTemplate:Destroy() backend.AnimationTemplate=nil end
        if not preserveController and type(Lifecycle.RetireController) == "function" then
            local ok, reason = pcall(Lifecycle.RetireController, backend.Rig)
            if not ok then backend.AnimationLifecycleError = tostring(reason) end
        end
        quiesceGelatekFollowerSupport()
        -- Reset callbacks/timers belong to the retiring generation even when
        -- its controller survives. Start installs a fresh bridge after binding.
        uninstallResetBridge()
        local global = environment()
        global.UhhhhhhTBZGelatekHeadFallbackAllowed = nil
        global.UhhhhhhTBZGelatekPDHeadTransport = nil
        global.UhhhhhhTBZGelatekPromoteResetPD = nil
        global.UhhhhhhTBZGelatekRuntimePD = nil
        global.UhhhhhhTBZGelatekFollowersPaused = nil
        global.UhhhhhhTBZGelatekPDTransitionPending = nil
        global.UhhhhhhTBZGelatekPauseOwnershipSupport = nil
        local accessoryTargetFolder = global.UhhhhhhTBZGelatekAccessoryTargetFolder
        if typeof(accessoryTargetFolder) == "Instance" and accessoryTargetFolder.Parent then
            pcall(function()
                accessoryTargetFolder:Destroy()
            end)
        end
        local bodyHideTargetFolder = global.UhhhhhhTBZGelatekBodyHideTargetFolder
        if typeof(bodyHideTargetFolder) == "Instance" and bodyHideTargetFolder.Parent then
            pcall(function()
                bodyHideTargetFolder:Destroy()
            end)
        end
        if type(global.TableOfEvents) == "table" then
            for _, connection in pairs(global.TableOfEvents) do
                pcall(function()
                    connection:Disconnect()
                end)
            end
            table.clear(global.TableOfEvents)
        end
        local rescuedCharacters = setmetatable({}, { __mode = "k" })
        local function rescueCharacter(character)
            if typeof(character) ~= "Instance"
                or rescuedCharacters[character]
                or not character.Parent
            then
                return
            end
            rescuedCharacters[character] = true
            local parent = character.Parent
            local parentOwned = type(global.UhhhhhhTBZGelatekControllerOwners) == "table"
                and global.UhhhhhhTBZGelatekControllerOwners[parent] ~= nil
            if (backend.Rig and character:IsDescendantOf(backend.Rig))
                or parentOwned
            then
                pcall(function()
                    character.Parent = workspace
                end)
            end
        end
        rescueCharacter(preserveCharacter)
        rescueCharacter(backend.RealCharacter)
        rescueCharacter(originalCharacter)
        local controllerOwners = global.UhhhhhhTBZGelatekControllerOwners
        if type(controllerOwners) == "table" then
            for controller in pairs(controllerOwners) do
                if typeof(controller) == "Instance"
                    and controller.Parent
                    and not (preserveController and controller == backend.Rig)
                then
                    pcall(function()
                        controller:Destroy()
                    end)
                end
            end
            table.clear(controllerOwners)
        end

        if continueRespawn then
            if not preserveController then
                detachCameraBridge()
                detachScaleBridge()
                if backend.Rig and backend.Rig.Parent then
                    pcall(function()
                        backend.Rig:Destroy()
                    end)
                end
                backend.Rig = nil
                Reanimate.Character = nil
                Bridge.Character = nil
                backend.Running = false
            else
                backend.Running = true
                Reanimate.Character = backend.Rig
                Bridge.Character = backend.Rig
                global.UhhhhhhTBZGelatekPreservedController = backend.Rig
            end
            backend.RealCharacter = nil
            backend.R15LinkState = nil
            backend.ActiveRealCharacter = nil
            Bridge.RealCharacter = nil
            global.RealChar = nil
            global.Stopped = false
            global.GelatekReanimateConfig = nil
            global.PartDisconnected = nil
            global.UhhhhhhTBZGelatekStop = nil
            global.UhhhhhhTBZGelatekPermaReady = nil
            global.UhhhhhhTBZGelatekPermaError = nil
            global.UhhhhhhTBZGelatekControllerReady = nil
            global.UhhhhhhTBZGelatekAlignStats = nil
            global.UhhhhhhTBZGelatekAccessoryTargets = nil
            global.UhhhhhhTBZGelatekAccessoryWriterActive = nil
            global.UhhhhhhTBZGelatekControllerOwners = nil
            global.UhhhhhhTBZGelatekAntiSleep = nil
            global.UhhhhhhTBZGelatekAccessoryTargetFolder = nil
            global.UhhhhhhTBZGelatekBodyHideTargetFolder = nil
            global.UhhhhhhTBZGelatekPhysicalRoot = nil
            global.UhhhhhhTBZGelatekControllerRoot = nil
            global.UhhhhhhTBZGelatekFlingActive = nil
            global.UhhhhhhTBZGelatekTorsoWriter = nil
            global.UhhhhhhTBZRestoreRepRoots = nil
            global.UhhhhhhTBZGelatekPreserveController = nil
            global.UhhhhhhTBZGelatekStaticRootCFrame = staticRootCFrame
            global.UhhhhhhTBZGelatekControllerDied = nil
            global.UhhhhhhTBZGelatekBridgeStopping = nil
            global.UhhhhhhTBZGelatekDeathRunning = nil
            global.UhhhhhhTBZShouldNoclip = nil
            global.UhhhhhhTBZGelatekRunToken = nil
            global.TableOfEvents = nil
            getPhysicalHeadIndex(nil)
            return
        end

        detachCameraBridge()
        detachScaleBridge()
        detachPoseMirror(true)
        clearAccessoryTemplates()
        rebindInProgress = false
        pendingPhysicalCharacter = nil
        restoreVoidDestruction()
        if backend.Rig and backend.Rig.Parent then
            pcall(function()
                backend.Rig:Destroy()
            end)
        end
        backend.Rig = nil
        backend.RealCharacter = nil
        backend.R15LinkState = nil
        backend.ActiveRealCharacter = nil
        backend.Running = false
        Reanimate.GelatekDisableDirectionalWalking = nil
        backend.EffectivePermanentDeath = false
        backend.PermanentDeathFallback = false
        backend.ServerPreparedPermanentDeath = false
        Reanimate.Character = nil
        Bridge.Character = nil
        Bridge.RealCharacter = nil
        global.HubMode = nil
        global.GelatekReanimateConfig = nil
        global.PartDisconnected = nil
        global.RealChar = nil
        global.Stopped = false
        global.UhhhhhhTBZGelatekStop = nil
        global.UhhhhhhTBZGelatekPermaReady = nil
        global.UhhhhhhTBZGelatekPermaError = nil
        global.UhhhhhhTBZGelatekControllerReady = nil
        global.UhhhhhhTBZGelatekAlignStats = nil
        global.UhhhhhhTBZShouldNoclip = nil
        global.UhhhhhhTBZGelatekDestroyHeight = nil
        global.UhhhhhhTBZGelatekHiddenPartsY = nil
        global.UhhhhhhTBZGelatekCharacterSpacingScale = nil
        global.UhhhhhhTBZGelatekAccessoryTargets = nil
        global.UhhhhhhTBZGelatekAccessoryWriterActive = nil
        global.UhhhhhhTBZGelatekControllerOwners = nil
        global.UhhhhhhTBZGelatekAntiSleep = nil
        global.UhhhhhhTBZGelatekAccessoryTargetFolder = nil
        global.UhhhhhhTBZGelatekBodyHideTargetFolder = nil
        global.UhhhhhhTBZGelatekPhysicalRoot = nil
        global.UhhhhhhTBZGelatekControllerRoot = nil
        global.UhhhhhhTBZGelatekFlingActive = nil
        global.UhhhhhhTBZGelatekTorsoWriter = nil
        global.UhhhhhhTBZRestoreRepRoots = nil
        global.UhhhhhhTBZGelatekPreserveController = nil
        global.UhhhhhhTBZGelatekPreservedController = nil
        global.UhhhhhhTBZGelatekStaticRootCFrame = nil
        global.UhhhhhhTBZGelatekControllerDied = nil
        global.UhhhhhhTBZGelatekBridgeStopping = nil
        global.UhhhhhhTBZGelatekDeathRunning = nil
        global.UhhhhhhTBZGelatekRunToken = nil
        global.TableOfEvents = nil
        getPhysicalHeadIndex(nil)
    end

    function backend.Start()
        backend.LastError = nil
        backend.LastFlingError = nil
        backend.AccessoryLifetimeError = nil
        backend.TorsoRepRootLastError = nil
        backend.TorsoRepRootWarned = false
        backend.TorsoRepRootFallbackReason = nil
        backend.TorsoRepRootBlockedReason = nil
        table.clear(torsoRepRootFailures)
        backend.Running = false
        backend.EffectivePermanentDeath = false
        backend.PermanentDeathFallback = false
        backend.ServerPreparedPermanentDeath = false
        backend.ResetRequested = false
        backend.ResetPDIntent = false
        backend.ResetPDCompletedSerial, backend.ResetPDLastError = nil, nil
        Reanimate.Starting = true
        Reanimate.Stopping = false

        local pendingResetPD = false
        local restartRequested = true
        local pendingReturnCFrame = nil
        local pendingPermanentDeathFallback = false
        while restartRequested and not Reanimate.Stopping do
        restartRequested = false
        local returnToStaticRoot = pendingReturnCFrame
        pendingReturnCFrame = nil
        local inheritedPermanentDeathFallback = pendingPermanentDeathFallback
        pendingPermanentDeathFallback = false
        local isRespawnGeneration = typeof(returnToStaticRoot) == "CFrame"
        local requestedGenerationPD = backend.ModePolicy.BeginGeneration(pendingResetPD)
        pendingResetPD = false
        if not (backend.Rig and backend.Rig.Parent) then
            backend.Running = false
        end
        local queuedRespawnCharacter = nil
        local respawnObserved = false
        local controllerDiedObserved = false
        local controllerPreserved = false
        local preservedControllerAtStart = backend.Rig and backend.Rig.Parent and backend.Rig or nil
        rebindInProgress = preservedControllerAtStart ~= nil
        local respawnConnections = {}
        local generationRunToken = {}
        local function disconnectRespawnObservers()
            for _, connection in ipairs(respawnConnections) do
                pcall(function()
                    connection:Disconnect()
                end)
            end
            table.clear(respawnConnections)
        end

        local ok, reason = xpcall(function()
            local compatible, missing = compatibility()
            assert(compatible, "missing required functions: " .. table.concat(missing, ", "))

            -- Validate the pinned vendor before touching Character, collision,
            -- camera, or FallenPartsDestroyHeight. A bad download now fails as
            -- a clean no-op instead of leaving half a reanimation behind.
            local compat = Context.LoadCompat()
            local sourcePath = Context.Config.GelatekSourcePath
            assert(type(sourcePath) == "string" and isfile(sourcePath), "missing local Gelatek source")
            local rawSource = readfile(sourcePath)
            assert(type(rawSource) == "string", "Gelatek source is not text")
            assert(#rawSource >= 10000 and #rawSource <= 4 * 1024 * 1024, "Gelatek source size is invalid")
            local sourcePrefix = string.lower(string.sub(rawSource, 1, 512))
            assert(
                not string.find(sourcePrefix, "<!doctype", 1, true)
                    and not string.find(sourcePrefix, "<html", 1, true),
                "Gelatek source is an HTML/download error"
            )
            local executeGelatek = vendorCache.Source == rawSource and vendorCache.Chunk or nil
            if not executeGelatek then
                local patchedSource = patchGelatekSource(rawSource)
                executeGelatek = compat.compile(patchedSource, "@Gelatek-Uhhhhhh")
                assert(type(executeGelatek) == "function", "Gelatek source did not compile")
                vendorCache.Source, vendorCache.Chunk = rawSource, executeGelatek
                patchedSource = nil
            end
            rawSource, sourcePrefix = nil, nil
            assert(type(executeGelatek) == "function", "Gelatek source did not compile")

            originalCharacter = Player.Character
            assert(originalCharacter and originalCharacter.Parent, "real character is not ready")
            captureSimulationRadius()
            local originalHumanoid = originalCharacter:FindFirstChildOfClass("Humanoid")
            assert(originalHumanoid, "real character Humanoid is not ready")
            local effectivePermanentDeath = requestedGenerationPD
            local permanentDeathFallback =
                effectivePermanentDeath and inheritedPermanentDeathFallback == true
            backend.EffectivePermanentDeath = effectivePermanentDeath
            backend.PermanentDeathFallback = permanentDeathFallback
            local serverPreparedPermanentDeath = false
            if effectivePermanentDeath then
                suspendGelatekHeadLifecycle("Gelatek permanent death setup")
                local prepared, response = preparePermanentDeathWithServerCodeRemote()
                serverPreparedPermanentDeath = prepared == true
                if serverPreparedPermanentDeath then
                    warn(
                        ("Gelatek: selected code remote prepared PD; %d neck joint(s) removed, %d owned part(s)"):format(
                            tonumber(response.NeckJointsBroken) or 0,
                            tonumber(response.OwnedParts) or 0
                        )
                    )
                end
            end
            backend.ServerPreparedPermanentDeath = serverPreparedPermanentDeath
            prepareCharacterAppearance(originalCharacter, originalHumanoid, isRespawnGeneration)
            if originalHumanoid.RigType.Name=="R15" then
                local deadline=os.clock()+math.max(game:GetService("Players").RespawnTime+3,8)
                local missing=Context.R15Body.Missing(originalCharacter)
                while #missing>0 and originalCharacter.Parent and os.clock()<deadline do
                    RunService.Heartbeat:Wait()
                    missing=Context.R15Body.Missing(originalCharacter)
                end
                assert(originalCharacter.Parent and #missing==0,"R15 body incomplete before controller cloning: "..table.concat(missing,", "))
            end
            captureAccessoryWeldBindings(originalCharacter)
            backend.CaptureOwnership("before-setup",originalCharacter)
            if backend.AnimationTemplate then backend.AnimationTemplate:Destroy() backend.AnimationTemplate=nil end
            if originalHumanoid.RigType.Name=="R15" and Reanimate.R15Animation then
                backend.AnimationTemplate=Reanimate.R15Animation.CreateTemplate(originalCharacter)
            end
            rebindInProgress = preservedControllerAtStart ~= nil
            pendingPhysicalCharacter = originalCharacter
            isolatePhysicalCharacter(originalCharacter)
            backend.RealCharacter = originalCharacter
            backend.R15LinkState=originalHumanoid.RigType.Name=="R15" and {
                Physical=originalCharacter,Links=Context.R15Body.CaptureLinks(originalCharacter,getPhysicalHeadIndex(originalCharacter).Joints,Util),Repairs=0,
            } or nil
            backend.ActiveRealCharacter = originalCharacter
            Bridge.RealCharacter = originalCharacter
            captureOriginalFace(originalCharacter)
            originalCameraSubject = workspace.CurrentCamera and workspace.CurrentCamera.CameraSubject
            local before = snapshotWorkspaceModels()
            backend.DetectedRig = originalHumanoid.RigType.Name
            backend.ControllerRig = "R6"
            backend.KeepBodyChain=false
            backend.BodyChainReason=backend.DetectedRig=="R15" and "R15 independent segments; separate root; non-PD Neck"
                or "Gelatek CFrame body followers; non-PD Motor6D Neck only"
            disableVoidDestruction()

            local global = environment()
            activeGenerationToken = generationRunToken
            -- A previous generation may have died between its vendor callback
            -- and bridge cleanup. Never inherit its locks or object maps.
            global.GelatekReanimateConfig = nil
            global.PartDisconnected = nil
            global.UhhhhhhTBZGelatekDeathRunning = nil
            global.UhhhhhhTBZGelatekBridgeStopping = nil
            global.UhhhhhhTBZGelatekAccessoryTargets = nil
            global.UhhhhhhTBZGelatekAccessoryWriterActive = nil
            global.UhhhhhhTBZGelatekPDHeadWriterActive = nil
            global.UhhhhhhTBZGelatekControllerOwners = nil
            global.UhhhhhhTBZGelatekAlignStats = nil
            global.HubMode = true
            global.Stopped = false
            global.UhhhhhhTBZGelatekPermaReady = false
            global.UhhhhhhTBZGelatekAntiSleep = options.AntiSleep == true
            global.UhhhhhhTBZGelatekPermaError = nil
            global.UhhhhhhTBZGelatekControllerReady = false
            global.UhhhhhhTBZGelatekStartupError = nil
            global.UhhhhhhTBZGelatekOwnershipHandoff = nil
            global.UhhhhhhTBZGelatekPauseOwnershipSupport = nil
