	m.Name = "Gangnam Style"
	m.Description = "oppa gangnam style\nuhngh..~"
	m.Assets = {"Gangnam.anim", "Gangnam.mp3"}

	m.Config = function(parent: GuiBase2d)
	end

	local animator = nil
