	local function createhatmap(mlist, tbl)
		table.clear(tbl)
		for _,v in string.split(mlist, "|") do
			if #v > 0 then
				local w = string.split(v, ",")
				if #w == 14 then
					local ref = {
						MeshId = w[1]:gsub("^%s*(.-)%s*$", "%1"), TextureId = w[2]:gsub("^%s*(.-)%s*$", "%1"),
						C0 = CFrame.identity,
						C1 = CFrame.new(
							tonumber(w[3]),
							tonumber(w[4]),
							tonumber(w[5]),
							tonumber(w[6]),
							tonumber(w[7]),
							tonumber(w[8]),
							tonumber(w[9]),
							tonumber(w[10]),
							tonumber(w[11]),
							tonumber(w[12]),
							tonumber(w[13]),
							tonumber(w[14])
						),
					}
					table.insert(HatReanimator.HatCFrameOverride, ref)
					table.insert(tbl, ref)
				elseif #w == 2 then
					local ref = {
						MeshId = w[1]:gsub("^%s*(.-)%s*$", "%1"), TextureId = w[2]:gsub("^%s*(.-)%s*$", "%1"),
						C0 = CFrame.identity,
						C1 = CFrame.identity,
					}
					table.insert(HatReanimator.HatCFrameOverride, ref)
					table.insert(tbl, ref)
				end
			end
		end
