		if isdancing then return end
		local rootu = root
		attacking = true
		randomdialog({
			"ROARRRRRRR", "RAAAAHHHHHHHH",
		})
		hum.WalkSpeed = 16
		task.spawn(function()
			animationOverride = function(timingsine, rt, nt, rst, lst, rht, lht, drhead, drleft, drrite)
				rt = ROOTC0
