			for i=1, #lbls do
				if i == m.AnimIndex then
					lbls[i][2].Text = lbls[i][1] .. " (ACTIVE)"
				else
					lbls[i][2].Text = lbls[i][1]
				end
			end
		end
		local animsel = function(txt)
			local idx = #lbls + 1
			table.insert(lbls, {txt, btn(txt, function()
				m.AnimIndex = idx
				update()
			end)})
			update()
		end
