		local animatorbtn = nil
		_, animatorbtn = btn("open MW animator lite", function()
			animatorbtn:Destroy()
			local mmhm = nil
			local update = {}
			local sig = function(x)
				x = tostring(x):lower()
				local exp = x:split("e")
				x = exp[1]
				local dec = x:split(".")
				if #dec > 1 then
					x = dec[1]
					dec = dec[2]:sub(1, 3)
					while dec:sub(-1, -1) == "0" do
						dec = dec:sub(1, -2)
					end
					if #dec > 0 then
						x ..= "." .. dec
					end
				end
				if #exp > 1 then
					x ..= "e" .. exp[2]
				end
				return x
			end
			local lmao = function(k, t, i)
				if mmhm == "mmhm" then
					k.Text = sig(t[i])
					return
				end
				if #k.Text > 0 then
					t[i] = tonumber(k.Text) or t[i]
				end
				if k:IsFocused() then return end
				k.Text = sig(t[i])
			end
			local prop = function(txt, a, b)
				local fr = Instance.new("Frame")
				fr.BackgroundTransparency = 1
				fr.Size = UDim2.new(1, 0, 0, 18)
