-- Independent Uhhhhhh editor, using the existing themed UI and dance pipeline.
-- ApexEngine supplies data interchange and Euler math, not the proprietary UI.
return function(ctx)
    local Files,Track=ctx.Files,ctx.AnimLib.Track
    local Editor={Time=0,Playing=false,Revision=0,DocumentSerial=0,UndoStack={},RedoStack={},FPS=30}
    local parents={Torso="HumanoidRootPart",Head="Torso",["Left Arm"]="Torso",["Right Arm"]="Torso",
        ["Left Leg"]="Torso",["Right Leg"]="Torso",LowerTorso="HumanoidRootPart",UpperTorso="LowerTorso",
        LeftUpperArm="UpperTorso",LeftLowerArm="LeftUpperArm",LeftHand="LeftLowerArm",
        RightUpperArm="UpperTorso",RightLowerArm="RightUpperArm",RightHand="RightLowerArm",
        LeftUpperLeg="LowerTorso",LeftLowerLeg="LeftUpperLeg",LeftFoot="LeftLowerLeg",
        RightUpperLeg="LowerTorso",RightLowerLeg="RightUpperLeg",RightFoot="RightLowerLeg"}
    local bodies={R6={"Torso","Head","Left Arm","Right Arm","Left Leg","Right Leg"},
        R15={"LowerTorso","UpperTorso","Head","LeftUpperArm","LeftLowerArm","LeftHand",
            "RightUpperArm","RightLowerArm","RightHand","LeftUpperLeg","LeftLowerLeg","LeftFoot",
            "RightUpperLeg","RightLowerLeg","RightFoot"}}
    local function finite(value,label)
        assert(type(value)=="number" and value==value and math.abs(value)<1e12,"invalid "..label)
        return value
    end
    local function poseCount(track)
        local count=0 for _,frame in ipairs(track.Keyframes)do count+=#frame.Poses end
        if track.Studio then
            local function curves(rows)for _,row in pairs(rows)do for _,channel in pairs(row.channels)do count+=#channel.keys end end end
            curves(track.Studio.Curves)
            for _,layer in ipairs(track.Studio.Layers)do
                for _,frame in ipairs(layer.Keyframes)do count+=#frame.Poses end curves(layer.Curves)
            end
            count+=#track.Studio.Camera
            for _,prop in ipairs(track.Studio.Props)do count+=#prop.Keys end
        end
        return count
    end
    local function remember(stack,state)
        table.insert(stack,state)
        local count=0 for _,item in ipairs(stack) do count+=poseCount(item.Track) end
        while #stack>12 or (#stack>1 and count>100000) do
            count-=poseCount(stack[1].Track) table.remove(stack,1)
        end
    end
    function Editor:Keys(track)return Files.Document.Keys(track or self.Track)end
    function Editor:EditableTrack()
        return {Keyframes=self:Keys(),Time=self.Track.Time,FPS=self.FPS}
    end
    function Editor:EvaluatedPoses(t)return Track.getPoses(self.Track,t or self.Time,false)end
    function Editor:LayerPose(name,cf,t)
        return Files.Document.Unblend(self.Track,name,cf,t or self.Time,function(source,at)return Track.getPoses(source,at,false,true)end)
    end
    function Editor:State() return {Track=self.Track,Time=self.Time,DocumentSerial=self.DocumentSerial} end
    function Editor:Changed()
        self.Track.Time=Files.Document.Length(self.Track)
        self.Revision+=1 self.Index=nil self.FPS=self.Track.FPS or 30
        self.Time=math.clamp(self.Time,0,self.Track.Time)
    end
    function Editor:Load(track)
        if self.Gesture then self:EndGesture(false)end
        local nextTrack=Files.Canonical(track)
        if self.Track then remember(self.UndoStack,self:State()) end
        self.Track=nextTrack
        self.DocumentSerial+=1
        self.Time,self.Playing,self.RedoStack=0,false,{}
        self:Changed()
        return self.Track
    end
    function Editor:New(rigType)
        assert(bodies[rigType],"choose R6 or R15")
        local track={Name="New "..rigType.." animation",RigType=rigType,FPS=30,Looped=true,
            Priority="Action",Keyframes={},Markers={}}
        for _,t in ipairs({0,1}) do
            local key={Time=t,Poses={}}
            for _,name in ipairs(bodies[rigType]) do
                table.insert(key.Poses,{Name=name,Parent=(name=="Head" and rigType=="R15") and "UpperTorso" or parents[name],
                    Weight=1,CFrame=CFrame.identity,EasingStyle="Linear",EasingDirection="InOut"})
            end
            table.insert(track.Keyframes,key)
        end
        return self:Load(track)
    end
    function Editor:Edit(mutator)
        if self.Gesture then self:EndGesture(false)end
        assert(self.Track,"load or create an animation")
        local nextTrack=Files.Canonical(self.Track)
        mutator(nextTrack)
        nextTrack=Files.Canonical(nextTrack)
        remember(self.UndoStack,self:State()) self.RedoStack={}
        self.Track=nextTrack self:Changed()
    end
    function Editor:Undo(redo)
        if self.Gesture then self:EndGesture(false)return end
        local from,to=redo and self.RedoStack or self.UndoStack,redo and self.UndoStack or self.RedoStack
        assert(#from>0,redo and "nothing to redo" or "nothing to undo")
        remember(to,self:State())
        local state=table.remove(from)
        self.Track,self.Time,self.Playing=state.Track,state.Time,false self:Changed()
        self.DocumentSerial=state.DocumentSerial or self.DocumentSerial
    end
    function Editor:Seek(t)
        assert(self.Track,"load or create an animation")
        self.Time=math.clamp(finite(t,"playhead time"),0,self.Track.Time) self.Playing=false
        return self.Time
    end
    function Editor:Joints()
        if not self.Index then
            self.Index={} self.AllIndex={} self.JointNames={}
            for _,key in ipairs(self:Keys()) do
                for _,pose in ipairs(key.Poses) do
                    if not self.Index[pose.Name] then
                        self.Index[pose.Name]={} self.AllIndex[pose.Name]={} table.insert(self.JointNames,pose.Name)
                    end
                    table.insert(self.AllIndex[pose.Name],{Time=key.Time,Pose=pose})
                    if pose.Weight>0 then table.insert(self.Index[pose.Name],{Time=key.Time,Pose=pose}) end
                end
            end
            local kind=self.Track.RigType
            if not bodies[kind] then
                for _,name in ipairs(bodies.R15)do if name~="Head"and self.Index[name]then kind="R15"break end end
                if not kind then for _,name in ipairs(bodies.R6)do if self.Index[name]then kind="R6"break end end end
            end
            for name in pairs(Files.Document.Curves(self.Track,false))do
                if not self.Index[name]then self.Index[name],self.AllIndex[name]={},{}table.insert(self.JointNames,name)end
            end
            self.DetectedRig=kind
            for _,name in ipairs(bodies[kind]or {})do
                if not self.Index[name]then
                    self.Index[name],self.AllIndex[name]={},{} table.insert(self.JointNames,name)
                end
            end
            table.sort(self.JointNames)
            self.TimelineIndex={}local frameTimes={}
            for _,name in ipairs(self.JointNames)do
                local list={}local seen={}
                for _,item in ipairs(self.AllIndex[name])do
                    table.insert(list,{Time=item.Time})seen[item.Time]=true frameTimes[item.Time]=true
                end
                local row=Files.Document.Curves(self.Track,false)[name]
                if row then for _,channel in pairs(row.channels)do for _,key in ipairs(channel.keys)do
                    if not seen[key.t]then table.insert(list,{Time=key.t})seen[key.t]=true end frameTimes[key.t]=true
                end end end
                table.sort(list,function(a,b)return a.Time<b.Time end)self.TimelineIndex[name]=list
            end
            self.TimelineFrames={}
            for t in pairs(frameTimes)do table.insert(self.TimelineFrames,{Time=t})end
            table.sort(self.TimelineFrames,function(a,b)return a.Time<b.Time end)
        end
        return self.JointNames
    end
    function Editor:Hierarchy()
        local names=self:Joints()
        if self.HierarchyIndex==self.Index then return self.HierarchyCache end
        local children,roots,seen={},{},{}
        local rank={} for i,name in ipairs(bodies[self.DetectedRig] or {}) do rank[name]=i end
        for _,name in ipairs(names) do children[name]={} end
        for _,name in ipairs(names) do
            local sample=self.AllIndex[name][1]
            local parent=sample and sample.Pose.Parent or (name=="Head" and children.UpperTorso and "UpperTorso") or parents[name]
            if parent~=name and children[parent] then table.insert(children[parent],name) else table.insert(roots,name) end
        end
        local function order(a,b)
            local aa,bb=rank[a] or math.huge,rank[b] or math.huge
            return aa==bb and a<b or aa<bb
        end
        table.sort(roots,order) for _,list in pairs(children) do table.sort(list,order) end
        local out={}
        local function visit(name,depth)
            if seen[name] then return end seen[name]=true
            table.insert(out,{Name=name,Depth=depth,Children=#children[name]})
            for _,child in ipairs(children[name]) do visit(child,depth+1) end
        end
        for _,name in ipairs(roots) do visit(name,0) end
        -- Malformed/custom parent cycles cannot hide joints or recurse forever.
        for _,name in ipairs(names) do visit(name,0) end
        self.HierarchyIndex,self.HierarchyCache=self.Index,out
        return out
    end
    function Editor:BasePoseAt(name,t)
        self:Joints()
        local all=self.AllIndex[name] or {}
        local low,high=1,#all
        while low<=high do
            local mid=math.floor((low+high)/2) local key=all[mid]
            if math.abs(key.Time-t)<1e-7 then return key.Pose.CFrame,key.Pose end
            if key.Time<t then low=mid+1 else high=mid-1 end
        end
        local keys=self.Index[name] or {}
        if #keys==0 then return CFrame.identity,{Weight=1,EasingStyle="Linear",EasingDirection="InOut",
            Parent=(name=="Head"and self.DetectedRig=="R15")and "UpperTorso"or parents[name]} end
        local lo,hi=1,#keys
        while lo<=hi do local mid=math.floor((lo+hi)/2) if keys[mid].Time<=t then lo=mid+1 else hi=mid-1 end end
        local left,right=keys[math.max(hi,1)],keys[math.min(lo,#keys)]
        local sample={Time=self.Track.Time,Keyframes={{Time=left.Time,Poses={left.Pose}}}}
        if right~=left then table.insert(sample.Keyframes,{Time=right.Time,Poses={right.Pose}}) end
        -- Use the same easing/interpolation as playback, not a second approximation.
        return Track.getPoses(sample,t,false)[name],left.Pose
