        if source.Priority~=nil then target.Priority=enumText(source.Priority,"priority") end
        if source.RigType~=nil then target.RigType=text(source.RigType,"rig type") end
        if source.FPS~=nil then
            target.FPS=number(source.FPS,"frame rate",1)
            assert(target.FPS<=240,"frame rate exceeds 240")
