                assert(type(entry)=="table","invalid animation attribution")
                local copy={}
                for _,key in ipairs({"Label","Author","Source","AssetId","Reference","URL"})do
                    if entry[key]~=nil then copy[key]=text(entry[key],"attribution "..key)end
