                Speed=number(source.Music.Speed or 1,"music speed",.1),Offset=number(source.Music.Offset or 0,"music offset",0)}
            assert(#target.Music.Id<=2048 and target.Music.Volume<=2 and target.Music.Speed<=4 and target.Music.Offset<=3600,"invalid music range")
        end
