        metadata(track,out)
        local total=0
        for _,key in ipairs(array(track.Keyframes,MAX_KEYS,"keyframes")) do
            assert(type(key)=="table", "invalid keyframe")
            local frame={Time=number(key.Time,"keyframe time",0),Poses={}}
            if key.Name~=nil then frame.Name=text(key.Name,"keyframe name") end
            local seen={}
            for _,pose in ipairs(array(key.Poses,MAX_POSES,"poses")) do
                assert(type(pose)=="table", "invalid pose")
                total+=1 assert(total<=MAX_TOTAL,"animation has too many poses")
                local p={Name=text(pose.Name,"pose name"),
                    Weight=number(if pose.Weight==nil then 1 else pose.Weight,"pose weight",0),
                    EasingStyle=enumText(pose.EasingStyle,"easing style","Linear"),
