-- Enumerate data we can actually edit. Module scripts are never run by this picker.
return function(ctx)
    local sources={}
    local function author(module)
        local stream=module and module._UhhhhhhStream
        local pack=stream and stream.Descriptor and stream.Descriptor.Pack
        return module and (module.Author or module.User or (pack and pack.User)
            or (ctx.ResolveAuthor and ctx.ResolveAuthor(module)))
    end
    function sources.List(module)
        local rows,seen={},{}
        local function add(row,key)
            if not seen[key] then seen[key]=true row.Id=key table.insert(rows,row)end
        end
        if module and module._UhhhhhhEditableTrack then
            add({Name=module.Name,Track=module._UhhhhhhEditableTrack,Module=module,Author=author(module),Source=module._UhhhhhhSource or "Imported animation"},module._UhhhhhhEditableTrack)
        end
        for _,row in ipairs(ctx.ActiveTracks and ctx.ActiveTracks()or {})do
            if row.Module and not row.Author then row=table.clone(row)row.Author=author(row.Module)end
            if not module or row.Module==module then add(row,row.Track or ("native/"..tostring(row.AssetId)))end
        end
        local modules=module and {module}or (ctx.SelectedModules and ctx.SelectedModules()or {})
        for _,current in ipairs(modules)do
            local function assets(list)
                for _,reference in ipairs(list or {})do
                    local path=reference:match("^([^@]+)")or reference
                    if path:lower():match("%.anim$")or path:lower():match("%.json$")or path:lower():match("%.txt$")then
                        add({Name=path:match("([^/]+)$")or path,Reference=reference,Module=current,
                            Author=author(current),Source=current.Name.." / "..(current._UhhhhhhSource or "Loaded module")},"asset/"..reference)
                    end
                end
            end
            assets(current.Assets)assets(current.OptionalAssets)
        end
        table.sort(rows,function(a,b)
            if (a.Playing==true)~=(b.Playing==true)then return a.Playing==true end
            return a.Name:lower()<b.Name:lower()
        end)
        return rows
    end
    function sources.Read(row,options)
        options=options or {}
        local track,report
        if row.Track then track=ctx.Files.Canonical(row.Track)
        elseif row.Reference then track,report=ctx.Files.Decode(ctx.ReadAsset(row.Reference,options.Cancelled))
        elseif row.AssetId then track,report=ctx.Files.FromAsset(row.AssetId,"Auto",options)
        elseif row.File then track,report=ctx.Files.Import(row.File)
        else error("no editable animation data in this selection",0)end
        track=ctx.Files.Canonical(track)
        track.Name=track.Name.." (copy)"
        track.Attribution=track.Attribution or {}
        local origin={Label=row.Name,Source=row.Source or "Animation source",Author=row.Author,
            AssetId=row.AssetId and tostring(row.AssetId)or nil,Reference=row.Reference}
        if #track.Attribution<64 then table.insert(track.Attribution,origin)end
        return track,report
    end
    return sources
end
