--!strict

local Sidecar = require(script.Parent.Sidecar)

local Deserialize = {}

Deserialize.MAX_DEPTH = 64

local CONSTRUCTORS: { [string]: (...any) -> any } = {
	Vector2 = Vector2.new,
	Vector3 = Vector3.new,
	CFrame = CFrame.new,
	Color3 = Color3.new,
	NumberRange = NumberRange.new,
	UDim = UDim.new,
	UDim2 = UDim2.new,
	NumberSequence = NumberSequence.new,
	NumberSequenceKeypoint = NumberSequenceKeypoint.new,
	ColorSequence = ColorSequence.new,
	ColorSequenceKeypoint = ColorSequenceKeypoint.new,
}

local PUNCTUATION: { [string]: boolean } = {
	["{"] = true,
	["}"] = true,
	["["] = true,
	["]"] = true,
	["("] = true,
	[")"] = true,
	["="] = true,
	[","] = true,
	[";"] = true,
	["."] = true,
	["-"] = true,
	["/"] = true,
}

local ESCAPES: { [string]: string } = {
	a = "\a",
	b = "\b",
	f = "\f",
	n = "\n",
	r = "\r",
	t = "\t",
	v = "\v",
	["\\"] = "\\",
	['"'] = '"',
	["'"] = "'",
	["\n"] = "\n",
}

type Token = {
	kind: string,
	value: any,
	line: number,
}

local function fail(line: number, message: string): any
	error({ __deserialize = true, line = line, message = message }, 0)
	return nil
end

local function tokenize(text: string): { Token }
	local tokens: { Token } = {}
	local size = #text
	local index = 1
	local line = 1

	local function at(offset: number): string
		local position = index + offset
		return string.sub(text, position, position)
	end

	local function readString(quote: string)
		local pattern = if quote == '"' then '["\\\n]' else "['\\\n]"
		local pieces: { string } = {}
		local cursor = index + 1

		while true do
			local found = string.find(text, pattern, cursor)
			if not found then
				fail(line, "a quote is never closed")
			end
			local stop = found :: number
			if stop > cursor then
				table.insert(pieces, string.sub(text, cursor, stop - 1))
			end

			local character = string.sub(text, stop, stop)
			if character == quote then
				cursor = stop + 1
				break
			elseif character == "\n" then
				fail(line, "a quote runs on to the next line without being closed")
			end

			local escaped = string.sub(text, stop + 1, stop + 1)
			if escaped == "" then
				fail(line, "a quote is never closed")
			elseif string.match(escaped, "%d") then
				local digits = string.match(text, "^%d%d?%d?", stop + 1) :: string
				local byte = tonumber(digits) :: number
				if byte > 255 then
					fail(line, `'\\{digits}' inside quotes is not a character`)
				end
				table.insert(pieces, string.char(byte))
				cursor = stop + 1 + #digits
			elseif escaped == "\r" then
				line += 1
				table.insert(pieces, "\n")
				cursor = stop + 2
				if string.sub(text, cursor, cursor) == "\n" then
					cursor += 1
				end
			elseif ESCAPES[escaped] then
				if escaped == "\n" then
					line += 1
				end
				table.insert(pieces, ESCAPES[escaped])
				cursor = stop + 2
			else
				fail(line, `'\\{escaped}' inside quotes is not a character Apex knows`)
			end
		end

		table.insert(tokens, { kind = "string", value = table.concat(pieces), line = line })
		index = cursor
	end

	local function readComment()
		index += 2
		if string.sub(text, index, index + 1) == "[[" then
			local found = string.find(text, "]]", index + 2, true)
			if not found then
				fail(line, "a --[[ comment never ends")
			end
			local close = found :: number
			for _ in string.gmatch(string.sub(text, index, close), "\n") do
				line += 1
			end
			index = close + 2
		else
			local newline = string.find(text, "\n", index, true)
			index = if newline then newline :: number else size + 1
		end
	end

	local function readNumber()
		local start = index
		while true do
			local _, stop = string.find(text, "^[%d%.]*", index)
			index = (stop :: number) + 1
			local character = string.sub(text, index, index)
			if character == "e" or character == "E" then
				index += 1
				local sign = string.sub(text, index, index)
				if sign == "+" or sign == "-" then
					index += 1
				end
			else
				break
			end
		end
		local literal = string.sub(text, start, index - 1)
		local number = tonumber(literal)
		if number == nil then
			fail(line, `'{literal}' is not a number`)
		end
		table.insert(tokens, { kind = "number", value = number, line = line })
	end

	local function readName()
		local start = index
		local _, stop = string.find(text, "^[%w_]*", index)
		index = (stop :: number) + 1
		table.insert(
			tokens,
			{ kind = "name", value = string.sub(text, start, index - 1), line = line }
		)
	end

	while index <= size do
		local character = string.sub(text, index, index)

		if character == "\n" then
			line += 1
			index += 1
		elseif character == " " or character == "\t" or character == "\r" then
			local _, stop = string.find(text, "^[ \t\r]+", index)
			index = (stop :: number) + 1
		elseif character == "-" and at(1) == "-" then
			readComment()
		elseif string.match(character, "[%a_]") then
			readName()
		elseif
			string.match(character, "%d") or (character == "." and string.match(at(1), "%d"))
		then
			readNumber()
		elseif character == '"' or character == "'" then
			readString(character)
		elseif PUNCTUATION[character] then
			table.insert(tokens, { kind = "punct", value = character, line = line })
			index += 1
		else
			fail(line, `'{character}' does not belong here`)
		end
	end

	table.insert(tokens, { kind = "eof", value = "<end of source>", line = line })
	return tokens
end

local function parse(tokens: { Token }): any
	local index = 1
	local depth = 0

	local function current(): Token
		return tokens[index]
	end

	local function check(kind: string, value: any?): boolean
		local token = tokens[index]
		return token.kind == kind and (value == nil or token.value == value)
	end

	local function advance(): Token
		local token = tokens[index]
		index += 1
		return token
	end

	local function accept(kind: string, value: any?): boolean
		if check(kind, value) then
			index += 1
			return true
		end
		return false
	end

	local function wanted(kind: string, value: any?): string
		if value ~= nil then
			return `'{tostring(value)}'`
		end
		return if kind == "name" then "a name" elseif kind == "number" then "a number" else kind
	end

	local function misplaced(token: Token, what: string): any
		if token.kind == "eof" then
			return fail(token.line, `the script ends where {what} should be`)
		end
		return fail(token.line, `'{tostring(token.value)}' is where {what} should be`)
	end

	local function expect(kind: string, value: any?): Token
		local token = tokens[index]
		if not check(kind, value) then
			misplaced(token, wanted(kind, value))
		end
		index += 1
		return token
	end

	local function descend(line: number)
		depth += 1
		if depth > Deserialize.MAX_DEPTH then
			fail(line, `the data nests more than {Deserialize.MAX_DEPTH} levels deep`)
		end
	end

	local parseValue: () -> any
	local parseTable: () -> any
	local parseNamed: () -> any

	function parseTable(): any
		local open = expect("punct", "{")
		descend(open.line)
		local result: any = {}
		local arrayCount = 0

		while not check("punct", "}") do
			if check("eof") then
				fail(open.line, "a '{' is never closed - the script ends before its '}'")
			end

			local nextToken = tokens[index + 1]
			if accept("punct", "[") then
				local key = parseValue()
				expect("punct", "]")
				expect("punct", "=")
				if key == nil then
					fail(current().line, "a name in [ ] is missing")
				end
				if key ~= key then
					fail(current().line, "a name in [ ] cannot be NaN (0/0)")
				end
				result[key] = parseValue()
			elseif check("name") and nextToken.kind == "punct" and nextToken.value == "=" then
				local key = advance().value
				advance()
				result[key] = parseValue()
			else
				arrayCount += 1
				result[arrayCount] = parseValue()
			end

			if not (accept("punct", ",") or accept("punct", ";")) then
				break
			end
		end

		expect("punct", "}")
		depth -= 1
		return result
	end

	function parseNamed(): any
		local first = advance()
		local name = first.value :: string

		if name == "true" then
			return true
		elseif name == "false" then
			return false
		elseif name == "nil" then
			return nil
		end

		if name == "math" then
			expect("punct", ".")
			local field = expect("name")
			if field.value ~= "huge" then
				return fail(field.line, `'math.{tostring(field.value)}' is not allowed here`)
			end
			return math.huge
		end

		if name == "Enum" then
			expect("punct", ".")
			local enumType = expect("name")
			expect("punct", ".")
			local item = expect("name")
			local found, enum = pcall(function()
				return (Enum :: any)[enumType.value]
			end)
			local resolved = nil
			if found and enum ~= nil then
				local ok, value = pcall(function()
					return enum[item.value]
				end)
				resolved = if ok then value else nil
			end
			if resolved == nil then
				return fail(
					item.line,
					`Roblox has no enum 'Enum.{tostring(enumType.value)}.{tostring(item.value)}'`
				)
			end
			return resolved
		end

		local constructor = CONSTRUCTORS[name]
		if not constructor then
			return fail(first.line, `'{name}' is not something a companion script may contain`)
		end

		expect("punct", ".")
		local field = expect("name")
		if field.value ~= "new" then
			return fail(
				field.line,
				`only '{name}.new' may be called, not '{name}.{tostring(field.value)}'`
			)
		end

		expect("punct", "(")
		descend(first.line)
		local arguments: { any } = {}
		local count = 0
		if not check("punct", ")") then
			repeat
				count += 1
				arguments[count] = parseValue()
			until not accept("punct", ",")
		end
		expect("punct", ")")
		depth -= 1

		local ok, result = pcall(constructor, table.unpack(arguments, 1, count))
		if not ok then
			return fail(first.line, `{name}.new(...) rejected its arguments: {tostring(result)}`)
		end
		return result
	end

	function parseValue(): any
		local token = current()

		if token.kind == "punct" and token.value == "-" then
			advance()
			local value = parseValue()
			if type(value) ~= "number" then
				return fail(token.line, "a '-' stands before something that is not a number")
			end
			return -value
		elseif token.kind == "number" then
			advance()
			if accept("punct", "/") then
				local divisor = expect("number")
				return token.value / divisor.value
			end
			return token.value
		elseif token.kind == "string" then
			advance()
			return token.value
		elseif token.kind == "punct" and token.value == "{" then
			return parseTable()
		elseif token.kind == "name" then
			return parseNamed()
		end

		return misplaced(token, "a value")
	end

	if not accept("name", "return") then
		local token = current()
		return fail(
			token.line,
			"it does not start with 'return', as a companion script Apex exported does"
		)
	end

	local value = parseValue()
	accept("punct", ";")
	if not check("eof") then
		local token = current()
		return fail(token.line, `'{tostring(token.value)}' comes after the end of the data`)
	end
	return value
end

function Deserialize.source(text: string): (any?, string?)
	if type(text) ~= "string" or text == "" then
		return nil, "the script is empty"
	end

	local ok, result = pcall(function()
		return parse(tokenize(text))
	end)
	if ok then
		return result, nil
	end

	if type(result) == "table" and (result :: any).__deserialize then
		local problem = result :: any
		return nil, `line {problem.line}: {problem.message}`
	end
	return nil, `something went wrong reading it: {tostring(result)}`
end

function Deserialize.sidecar(text: string): (Sidecar.Sidecar?, string?)
	local value, problem = Deserialize.source(text)
	if value == nil then
		return nil, problem
	end
	local valid, reason = Sidecar.validate(value)
	if not valid then
		return nil, reason
	end
	return value :: Sidecar.Sidecar, nil
end

return Deserialize
