    ["UhhhhhhReanim/System/runtime/steve110/main/apex_engine/Core/Evaluator.lua"] = [=====[
--!strict

local Joint = require(script.Parent.Joint)
local JointGraph = require(script.Parent.JointGraph)
local Types = require(script.Parent.Types)
local LayerEval = require(script.Parent.Parent.Shared.LayerEval)
local Modifiers = require(script.Parent.Parent.Shared.Modifiers)
local Pose = require(script.Parent.Parent.Shared.Pose)
local RigSolve = require(script.Parent.Parent.Shared.RigSolve)
local ChainKeys = require(script.Parent.Parent.Shared.ChainKeys)

local Evaluator = {}

export type Sample = { [string]: CFrame }

export type Timed = { any }

local OPTIONS: Modifiers.EvalOptions = {}

local function optionsFor(doc: Types.RigDocument): Modifiers.EvalOptions
	OPTIONS.presets = doc.presets
	OPTIONS.fps = doc.fps
	return OPTIONS
end

export type SampleOptions = {
	solo: boolean?,
	rig: RigSolve.Rig?,
}

local LAYER_OPTIONS: LayerEval.Options = {}

local function layerOptionsFor(doc: Types.RigDocument, options: SampleOptions?): LayerEval.Options
	LAYER_OPTIONS.presets = doc.presets
	LAYER_OPTIONS.fps = doc.fps
	LAYER_OPTIONS.solo = if options ~= nil then options.solo else nil
	return LAYER_OPTIONS
end

local function layered(doc: Types.RigDocument): boolean
	local layers = doc.layers
	return layers ~= nil and #layers > 0
end

function Evaluator.sampleChannel(
	doc: Types.RigDocument,
	address: string,
	channelName: string,
	t: number
): number?
	local track = doc.joints[address]
	if track == nil then
		return nil
	end
	local channel = track.channels[channelName]
	if channel == nil then
		return nil
	end
	return Modifiers.evaluate(channel, t, optionsFor(doc))
end

function Evaluator.sampleJoint(
	doc: Types.RigDocument,
	address: string,
	t: number,
	options: SampleOptions?
): CFrame
	local rig = if options ~= nil then options.rig else nil
	if rig ~= nil and RigSolve.rigged(doc :: any, rig) then
		return RigSolve.pose(doc :: any, address, t, rig, layerOptionsFor(doc, options))
	end
	if layered(doc) then
		return LayerEval.pose(doc :: any, address, t, layerOptionsFor(doc, options))
	end
	local track = doc.joints[address]
	if track == nil then
		return CFrame.identity
	end
	return Pose.evaluate(track, t, optionsFor(doc))
end

function Evaluator.sample(
	doc: Types.RigDocument,
	t: number,
	into: Sample?,
	options: SampleOptions?
): (Sample, string?)
	local rig = if options ~= nil then options.rig else nil
	if rig ~= nil and RigSolve.rigged(doc :: any, rig) then
		return RigSolve.sample(doc :: any, t, rig, layerOptionsFor(doc, options), into)
	end
	if layered(doc) then
		return LayerEval.sample(doc :: any, t, layerOptionsFor(doc, options), into)
	end
	local out: Sample = into or {}
	table.clear(out)
	local evalOptions = optionsFor(doc)
	for address, track in doc.joints do
		out[address] = Pose.evaluate(track, t, evalOptions)
	end
	return out
end

function Evaluator.rigOf(graph: JointGraph.Graph, controlRig: Types.ControlRig?): RigSolve.Rig
	local rootPart = graph.rootPart
	local joints: { [string]: any } = {}
	for _, joint in graph.joints do
		if graph.byAddress[joint.address] ~= joint then
			continue
		end
		local rest = joint:getRest()
		local entry: { [string]: any } = {
			parentOffset = rest.parentOffset,
			childOffset = rest.childOffset,
		}
		local parent = graph.parentOf[joint]
		if parent ~= nil and graph.byAddress[parent.address] == parent then
			entry.parent = parent.address
		elseif parent ~= nil or joint.parent ~= rootPart or joint.kind == "Pivot" then
			entry.parentWorld = Joint.worldCFrameOf(joint.parent) or CFrame.identity
		end
		joints[joint.address] = entry
	end
	return {
		root = if rootPart then rootPart.CFrame else CFrame.identity,
		joints = joints,
		controlRig = controlRig :: any,
	}
end

local function latest(keys: Timed, last: number): number
	local n = #keys
	if n > 0 and keys[n].t > last then
		return keys[n].t
	end
	return last
end

local function latestIn(tracks: { [string]: Types.JointTrack }?, last: number): number
	if tracks ~= nil then
		for _, track in tracks do
			for _, channel in track.channels do
				last = latest(channel.keys, last)
			end
		end
	end
	return last
end

function Evaluator.lastKeyTime(doc: Types.RigDocument): number
	local last = latestIn(doc.joints, 0)
	if doc.layers ~= nil then
		for _, layer in doc.layers do
			last = latestIn(layer.joints, last)
		end
	end
	last = latestIn(doc.controls, last)
	for _, channel in doc.ikBlend or {} do
		last = latest(channel.keys, last)
	end
	for _, family in ChainKeys.FAMILIES do
		for _, channel in (doc :: any)[family] or {} do
			last = latest(channel.keys, last)
		end
	end
	if doc.states ~= nil then
		for _, state in doc.states do
			if state.curve ~= nil then
				last = latest(state.curve.keys, last)
			end
		end
	end
	if doc.props ~= nil then
		for _, target in doc.props do
			for _, property in target.properties do
				last = latest(property.keys, last)
			end
		end
	end
	return last
end

function Evaluator.firstFrom(items: Timed, fromT: number, inclusive: boolean?): number
	local lo, hi = 1, #items + 1
	while lo < hi do
		local mid = (lo + hi) // 2
		local at = items[mid].t
		local before = if inclusive then at < fromT else at <= fromT
		if before then
			lo = mid + 1
		else
			hi = mid
		end
	end
	return lo
end

local function appendForward(
	markers: { Types.Marker },
	fromT: number,
	toT: number,
	inclusive: boolean,
	found: { Types.Marker }
)
	if toT < fromT then
		return
	end
	for index = Evaluator.firstFrom(markers, fromT, inclusive), #markers do
		local marker = markers[index]
		if marker.t > toT then
			break
		end
		table.insert(found, marker)
	end
end

function Evaluator.markersCrossed(
	markers: { Types.Marker }?,
	fromT: number,
	toT: number,
	inclusive: boolean?,
	out: { Types.Marker }?
): { Types.Marker }
	local found: { Types.Marker } = out or {}
	table.clear(found)
	if markers == nil or #markers == 0 then
		return found
	end
	if toT >= fromT then
		appendForward(markers, fromT, toT, inclusive == true, found)
		return found
	end
	for index = Evaluator.firstFrom(markers, fromT, not inclusive) - 1, 1, -1 do
		local marker = markers[index]
		if marker.t < toT then
			break
		end
		table.insert(found, marker)
	end
	return found
end

function Evaluator.markersWrapped(
	markers: { Types.Marker }?,
	fromT: number,
	toT: number,
	loopFrom: number,
	loopTo: number,
	out: { Types.Marker }?
): { Types.Marker }
	local found: { Types.Marker } = out or {}
	table.clear(found)
	if markers == nil or #markers == 0 then
		return found
	end
	appendForward(markers, fromT, loopTo, false, found)
	appendForward(markers, loopFrom, toT, true, found)
	return found
end

