--!strict
--!native
--!optimize 2

local Interpolate = {}

local MAX_SEQUENCE_KEYPOINTS = 20

local function lerpNumber(a: number, b: number, f: number): number
	return a + (b - a) * f
end

local function sampleNumberSequence(seq: NumberSequence, t: number): (number, number)
	local kps = seq.Keypoints
	local n = #kps
	if n == 0 then
		return 0, 0
	end
	if t <= kps[1].Time then
		return kps[1].Value, kps[1].Envelope
	end
	if t >= kps[n].Time then
		return kps[n].Value, kps[n].Envelope
	end
	for i = 1, n - 1 do
		local a, b = kps[i], kps[i + 1]
		if t >= a.Time and t <= b.Time then
			local span = b.Time - a.Time
			if span <= 0 then
				return b.Value, b.Envelope
			end
			local f = (t - a.Time) / span
			return lerpNumber(a.Value, b.Value, f), lerpNumber(a.Envelope, b.Envelope, f)
		end
	end
	return kps[n].Value, kps[n].Envelope
end

local function sampleColorSequence(seq: ColorSequence, t: number): Color3
	local kps = seq.Keypoints
	local n = #kps
	if n == 0 then
		return Color3.new(1, 1, 1)
	end
	if t <= kps[1].Time then
		return kps[1].Value
	end
	if t >= kps[n].Time then
		return kps[n].Value
	end
	for i = 1, n - 1 do
		local a, b = kps[i], kps[i + 1]
		if t >= a.Time and t <= b.Time then
			local span = b.Time - a.Time
			if span <= 0 then
				return b.Value
			end
			return a.Value:Lerp(b.Value, (t - a.Time) / span)
		end
	end
	return kps[n].Value
end

local function unionTimes(aKps: { any }, bKps: { any }): { number }
	local seen: { [number]: boolean } = {}
	local times: { number } = {}

	local function add(v: number)
		if not seen[v] then
			seen[v] = true
			table.insert(times, v)
		end
	end

	add(0)
	add(1)
	for _, kp in aKps do
		add(kp.Time)
	end
	for _, kp in bKps do
		add(kp.Time)
	end
	table.sort(times)

	if #times <= MAX_SEQUENCE_KEYPOINTS then
		return times
	end

	local even = table.create(MAX_SEQUENCE_KEYPOINTS)
	for i = 1, MAX_SEQUENCE_KEYPOINTS do
		even[i] = (i - 1) / (MAX_SEQUENCE_KEYPOINTS - 1)
	end
	return even
end

local function lerpNumberSequence(a: NumberSequence, b: NumberSequence, f: number): NumberSequence
	local times = unionTimes(a.Keypoints, b.Keypoints)
	local out = table.create(#times)
	for i, t in times do
		local av, ae = sampleNumberSequence(a, t)
		local bv, be = sampleNumberSequence(b, t)
		out[i] = NumberSequenceKeypoint.new(t, lerpNumber(av, bv, f), lerpNumber(ae, be, f))
	end
	return NumberSequence.new(out)
end

local function lerpColorSequence(a: ColorSequence, b: ColorSequence, f: number): ColorSequence
	local times = unionTimes(a.Keypoints, b.Keypoints)
	local out = table.create(#times)
	for i, t in times do
		out[i] = ColorSequenceKeypoint.new(
			t,
			sampleColorSequence(a, t):Lerp(sampleColorSequence(b, t), f)
		)
	end
	return ColorSequence.new(out)
end

local LERPERS: { [string]: (any, any, number) -> any } = {
	number = lerpNumber,

	Vector2 = function(a: Vector2, b: Vector2, f)
		return a:Lerp(b, f)
	end,
	Vector3 = function(a: Vector3, b: Vector3, f)
		return a:Lerp(b, f)
	end,
	CFrame = function(a: CFrame, b: CFrame, f)
		return a:Lerp(b, f)
	end,
	Color3 = function(a: Color3, b: Color3, f)
		return a:Lerp(b, f)
	end,

	NumberRange = function(a: NumberRange, b: NumberRange, f)
		return NumberRange.new(lerpNumber(a.Min, b.Min, f), lerpNumber(a.Max, b.Max, f))
	end,

	UDim = function(a: UDim, b: UDim, f)
		return UDim.new(
			lerpNumber(a.Scale, b.Scale, f),
			math.round(lerpNumber(a.Offset, b.Offset, f))
		)
	end,
	UDim2 = function(a: UDim2, b: UDim2, f)
		return UDim2.new(
			lerpNumber(a.X.Scale, b.X.Scale, f),
			math.round(lerpNumber(a.X.Offset, b.X.Offset, f)),
			lerpNumber(a.Y.Scale, b.Y.Scale, f),
			math.round(lerpNumber(a.Y.Offset, b.Y.Offset, f))
		)
	end,

	NumberSequence = lerpNumberSequence,
	ColorSequence = lerpColorSequence,
}

local DISCRETE: { [string]: boolean } = {
	boolean = true,
	string = true,
	EnumItem = true,
}

function Interpolate.isDiscrete(typeName: string): boolean
	return DISCRETE[typeName] == true or LERPERS[typeName] == nil
end

function Interpolate.supports(typeName: string): boolean
	return LERPERS[typeName] ~= nil or DISCRETE[typeName] == true
end

function Interpolate.lerp(typeName: string, a: any, b: any, alpha: number): any
	local f = LERPERS[typeName]
	if f == nil then
		return if alpha >= 1 then b else a
	end
	return f(a, b, alpha)
end

return Interpolate
