	endpoints: { Instance },
}

export type Skipped = {
	instance: Instance,
	kind: Joint.JointKind,
	address: string?,
	reason: string,
}

export type Graph = {
	root: Instance,
	rootPart: BasePart?,
	joints: { Joint },
	byAddress: { [string]: Joint },
	parentOf: { [Joint]: Joint },
	childrenOf: { [Joint]: { Joint } },
	depthOf: { [Joint]: number },
	collisions: { Collision },
	unsupported: { Skipped },
	broken: { Skipped },
	detached: { Joint },
	pivots: { Joint }?,
