function JointGraph.build(root: Instance, options: BuildOptions?): Graph
	local found: { Joint } = {}
	local unsupported: { Skipped } = {}
	local broken: { Skipped } = {}

	for _, instance in root:GetDescendants() do
		local kind = Joint.kindOf(instance)
