	local graph: Graph = {
		root = root,
		rootPart = rootPart,
		joints = ordered,
		byAddress = byAddress,
		parentOf = parentOf,
		childrenOf = childrenOf,
		depthOf = depthOf,
		collisions = collisions,
		unsupported = unsupported,
		broken = broken,
		detached = detached,
