		sizes[top] = (sizes[top] or 0) + 1
	end
	local branches: { Joint } = {}
	local main = 0
	for _, joint in graph.joints do
		if joint.parent == rootPart and joint.kind ~= "Pivot" then
			table.insert(branches, joint)
			if main == 0 or (sizes[joint] or 0) > (sizes[branches[main]] or 0) then
				main = #branches
			end
		end
	end
	if main > 1 then
		table.insert(branches, 1, table.remove(branches, main) :: Joint)
	end
	return branches
end

function JointGraph.worldCFrames(
	graph: Graph,
	transformOf: ((joint: Joint) -> CFrame)?,
	rootWorld: CFrame?
): { [Joint]: CFrame }
	local rootPart = graph.rootPart
	local base = rootWorld or (if rootPart then rootPart.CFrame else CFrame.identity)
	local world: { [Joint]: CFrame } = {}
	for _, joint in graph.joints do
		local parent = graph.parentOf[joint]
		local parentWorld: CFrame
		if parent then
			parentWorld = world[parent]
		elseif joint.parent == rootPart then
			parentWorld = base
		else
			parentWorld = Joint.worldCFrameOf(joint.parent) or CFrame.identity
		end
		local transform = if transformOf then transformOf(joint) else nil
		world[joint] = joint:worldCFrame(parentWorld, transform)
	end
	return world
end

return JointGraph
