--!strict

local Schema = require(script.Parent.Schema)
local Types = require(script.Parent.Types)
local Value = require(script.Parent.Value)

local PropRegistry = {}

PropRegistry.CLASSES = Schema.PROP_REGISTRY

PropRegistry.MATCH_ORDER = table.freeze({
	"BasePart",
	"Model",
	"Texture",
	"Decal",
	"PointLight",
	"SpotLight",
	"SurfaceLight",
	"Beam",
	"Trail",
