	"ColorCorrectionEffect",
	"BloomEffect",
	"DepthOfFieldEffect",
})

PropRegistry.NATIVE = table.freeze({ FaceControls = true }) :: { [string]: boolean }

PropRegistry.ENUMS = table.freeze({
	BasePart = table.freeze({ Material = "Material" }),
	SpotLight = table.freeze({ Face = "NormalId" }),
	SurfaceLight = table.freeze({ Face = "NormalId" }),
	SurfaceGui = table.freeze({ Face = "NormalId" }),
	Highlight = table.freeze({ DepthMode = "HighlightDepthMode" }),
}) :: { [string]: { [string]: string } }

local BEFORE_14: { [string]: { [string]: boolean } } = {
	BasePart = { Transparency = true, Color = true, Material = true, Size = true },
	Model = { Scale = true },
	Decal = { Transparency = true, Texture = true },
	Texture = { Transparency = true, Texture = true },
	PointLight = { Enabled = true, Brightness = true, Range = true, Color = true },
	SpotLight = { Enabled = true, Brightness = true, Range = true, Color = true },
	SurfaceLight = { Enabled = true, Brightness = true, Range = true, Color = true },
	Beam = { Enabled = true, Transparency = true, Color = true, Width0 = true, Width1 = true },
	Trail = { Enabled = true, Transparency = true, Color = true, WidthScale = true },
	Sound = {},
}

function PropRegistry.needs14(class: string, property: string?): boolean
	local before = BEFORE_14[class]
	if before == nil then
		return true
	end
	return property ~= nil and before[property] == nil
end

PropRegistry.LENGTHS = table.freeze({
	BasePart = table.freeze({ Size = true }),
	Model = table.freeze({ Scale = true }),
	Attachment = table.freeze({ Position = true }),
	Texture = table.freeze({
		OffsetStudsU = true,
		OffsetStudsV = true,
		StudsPerTileU = true,
		StudsPerTileV = true,
	}),
	Beam = table.freeze({ Width0 = true, Width1 = true, CurveSize0 = true, CurveSize1 = true }),
	Trail = table.freeze({ MinLength = true, MaxLength = true }),
	Fire = table.freeze({ Size = true, Heat = true }),
	Smoke = table.freeze({ Size = true, RiseVelocity = true }),
	DataModelMesh = table.freeze({ Offset = true }),
	BillboardGui = table.freeze({ StudsOffset = true, MaxDistance = true }),
}) :: { [string]: { [string]: boolean } }

PropRegistry.STEPPED = table.freeze({ boolean = true, Enum = true, string = true }) :: {
	[string]: boolean,
}

local KINDS =
	"parts, models, lights, beams, trails, decals, textures, attachments, highlights, fire, smoke, sparkles, meshes, GUIs, clothing, sounds, faces and the look"

local PLACED = "a part in a rig is placed by its joint - animate the joint instead"
local PHYSICS =
	"it changes how the rig collides and moves, which the game's physics and hit detection rely on - set it from a script instead"
local MOTION = "the rig's motion comes from its joints and its physics"
local FOUND = "the animation finds its props by their names and where they are"
local REFUSED: { [string]: string } = {
	CFrame = PLACED,
	Position = PLACED,
	Orientation = PLACED,
	Rotation = PLACED,
	PivotOffset = PLACED,
	Anchored = "anchoring one part of a rig pins the whole rig where it stands",
	CanCollide = PHYSICS,
	CanTouch = PHYSICS,
	CanQuery = PHYSICS,
	Massless = PHYSICS,
	CustomPhysicalProperties = PHYSICS,
	CollisionGroup = PHYSICS,
	RootPriority = PHYSICS,
	AssemblyLinearVelocity = MOTION,
	AssemblyAngularVelocity = MOTION,
	Velocity = MOTION,
	RotVelocity = MOTION,
	Parent = FOUND,
	Name = FOUND,
}

local JOINT = "joints are animated on the timeline as joints, not as props"
local WELD = "welds hold the rig together, and changing one breaks it"
local RUNS = "it runs the character, and its settings belong to game code"
local CLASS_REFUSED: { [string]: string } = {
	Motor6D = JOINT,
	Bone = JOINT,
	AnimationConstraint = JOINT,
	Weld = WELD,
	WeldConstraint = WELD,
	ManualWeld = WELD,
	Humanoid = RUNS,
	Animator = RUNS,
	AnimationController = RUNS,
}

local function oneOf(names: { string }): string
	if #names <= 1 then
		return names[1] or ""
	end
	return table.concat(names, ", ", 1, #names - 1) .. " or " .. names[#names]
end

function PropRegistry.classOf(className: string, isA: ((class: string) -> boolean)?): string?
	if PropRegistry.CLASSES[className] ~= nil then
		return className
	end
	if isA ~= nil then
		for _, class in PropRegistry.MATCH_ORDER do
			if isA(class) then
				return class
			end
		end
	end
	return nil
end

function PropRegistry.typeOf(class: string, property: string): Types.PropValueType?
	local properties = PropRegistry.CLASSES[class]
	return if properties ~= nil then properties[property] else nil
end

function PropRegistry.enumOf(class: string, property: string): string?
	local enums = PropRegistry.ENUMS[class]
	return if enums ~= nil then enums[property] else nil
end

function PropRegistry.properties(class: string): { string }
	local out: { string } = {}
	for property in PropRegistry.CLASSES[class] or {} do
		if property ~= Schema.HEAD_PROPERTY then
			table.insert(out, property)
		end
	end
	table.sort(out)
	return out
end

local function withArticle(word: string): string
	return if string.match(word, "^[AEIOUaeiou]") then `an {word}` else `a {word}`
end

function PropRegistry.classRefusal(className: string): string
	local why = CLASS_REFUSED[className]
	if why ~= nil then
		return `{withArticle(className)} cannot be animated as a prop: {why}`
	end
	return `Apex cannot animate {withArticle(className)} as a prop (it animates {KINDS})`
end

function PropRegistry.refusal(class: string, property: string): string?
	local properties = PropRegistry.CLASSES[class]
	if properties == nil then
		return PropRegistry.classRefusal(class)
	end
	if properties[property] ~= nil then
		return nil
	end
	local why = REFUSED[property]
	if why ~= nil then
		return `{property} cannot be animated: {why}`
	end
	local allowed = PropRegistry.properties(class)
	if #allowed == 0 then
		return `a {class} is not animated through its properties - it is played and stopped with sound cues`
	end
	return `{property} is not something Apex animates on a {class} (it animates {oneOf(allowed)})`
end

function PropRegistry.stepped(valueType: Types.PropValueType): boolean
	return PropRegistry.STEPPED[valueType] == true
end

local function finite(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

function PropRegistry.decode(valueType: Types.PropValueType, value: any, enumType: string?): any
	if valueType == "number" then
		return if finite(value) then value else nil
	elseif valueType == "boolean" then
		return if type(value) == "boolean" then value else nil
	elseif valueType == "string" then
		return if type(value) == "string" then value else nil
	elseif valueType == "Enum" then
		if enumType == nil or type(value) ~= "string" then
			return nil
		end
		local ok, item = pcall(function()
			return (Enum :: any)[enumType][value]
		end)
		return if ok then item else nil
	elseif valueType == "Color3" then
		if
			type(value) ~= "table"
			or not (finite(value[1]) and finite(value[2]) and finite(value[3]))
		then
			return nil
		end
		return Color3.new(value[1], value[2], value[3])
	elseif valueType == "Vector3" then
		if
			type(value) ~= "table"
			or not (finite(value[1]) and finite(value[2]) and finite(value[3]))
		then
			return nil
		end
		return Vector3.new(value[1], value[2], value[3])
	elseif valueType == "NumberSequence" or valueType == "ColorSequence" then
		if type(value) ~= "table" then
			return nil
		end
		local ok, sequence = pcall(Value.decode, valueType, value)
		return if ok then sequence else nil
	end
	return nil
end

function PropRegistry.encode(valueType: Types.PropValueType, value: any): Types.PropValue?
	local kind = typeof(value)
	if valueType == "number" or valueType == "boolean" or valueType == "string" then
		return if kind == valueType then value else nil
	elseif valueType == "Enum" then
		return if kind == "EnumItem" then value.Name else nil
	elseif valueType == "Color3" then
		return if kind == "Color3" then { value.R, value.G, value.B } else nil
	elseif valueType == "Vector3" then
		return if kind == "Vector3" then { value.X, value.Y, value.Z } else nil
	elseif valueType == "NumberSequence" or valueType == "ColorSequence" then
		return if kind == valueType then Value.encode(valueType, value) else nil
	end
	return nil
end

return PropRegistry
