--!strict

local Types = require(script.Parent.Types)
local Schema = require(script.Parent.Schema)
local Sidecar = require(script.Parent.Sidecar)

local SceneSidecar = {}

SceneSidecar.KIND = "Scene"

SceneSidecar.SCREEN_FORMAT = 15

SceneSidecar.TAKES_FORMAT = 19

export type Slot = {
	requirement: Types.RigRequirement,
	placement: Types.CFrameData,
	animation: Sidecar.Sidecar,
	tempId: string?,
}

export type Take = {
	name: string,
	length: number,
	cut: number?,
	fps: number,
	anchor: Types.SceneAnchor,
	camera: Types.CameraTrack?,
	screen: { Types.ScreenClip }?,
	presets: { [string]: Types.EasingPreset }?,
	slots: { [string]: Slot },
}

export type SceneSidecar = {
	format: number,
	kind: "Scene",
	name: string,
	length: number,
	cut: number?,
	fps: number,
	anchor: Types.SceneAnchor,
	camera: Types.CameraTrack?,
	screen: { Types.ScreenClip }?,
	presets: { [string]: Types.EasingPreset }?,
	slots: { [string]: Slot },
	takes: { Take }?,
}

export type SlotInput = {
	bake: { hash: string },
	movement: Types.MovementTrack?,
	assetId: number?,
	tempId: string?,
}

local function copy<T>(value: T): T
	if type(value) ~= "table" then
		return value
	end
	local out = {}
	for key, item in value :: any do
		out[key] = copy(item)
	end
	return out :: any
end

function SceneSidecar.slotNames(slots: { [string]: any }): { string }
	local names: { string } = {}
	for name in slots do
		table.insert(names, name)
	end
	table.sort(names)
	return names
end

function SceneSidecar.build(
	scene: Types.SceneDocument,
	inputs: { [string]: SlotInput }
): SceneSidecar
	local slots: { [string]: Slot } = {}
	local format = Sidecar.BASE_FORMAT
	for _, name in SceneSidecar.slotNames(scene.slots) do
		local slot = scene.slots[name]
		local input = inputs[name]
		if input == nil then
			error(`SceneSidecar.build: no bake was given for the slot '{name}'`, 2)
		end
		slots[name] = {
			requirement = copy(slot.requirement),
			placement = copy(slot.placement),
			animation = Sidecar.build(slot.document, input.bake, {
				assetId = input.assetId,
				movement = input.movement,
			}),
			tempId = input.tempId,
		}
		format = math.max(format, slots[name].animation.format)
	end
	local screen = scene.screen
	if screen ~= nil and #screen > 0 then
		format = math.max(format, SceneSidecar.SCREEN_FORMAT)
	else
		screen = nil
	end
	return {
		format = format,
		kind = "Scene",
		name = scene.name,
		length = scene.length,
		fps = scene.fps,
		anchor = copy(scene.anchor),
		camera = copy(scene.camera),
		screen = copy(screen),
		presets = copy(scene.presets),
		slots = slots,
	}
end

function SceneSidecar.join(scenes: { SceneSidecar }): SceneSidecar
	if #scenes == 0 then
		error("SceneSidecar.join: there are no takes to join", 2)
	end
	local out = copy(scenes[1])
	out.takes = nil
	if #scenes == 1 then
		return out
	end
	local takes: { Take } = {}
	local format = math.max(out.format, SceneSidecar.TAKES_FORMAT)
	for index = 2, #scenes do
		local scene = scenes[index]
		format = math.max(format, scene.format)
		table.insert(takes, {
			name = scene.name,
			length = scene.length,
			cut = scene.cut,
			fps = scene.fps,
			anchor = copy(scene.anchor),
			camera = copy(scene.camera),
			screen = copy(scene.screen),
			presets = copy(scene.presets),
			slots = copy(scene.slots),
		})
	end
	out.format = format
	out.takes = takes
	return out
end

function SceneSidecar.takesOf(scene: SceneSidecar): { SceneSidecar }
	local first = table.clone(scene)
	first.takes = nil
	local out: { SceneSidecar } = { first }
	for _, take in scene.takes or {} do
		table.insert(out, {
			format = scene.format,
			kind = "Scene",
			name = take.name,
			length = take.length,
			cut = take.cut,
			fps = take.fps,
			anchor = take.anchor,
			camera = take.camera,
			screen = take.screen,
			presets = take.presets,
			slots = take.slots,
		})
	end
	return out
end

function SceneSidecar.allSlotNames(scene: SceneSidecar): { string }
	local all: { [string]: boolean } = {}
	for _, take in SceneSidecar.takesOf(scene) do
		for name in take.slots do
			all[name] = true
		end
	end
	return SceneSidecar.slotNames(all)
end

function SceneSidecar.endOf(take: SceneSidecar | Take): number
	return take.cut or take.length
end

function SceneSidecar.lengthOf(scene: SceneSidecar): number
	local total = 0
	for _, take in SceneSidecar.takesOf(scene) do
		total += SceneSidecar.endOf(take)
	end
	return total
end

function SceneSidecar.slotSidecar(scene: SceneSidecar, slot: string): Sidecar.Sidecar?
	local entry = scene.slots[slot]
	if entry == nil then
		error(`SceneSidecar.slotSidecar: the scene has no slot '{slot}'`, 2)
	end
	if entry.animation.assetId == nil and entry.tempId == nil then
		return nil
	end
	local assets: { [string]: number } = {}
	local temps: { [string]: string } = {}
	for name, other in scene.slots do
		local id = other.animation.assetId
		if id ~= nil then
			assets[name] = id
		end
		if other.tempId ~= nil then
			temps[name] = other.tempId
		end
	end
	local out = copy(entry.animation)
	out.name = slot
	out.scene = {
		name = scene.name,
		slot = slot,
		slots = SceneSidecar.slotNames(scene.slots),
		assets = assets,
		temps = if next(temps) ~= nil then temps else nil,
	}
	return out
end

local function validateTake(value: any): (boolean, string?)
	if type(value.slots) ~= "table" or next(value.slots) == nil then
		return false, "it has no slots - export the scene again from Apex Animator"
	end
	local cut = value.cut
	if
		cut ~= nil
		and (
			type(cut) ~= "number"
			or cut ~= cut
			or cut <= 0
			or type(value.length) ~= "number"
			or cut > value.length + 1e-6
		)
	then
		return false, "its cut is damaged - export the scene again from Apex Animator"
	end
	local slots: { [string]: any } = {}
	for _, name in SceneSidecar.slotNames(value.slots) do
		local slot = value.slots[name]
		if type(slot) ~= "table" then
			return false, `its slot '{name}' is damaged - export the scene again from Apex Animator`
		end
		local problem = Sidecar.checkHeader(slot.animation)
		if problem ~= nil then
			return false, `the animation of its slot '{name}' cannot be used: {problem}`
		end
		slots[name] = {
			model = name,
			requirement = slot.requirement,
			placement = slot.placement,
			document = Sidecar.documentOf(slot.animation),
		}
	end
	return Schema.validateScene({
		kind = "Scene",
		version = Schema.VERSION,
		name = value.name,
		length = value.length,
		fps = value.fps,
		slots = slots,
		anchor = value.anchor,
		camera = value.camera,
		screen = value.screen,
		presets = value.presets,
	})
end

function SceneSidecar.validate(value: any): (boolean, string?)
	if type(value) ~= "table" then
		return false, `it does not hold an Apex scene (it is a {type(value)}, not a table)`
	end
	local format = value.format
	if type(format) ~= "number" or format ~= format or format % 1 ~= 0 or format < 1 then
		return false, "it is damaged: it has no format number - export it again from Apex Animator"
	end
	if format > Sidecar.FORMAT then
		return false, Sidecar.newerMessage(format)
	end
	if value.kind ~= SceneSidecar.KIND then
		if value.kind == nil and type(value.joints) == "table" then
			return false,
				"it is an animation for one rig, not a scene - play it with ApexEngine.LoadAnimation"
		end
		return false, "it is not an Apex scene - export the scene again from Apex Animator"
	end
	local takes = value.takes
	if takes ~= nil then
		if type(takes) ~= "table" then
			return false, "its takes are damaged - export the scene again from Apex Animator"
		end
		for index = 1, #takes do
			local take = takes[index]
			if type(take) ~= "table" or type(take.name) ~= "string" then
				return false,
					`its take {index + 1} is damaged - export the scene again from Apex Animator`
			end
		end
	end
	for index, take in SceneSidecar.takesOf(value) do
		local ok, problem = validateTake(take)
		if not ok then
			return false, if index == 1 then problem else `in its take '{take.name}', {problem}`
		end
	end
	return true, nil
end

return SceneSidecar
