local function merged(...: { [string]: Types.PropValueType }): { [string]: Types.PropValueType }
	local out: { [string]: Types.PropValueType } = {}
	for _, part in { ... } do
		for name, valueType in part do
			out[name] = valueType
		end
	end
	return table.freeze(out)
end

