local VALUE_WORDS: { [string]: string } = {
	number = "a number",
	boolean = "on / off",
	Color3 = "a colour",
	Vector3 = "three numbers (X, Y and Z)",
	Enum = "a choice from a list",
	string = "text",
	NumberSequence = "a number sequence",
	ColorSequence = "a colour sequence",
}

type Context = {
	length: number,
	fps: number,
	presets: { [string]: any }?,
	slots: { [string]: boolean }?,
	slot: string?,
}

local function isNumber(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function isWhole(value: any): boolean
	return isNumber(value) and value % 1 == 0
end

local function isName(value: any): boolean
	return type(value) == "string" and value ~= ""
end

local function isUnit(value: any): boolean
	return isNumber(value) and value >= 0 and value <= 1
end

local function isList(value: any): boolean
	if type(value) ~= "table" then
		return false
	end
	local count = 0
	for _ in value do
		count += 1
	end
	for key in value do
		if type(key) ~= "number" or key % 1 ~= 0 or key < 1 or key > count then
			return false
		end
	end
	return true
end

local function isTriple(value: any): boolean
	return isList(value)
		and #value == 3
		and isNumber(value[1])
		and isNumber(value[2])
		and isNumber(value[3])
end

local function oneOf(list: { string }): string
	if #list == 1 then
		return list[1]
	end
	return `{table.concat(list, ", ", 1, #list - 1)} or {list[#list]}`
end

local function sortedKeys(map: { [string]: any }): { string }
	local keys = {}
	for key in map do
		table.insert(keys, key)
	end
	table.sort(keys)
	return keys
end

local function describe(value: any): string
	if value == nil then
		return "missing"
	elseif type(value) == "string" then
		return `'{value}'`
	elseif type(value) == "number" then
		if value ~= value then
			return "not a number"
		elseif value == math.huge or value == -math.huge then
			return "endless"
		end
		return string.format("%g", value)
	elseif type(value) == "boolean" then
		return tostring(value)
	elseif type(value) == "table" then
		return "a list"
	end
	return "something Apex cannot read"
end

local function article(word: string): string
	return if word:match("^[aeiouAEIOU]") then "an" else "a"
end

local function badChoice(subject: string, what: string, value: any, list: { string }): string
	if value == nil then
		return `{subject} has no {what} (it takes {oneOf(list)})`
	end
	return `{subject} has {article(what)} {what} Apex does not know, {describe(value)} (it takes {oneOf(
		list
	)})`
end

local function seconds(t: number): string
	return string.format("%.2f s", t)
end

local function at(ctx: Context, t: number): string
	local frame = math.floor(t * ctx.fps * 100 + 0.5) / 100
	return `{seconds(t)} (frame {string.format("%g", frame)})`
end

local function orderOf(previous: number?, t: number, strict: boolean): ("before" | "same")?
	if previous == nil then
		return nil
	elseif t < previous - EPSILON then
		return "before"
	elseif strict and t - previous < EPSILON then
		return "same"
	end
	return nil
end

local function checkVersion(version: any, newest: number, what: string): string?
	if not isWhole(version) or version < 1 then
		return `the {what} is damaged: it has no format version`
	end
	if version > newest then
		return `this {what} was saved by a newer Apex (format {version}; this copy reads up to {newest}) - update Apex Animator and ApexEngine`
	end
	return nil
end

local function isPath(value: any): boolean
	if not isName(value) then
		return false
	end
	for segment in (value .. "/"):gmatch("(.-)/") do
		if segment == "" then
			return false
		end
	end
	return true
end

local function isCFrame(value: any): boolean
	if not isList(value) or #value ~= 12 then
		return false
	end
	for index = 1, 12 do
		if not isNumber(value[index]) then
			return false
		end
	end
	local function dot(a: number, b: number): number
		return value[a] * value[b] + value[a + 1] * value[b + 1] + value[a + 2] * value[b + 2]
	end
	for _, row in { 4, 7, 10 } do
		if math.abs(dot(row, row) - 1) > 1e-3 then
			return false
		end
	end
	if math.abs(dot(4, 7)) > 1e-3 or math.abs(dot(4, 10)) > 1e-3 or math.abs(dot(7, 10)) > 1e-3 then
		return false
	end
	local r = value
	local determinant = r[4] * (r[8] * r[12] - r[9] * r[11])
		- r[5] * (r[7] * r[12] - r[9] * r[10])
		+ r[6] * (r[7] * r[11] - r[8] * r[10])
	return determinant > 0
end

local function isColour(value: any): boolean
	return isList(value)
		and #value == 3
		and isUnit(value[1])
		and isUnit(value[2])
		and isUnit(value[3])
end

local function checkFlag(value: any, subject: string, what: string): string?
	if value ~= nil and type(value) ~= "boolean" then
		return `the {what} setting of {subject} is damaged (it should be true or false)`
	end
	return nil
end

local function checkEndBehaviour(value: any, subject: string): string?
	if value ~= nil and not END_BEHAVIOUR[value] then
		return badChoice(subject, "end behaviour", value, Schema.END_BEHAVIOURS)
	end
	return nil
end

local function checkHandle(handle: any, left: boolean, subject: string): string?
	local side = if left then "left" else "right"
	if not isList(handle) or #handle ~= 2 or not isNumber(handle[1]) or not isNumber(handle[2]) then
		return `{subject} whose {side} handle is damaged (it should be two numbers: time and value)`
	end
	if left and handle[1] > 0 then
		return `{subject} whose left handle points forward in time; a left handle must point back, or the curve folds over itself`
	end
	if not left and handle[1] < 0 then
		return `{subject} whose right handle points back in time; a right handle must point forward, or the curve folds over itself`
	end
	return nil
end

local function checkEase(
	key: any,
	label: string,
	when: string,
	ctx: Context,
	handles: boolean
): string?
	local subject = `{label} has a key at {when}`
	if key.interp ~= nil and not INTERP[key.interp] then
		return `{subject} with an interpolation Apex does not know, {describe(key.interp)} (it takes {oneOf(
			Schema.INTERPS
		)})`
	end
	if key.easing ~= nil and not EASING[key.easing] then
		return `{subject} with an easing Apex does not know, {describe(key.easing)} (it takes {oneOf(
			Schema.EASINGS
		)})`
	end
	if key.handleType ~= nil and not HANDLE_TYPE[key.handleType] then
		return `{subject} with a handle type Apex does not know, {describe(key.handleType)} (it takes {oneOf(
			Schema.HANDLE_TYPES
		)})`
	end
	if handles then
		if key.handleL ~= nil then
			local problem = checkHandle(key.handleL, true, subject)
			if problem then
				return problem
			end
		end
		if key.handleR ~= nil then
			local problem = checkHandle(key.handleR, false, subject)
			if problem then
				return problem
			end
		end
	elseif key.handleL ~= nil or key.handleR ~= nil or key.handleType ~= nil then
		return `{subject} with Bezier handles, but only a property keyed as a number can have them`
	end

	local params = key.params
	if params ~= nil then
		if type(params) ~= "table" then
			return `{subject} with damaged easing parameters`
		end
		for name, value in params do
			if not KEY_PARAM[name] then
				return `{subject} with a parameter Apex does not know, {describe(name)} (it takes {oneOf(
					Schema.KEY_PARAMS
				)})`
			end
			if not isNumber(value) then
				return `{subject} whose {name} is {describe(value)}, not a number`
			end
		end
		if params.back ~= nil and params.back < 0 then
			return `{subject} whose Back overshoot is {describe(params.back)}; it must be 0 or more`
		end
		if params.amplitude ~= nil and params.amplitude < 0 then
			return `{subject} whose Elastic amplitude is {describe(params.amplitude)}; it must be 0 or more`
		end
		if params.period ~= nil and params.period <= 0 then
			return `{subject} whose Elastic period is {describe(params.period)}; it must be more than 0`
		end
	end

	if key.preset ~= nil then
		if not isName(key.preset) then
			return `{subject} with a damaged custom easing name`
		end
		local presets = ctx.presets
		if presets == nil or presets[key.preset] == nil then
			return `{subject} using the custom easing {describe(key.preset)}, which this animation does not carry - apply the custom easing again`
		end
	end
	return nil
end

local function checkModifier(modifier: any, label: string, index: number): string?
	if type(modifier) ~= "table" then
		return `{label} has a damaged modifier (number {index} in its stack)`
	end
	if not MODIFIER_KIND[modifier.kind] then
		return badChoice(
			`modifier number {index} on {label}`,
			"kind",
			modifier.kind,
			Schema.MODIFIER_KINDS
		)
	end
	local name = `the {modifier.kind} modifier on {label}`
	if modifier.bakeRate ~= nil and (not isNumber(modifier.bakeRate) or modifier.bakeRate <= 0) then
		return `{name} has a bake rate of {describe(modifier.bakeRate)}; it must be more than 0 samples per second`
	end
	local problem = checkFlag(modifier.mute, name, "mute")
	if problem then
		return problem
	end
	if modifier.influence ~= nil and not isUnit(modifier.influence) then
		return `{name} has an influence of {describe(modifier.influence)}; influence runs from 0 to 1`
	end
	local ok, reason = Modifiers.validate(modifier)
	if not ok then
		return `{label}: {reason}`
	end
	if modifier.kind == "Cycles" and index ~= 1 then
		return `{name} must be the first modifier in its stack - a Cycles modifier anywhere else does nothing`
	end
	return nil
end

local function checkChannel(channel: any, label: string, ctx: Context): string?
	if type(channel) ~= "table" then
		return `{label} is damaged`
	end
	if not isList(channel.keys) then
		return `{label} has no list of keys`
	end
	if channel.interp ~= nil and not INTERP[channel.interp] then
		return `{label} defaults to an interpolation Apex does not know, {describe(channel.interp)} (it takes {oneOf(
			Schema.INTERPS
		)})`
	end
	local previous: number? = nil
	for index = 1, #channel.keys do
		local key = channel.keys[index]
		if type(key) ~= "table" or not isNumber(key.t) then
			return `{label} has a key with no usable time (key {index})`
		end
		local when = at(ctx, key.t)
		if key.t < -EPSILON then
			return `{label} has a key before the start of the animation, at {when}`
		end
		local order = orderOf(previous, key.t, true)
		if order == "before" then
			return `{label} has its keys out of order at {when}`
		elseif order == "same" then
			return `{label} has two keys at the same time, {when}`
		end
		previous = key.t
		if not isNumber(key.v) then
			return `{label} has a key at {when} whose value is {describe(key.v)}, not a number`
		end
		local problem = checkEase(key, label, when, ctx, true)
		if problem then
			return problem
		end
	end
	if channel.modifiers ~= nil then
		if not isList(channel.modifiers) then
			return `{label} has a damaged modifier stack`
		end
		for index = 1, #channel.modifiers do
			local problem = checkModifier(channel.modifiers[index], label, index)
			if problem then
				return problem
			end
		end
	end
	return nil
end

local function checkKeyRange(
	channel: any,
	label: string,
	ctx: Context,
	low: number,
	high: number,
	meaning: string
): string?
	for _, key in channel.keys do
		if key.v < low or key.v > high then
			return `{label} is {describe(key.v)} at {at(ctx, key.t)}; {meaning}`
		end
	end
	return nil
end

local function checkPreset(preset: any, name: any): string?
	if not isName(name) then
		return "a custom easing has no name"
	end
	local label = `the custom easing '{name}'`
	if type(preset) ~= "table" or not isList(preset.points) or #preset.points < 2 then
		return `{label} is damaged (it needs at least two points)`
	end
	local points = preset.points
	local previous: number? = nil
	for index = 1, #points do
		local point = points[index]
		if type(point) ~= "table" or not isNumber(point.x) or not isNumber(point.y) then
			return `{label} has a damaged point (number {index})`
		end
		if point.x < 0 or point.x > 1 then
			return `{label} has a point outside the segment, at {describe(point.x)} of the way (it runs from 0 to 1)`
		end
		if previous ~= nil and point.x <= previous then
			return `{label} goes back in time at point {index}; each point must come after the one before`
		end
		previous = point.x
		local subject = `{label} has a point (number {index})`
		if point.handleL ~= nil then
			local problem = checkHandle(point.handleL, true, subject)
			if problem then
				return problem
			end
		end
		if point.handleR ~= nil then
			local problem = checkHandle(point.handleR, false, subject)
			if problem then
				return problem
			end
		end
	end
	local first, last = points[1], points[#points]
	if math.abs(first.x) > EPSILON or math.abs(first.y) > EPSILON then
		return `{label} does not start at 0, 0 - it must leave from the key's own value`
	end
	if math.abs(last.x - 1) > EPSILON or math.abs(last.y - 1) > EPSILON then
		return `{label} does not end at 1, 1 - it must land on the next key's value`
	end
	return nil
end

local function checkPresets(presets: any): string?
	if presets == nil then
		return nil
	end
	if type(presets) ~= "table" then
		return "the custom easings are damaged"
	end
	for name, preset in presets do
		local problem = checkPreset(preset, name)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkTarget(
	target: any,
	label: string,
	ctx: Context,
	owner: string?,
	camera: boolean
): string?
	if type(target) ~= "table" then
		return `{label} does not say which space`
	end
	local kind = target.kind
	if not SPACE_KIND[kind] then
		return badChoice(label, "space", kind, Schema.SPACE_KINDS)
	end
	if kind == "Joint" then
		if not isName(target.joint) then
			return `{label} follows a joint but does not say which`
		end
	elseif target.joint ~= nil then
		return `{label} names the joint {describe(target.joint)}, but its space is {kind}, not a joint`
	end
	local slot = target.slot
	if slot ~= nil then
		if not isName(slot) then
			return `{label} names a slot, but the slot's name is damaged`
		end
		if kind ~= "Joint" and kind ~= "RigRoot" then
			return `{label} names the slot '{slot}', but only a joint or the root of another rig can be followed`
		end
		local slots = ctx.slots
		if slots == nil then
			return `{label} follows the rig in slot '{slot}', but this animation is not in a scene`
		end
		if not slots[slot] then
			return `{label} follows slot '{slot}', which this scene does not have`
		end
		if slot == ctx.slot then
			return `{label} names its own slot '{slot}'; leave the slot out to follow this rig`
		end
	end
	if camera then
		if kind == "Parent" then
			return `{label} puts the camera in its parent's space, but the camera has no parent (use World, or a slot's joint or root)`
		end
		if kind ~= "World" and slot == nil then
			local what = if kind == "Joint" then "a joint" else "a rig root"
			return `{label} follows {what} without saying which slot's rig it is on`
		end
	elseif owner ~= nil and kind == "Joint" and slot == nil and target.joint == owner then
		return `{label} puts {owner} in its own space`
	end
	return nil
end

local function checkSpaces(
	spaces: any,
	who: string,
	ctx: Context,
	owner: string?,
	camera: boolean
): string?
	if not isList(spaces) then
		return `{who}'s space switches are damaged`
	end
	local previous: number? = nil
	for index = 1, #spaces do
		local segment = spaces[index]
		if type(segment) ~= "table" or not isNumber(segment.t) then
			return `{who} has a space switch with no usable time (switch {index})`
		end
		local t = segment.t
		local label = `{who}'s space switch at {at(ctx, t)}`
		if t < -EPSILON then
			return `{who} switches space before the start of the animation, at {at(ctx, t)}`
		end
		if t > ctx.length + EPSILON then
			return `{label} is after the animation ends at {at(ctx, ctx.length)}`
		end
		local order = orderOf(previous, t, true)
		if order == "before" then
			return `{who}'s space switches are out of order at {at(ctx, t)}`
		elseif order == "same" then
			return `{who} has two space switches at the same time, {at(ctx, t)}`
		end
		previous = t
		local problem = checkTarget(segment.target, label, ctx, owner, camera)
		if problem then
			return problem
		end
		local blend = segment.blend
		if blend ~= nil then
			if not isNumber(blend) or blend < 0 then
				return `{label} has a blend time of {describe(blend)}; it must be 0 seconds or more`
			end
			local limit, limitName = ctx.length, "the end of the animation"
			local following = spaces[index + 1]
			if
				type(following) == "table"
				and isNumber(following.t)
				and following.t > t + EPSILON
			then
				limit, limitName = following.t, `the next switch at {at(ctx, following.t)}`
			end
			if t + blend > limit + EPSILON then
				return `{label} blends for {seconds(blend)}, past {limitName}`
			end
		end
		problem = checkEndBehaviour(segment.onEnd, label)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkTrack(
	track: any,
	who: string,
	where: string,
	ctx: Context,
	owner: string?,
	camera: boolean
): string?
	local subject = `{who}{where}`
	if type(track) ~= "table" then
		return `{subject} is damaged`
	end
	local mode = track.rotationMode
	if not ROTATION_MODE[mode] then
		return badChoice(subject, "rotation mode", mode, Schema.ROTATION_MODES)
	end
	if type(track.channels) ~= "table" then
		return `{subject} has no list of channels`
	end
	local allowed = if mode == "Quaternion" then QUATERNION_CHANNEL else EULER_CHANNEL
	for name, channel in track.channels do
		if type(name) ~= "string" then
			return `{subject} has a channel with a damaged name`
		end
		local isFov = camera and name == Schema.FOV_CHANNEL
		if not allowed[name] and not isFov then
			if mode == "Quaternion" and EULER_CHANNEL[name] then
				return `{subject} is set to Quaternion rotation but has an {name} channel; rx, ry and rz need an Euler rotation mode such as XYZ`
			elseif mode ~= "Quaternion" and QUATERNION_CHANNEL[name] then
				return `{subject} is set to {mode} rotation but has a {name} channel; qw, qx, qy and qz need Quaternion rotation`
			end
			local choices = "px, py, pz with rx, ry, rz - or qw, qx, qy, qz in Quaternion mode"
			if camera then
				choices ..= ", and fov"
			end
			return `{subject} has a channel Apex does not know, {describe(name)} (it takes {choices})`
		end
		local label = `{who}'s {name} channel{where}`
		local problem = checkChannel(channel, label, ctx)
		if problem then
			return problem
		end
		if isFov then
			problem = checkKeyRange(
				channel,
				"the camera's field of view",
				ctx,
				Schema.MIN_FOV,
				Schema.MAX_FOV,
				`a camera takes {Schema.MIN_FOV} to {Schema.MAX_FOV} degrees`
			)
			if problem then
				return problem
			end
		end
	end
	if track.spaces ~= nil then
		return checkSpaces(track.spaces, who, ctx, owner, camera)
	end
	return nil
end

local function checkJoints(joints: any, where: string, ctx: Context, inLayer: boolean): string?
	for address, track in joints do
		if not isName(address) then
			return `a joint{where} has no name`
		end
		if inLayer and type(track) == "table" and track.spaces ~= nil then
			return `{address}{where} has space switches; a joint's spaces belong to the Base layer only`
		end
		local problem = checkTrack(track, address, where, ctx, address, false)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkLayers(layers: any, ctx: Context): string?
	if not isList(layers) then
		return "the layer list is damaged"
	end
	local seen: { [string]: boolean } = {}
	for index = 1, #layers do
		local layer = layers[index]
		if type(layer) ~= "table" then
			return `layer {index} is damaged`
		end
		if not isName(layer.name) then
			return `layer {index} has no name`
		end
		local label = `the layer '{layer.name}'`
		if seen[layer.name] then
			return `two layers are called '{layer.name}'; each needs its own name`
		end
		seen[layer.name] = true
		if not LAYER_BLEND[layer.blend] then
			return badChoice(label, "blend mode", layer.blend, Schema.LAYER_BLENDS)
		end
		if not isUnit(layer.weight) then
			return `{label} has a weight of {describe(layer.weight)}; a weight runs from 0 to 1`
		end
		if layer.mask ~= nil then
			if type(layer.mask) ~= "table" then
				return `the joint mask of {label} is damaged`
			end
			for joint, factor in layer.mask do
				if not isName(joint) then
					return `the joint mask of {label} has an entry with no joint name`
				end
				if not isUnit(factor) then
					return `{label} masks {joint} at {describe(factor)}; a mask runs from 0 to 1`
				end
			end
		end
		local problem = checkFlag(layer.mute, label, "mute") or checkFlag(layer.solo, label, "solo")
		if problem then
			return problem
		end
		if type(layer.joints) ~= "table" then
			return `{label} has no list of joints`
		end
		problem = checkJoints(layer.joints, ` in layer '{layer.name}'`, ctx, true)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkMarkers(markers: any, ctx: Context): string?
	if not isList(markers) then
		return "the marker list is damaged"
	end
	local previous: number? = nil
	for index = 1, #markers do
		local marker = markers[index]
		if type(marker) ~= "table" then
			return `marker {index} is damaged`
		end
		if not isName(marker.name) then
			return `marker {index} has no name`
		end
		local label = `the marker '{marker.name}'`
		if marker.name == Schema.RESERVED_MARKER then
			return `{label} uses a name Apex keeps for itself (it marks every exported clip); rename it`
		end
		if not isNumber(marker.t) then
			return `{label} has no usable time`
		end
		local when = at(ctx, marker.t)
		if marker.t < -EPSILON then
			return `{label} is before the start of the animation, at {when}`
		end
		if marker.t > ctx.length + EPSILON then
			return `{label} at {when} is after the animation ends at {at(ctx, ctx.length)}`
		end
		if marker.len ~= nil then
			if not isNumber(marker.len) or marker.len < 0 then
				return `{label} has a length of {describe(marker.len)}; it must be 0 seconds or more`
			end
			local finish = marker.t + marker.len
			if finish > ctx.length + EPSILON then
				return `{label} runs to {at(ctx, finish)}, past the end of the animation at {at(
					ctx,
					ctx.length
				)}`
			end
		end
		if marker.metadata ~= nil and type(marker.metadata) ~= "string" then
			return `{label} has damaged metadata (it should be text)`
		end
		if marker.row ~= nil and not (isWhole(marker.row) and marker.row >= 1) then
			return `{label} is on row {describe(marker.row)}; a row is a whole number, 1 or more`
		end
		if orderOf(previous, marker.t, false) == "before" then
			return `{label} at {when} is out of order; markers must be sorted by time`
		end
		previous = marker.t
	end
	return nil
end

local function isStateValue(value: any): boolean
	return type(value) == "string" or type(value) == "boolean" or isNumber(value)
end

local function checkPayload(payload: any, label: string): string?
	if payload == nil then
		return nil
	end
	if type(payload) ~= "table" then
		return `{label} has a damaged payload`
	end
	for field, value in payload do
		if not isName(field) then
			return `{label} has a payload field with no name`
		end
		if not isStateValue(value) then
			return `{label} has a payload field '{field}' holding {describe(value)}; a payload holds text, numbers or true / false`
		end
	end
	return nil
end

local function checkSpans(spans: any, label: string, ctx: Context): string?
	if not isList(spans) then
		return `{label} is a span state with no list of spans`
	end
	local previousStart: number?, previousEnd = nil, 0
	for index = 1, #spans do
		local span = spans[index]
		if type(span) ~= "table" or not isNumber(span.t) then
			return `{label} has a span with no usable time (span {index})`
		end
		local spanLabel = `the span of {label} at {at(ctx, span.t)}`
		if span.t < -EPSILON then
			return `{label} has a span before the start of the animation, at {at(ctx, span.t)}`
		end
		if not isNumber(span.len) or span.len <= 0 then
			return `{spanLabel} lasts {describe(span.len)} seconds; a span must last longer than 0 (use a marker for an instant)`
		end
		local finish = span.t + span.len
		if finish > ctx.length + EPSILON then
			return `{spanLabel} runs to {at(ctx, finish)}, past the end of the animation at {at(
				ctx,
				ctx.length
			)}`
		end
		if previousStart ~= nil then
			if span.t < previousStart - EPSILON then
				return `{label} has its spans out of order at {at(ctx, span.t)}`
			end
			if span.t < previousEnd - EPSILON then
				return `{label} has two spans overlapping at {at(ctx, span.t)}`
			end
		end
		previousStart, previousEnd = span.t, finish
		local problem = checkPayload(span.payload, spanLabel)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkSteps(steps: any, label: string, ctx: Context): string?
	if not isList(steps) then
		return `{label} is a stepped state with no list of steps`
	end
	local previous: number? = nil
	for index = 1, #steps do
		local step = steps[index]
		if type(step) ~= "table" or not isNumber(step.t) then
			return `{label} has a step with no usable time (step {index})`
		end
		local when = at(ctx, step.t)
		local stepLabel = `the step of {label} at {when}`
		if step.t < -EPSILON then
			return `{label} has a step before the start of the animation, at {when}`
		end
		if step.t > ctx.length + EPSILON then
			return `{stepLabel} is after the animation ends at {at(ctx, ctx.length)}`
		end
		local order = orderOf(previous, step.t, true)
		if order == "before" then
			return `{label} has its steps out of order at {when}`
		elseif order == "same" then
			return `{label} has two steps at the same time, {when}`
		end
		previous = step.t
		if not isStateValue(step.value) then
			return `{stepLabel} holds {describe(step.value)}; a state holds text, a number or true / false`
		end
		local problem = checkPayload(step.payload, stepLabel)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkStates(states: any, ctx: Context): string?
	if not isList(states) then
		return "the list of gameplay states is damaged"
	end
	local seen: { [string]: boolean } = {}
	for index = 1, #states do
		local state = states[index]
		if type(state) ~= "table" then
			return `gameplay state {index} is damaged`
		end
		if not isName(state.name) then
			return `gameplay state {index} has no name`
		end
		local label = `the state '{state.name}'`
		if seen[state.name] then
			return `two gameplay states are called '{state.name}'; game code finds a state by its name, so each needs its own`
		end
		seen[state.name] = true
		local kind = state.kind
		if not STATE_KIND[kind] then
			return badChoice(label, "kind", kind, Schema.STATE_KINDS)
		end
		for otherKind, field in STATE_FIELD do
			if otherKind ~= kind and state[field] ~= nil then
				local carried = if field == "curve" then "a curve" else field
				return `{label} is a {string.lower(kind)} state but also carries {carried}; a state has one kind`
			end
		end
		local problem = checkFlag(state.nativeMarkers, label, "native markers")
		if problem then
			return problem
		end
		if state.nativeMarkers and kind ~= "Span" then
			return `{label} exports native markers, but only a span state can`
		end
		if kind == "Span" then
			problem = checkSpans(state.spans, label, ctx)
		elseif kind == "Stepped" then
			problem = checkSteps(state.steps, label, ctx)
		else
			problem = checkChannel(state.curve, `the curve of the state '{state.name}'`, ctx)
		end
		if problem then
			return problem
		end
	end
	return nil
end

local function sequenceProblem(value: any, colour: boolean): string?
	local max = Schema.MAX_SEQUENCE_POINTS
	if not isList(value) or #value < 2 or #value > max then
		return `is not a sequence of 2 to {max} points`
	end
	local previous = 0
	for index = 1, #value do
		local point = value[index]
		local width = if isList(point) then #point else 0
		local fits = if colour then width == 4 else width == 2 or width == 3
		if not fits then
			return `has a damaged point (number {index})`
		end
		for part = 1, width do
			if not isNumber(point[part]) then
				return `has a damaged point (number {index})`
			end
		end
		local time = point[1]
		if time < previous - EPSILON or time > 1 + EPSILON then
			return `has its points out of order at point {index} (times run from 0 to 1)`
		end
		previous = time
		if colour then
			if not (isUnit(point[2]) and isUnit(point[3]) and isUnit(point[4])) then
				return `has a colour outside 0 to 1 at point {index}`
			end
		elseif width == 3 and point[3] < 0 then
			return `has an envelope below 0 at point {index}`
		end
	end
	if math.abs(value[1][1]) > EPSILON or math.abs(value[#value][1] - 1) > EPSILON then
		return "does not start at time 0 and end at time 1, as Roblox needs"
	end
	return nil
end

local function valueProblem(value: any, valueType: string): string?
	if valueType == "number" then
		return if isNumber(value) then nil else "is not a number"
	elseif valueType == "boolean" then
		return if type(value) == "boolean" then nil else "is not on / off (true or false)"
	elseif valueType == "Color3" then
		return if isColour(value) then nil else "is not a colour (three numbers from 0 to 1)"
	elseif valueType == "Vector3" then
		return if isTriple(value) then nil else "is not three numbers (X, Y and Z)"
	elseif valueType == "Enum" then
		return if isName(value) then nil else "is not the name of a choice"
	elseif valueType == "string" then
		return if type(value) == "string" then nil else "is not text"
	end
	return sequenceProblem(value, valueType == "ColorSequence")
end

local function checkPropTrack(
	track: any,
	label: string,
	property: string,
	expected: Types.PropValueType,
	ctx: Context
): string?
	if type(track) ~= "table" then
		return `{label} is damaged`
	end
	if track.type ~= expected then
		if track.type == nil then
			return `{label} does not say what kind of value it holds ({property} takes {VALUE_WORDS[expected]})`
		end
		local holds = VALUE_WORDS[track.type] or describe(track.type)
		return `{label} is keyed as {holds}, but {property} takes {VALUE_WORDS[expected]}`
	end
	if track.interp ~= nil and not INTERP[track.interp] then
		return `{label} defaults to an interpolation Apex does not know, {describe(track.interp)} (it takes {oneOf(
			Schema.INTERPS
		)})`
	end
	local problem = checkEndBehaviour(track.onEnd, label)
	if problem then
		return problem
	end
	if not isList(track.keys) then
		return `{label} has no list of keys`
	end
	local previous: number? = nil
	for index = 1, #track.keys do
		local key = track.keys[index]
		if type(key) ~= "table" or not isNumber(key.t) then
			return `{label} has a key with no usable time (key {index})`
		end
		local when = at(ctx, key.t)
		if key.t < -EPSILON then
			return `{label} has a key before the start of the animation, at {when}`
		end
		local order = orderOf(previous, key.t, true)
		if order == "before" then
			return `{label} has its keys out of order at {when}`
		elseif order == "same" then
			return `{label} has two keys at the same time, {when}`
		end
		previous = key.t
		local wrong = valueProblem(key.v, expected)
		if wrong then
			return `{label} has a key at {when} whose value {wrong}`
		end
		problem = checkEase(key, label, when, ctx, expected == "number")
		if problem then
			return problem
		end
	end
	return nil
end

local function checkCues(cues: any, path: string, ctx: Context): string?
	if not isList(cues) then
		return `the sound cues of {path} are damaged`
	end
	local previous: number? = nil
	for index = 1, #cues do
		local cue = cues[index]
		if type(cue) ~= "table" or not isNumber(cue.t) then
			return `{path} has a sound cue with no usable time (cue {index})`
		end
		local when = at(ctx, cue.t)
		local label = `{path}'s sound cue at {when}`
		if cue.t < -EPSILON then
			return `{path} has a sound cue before the start of the animation, at {when}`
		end
		if cue.t > ctx.length + EPSILON then
			return `{label} is after the animation ends at {at(ctx, ctx.length)}`
		end
		local order = orderOf(previous, cue.t, true)
		if order == "before" then
			return `{path}'s sound cues are out of order at {when}`
		elseif order == "same" then
			return `{path} has two sound cues at the same time, {when}`
		end
		previous = cue.t
		if not SOUND_ACTION[cue.action] then
			return badChoice(label, "action", cue.action, Schema.SOUND_ACTIONS)
		end
	end
	return nil
end

local function checkFade(fade: any, label: string, which: string, ctx: Context): string?
	if fade == nil then
		return nil
	end
	if type(fade) ~= "table" then
		return `{label} has a damaged fade {which}`
	end
	if not isNumber(fade.len) or fade.len < 0 then
		return `{label} fades {which} over {describe(fade.len)} seconds; a fade takes 0 seconds or more`
	end
	local subject = `{label} fades {which}`
	if fade.interp ~= nil and not INTERP[fade.interp] then
		return `{subject} with a shape Apex does not know, {describe(fade.interp)} (it takes {oneOf(
			Schema.INTERPS
		)})`
	end
	if fade.easing ~= nil and not EASING[fade.easing] then
		return `{subject} with an easing Apex does not know, {describe(fade.easing)} (it takes {oneOf(
			Schema.EASINGS
		)})`
	end
	if fade.params ~= nil then
		if type(fade.params) ~= "table" then
			return `{subject} with damaged easing parameters`
		end
		for name, value in fade.params do
			if not KEY_PARAM[name] or not isNumber(value) then
				return `{subject} with a damaged easing parameter, {describe(name)}`
			end
		end
	end
	if fade.preset ~= nil then
		local presets = ctx.presets
		if not isName(fade.preset) or presets == nil or presets[fade.preset] == nil then
			return `{subject} with the custom easing {describe(fade.preset)}, which this animation does not carry - pick the fade's shape again`
		end
	end
	return nil
end

local function checkSoundClips(clips: any, label: string, track: any, ctx: Context): string?
	if not isList(clips) then
		return `{label} has no list of clips`
	end
	local speed = track.speed or 1
	local previousStart: number?, previousEnd = nil, 0
	for index = 1, #clips do
		local clip = clips[index]
		if type(clip) ~= "table" or not isNumber(clip.t) then
			return `{label} has a clip with no usable time (clip {index})`
		end
		local clipLabel = `the clip of {label} at {at(ctx, clip.t)}`
		if clip.t < -EPSILON then
			return `{label} has a clip before the start of the animation, at {at(ctx, clip.t)}`
		end
		if clip.t > ctx.length + EPSILON then
			return `{clipLabel} starts after the animation ends at {at(ctx, ctx.length)}`
		end
		if not isNumber(clip.len) or clip.len <= EPSILON then
			return `{clipLabel} lasts {describe(clip.len)} seconds; a clip must last longer than 0`
		end
		local from = clip.from or 0
		if not isNumber(from) or from < 0 then
			return `{clipLabel} starts {describe(clip.from)} seconds into the sound; it must be 0 or more`
		end
		if from >= track.duration then
			return `{clipLabel} starts {seconds(from)} into the sound, which is only {seconds(
				track.duration
			)} long`
		end
		if from + clip.len * speed > track.duration + Schema.SOUND_SLACK then
			return `{clipLabel} plays on past the end of the sound; it can last at most {seconds(
				(track.duration - from) / speed
			)}`
		end
		if
			clip.volume ~= nil
			and (
				not isNumber(clip.volume)
				or clip.volume < 0
				or clip.volume > Schema.MAX_SOUND_VOLUME
			)
		then
			return `{clipLabel} has a volume of {describe(clip.volume)} (it takes 0 to {Schema.MAX_SOUND_VOLUME})`
		end
		local problem = checkFade(clip.fadeIn, clipLabel, "in", ctx)
			or checkFade(clip.fadeOut, clipLabel, "out", ctx)
		if problem then
			return problem
		end
		local fades = (if clip.fadeIn ~= nil then clip.fadeIn.len else 0)
			+ (if clip.fadeOut ~= nil then clip.fadeOut.len else 0)
		if fades > clip.len + EPSILON then
			return `{clipLabel} fades in and out for {seconds(fades)} in all, longer than the clip lasts, {seconds(
				clip.len
			)}`
		end
		local finish = clip.t + clip.len
		if previousStart ~= nil then
			if clip.t < previousStart - EPSILON then
				return `{label} has its clips out of order at {at(ctx, clip.t)}`
			end
			if clip.t < previousEnd - EPSILON then
				return `{label} has two clips overlapping at {at(ctx, clip.t)}`
			end
		end
		previousStart, previousEnd = clip.t, finish
	end
	return nil
end

local function checkSounds(sounds: any, ctx: Context): string?
	if not isList(sounds) then
		return "the list of sounds is damaged"
	end
	local seen: { [string]: boolean } = {}
	for index = 1, #sounds do
		local track = sounds[index]
		if type(track) ~= "table" or not isName(track.name) then
			return `sound {index} has no name`
		end
		local label = `the sound '{track.name}'`
		if seen[track.name] then
			return `two sounds are called '{track.name}'; each sound needs its own name`
		end
		seen[track.name] = true
		if not isName(track.id) then
			return `{label} has no sound id`
		end
		if track.source ~= nil and not isPath(track.source) then
			return `{label} plays {describe(track.source)}, which is not a path (instance names joined by "/")`
		end
		if not isNumber(track.duration) or track.duration <= 0 then
			return `{label} lasts {describe(track.duration)} seconds; a sound must last longer than 0`
		end
		if
			track.volume ~= nil
			and (
				not isNumber(track.volume)
				or track.volume < 0
				or track.volume > Schema.MAX_SOUND_VOLUME
			)
		then
			return `{label} has a volume of {describe(track.volume)} (it takes 0 to {Schema.MAX_SOUND_VOLUME})`
		end
		if
			track.speed ~= nil
			and (
				not isNumber(track.speed)
				or track.speed < Schema.MIN_SOUND_SPEED
				or track.speed > Schema.MAX_SOUND_SPEED
			)
		then
			return `{label} has a speed of {describe(track.speed)} (it takes {Schema.MIN_SOUND_SPEED} to {Schema.MAX_SOUND_SPEED})`
		end
		local problem = checkSoundClips(track.clips, label, track, ctx)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkProps(props: any, ctx: Context): string?
	if type(props) ~= "table" then
		return "the list of props is damaged"
	end
	for path, target in props do
		if not isPath(path) then
			return `the prop path {describe(path)} is not a path (instance names joined by "/")`
		end
		if path == Path.WORKSPACE then
			return `the prop path {path} is the Workspace itself, not something in it`
		end
		if type(target) ~= "table" then
			return `the prop {path} is damaged`
		end
		local className = target.className
		local registry = if type(className) == "string"
			then Schema.PROP_REGISTRY[className]
			else nil
		if registry == nil then
			return `the prop {path} is {describe(className)}, which Apex cannot animate (it animates {oneOf(
				sortedKeys(Schema.PROP_REGISTRY)
			)})`
		end
		local lookClass = Schema.LOOK_TARGETS[path]
		if lookClass ~= nil and className ~= lookClass then
			return `the look's {path} is a {lookClass}, not a {className}`
		elseif lookClass == nil and LOOK_CLASS[className] then
			return `the prop {path} is a {className}, which only the look animates, at {LOOK_CLASS[className]}`
		end
		if type(target.properties) ~= "table" then
			return `the prop {path} has no list of properties`
		end
		for property, track in target.properties do
			local expected = if type(property) == "string" then registry[property] else nil
			if expected == nil then
				local allowed = sortedKeys(registry)
				local swap = table.find(allowed, Schema.HEAD_PROPERTY)
				if swap ~= nil then
					table.remove(allowed, swap)
				end
				if #allowed == 0 then
					return `the prop {path} animates {describe(property)}, but a {className} can only be played and stopped`
				end
				return `the prop {path} animates {describe(property)}, which Apex does not animate on a {className} (it animates {oneOf(
					allowed
				)})`
			end
			local problem = checkPropTrack(track, `{path}'s {property}`, property, expected, ctx)
			if problem then
				return problem
			end
			local fades = property == "Texture" and (className == "Decal" or className == "Texture")
			for _, key in track.keys do
				if key.fade == nil then
					continue
				end
				if not fades then
					return `{path}'s {property} has a key with a crossfade, which only a Decal's or Texture's Texture takes`
				elseif not isNumber(key.fade) or key.fade < 0 then
					return `{path}'s Texture crossfades over {describe(key.fade)} seconds at {at(
						ctx,
						key.t
					)}; a crossfade takes 0 seconds or more`
				end
			end
		end
		if target.layer ~= nil then
			local layer = target.layer
			if className ~= "Decal" then
				return `the prop {path} is a face layer, but it is a {className}, not a Decal`
			elseif type(layer) ~= "table" then
				return `the face layer {path} is damaged`
			elseif not LAYER_FACE[layer.face] then
				return badChoice(`the face layer {path}`, "side", layer.face, Schema.LAYER_FACES)
			elseif not isNumber(layer.zIndex) or layer.zIndex % 1 ~= 0 then
				return `the face layer {path} has no whole ZIndex`
			end
		end
		if target.cues ~= nil then
			if className ~= "Sound" then
				return `the prop {path} has sound cues, but it is a {className}, not a Sound`
			end
			local problem = checkCues(target.cues, path, ctx)
			if problem then
				return problem
			end
		end
	end
	return nil
end

local function checkReleases(releases: any, ctx: Context): string?
	if not isList(releases) then
		return "the release list is damaged"
	end
	local previous: number? = nil
	for index = 1, #releases do
		local release = releases[index]
		if type(release) ~= "table" then
			return `release {index} is damaged`
		end
		if not isName(release.joint) then
			return `release {index} does not say which joint lets go`
		end
		if not isNumber(release.t) then
			return `the release of {release.joint} has no usable time`
		end
		if release.kind ~= nil and not RELEASE_KIND[release.kind] then
			return badChoice(
				`release {index} of {release.joint}`,
				"kind",
				release.kind,
				Schema.RELEASE_KINDS
			)
		end
		local what = if release.kind == "Attach" then "attach" else "release"
		local when = at(ctx, release.t)
		local label = `the {what} of {release.joint} at {when}`
		if release.t < -EPSILON then
			return `the {what} of {release.joint} is before the start of the animation, at {when}`
		end
		if release.t > ctx.length + EPSILON then
			return `{label} is after the animation ends at {at(ctx, ctx.length)}`
		end
		if orderOf(previous, release.t, false) == "before" then
			return `{label} is out of order; releases and attaches must be sorted by time`
		end
		previous = release.t
		if
			release.lifetime ~= nil and (not isNumber(release.lifetime) or release.lifetime <= 0)
		then
			return `the copies from {label} last {describe(release.lifetime)} seconds; they must last more than 0`
		end
		if release.cap ~= nil and (not isWhole(release.cap) or release.cap < 1) then
			return `{label} keeps at most {describe(release.cap)} copies at once; that must be a whole number of 1 or more`
		end
		local problem = checkFlag(release.cosmetic, label, "Copies")
		if problem then
			return problem
		end
		problem = checkFlag(release.collide, label, "Collides")
		if problem then
			return problem
		end
		if release.event ~= nil and not isName(release.event) then
			return `{label} fires an event with no name`
		end
		if release.event == Schema.RESERVED_MARKER then
			return `{label} fires an event named '{release.event}', a name Apex keeps for itself (it marks every exported clip); rename it`
		end
		problem = checkEndBehaviour(release.onEnd, label)
		if problem then
			return problem
		end
		if release.push ~= nil and not isTriple(release.push) then
			return `the push of {label} is damaged (it should be three numbers, in studs per second)`
		end
		if release.spin ~= nil and not isTriple(release.spin) then
			return `the spin of {label} is damaged (it should be three numbers, in radians per second)`
		end
		problem = checkFlag(release.leaveCopy, label, "Leave the copy")
		if problem then
			return problem
		end
		local onto = release.onto
		if onto ~= nil then
			if release.kind ~= "Attach" then
				return `{label} names a part to put it on, but only an attach puts its part back`
			end
			problem = checkTarget(onto, label, ctx, release.joint, false)
			if problem then
				return problem
			end
			if onto.kind == "World" then
				return `{label} puts {release.joint} in World, where it already is while let go of; choose a part, the rig's root or where it was`
			end
		end
	end
	return nil
end

local function checkTransition(
	key: any,
	subject: string,
	when: string,
	ctx: Context,
	name: string
): string?
	if key.transition ~= nil and (not isNumber(key.transition) or key.transition < 0) then
		return `{subject} gives way to the next key over {describe(key.transition)} seconds; that must be 0 or more`
	end
	if key.handles ~= nil then
		local handles = key.handles
		if not isList(handles) or #handles ~= 4 then
			return `{subject} has damaged Bezier handles (they should be four numbers)`
		end
		for _, value in handles do
			if not isNumber(value) then
				return `{subject} has a Bezier handle at {describe(value)}, not a number`
			end
		end
		if not isUnit(handles[1]) or not isUnit(handles[3]) then
			return `{subject} has a Bezier handle outside its transition; a handle's time must stay between the two keys`
		end
	end
	if key.handleL ~= nil or key.handleR ~= nil or key.handleType ~= nil then
		return `{subject} has a joint key's Bezier handles, which a movement key has no use for`
	end
	if key.preset ~= nil then
		return `{subject} uses a custom easing, which a movement key cannot; pick an interpolation`
	end
	return checkEase(key, name, when, ctx, false)
end

local function checkWaypoint(key: any, subject: string): string?
	if not isCFrame(key.cframe) then
		return `{subject} has a damaged place to be (it should be a CFrame's twelve numbers)`
	end
	if key.speed ~= nil or key.direction ~= nil then
		return `{subject} has a speed or a direction; only a walk has them`
	end
	if key.turn ~= nil and (not isNumber(key.turn) or key.turn < 0) then
		return `{subject} rounds its corner in {describe(key.turn)} seconds; that must be 0 or more`
	end
	if key.shape ~= nil and not PATH_SHAPE[key.shape] then
		return badChoice(subject, "shape", key.shape, Schema.PATH_SHAPES)
	end
	local own = key.shape == "Aligned" or key.shape == "Free"
	for _, field in { "shapeIn", "shapeOut" } do
		local handle = key[field]
		if handle ~= nil then
			if not own then
				return `{subject} keeps handles of its own, but only an Aligned or Free waypoint has them`
			end
			if not isTriple(handle) then
				return `{subject} has a damaged handle (it should be three numbers)`
			end
		end
	end
	if key.face ~= nil and not PATH_FACE[key.face] then
		return badChoice(subject, "facing", key.face, Schema.PATH_FACES)
	end
	if key.lean ~= nil and not isUnit(key.lean) then
		return `{subject} leans {describe(key.lean)} into its turns; that must be between 0 and 1`
	end
	return nil
end

local function hasPathFields(key: any): boolean
	return key.shape ~= nil
		or key.shapeIn ~= nil
		or key.shapeOut ~= nil
		or key.face ~= nil
		or key.lean ~= nil
end

local function checkMovementKey(key: any, index: number, ctx: Context, name: string): string?
	local label = if name == "the movement" then "movement key" else `{name} key`
	if type(key) ~= "table" then
		return `{label} {index} is damaged`
	end
	if not isNumber(key.t) then
		return `{label} {index} has no usable time`
	end
	local when = at(ctx, key.t)
	if key.t < -EPSILON then
		return `{name} has a key before the start of the animation, at {when}`
	end
	if key.t > ctx.length + EPSILON then
		return `{name} has a key at {when}, after the animation ends at {at(ctx, ctx.length)}`
	end
	if not MOVEMENT_KIND[key.kind] then
		return badChoice(`{name}'s key at {when}`, "kind", key.kind, Schema.MOVEMENT_KINDS)
	end
	if key.kind == "Walk" then
		local subject = `{name}'s walk at {when}`
		if not isNumber(key.speed) or key.speed < 0 then
			return `{subject} has a speed of {describe(key.speed)}; it must be 0 or more studs per second`
		end
		if key.direction ~= nil and not isNumber(key.direction) then
			return `{subject} has a direction of {describe(key.direction)}; it must be an angle`
		end
		if key.turn ~= nil and (not isNumber(key.turn) or key.turn < 0) then
			return `{subject} turns in {describe(key.turn)} seconds; that must be 0 or more`
		end
		if key.cframe ~= nil then
			return `{subject} has a place to be; only a target has one`
		end
		if hasPathFields(key) then
			return `{subject} has a path's shape or facing; only a waypoint has them`
		end
		return checkTransition(key, subject, when, ctx, name)
	end
	if key.kind == "Waypoint" then
		local subject = `{name}'s waypoint at {when}`
		return checkWaypoint(key, subject) or checkTransition(key, subject, when, ctx, name)
	end
	local subject = `{name}'s target at {when}`
	if hasPathFields(key) then
		return `{subject} has a path's shape or facing; only a waypoint has them`
	end
	if not isCFrame(key.cframe) then
		return `{subject} has a damaged place to be (it should be a CFrame's twelve numbers)`
	end
	if key.speed ~= nil or key.direction ~= nil or key.turn ~= nil then
		return `{subject} has a speed or a direction; only a walk has them`
	end
	return checkTransition(key, subject, when, ctx, name)
end

local function checkMovementKeys(keys: any, ctx: Context, name: string): string?
	if not isList(keys) then
		return `{name}'s list of keys is damaged`
	end
	local previous: number? = nil
	for index = 1, #keys do
		local problem = checkMovementKey(keys[index], index, ctx, name)
		if problem then
			return problem
		end
		local t = keys[index].t
		local order = orderOf(previous, t, true)
		if order == "before" then
			return `{name}'s key at {at(ctx, t)} is out of order; its keys must be sorted by time`
		elseif order == "same" then
			return `{name} has two keys at {at(ctx, t)}; one instant takes one key`
		end
		previous = t
	end
	return nil
end

local function checkMovement(movement: any, ctx: Context): string?
	if type(movement) ~= "table" then
		return "the movement is damaged"
	end
	if movement.export ~= nil and not MOVEMENT_EXPORT[movement.export] then
		return badChoice("the movement", "export", movement.export, Schema.MOVEMENT_EXPORTS)
	end
	local problem = checkFlag(movement.module, "the movement", "movement module")
	if problem then
		return problem
	end
	problem = checkMovementKeys(movement.keys, ctx, "the movement")
	if problem then
		return problem
	end
	local joints = movement.joints
	if joints == nil then
		return nil
	end
	if type(joints) ~= "table" then
		return "the movement's joints on the root part are damaged"
	end
	for address, branch in joints do
		if not isName(address) then
			return `the movement names a joint on the root part {describe(address)}, which is not a joint's name`
		end
		local name = `{address}'s movement`
		if type(branch) ~= "table" then
			return `{name} is damaged`
		end
		problem = checkMovementKeys(branch.keys, ctx, name)
		if problem then
			return problem
		end
	end
	return nil
end

local GRIP_CHANNELS = {
	{ field = "gripStrength", noun = "strength" },
	{ field = "gripTurn", noun = "rotation share" },
	{ field = "gripMove", noun = "position share" },
}

local function checkBaked(baked: any, name: string): string?
	if type(baked) ~= "table" or not isList(baked.times) or type(baked.values) ~= "table" then
		return `what {name} last baked is damaged`
	end
	local times = baked.times
	local previous: number? = nil
	for _, t in times do
		if not isNumber(t) or orderOf(previous, t, true) ~= nil then
			return `the times {name} last baked at are damaged`
		end
		previous = t
	end
	for channel, values in baked.values do
		if not EULER_CHANNEL[channel] and not QUATERNION_CHANNEL[channel] then
			return `{name} last baked a channel Apex does not know, {describe(channel)}`
		end
		if not isList(values) or #values ~= #times then
			return `the {channel} values {name} last baked are damaged`
		end
		for _, value in values do
			if not isNumber(value) then
				return `the {channel} values {name} last baked are damaged`
			end
		end
	end
	return nil
end

local function checkPath(path: any, address: string, ctx: Context): string?
	local name = `{address}'s path`
	if type(path) ~= "table" then
		return `{name} is damaged`
	end
	if path.forward ~= nil and not PATH_FORWARD[path.forward] then
		return badChoice(name, "forward", path.forward, Schema.PATH_FORWARDS)
	end
	if path.step ~= nil and (not isWhole(path.step) or path.step < 1) then
		return `{name} keys every {describe(path.step)} frames; that must be a whole number, 1 or more`
	end
	local waypoints = path.waypoints
	if not isList(waypoints) or #waypoints == 0 then
		return `{name} has no waypoints`
	end
	local previous: number? = nil
	for index = 1, #waypoints do
		local waypoint = waypoints[index]
		if type(waypoint) ~= "table" or not isNumber(waypoint.t) then
			return `{name}'s waypoint {index} has no usable time`
		end
		local when = at(ctx, waypoint.t)
		if waypoint.t < -EPSILON then
			return `{name} has a waypoint before the start of the animation, at {when}`
		end
		if waypoint.t > ctx.length + EPSILON then
			return `{name} has a waypoint at {when}, after the animation ends at {at(
				ctx,
				ctx.length
			)}`
		end
		local order = orderOf(previous, waypoint.t, true)
		if order == "before" then
			return `{name}'s waypoint at {when} is out of order; its waypoints must be sorted by time`
		elseif order == "same" then
			return `{name} has two waypoints at {when}; one instant takes one waypoint`
		end
		previous = waypoint.t
		local subject = `{name}'s waypoint at {when}`
		if waypoint.kind ~= nil or waypoint.transition ~= nil then
			return `{subject} has a movement key's kind or transition, which a joint's path has no use for`
		end
		local problem = checkWaypoint(waypoint, subject)
			or checkTransition(waypoint, subject, when, ctx, name)
		if problem then
			return problem
		end
	end
	if path.baked ~= nil then
		local problem = checkBaked(path.baked, name)
		if problem then
			return problem
		end
	end
	local before = path.before
	if before ~= nil then
		if type(before) ~= "table" then
			return `the keys {name} covered are damaged`
		end
		for channel, keys in before do
			if not EULER_CHANNEL[channel] and not QUATERNION_CHANNEL[channel] then
				return `{name} covered keys on a channel Apex does not know, {describe(channel)}`
			end
			local problem = checkChannel({ keys = keys }, `the {channel} keys {name} covered`, ctx)
			if problem then
				return problem
			end
		end
	end
	return nil
end

local function checkPaths(paths: any, ctx: Context): string?
	if type(paths) ~= "table" then
		return "the paths are damaged"
	end
	for address, path in paths do
		if not isName(address) then
			return `a path names a joint {describe(address)}, which is not a joint's name`
		end
		local problem = checkPath(path, address, ctx)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkGrips(doc: any, ctx: Context): string?
	local grips = doc.grips
	if grips ~= nil then
		if type(grips) ~= "table" then
			return "the grips are damaged"
		end
		for name, grip in grips do
			if not isName(name) then
				return "a grip has no name"
			end
			local label = `the grip '{name}'`
			if type(grip) ~= "table" then
				return `{label} is damaged`
			end
			if not isName(grip.target) then
				return `{label} does not say which joint it holds`
			end
			local space = grip.space
			local problem = checkTarget(space, `the space of {label}`, ctx, nil, false)
			if problem then
				return problem
			end
			if space.kind == "Parent" then
				return `{label} rides on its parent, but a grip has none (it rides on a joint, the rig root or World)`
			end
			if space.slot ~= nil then
				return `{label} rides on another slot's rig; a grip rides on a joint of its own rig, the rig root or World`
			end
			if space.kind == "Joint" and space.joint == grip.target then
				return `{label} rides on {grip.target}, the joint it holds`
			end
			if grip.hold ~= nil and not isTriple(grip.hold) then
				return `the hold point of {label} is damaged (it should be three numbers, studs on the part it holds)`
			end
			local box = grip.box
			if
				box ~= nil and not (isTriple(box) and box[1] >= 0 and box[2] >= 0 and box[3] >= 0)
			then
				return `the box of {label} is damaged (it should be three sizes of 0 or more, studs of the part it rides on)`
			end
			if grip.reach ~= nil and grip.reach ~= "Drag" and grip.reach ~= "Stop" then
				return `the reach of {label} is damaged (it should be Drag or Stop)`
			end
			problem = checkTrack(grip, label, "", ctx, nil, false)
			if problem then
				return problem
			end
		end
	end
	for _, entry in GRIP_CHANNELS do
		local channels = doc[entry.field]
		if channels == nil then
			continue
		end
		if type(channels) ~= "table" then
			return `the grips' {entry.noun} keys are damaged`
		end
		for name, channel in channels do
			if not isName(name) then
				return `a grip {entry.noun} track does not say which grip it is for`
			end
			if grips == nil or grips[name] == nil then
				return `the grip {entry.noun} of '{name}' belongs to no grip of this animation`
			end
			local label = `the {entry.noun} of the grip '{name}'`
			local problem = checkChannel(channel, label, ctx)
				or checkKeyRange(channel, label, ctx, 0, 1, "it runs from 0 to 1 (100%)")
			if problem then
				return problem
			end
		end
	end
	return nil
end

local function checkStartingSpaces(spaces: any, ctx: Context): string?
	if type(spaces) ~= "table" then
		return "the starting spaces are damaged"
	end
	for joint, target in spaces do
		if not isName(joint) then
			return "a starting space has no joint name"
		end
		local problem = checkTarget(target, `the starting space of {joint}`, ctx, joint, false)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkBake(bake: any): string?
	if type(bake) ~= "table" then
		return "the bake settings are damaged"
	end
	for _, setting in
		{
			{ "position", "position tolerance", "studs" },
			{ "rotation", "rotation tolerance", "radians" },
			{ "rate", "rate", "samples per second" },
		}
	do
		local value = bake[setting[1]]
		if value ~= nil and (not isNumber(value) or value <= 0) then
			return `the bake {setting[2]} is {describe(value)}; it must be more than 0 {setting[3]}`
		end
	end
	return nil
end

local function checkPublish(publish: any): string?
	if type(publish) ~= "table" then
		return "the publish details are damaged"
	end
	if publish.assetId ~= nil and (not isWhole(publish.assetId) or publish.assetId <= 0) then
		return `the published asset id is {describe(publish.assetId)}; an asset id is a whole number above 0`
	end
	local owner = publish.owner
	if owner ~= nil then
		if type(owner) ~= "table" or (owner.kind ~= "User" and owner.kind ~= "Group") then
			return "the owner in the publish details is damaged (it should be a user or a group)"
		end
		if not isWhole(owner.id) or owner.id <= 0 then
			return `the owner id in the publish details is {describe(owner.id)}; it should be a whole number above 0`
		end
	end
	if publish.bakeHash ~= nil and not isName(publish.bakeHash) then
		return "the bake hash in the publish details is damaged"
	end
	if publish.revision ~= nil and (not isWhole(publish.revision) or publish.revision < 0) then
		return "the revision in the publish details is damaged (it should be a whole number)"
	end
	if publish.time ~= nil and (not isNumber(publish.time) or publish.time < 0) then
		return "the time in the publish details is damaged"
	end
	return nil
end

local function checkSession(doc: any, what: string): string?
	if doc.revision ~= nil and (not isWhole(doc.revision) or doc.revision < 0) then
		return `the {what}'s revision counter is damaged (it should be a whole number)`
	end
	for _, field in { "playFrom", "playTo" } do
		local value = doc[field]
		if value ~= nil and (not isNumber(value) or value < 0) then
			local side = if field == "playFrom" then "start" else "end"
			return `the {what}'s play range is damaged: its {side} is {describe(value)}, and should be a time of 0 seconds or more`
		end
	end
	return nil
end

local function checkHeader(doc: any, what: string): string?
	local problem = checkVersion(doc.version, Schema.VERSION, what)
	if problem then
		return problem
	end
	if not isName(doc.name) then
		return `the {what} has no name`
	end
	if not isNumber(doc.length) or doc.length <= 0 then
		return `the {what}'s length is {describe(doc.length)}; it must be more than 0 seconds`
	end
	if not isNumber(doc.fps) or doc.fps <= 0 then
		return `the {what}'s frame rate is {describe(doc.fps)}; it must be more than 0 frames per second`
	end
	return nil
end

local function checkRig(doc: any, scene: { slots: { [string]: boolean }, slot: string }?): string?
	if type(doc) ~= "table" then
		return `the animation is damaged (it is {describe(doc)}, not an animation)`
	end
	if doc.kind == "Scene" then
		return "this is a scene, not a rig animation - open it as a scene"
	end
	if doc.kind ~= nil and doc.kind ~= "Rig" then
		return `this is not an animation: it is of a kind Apex does not know, {describe(doc.kind)}`
	end
	local problem = checkHeader(doc, "animation")
	if problem then
		return problem
	end
	if type(doc.loop) ~= "boolean" then
		return "the animation's loop setting is damaged (it should be true or false)"
	end
	if not PRIORITY[doc.priority] then
		return `the animation's priority, {describe(doc.priority)}, is not one Roblox has (it takes {oneOf(
			Schema.PRIORITIES
		)})`
	end

	problem = checkPresets(doc.presets)
	if problem then
		return problem
	end
	local ctx: Context = {
		length = doc.length,
		fps = doc.fps,
		presets = doc.presets,
		slots = if scene then scene.slots else nil,
		slot = if scene then scene.slot else nil,
	}

	if type(doc.joints) ~= "table" then
		return "the animation has no list of joints (the save may be damaged)"
	end
	problem = checkJoints(doc.joints, "", ctx, false)
	if problem then
		return problem
	end
	if doc.layers ~= nil then
		problem = checkLayers(doc.layers, ctx)
		if problem then
			return problem
		end
	end

	if doc.controls ~= nil then
		if type(doc.controls) ~= "table" then
			return "the control keys are damaged"
		end
		for name, track in doc.controls do
			if not isName(name) then
				return "keys are saved for a control with no name"
			end
			problem = checkTrack(track, `the control {name}`, "", ctx, nil, false)
			if problem then
				return problem
			end
		end
	end
	if doc.ikBlend ~= nil then
		if type(doc.ikBlend) ~= "table" then
			return "the IK/FK blends are damaged"
		end
		for chain, channel in doc.ikBlend do
			if not isName(chain) then
				return "an IK/FK blend does not say which chain it is for"
			end
			local label = `the IK/FK blend of chain '{chain}'`
			problem = checkChannel(channel, label, ctx)
				or checkKeyRange(channel, label, ctx, 0, 1, "it runs from 0 (FK) to 1 (IK)")
			if problem then
				return problem
			end
		end
	end
	for _, key in ChainKeys.LIST do
		local chains = (doc :: any)[key.family]
		if chains == nil then
			continue
		end
		local noun = string.lower(key.label)
		if type(chains) ~= "table" then
			return `the {noun} keys are damaged`
		end
		for chain, channel in chains do
			if not isName(chain) then
				return `a {noun} track does not say which chain it is for`
			end
			local label = `the {noun} of chain '{chain}'`
			problem = checkChannel(channel, label, ctx)
				or checkKeyRange(channel, label, ctx, key.low, key.high, key.range)
			if problem then
				return problem
			end
		end
	end
	problem = checkGrips(doc, ctx)
	if problem then
		return problem
	end
	if doc.contacts ~= nil then
		if not isList(doc.contacts) then
			return "the contact list is damaged"
		end
		local previous: number? = nil
		local lastEnd: { [string]: number } = {}
		for index = 1, #doc.contacts do
			local contact = doc.contacts[index]
			if type(contact) ~= "table" or not isName(contact.chain) then
				return `contact {index} does not say which chain it plants`
			end
			if not isNumber(contact.t) then
				return `the contact on chain '{contact.chain}' has no usable time`
			end
			local label = `the contact on chain '{contact.chain}' at {at(ctx, contact.t)}`
			if contact.t < -EPSILON then
				return `{label} is before the start of the animation`
			end
			if not isNumber(contact.len) or contact.len <= 0 then
				return `{label} lasts {describe(contact.len)} seconds; it must last longer than 0`
			end
			if contact.t + contact.len > ctx.length + EPSILON then
				return `{label} runs past the end of the animation at {at(ctx, ctx.length)}`
			end
			local blendIn, blendOut = contact.blendIn or 0, contact.blendOut or 0
			if not isNumber(blendIn) or not isNumber(blendOut) or blendIn < 0 or blendOut < 0 then
				return `{label} has a blend-in or blend-out that is not a time of 0 seconds or more`
			end
			if blendIn + blendOut > contact.len + EPSILON then
				return `{label} blends in and out for longer than it lasts`
			end
			if orderOf(previous, contact.t, false) == "before" then
				return `{label} is out of order; contacts must be sorted by time`
			end
			previous = contact.t
			local chainEnd = lastEnd[contact.chain]
			if chainEnd ~= nil and contact.t < chainEnd - EPSILON then
				return `{label} overlaps the contact before it on the same chain`
			end
			lastEnd[contact.chain] = contact.t + contact.len
		end
	end

	if doc.markers ~= nil then
		problem = checkMarkers(doc.markers, ctx)
		if problem then
			return problem
		end
	end
	if doc.states ~= nil then
		problem = checkStates(doc.states, ctx)
		if problem then
			return problem
		end
	end
	if doc.props ~= nil then
		problem = checkProps(doc.props, ctx)
		if problem then
			return problem
		end
	end
	if doc.sounds ~= nil then
		problem = checkSounds(doc.sounds, ctx)
		if problem then
			return problem
		end
	end
	if doc.releases ~= nil then
		problem = checkReleases(doc.releases, ctx)
		if problem then
			return problem
		end
	end
	if doc.movement ~= nil then
		problem = checkMovement(doc.movement, ctx)
		if problem then
			return problem
		end
	end
	if doc.paths ~= nil then
		problem = checkPaths(doc.paths, ctx)
		if problem then
			return problem
		end
	end
	if doc.startingSpaces ~= nil then
		problem = checkStartingSpaces(doc.startingSpaces, ctx)
		if problem then
			return problem
		end
	end
	if doc.interrupt ~= nil and not INTERRUPT_POLICY[doc.interrupt] then
		return `the animation's choice for when it is stopped part-way is {describe(doc.interrupt)}, which Apex does not know (it takes {oneOf(
			Schema.INTERRUPT_POLICIES
		)})`
	end
	if doc.spaceMismatch ~= nil and not SPACE_MISMATCH_POLICY[doc.spaceMismatch] then
		return `the animation's choice for when a joint starts in another space is {describe(
			doc.spaceMismatch
		)}, which Apex does not know (it takes {oneOf(Schema.SPACE_MISMATCH_POLICIES)})`
	end
	local adopt = doc.spaceAdoptTime
	if adopt ~= nil and (not isNumber(adopt) or adopt < 0) then
		return `the animation's adopt time is {describe(adopt)}; it must be 0 seconds or more`
	end
	if doc.bake ~= nil then
		problem = checkBake(doc.bake)
		if problem then
			return problem
		end
	end
	if doc.publish ~= nil then
		problem = checkPublish(doc.publish)
		if problem then
			return problem
		end
	end
	return checkSession(doc, "animation")
end

function Schema.validate(
	doc: any,
	scene: { slots: { [string]: boolean }, slot: string }?
): (boolean, string?)
	local problem = checkRig(doc, scene)
	if problem then
		return false, problem
	end
	return true, nil
end

local function checkRequirement(requirement: any, label: string): string?
	if type(requirement) ~= "table" then
		return `{label} does not say what rig it accepts`
	end
	local kind = requirement.kind
	if not RIG_REQUIREMENT[kind] then
		return badChoice(label, "rig requirement", kind, Schema.RIG_REQUIREMENTS)
	end
	if kind == "Signature" then
		local joints = requirement.joints
		if not isList(joints) or #joints == 0 then
			return `{label} accepts a custom rig but does not list the joints it needs`
		end
		local seen: { [string]: boolean } = {}
		for _, joint in joints do
			if not isName(joint) then
				return `{label} requires a joint with no name`
			end
			if seen[joint] then
				return `{label} lists the joint {joint} twice`
			end
			seen[joint] = true
		end
	elseif requirement.joints ~= nil then
		return `{label} accepts any {kind} rig, so it cannot also list joints`
	end
	return nil
end

local function checkAnchor(anchor: any, slots: { [string]: boolean }): string?
	if type(anchor) ~= "table" then
		return "the scene has no anchor"
	end
	local kind = anchor.kind
	if not ANCHOR_KIND[kind] then
		return badChoice("the scene's anchor", "kind", kind, Schema.ANCHOR_KINDS)
	end
	if anchor.cframe ~= nil and not isCFrame(anchor.cframe) then
		return "the scene's anchor position is not a valid position and rotation"
	end
	if kind == "Authored" and anchor.cframe == nil then
		return "the scene is anchored where it was authored, but does not record where that was"
	end
	if kind == "Part" then
		if not isPath(anchor.part) then
			return `the scene is anchored to a map part but does not say which (a path from Workspace, names joined by "/")`
		end
	elseif anchor.part ~= nil then
		return `the scene's anchor is {kind}, so it cannot also name a part`
	end
	if kind == "Slot" then
		if not isName(anchor.slot) then
			return "the scene is anchored to one of its slots but does not say which"
		end
		if not slots[anchor.slot] then
			return `the scene is anchored to slot '{anchor.slot}', which it does not have`
		end
	elseif anchor.slot ~= nil then
		return `the scene's anchor is {kind}, so it cannot also name a slot`
	end
	return nil
end

local function checkScreenText(value: any, subject: string, what: string, most: number): string?
	if value == nil then
		return nil
	end
	if type(value) ~= "string" then
		return `the {what} of {subject} is damaged (it should be text)`
	end
	local length = utf8.len(value) or #value
	if length > most then
		return `the {what} of {subject} is {length} characters long; it can be at most {most}`
	end
	return nil
end

local function checkScreenFades(clip: any, label: string): string?
	for _, which in { "in", "out" } do
		local fade = if which == "in" then clip.fadeIn else clip.fadeOut
		if fade ~= nil and (not isNumber(fade) or fade < 0) then
			return `{label} fades {which} over {describe(fade)} seconds; a fade takes 0 seconds or more`
		end
	end
	local fades = (clip.fadeIn or 0) + (clip.fadeOut or 0)
	if fades > clip.len + EPSILON then
		return `{label} fades in and out for {seconds(fades)} in all, longer than the clip lasts, {seconds(
			clip.len
		)}`
	end
	return nil
end

local function checkScreenSize(clip: any, label: string): string?
	local size = clip.size
	if size == nil then
		return nil
	end
	local most = if clip.kind == "Edges" then Schema.MAX_EDGE_SIZE else Schema.MAX_BAR_SIZE
	if not isNumber(size) or size <= 0 or size > most then
		local what = if clip.kind == "Edges" then "edges reaching" else "bars"
		return `{label} has {what} {describe(size)} of the screen high (it takes more than 0, up to {most})`
	end
	return nil
end

local function checkSubtitleLook(clip: any, label: string): string?
	if clip.speakerColor ~= nil and not isColour(clip.speakerColor) then
		return `{label} has a damaged speaker colour (it should be three numbers from 0 to 1)`
	end
	if clip.style ~= nil and not SUBTITLE_STYLE[clip.style] then
		return badChoice(label, "style", clip.style, Schema.SUBTITLE_STYLES)
	end
	if clip.reveal ~= nil and not SUBTITLE_REVEAL[clip.reveal] then
		return badChoice(label, "reveal", clip.reveal, Schema.SUBTITLE_REVEALS)
	end
	if clip.font ~= nil and not SUBTITLE_FONT[clip.font] then
		return badChoice(label, "font", clip.font, Schema.SUBTITLE_FONTS)
	end
	local scale = clip.scale
	if
		scale ~= nil
		and (
			not isNumber(scale)
			or scale < Schema.MIN_SUBTITLE_SCALE
			or scale > Schema.MAX_SUBTITLE_SCALE
		)
	then
		return `{label} has its text at {describe(scale)} times its size (it takes {Schema.MIN_SUBTITLE_SCALE} to {Schema.MAX_SUBTITLE_SCALE})`
	end
	local speed = clip.speed
	if speed ~= nil and (not isNumber(speed) or speed <= 0 or speed > Schema.MAX_REVEAL_SPEED) then
		return `{label} comes in at {describe(speed)} a second (it takes more than 0, up to {Schema.MAX_REVEAL_SPEED})`
	end
	if (clip.x == nil) ~= (clip.y == nil) then
		return `{label} has only half a place on the screen (it needs both x and y, or neither)`
	end
	if clip.x ~= nil and (not isUnit(clip.x) or not isUnit(clip.y)) then
		return `{label} sits off the screen at {describe(clip.x)}, {describe(clip.y)} (each takes 0 to 1)`
	end
	return checkScreenText(clip.text, label, "text", Schema.MAX_SUBTITLE_LENGTH)
		or checkScreenText(clip.speaker, label, "speaker's name", Schema.MAX_SPEAKER_LENGTH)
end

local function checkScreenLook(clip: any, label: string): string?
	local problem = checkScreenSize(clip, label)
	if problem ~= nil then
		return problem
	end
	if clip.color ~= nil and not isColour(clip.color) then
		return `{label} has a damaged colour (it should be three numbers from 0 to 1)`
	end
	if clip.amount ~= nil and not isUnit(clip.amount) then
		return `{label} has a strength of {describe(clip.amount)} (it takes 0 to 1)`
	end
	return checkSubtitleLook(clip, label)
end

local function checkScreen(screen: any, ctx: Context): string?
	if not isList(screen) then
		return "the scene's Screen row is damaged (it should be a list of clips)"
	end
	if #screen > Schema.MAX_SCREEN_CLIPS then
		return `the Screen row has {#screen} clips; it can hold at most {Schema.MAX_SCREEN_CLIPS}`
	end
	local previous: number? = nil
	for index = 1, #screen do
		local clip = screen[index]
		if type(clip) ~= "table" or not isNumber(clip.t) then
			return `the Screen row has a clip with no usable time (clip {index})`
		end
		if not SCREEN_KIND[clip.kind] then
			return badChoice(
				`the Screen clip at {at(ctx, clip.t)}`,
				"kind",
				clip.kind,
				Schema.SCREEN_KINDS
			)
		end
		local label = `the {clip.kind} clip at {at(ctx, clip.t)}`
		if clip.t < -EPSILON then
			return `the Screen row has a clip before the start of the scene, at {at(ctx, clip.t)}`
		end
		if orderOf(previous, clip.t, false) ~= nil then
			return `the Screen row has its clips out of order at {at(ctx, clip.t)}`
		end
		previous = clip.t
		if not isNumber(clip.len) or clip.len <= EPSILON then
			return `{label} lasts {describe(clip.len)} seconds; a clip must last longer than 0`
		end
		if clip.t + clip.len > ctx.length + EPSILON then
			return `{label} runs past the end of the scene at {at(ctx, ctx.length)}`
		end
		local problem = checkScreenFades(clip, label) or checkScreenLook(clip, label)
		if problem then
			return problem
		end
	end
	return nil
end

local function checkScene(scene: any): string?
	if type(scene) ~= "table" then
		return `the scene is damaged (it is {describe(scene)}, not a scene)`
	end
	if scene.kind ~= "Scene" then
		if scene.kind == nil or scene.kind == "Rig" then
			return "this is a rig animation, not a scene - open it on its rig"
		end
		return `this is not a scene: it is of a kind Apex does not know, {describe(scene.kind)}`
	end
	local problem = checkHeader(scene, "scene")
	if problem then
		return problem
	end
	problem = checkPresets(scene.presets)
	if problem then
		return problem
	end
	if type(scene.slots) ~= "table" then
		return "the scene has no list of slots (the save may be damaged)"
	end
	local names: { [string]: boolean } = {}
	for name in scene.slots do
		if not isName(name) then
			return "a slot has no name"
		end
		names[name] = true
	end
	local models: { [string]: string } = {}
	for name, slot in scene.slots do
		local label = `slot '{name}'`
		if type(slot) ~= "table" then
			return `{label} is damaged`
		end
		if not isName(slot.model) then
			return `{label} does not say which rig in the scene plays it`
		end
		local other = models[slot.model]
		if other ~= nil then
			return `slots '{other}' and '{name}' both play the rig '{slot.model}'; each slot needs its own rig`
		end
		models[slot.model] = name
		problem = checkRequirement(slot.requirement, label)
		if problem then
			return problem
		end
		if not isCFrame(slot.placement) then
			return `the placement of {label} is not a valid position and rotation`
		end
		problem = checkRig(slot.document, { slots = names, slot = name })
		if problem then
			return `in {label}: {problem}`
		end
		local slotLength = slot.document.length
		if slotLength > scene.length + EPSILON then
			return `the animation in {label} is {seconds(slotLength)} long, longer than the scene's {seconds(
				scene.length
			)}; it would be cut off`
		end
	end
	problem = checkAnchor(scene.anchor, names)
	if problem then
		return problem
	end
	local ctx: Context = {
		length = scene.length,
		fps = scene.fps,
		presets = scene.presets,
		slots = names,
		slot = nil,
	}
	if scene.camera ~= nil then
		problem = checkTrack(scene.camera, "the camera", "", ctx, nil, true)
		if problem then
			return problem
		end
	end
	if scene.screen ~= nil then
		problem = checkScreen(scene.screen, ctx)
		if problem then
			return problem
		end
	end
	if scene.markers ~= nil then
		problem = checkMarkers(scene.markers, ctx)
		if problem then
			return problem
		end
	end
	return checkSession(scene, "scene")
end

function Schema.validateScene(scene: any): (boolean, string?)
	local problem = checkScene(scene)
	if problem then
		return false, problem
	end
	return true, nil
end

local function checkControl(control: any, name: any): string?
	if not isName(name) then
		return "a control has no name"
	end
	local label = `the control {name}`
	if type(control) ~= "table" then
		return `{label} is damaged`
	end
	if not CONTROL_KIND[control.kind] then
		return badChoice(label, "kind", control.kind, Schema.CONTROL_KINDS)
	end
	if control.shape ~= nil and not CONTROL_SHAPE[control.shape] then
		return badChoice(label, "shape", control.shape, Schema.CONTROL_SHAPES)
	end
	if control.joint ~= nil and not isName(control.joint) then
		return `{label} names its joint, but the name is damaged`
	end
	local offset = control.offset
	if
		offset ~= nil
		and not (
			isList(offset)
			and #offset == 3
			and isNumber(offset[1])
			and isNumber(offset[2])
			and isNumber(offset[3])
		)
	then
		return `{label}'s offset from its joint is damaged (it should be three numbers, in studs)`
	end
	if control.parent ~= nil and not isName(control.parent) then
		return `{label} names the joint it hangs from, but the name is damaged`
	end
	if control.size ~= nil and (not isNumber(control.size) or control.size <= 0) then
		return `{label} has a size of {describe(control.size)}; it must be more than 0 studs`
	end
	if control.color ~= nil and not isColour(control.color) then
		return `{label}'s colour is damaged (it should be three numbers from 0 to 1)`
	end
	return checkFlag(control.hidden, label, "hidden") or checkFlag(control.locked, label, "locked")
end

local function checkChain(
	chain: any,
	name: any,
	controls: { [string]: any },
	owners: { [string]: string }
): string?
	if not isName(name) then
		return "a chain has no name"
	end
	local label = `the chain '{name}'`
	if type(chain) ~= "table" then
		return `{label} is damaged`
	end
	if not SOLVER[chain.solver] then
		return badChoice(label, "solver", chain.solver, Schema.SOLVERS)
	end
	local joints = chain.joints
	if not isList(joints) then
		return `{label} does not list its joints`
	end
	if chain.solver == "Aim" then
		if #joints ~= 1 then
			return `{label} is an aim chain with {#joints} joints; it turns exactly 1 (for example a shoulder)`
		end
	else
		if chain.solver == "TwoBone" and #joints ~= 3 then
			return `{label} is a two-bone chain with {#joints} joints; it needs exactly 3 (for example shoulder, elbow and wrist)`
		end
		if #joints < 2 then
			return `{label} has {#joints} joints; a chain needs at least 2`
		end
	end
	local inChain: { [string]: boolean } = {}
	for _, joint in joints do
		if not isName(joint) then
			return `{label} lists a joint with no name`
		end
		if inChain[joint] then
			return `{label} lists {joint} twice`
		end
		inChain[joint] = true
		local other = owners[joint]
		if other ~= nil then
			return `{joint} is in both chain '{other}' and chain '{name}'; two solvers would fight over it`
		end
		owners[joint] = name
	end

	if not isName(chain.target) then
		return `{label} does not say which control it reaches for`
	end
	local target = controls[chain.target]
	if target == nil then
		return `{label} reaches for the control {chain.target}, which the Control Rig does not have`
	end
	if type(target) == "table" and target.kind ~= "IKTarget" then
		return `{label} reaches for {chain.target}, which is {article(tostring(target.kind))} {tostring(
			target.kind
		)} control, not an IK target`
	end
	if chain.pole ~= nil then
		local pole = if isName(chain.pole) then controls[chain.pole] else nil
		if pole == nil then
			return `{label} bends toward the pole {describe(chain.pole)}, which the Control Rig does not have`
		end
		if type(pole) == "table" and pole.kind ~= "Pole" then
			return `{label} bends toward {chain.pole}, which is {article(tostring(pole.kind))} {tostring(
				pole.kind
			)} control, not a pole`
		end
	end
	if chain.plant ~= nil then
		local plant = if isName(chain.plant) then controls[chain.plant] else nil
		if plant == nil then
			return `{label} is planted on {describe(chain.plant)}, which the Control Rig does not have`
		end
		if type(plant) == "table" and plant.kind ~= "Plant" then
			return `{label} is planted on {chain.plant}, which is {article(tostring(plant.kind))} {tostring(
				plant.kind
			)} control, not a plant`
		end
	end
	if chain.poleAngle ~= nil and not isNumber(chain.poleAngle) then
		return `the pole angle of {label} is {describe(chain.poleAngle)}, not a number`
	end

	if chain.limits ~= nil then
		if type(chain.limits) ~= "table" then
			return `the rotation limits of {label} are damaged`
		end
		for joint, limit in chain.limits do
			if not inChain[joint] then
				return `{label} limits {describe(joint)}, which is not in the chain`
			end
			if type(limit) ~= "table" then
				return `the limits of {label} on {joint} are damaged`
			end
			for _, axis in { "x", "y", "z" } do
				local pair = limit[axis]
				if pair ~= nil then
					local fine = isList(pair)
						and #pair == 2
						and isNumber(pair[1])
						and isNumber(pair[2])
						and pair[1] <= pair[2]
					if not fine then
						return `the {axis} limit of {label} on {joint} is damaged (it should be a lowest and a highest angle, lowest first)`
					end
				end
			end
		end
	end
	if chain.stiffness ~= nil then
		if type(chain.stiffness) ~= "table" then
			return `the stiffness of {label} is damaged`
		end
		for joint, value in chain.stiffness do
			if not inChain[joint] then
				return `{label} sets the stiffness of {describe(joint)}, which is not in the chain`
			end
			if not isUnit(value) then
				return `{label} gives {joint} a stiffness of {describe(value)}; stiffness runs from 0 to 1`
			end
		end
	end
	if chain.stretch ~= nil and (not isNumber(chain.stretch) or chain.stretch < 1) then
		return `{label} stretches to {describe(chain.stretch)} times its length; 1 is no stretch, and it cannot be less`
	end
	local softness = chain.softness
	if softness ~= nil and (not isNumber(softness) or softness < 0 or softness >= 1) then
		return `the softness of {label} is {describe(softness)}; it runs from 0 up to (not including) 1`
	end
	if chain.iterations ~= nil and (not isWhole(chain.iterations) or chain.iterations < 1) then
		return `{label} solves in {describe(chain.iterations)} passes; it needs a whole number of 1 or more`
	end
	if chain.tolerance ~= nil and (not isNumber(chain.tolerance) or chain.tolerance <= 0) then
		return `the tolerance of {label} is {describe(chain.tolerance)}; it must be more than 0 studs`
	end
	local tip = chain.tip
	if
		tip ~= nil
		and not (
			isList(tip)
			and #tip == 3
			and isNumber(tip[1])
			and isNumber(tip[2])
			and isNumber(tip[3])
		)
	then
		return `the tip of {label} is damaged (it should be three numbers, in studs)`
	end
	if chain.foldShare ~= nil and not isUnit(chain.foldShare) then
		return `{label} folds with a share of {describe(chain.foldShare)}; it runs from 0 to 1`
	end
	return checkFlag(chain.roll, label, "roll") or checkFlag(chain.slideIn, label, "slide in")
end

local function checkMirror(map: any, what: string, known: { [string]: any }?): string?
	if type(map) ~= "table" then
		return `the left/right {what} map is damaged`
	end
	for from, to in map do
		if not isName(from) or not isName(to) then
			return `the left/right {what} map has an entry with no name`
		end
		if from == to then
			return `the left/right map pairs {from} with itself; leave a centre {what} out of the map`
		end
		if map[to] ~= from then
			if map[to] == nil then
				return `the left/right map pairs {from} with {to}, but not {to} with {from}`
			end
			return `the left/right map pairs {from} with {to}, but {to} with {describe(map[to])}`
		end
		if known ~= nil and known[from] == nil then
			return `the left/right map mirrors the control {from}, which the Control Rig does not have`
		end
	end
	return nil
end

local function checkControlRig(rig: any): string?
	if type(rig) ~= "table" then
		return `the Control Rig is damaged (it is {describe(rig)}, not a Control Rig)`
	end
	local problem = checkVersion(rig.version, Schema.CONTROL_RIG_VERSION, "Control Rig")
	if problem then
		return problem
	end
	if rig.preset ~= nil and not CONTROL_RIG_PRESET[rig.preset] then
		return badChoice("the Control Rig", "preset", rig.preset, Schema.CONTROL_RIG_PRESETS)
	end
	if rig.signature ~= nil then
		if not isList(rig.signature) then
			return "the Control Rig's list of the joints it fits is damaged"
		end
		local seen: { [string]: boolean } = {}
		for _, joint in rig.signature do
			if not isName(joint) or seen[joint] then
				return "the Control Rig's list of the joints it fits is damaged (each joint once, by name)"
			end
			seen[joint] = true
		end
	end
	if type(rig.controls) ~= "table" then
		return "the Control Rig has no list of controls"
	end
	for name, control in rig.controls do
		problem = checkControl(control, name)
		if problem then
			return problem
		end
	end
	if type(rig.chains) ~= "table" then
		return "the Control Rig has no list of chains"
	end
	local owners: { [string]: string } = {}
	for name, chain in rig.chains do
		problem = checkChain(chain, name, rig.controls, owners)
		if problem then
			return problem
		end
	end
	local symmetry = rig.symmetry
	if symmetry ~= nil then
		if type(symmetry) ~= "table" then
			return "the Control Rig's symmetry plane is damaged"
		end
		if not SYMMETRY_AXIS[symmetry.axis] then
			return badChoice("the symmetry plane", "axis", symmetry.axis, Schema.SYMMETRY_AXES)
		end
		if symmetry.offset ~= nil and not isNumber(symmetry.offset) then
			return `the symmetry plane's offset is {describe(symmetry.offset)}, not a number`
		end
	end
	local mirror = rig.mirror
	if mirror ~= nil then
		if type(mirror) ~= "table" then
			return "the left/right map is damaged"
		end
		problem = checkMirror(mirror.joints, "joint", nil)
		if problem then
			return problem
		end
		if mirror.controls ~= nil then
			problem = checkMirror(mirror.controls, "control", rig.controls)
			if problem then
				return problem
			end
		end
	end
	return nil
end

function Schema.validateControlRig(rig: any): (boolean, string?)
	local problem = checkControlRig(rig)
	if problem then
		return false, problem
	end
	return true, nil
end

return Schema
