--!strict

local Signal = require(script.Parent.Parent.Signal)
local Schema = require(script.Parent.Parent.Core.Schema)
local Sidecar = require(script.Parent.Parent.Core.Sidecar)
local Types = require(script.Parent.Parent.Core.Types)

local ApexTrack = {}

ApexTrack.END_TOLERANCE = 0.05

ApexTrack.FADE_TIMEOUT = 10

ApexTrack.HASH_MARKER = Schema.RESERVED_MARKER

export type Phase = "Idle" | "Playing" | "Stopping"
export type EndReason = "Completed" | "Interrupted"
export type Outcome = "Final" | "Revert" | "Freeze"

export type Hooks = {
	began: (live: Live) -> (),
	stopped: (live: Live, reason: EndReason, policy: Types.InterruptPolicy) -> (),
	ended: (live: Live) -> (),
}

export type Live = {
	track: any,
	animator: any,
	rig: any?,
	sidecar: Sidecar.Sidecar,
	source: Sidecar.Sidecar,
	scale: number,
	label: string,
	showsLook: boolean?,

	phase: Phase,
	plays: number,
	late: boolean,
	reason: EndReason?,
	laps: number,

	time: number,
	weight: number,
	speed: number,
	length: number,
	looped: boolean,

	seenTime: number,
	seenSpeed: number,
	seenClock: number,
	stoppedClock: number,

	pending: ("start" | "late")?,
	lapped: boolean,
	endedEvent: boolean,

	stopped: Signal.Signal,
	ended: Signal.Signal,
	didLoop: Signal.Signal,
	stateSignals: { [string]: Signal.Signal },
	spanSignals: { [string]: Signal.Signal },
	readState: ((name: string) -> any)?,

	data: { [string]: any },

	hooks: Hooks,
	clock: () -> number,
	warnOnce: (key: string, message: string) -> (),
	connections: { any },
	handle: any?,
}

export type Config = {
	track: any,
	animator: any,
	rig: any?,
	sidecar: Sidecar.Sidecar,
	label: string,
	hooks: Hooks,
	clock: () -> number,
	warnOnce: (key: string, message: string) -> (),
}

export type EndInput = {
	looped: boolean,
	length: number,
	time: number,
	speed: number,
	elapsed: number,
	stoppedAt: number?,
}

function ApexTrack.endReason(input: EndInput): EndReason
	if input.looped then
		return "Interrupted"
	end
	local length = input.length
	if length <= 0 then
		return "Completed"
	end
	local tolerance = ApexTrack.END_TOLERANCE
	local travelled = input.speed * math.max(input.elapsed, 0)
	if input.speed < 0 then
		local reached = input.time + travelled
		if input.stoppedAt ~= nil then
			reached = math.min(reached, input.stoppedAt)
		end
		return if reached <= tolerance then "Completed" else "Interrupted"
	end
	local reached = input.time + travelled
	if input.stoppedAt ~= nil then
		reached = math.max(reached, input.stoppedAt)
	end
	return if reached >= length - tolerance then "Completed" else "Interrupted"
end

function ApexTrack.outcome(
	reason: EndReason,
	policy: Types.InterruptPolicy,
	onEnd: Types.EndBehaviour?
): Outcome
	local persist = onEnd == "Persist"
	if reason == "Completed" or policy == "Complete" then
		return if persist then "Final" else "Revert"
	elseif policy == "Keep" then
		return "Freeze"
	end
	return "Revert"
end

function ApexTrack.hashMatches(heard: any, expected: string): boolean
	if type(heard) ~= "string" then
		return false
	end
	local function clean(text: string): string
		return string.lower((string.gsub(text, "%s+", "")))
	end
	return clean(heard) == clean(expected)
end

function ApexTrack.staleMessage(label: string, assetId: number?): string
	local asset = if assetId ~= nil then string.format("asset %d", assetId) else "its asset"
	return `ApexEngine: {label} is out of date with {asset} - re-export it from Apex Animator (publishing again updates it for you). Until then its enhanced parts may not match the animation.`
end

local function index(track: any, key: string): any
	return track[key]
end

local function read(track: any, key: string, fallback: any): any
	local ok, value = pcall(index, track, key)
	if ok and value ~= nil then
		return value
	end
	return fallback
end

function ApexTrack.sample(live: Live)
	local track = live.track
	live.time = read(track, "TimePosition", live.time)
	live.weight = read(track, "WeightCurrent", live.weight)
	live.speed = read(track, "Speed", live.speed)
	live.length = read(track, "Length", live.length)
	live.looped = read(track, "Looped", live.looped)
end

function ApexTrack.new(config: Config): Live
	local live: Live = {
		track = config.track,
		animator = config.animator,
		rig = config.rig,
		sidecar = config.sidecar,
		source = config.sidecar,
		scale = 1,
		label = config.label,
		phase = "Idle",
		plays = 0,
		late = false,
		reason = nil,
		laps = 0,
		time = 0,
		weight = 0,
		speed = 1,
		length = config.sidecar.length,
		looped = config.sidecar.loop,
		seenTime = 0,
		seenSpeed = 1,
		seenClock = 0,
		stoppedClock = 0,
		pending = nil,
		lapped = false,
		endedEvent = false,
		stopped = Signal.new(),
		ended = Signal.new(),
		didLoop = Signal.new(),
		stateSignals = {},
		spanSignals = {},
		readState = nil,
		data = {},
		hooks = config.hooks,
		clock = config.clock,
		warnOnce = config.warnOnce,
		connections = {},
		handle = nil,
	}
	ApexTrack.fit(live)

	local track = config.track
	local function connect(signal: () -> any, handler: (...any) -> ())
		local ok, connection = pcall(function()
			return signal():Connect(handler)
		end)
		if ok and connection ~= nil then
			table.insert(live.connections, connection)
		end
	end
	connect(function()
		return track.DidLoop
	end, function()
		live.lapped = true
	end)
	connect(function()
		return track.Ended
	end, function()
		live.endedEvent = true
	end)
	connect(function()
		return track:GetMarkerReachedSignal(ApexTrack.HASH_MARKER)
	end, function(heard: any)
		if not ApexTrack.hashMatches(heard, live.sidecar.hash) then
			local id = live.sidecar.assetId
			live.warnOnce(
				`stale:{live.label}:{tostring(id)}`,
				ApexTrack.staleMessage(live.label, id)
			)
		end
	end)
	return live
end

function ApexTrack.markPlayed(live: Live, late: boolean)
	if late then
		if live.phase ~= "Idle" or live.pending ~= nil then
			return
		end
		if not read(live.track, "IsPlaying", true) then
			return
		end
		live.pending = "late"
		return
	end
	live.pending = "start"
end

function ApexTrack.fit(live: Live)
	local factor = Sidecar.factorOf(live.source, live.rig)
	if factor ~= live.scale then
		live.sidecar = Sidecar.scaled(live.source, factor)
		live.scale = factor
	end
end

local function policyOf(live: Live): Types.InterruptPolicy
	return Sidecar.policies(live.sidecar).interrupt
end

local function stopPlay(live: Live, now: number)
	local stoppedAt = read(live.track, "TimePosition", nil)
	local reason = ApexTrack.endReason({
		looped = live.looped,
		length = live.length,
		time = live.seenTime,
		speed = live.seenSpeed,
		elapsed = now - live.seenClock,
		stoppedAt = stoppedAt,
	})
	live.reason = reason
	live.phase = "Stopping"
	live.stoppedClock = now
	live.hooks.stopped(live, reason, policyOf(live))
	Signal.fire(live.stopped, reason)
end

local function finishPlay(live: Live)
	live.phase = "Idle"
	live.hooks.ended(live)
end

local function beginPlay(live: Live, now: number, late: boolean)
	live.phase = "Playing"
	live.plays += 1
	live.late = late
	live.reason = nil
	live.laps = 0
	live.lapped = false
	live.endedEvent = false
	ApexTrack.sample(live)
	live.seenTime = live.time
	live.seenSpeed = live.speed
	live.seenClock = now
	ApexTrack.fit(live)
	live.hooks.began(live)
end

function ApexTrack.poll(live: Live, now: number): boolean
	local pending = live.pending
	if pending ~= nil then
		live.pending = nil
		if live.phase == "Playing" then
			stopPlay(live, now)
		end
		if live.phase == "Stopping" then
			finishPlay(live)
		end
		beginPlay(live, now, pending == "late")
	end

	ApexTrack.sample(live)
	if live.phase == "Playing" then
		if read(live.track, "IsPlaying", false) then
			live.seenTime = live.time
			live.seenSpeed = live.speed
			live.seenClock = now
			if live.lapped then
				live.lapped = false
				live.laps += 1
				Signal.fire(live.didLoop)
			end
		else
			stopPlay(live, now)
		end
	end
	if live.phase == "Stopping" then
		if
			live.endedEvent
			or live.weight <= 0
			or now - live.stoppedClock >= ApexTrack.FADE_TIMEOUT
		then
			finishPlay(live)
			Signal.fire(live.ended)
			return false
		end
	end
	return live.phase ~= "Idle"
end

function ApexTrack.abandon(live: Live, now: number)
	live.pending = nil
	if live.phase == "Playing" then
		stopPlay(live, now)
	end
	if live.phase == "Stopping" then
		finishPlay(live)
		Signal.fire(live.ended)
	end
end

function ApexTrack.destroy(live: Live)
	for _, connection in live.connections do
		connection:Disconnect()
	end
	table.clear(live.connections)
end

local function stateNamed(live: Live, name: any, level: number): Types.StateTrack
	for _, state in live.sidecar.states or {} do
		if state.name == name then
			return state
		end
	end
	local names: { string } = {}
	for _, state in live.sidecar.states or {} do
		table.insert(names, `'{state.name}'`)
	end
	local have = if #names == 0
		then "it has no state tracks"
		else `its state tracks are {table.concat(names, ", ")}`
	error(`ApexEngine: {live.sidecar.name} has no state track '{tostring(name)}' - {have}`, level)
end

function ApexTrack.stateSignal(live: Live, name: string): Signal.Signal
	local signal = live.stateSignals[name]
	if signal == nil then
		signal = Signal.new()
		live.stateSignals[name] = signal
	end
	return signal
end

function ApexTrack.spanSignal(live: Live, name: string): Signal.Signal
	local signal = live.spanSignals[name]
	if signal == nil then
		signal = Signal.new()
		live.spanSignals[name] = signal
	end
	return signal
end

local owners: { [any]: Live } = setmetatable({}, { __mode = "k" }) :: any

local MIRRORED: { [string]: boolean } = {
	TimePosition = true,
	Length = true,
	IsPlaying = true,
	Looped = true,
	Speed = true,
	WeightCurrent = true,
	WeightTarget = true,
	Priority = true,
	Animation = true,
	Name = true,
}
local WRITABLE: { [string]: boolean } = {
	TimePosition = true,
	Looped = true,
	Priority = true,
}

--[=[
	@class ApexTrack

	An enhanced AnimationTrack, from LoadAnimation, GetTrack or a scene's GetTrack. It mirrors
	the Roblox track and adds state tracks. TimePosition, Length, IsPlaying, Looped, Speed,
	WeightCurrent, WeightTarget, Priority, Animation and Name read from the Roblox track, and
	TimePosition, Looped and Priority can be set. Call its methods with `:`.
]=]
local Methods = {}

local function liveOf(handle: any): Live
	local live = owners[handle]
	if live == nil then
		error("ApexEngine: call this on a track, with ':' (track:Play()), not '.'", 3)
	end
	return live
end

--[=[
	@method Play
	@within ApexTrack

	Plays the Roblox track, with AnimationTrack:Play's arguments.

	@param fadeTime number?
	@param weight number?
	@param speed number?
]=]
function Methods.Play(self: any, fadeTime: number?, weight: number?, speed: number?)
	liveOf(self).track:Play(fadeTime, weight, speed)
end

--[=[
	@method Stop
	@within ApexTrack

	Stops the Roblox track. Stopped then fires with "Interrupted" unless the play had reached
	its end.

	@param fadeTime number?
]=]
function Methods.Stop(self: any, fadeTime: number?)
	liveOf(self).track:Stop(fadeTime)
end

--[=[
	@method AdjustSpeed
	@within ApexTrack

	Calls AdjustSpeed on the Roblox track.

	@param speed number?
]=]
function Methods.AdjustSpeed(self: any, speed: number?)
	liveOf(self).track:AdjustSpeed(speed)
end

--[=[
	@method AdjustWeight
	@within ApexTrack

	Calls AdjustWeight on the Roblox track.

	@param weight number?
	@param fadeTime number?
]=]
function Methods.AdjustWeight(self: any, weight: number?, fadeTime: number?)
	liveOf(self).track:AdjustWeight(weight, fadeTime)
end

--[=[
	@method GetMarkerReachedSignal
	@within ApexTrack

	Returns the Roblox track's own marker signal, since the asset's markers fire natively.

	@param name string
	@return RBXScriptSignal
]=]
function Methods.GetMarkerReachedSignal(self: any, name: string): any
	return liveOf(self).track:GetMarkerReachedSignal(name)
end

--[=[
	@method GetState
	@within ApexTrack

	Returns a state track's value at the track's current time, so it is right after a seek.

	@param name string
	@return any -- nil or false while the track is not playing
	@error string -- the animation has no state track with that name
]=]
function Methods.GetState(self: any, name: string): any
	local live = liveOf(self)
	stateNamed(live, name, 3)
	local reader = live.readState
	if reader == nil then
		return nil
	end
	return reader(name)
end

--[=[
	@method GetStateChangedSignal
	@within ApexTrack

	Returns a signal that fires with (new, old, payload) when the state changes. It is checked
	once a frame, so a change shorter than a frame can go unannounced.

	@param name string
	@return Signal
	@error string -- the animation has no state track with that name
]=]
function Methods.GetStateChangedSignal(self: any, name: string): Signal.Signal
	local live = liveOf(self)
	stateNamed(live, name, 3)
	return ApexTrack.stateSignal(live, name)
end

--[=[
	@method GetSpanSignal
	@within ApexTrack

	Returns a signal for a span state. It fires (true, payload) as a span opens and
	(false, payload, reason) as it closes, with reason "ended" or "interrupted".

	@param name string
	@return Signal
	@error string -- the state is not a span
]=]
function Methods.GetSpanSignal(self: any, name: string): Signal.Signal
	local live = liveOf(self)
	local state = stateNamed(live, name, 3)
	if state.kind ~= "Span" then
		error(
			`ApexEngine: '{name}' is a {string.lower(state.kind)} state, not a span - use GetStateChangedSignal("{name}")`,
			2
		)
	end
	return ApexTrack.spanSignal(live, name)
end

local HandleMeta = {}

--[=[
	@prop AnimationTrack AnimationTrack
	@within ApexTrack
	@readonly

	The Roblox track underneath.
]=]

--[=[
	@prop Stopped Signal
	@within ApexTrack
	@readonly

	Fires with "Completed" or "Interrupted" as a play stops.
]=]

--[=[
	@prop Ended Signal
	@within ApexTrack
	@readonly

	Fires once a play's fade-out is over.
]=]

--[=[
	@prop DidLoop Signal
	@within ApexTrack
	@readonly

	Fires on each lap of a looping track.
]=]
function HandleMeta.__index(handle: any, key: any): any
	local method = (Methods :: any)[key]
	if method ~= nil then
		return method
	end
	local live = liveOf(handle)
	if key == "AnimationTrack" then
		return live.track
	elseif key == "Stopped" then
		return live.stopped
	elseif key == "Ended" then
		return live.ended
	elseif key == "DidLoop" then
		return live.didLoop
	elseif MIRRORED[key] then
		return live.track[key]
	end
	error(`ApexEngine: '{tostring(key)}' is not a member of an ApexEngine track`, 2)
end

function HandleMeta.__newindex(handle: any, key: any, value: any)
	local live = liveOf(handle)
	if WRITABLE[key] then
		live.track[key] = value
		return
	end
	error(`ApexEngine: '{tostring(key)}' cannot be set on an ApexEngine track`, 2)
end

function HandleMeta.__tostring(handle: any): string
	local live = owners[handle]
	return if live ~= nil then `ApexTrack({live.label})` else "ApexTrack"
end

function ApexTrack.handle(live: Live): any
	local handle = live.handle
	if handle == nil then
		handle = setmetatable({}, HandleMeta)
		owners[handle] = live
		live.handle = handle
	end
	return handle
end

function ApexTrack.liveOf(handle: any): Live?
	return owners[handle]
end

return ApexTrack
