--!strict

local ApexTrack = require(script.Parent.ApexTrack)
local Types = require(script.Parent.Parent.Core.Types)

local Frame = {}

Frame.EVENT = "PreSimulation"

function Frame.event(runService: any): any
	return runService[Frame.EVENT]
end

export type Stage = "root" | "spaces" | "props" | "states" | "releases"

Frame.STAGES = table.freeze({ "root", "spaces", "props", "states", "releases" })

local STAGE_INDEX: { [string]: number } = {}
for index, stage in Frame.STAGES do
	STAGE_INDEX[stage] = index
end

export type Rig = {
	model: any,
	lives: { ApexTrack.Live },
	holds: { [string]: boolean },
	data: { [string]: any },
	visible: boolean,
	pending: number,
	waited: number,
	owed: boolean,
}

export type Extension = {
	name: string,
	stage: Stage,
	cosmetic: boolean?,
	began: ((live: ApexTrack.Live) -> ())?,
	stopped: ((
		live: ApexTrack.Live,
		reason: ApexTrack.EndReason,
		policy: Types.InterruptPolicy
	) -> ())?,
	ended: ((live: ApexTrack.Live) -> ())?,
	step: ((rig: Rig, dt: number, catchUp: boolean) -> ())?,
	reads: ((rig: Rig) -> { any }?)?,
	places: ((rig: Rig) -> { Vector3 }?)?,
	released: ((rig: Rig) -> ())?,
}

export type Settings = {
	maxDistance: number,
	radius: number,
	budget: number,
	maxWait: number,
}

Frame.DEFAULT_SETTINGS = table.freeze({
	maxDistance = 300,
	radius = 8,
	budget = 64,
	maxWait = 6,
}) :: Settings

export type View = {
	cframe: CFrame,
	tanX: number,
	tanY: number,
}

export type Candidate = {
	key: any,
	cost: number,
	waited: number,
	owed: boolean,
	forced: boolean,
}

export type Config = {
	extensions: { Extension }?,
	settings: { [string]: number }?,
	clock: () -> number,
	warn: (message: string) -> (),
	locate: ((model: any) -> Vector3?)?,
	focus: ((model: any) -> boolean)?,
	alive: ((model: any) -> boolean)?,
}

export type Frame = {
	extensions: { Extension },
	settings: Settings,
	rigs: { Rig },
	byModel: { [any]: Rig },
	frames: number,
	clock: () -> number,
	warn: (message: string) -> (),
	locate: (model: any) -> Vector3?,
	focus: (model: any) -> boolean,
	alive: (model: any) -> boolean,
	failed: { [string]: boolean },
	hooks: ApexTrack.Hooks,
}

function Frame.order(extensions: { Extension }): { Extension }
	local indexed: { { extension: Extension, at: number } } = {}
	for at, extension in extensions do
		if STAGE_INDEX[extension.stage] == nil then
			error(
				`ApexEngine: the extension '{tostring(extension.name)}' names a stage that does not exist, '{tostring(
					extension.stage
				)}'`,
				2
			)
		end
		table.insert(indexed, { extension = extension, at = at })
	end
	table.sort(indexed, function(a, b): boolean
		local sa, sb = STAGE_INDEX[a.extension.stage], STAGE_INDEX[b.extension.stage]
		if sa ~= sb then
			return sa < sb
		end
		return a.at < b.at
	end)
	local out: { Extension } = {}
	for _, item in indexed do
		table.insert(out, item.extension)
	end
	return out
end

function Frame.visible(view: View?, position: Vector3?, settings: Settings): boolean
	if view == nil or position == nil then
		return true
	end
	local offset = view.cframe:PointToObjectSpace(position)
	local distance = offset.Magnitude
	local radius = settings.radius
	if distance - radius > settings.maxDistance then
		return false
	end
	if distance <= radius then
		return true
	end
	local depth = -offset.Z
	if depth + radius < 0 then
		return false
	end
	local slackX = radius * math.sqrt(1 + view.tanX * view.tanX)
	local slackY = radius * math.sqrt(1 + view.tanY * view.tanY)
	return math.abs(offset.X) <= depth * view.tanX + slackX
		and math.abs(offset.Y) <= depth * view.tanY + slackY
end

function Frame.schedule(
	candidates: { Candidate },
	budget: number,
	maxWait: number
): { [any]: boolean }
	local order: { number } = {}
	for index in candidates do
		table.insert(order, index)
	end
	local function must(candidate: Candidate): boolean
		return candidate.forced or candidate.waited >= maxWait
	end
	table.sort(order, function(a: number, b: number): boolean
		local ca, cb = candidates[a], candidates[b]
		local ma, mb = must(ca), must(cb)
		if ma ~= mb then
			return ma
		end
		if ca.owed ~= cb.owed then
			return ca.owed
		end
		if ca.waited ~= cb.waited then
			return ca.waited > cb.waited
		end
		return a < b
	end)
	local chosen: { [any]: boolean } = {}
	local spent = 0
	local any = false
	for _, index in order do
		local candidate = candidates[index]
		if must(candidate) or not any or spent + candidate.cost <= budget then
			chosen[candidate.key] = true
			spent += candidate.cost
			any = true
		end
	end
	return chosen
end

function Frame.view(camera: any): View?
	if camera == nil then
		return nil
	end
	local ok, view = pcall(function(): View
		local tanY = math.tan(math.rad(camera.FieldOfView) * 0.5)
		local size = camera.ViewportSize
		local aspect = if size.Y > 0 then size.X / size.Y else 1
		return { cframe = camera.CFrame, tanX = tanY * aspect, tanY = tanY }
	end)
	return if ok then view else nil
end

function Frame.sequence<T>(items: { T }, reads: (item: T) -> { T }?): { T }
	local inPass: { [any]: boolean } = {}
	for _, item in items do
		inPass[item] = true
	end
	local out: { T } = {}
	local met: { [any]: boolean } = {}
	local function place(item: T)
		if met[item] then
			return
		end
		met[item] = true
		for _, other in reads(item) or {} do
			if inPass[other] then
				place(other)
			end
		end
		table.insert(out, item)
	end
	for _, item in items do
		place(item)
	end
	return out
end

function Frame.costOf(rig: Rig): number
	local cost = #rig.lives
	for _ in rig.holds do
		cost += 1
	end
	return math.max(cost, 1)
end

local function defaultLocate(model: any): Vector3?
	local ok, position = pcall(function()
		return model:GetPivot().Position
	end)
	return if ok then position else nil
end

local function defaultAlive(model: any): boolean
	local ok, parent = pcall(function()
		return model.Parent
	end)
	return ok and parent ~= nil
end

local function report(frame: Frame, extension: Extension, what: string, problem: any)
	local key = `{extension.name}:{what}`
	if not frame.failed[key] then
		frame.failed[key] = true
		frame.warn(
			`ApexEngine: the {extension.name} part of the engine failed ({what}) and is skipped where it fails: {tostring(
				problem
			)}`
		)
	end
end

local function call(frame: Frame, extension: Extension, what: string, fn: any, ...: any)
	local ok, problem = pcall(fn, ...)
	if not ok then
		report(frame, extension, what, problem)
	end
end

local function seenElsewhere(frame: Frame, rig: Rig, view: View, settings: Settings): boolean
	for _, extension in frame.extensions do
		local placesFn = extension.places
		if placesFn == nil then
			continue
		end
		local ok, points = pcall(placesFn, rig)
		if not ok then
			report(frame, extension, "places", points)
			continue
		end
		for _, point in points or {} do
			if Frame.visible(view, point, settings) then
				return true
			end
		end
	end
	return false
end

function Frame.new(config: Config): Frame
	local settings = table.clone(Frame.DEFAULT_SETTINGS) :: any
	for key, value in config.settings or {} do
		settings[key] = value
	end
	local frame: Frame
	frame = {
		extensions = Frame.order(config.extensions or {}),
		settings = settings,
		rigs = {},
		byModel = {},
		frames = 0,
		clock = config.clock,
		warn = config.warn,
		locate = config.locate or defaultLocate,
		focus = config.focus or function()
			return false
		end,
		alive = config.alive or defaultAlive,
		failed = {},
		hooks = {
			began = function(live: ApexTrack.Live)
				for _, extension in frame.extensions do
					if extension.began then
						call(frame, extension, "began", extension.began, live)
					end
				end
			end,
			stopped = function(
				live: ApexTrack.Live,
				reason: ApexTrack.EndReason,
				policy: Types.InterruptPolicy
			)
				for _, extension in frame.extensions do
					if extension.stopped then
						call(frame, extension, "stopped", extension.stopped, live, reason, policy)
					end
				end
			end,
			ended = function(live: ApexTrack.Live)
				for _, extension in frame.extensions do
					if extension.ended then
						call(frame, extension, "ended", extension.ended, live)
					end
				end
			end,
		},
	}
	return frame
end

function Frame.hooks(frame: Frame): ApexTrack.Hooks
	return frame.hooks
end

local function rigFor(frame: Frame, model: any): Rig
	local rig = frame.byModel[model]
	if rig == nil then
		rig = {
			model = model,
			lives = {},
			holds = {},
			data = {},
			visible = true,
			pending = 0,
			waited = 0,
			owed = false,
		}
		frame.byModel[model] = rig
		table.insert(frame.rigs, rig :: Rig)
	end
	return rig :: Rig
end

function Frame.rigOf(frame: Frame, model: any): Rig?
	return frame.byModel[model]
end

function Frame.add(frame: Frame, live: ApexTrack.Live)
	local rig = rigFor(frame, live.rig or live.animator)
	if table.find(rig.lives, live) == nil then
		table.insert(rig.lives, live)
	end
end

function Frame.hold(frame: Frame, model: any, name: string, on: boolean)
	if on then
		rigFor(frame, model).holds[name] = true
		return
	end
	local rig = frame.byModel[model]
	if rig ~= nil then
		rig.holds[name] = nil
	end
end

function Frame.idle(frame: Frame): boolean
	return #frame.rigs == 0
end

local function release(frame: Frame, rig: Rig)
	frame.byModel[rig.model] = nil
	local index = table.find(frame.rigs, rig)
	if index ~= nil then
		table.remove(frame.rigs, index)
	end
	for _, extension in frame.extensions do
		if extension.released then
			call(frame, extension, "released", extension.released, rig)
		end
	end
end

function Frame.step(frame: Frame, dt: number, view: View?)
	frame.frames += 1
	local now = frame.clock()

	for _, rig in table.clone(frame.rigs) do
		if not frame.alive(rig.model) then
			for _, live in rig.lives do
				ApexTrack.abandon(live, now)
			end
			table.clear(rig.lives)
			table.clear(rig.holds)
		else
			local index = 1
			while index <= #rig.lives do
				if ApexTrack.poll(rig.lives[index], now) then
					index += 1
				else
					table.remove(rig.lives, index)
				end
			end
		end
		if #rig.lives == 0 and next(rig.holds) == nil then
			release(frame, rig)
		end
	end
	if #frame.rigs == 0 then
		return
	end

	local settings = frame.settings
	local candidates: { Candidate } = {}
	for _, rig in frame.rigs do
		rig.pending += dt
		local forced = frame.focus(rig.model)
		local seen = forced
			or Frame.visible(view, frame.locate(rig.model), settings)
			or seenElsewhere(frame, rig, view :: View, settings)
		rig.visible = seen
		if seen then
			table.insert(candidates, {
				key = rig,
				cost = Frame.costOf(rig),
				waited = rig.waited,
				owed = rig.owed,
				forced = forced,
			})
		else
			rig.owed = true
		end
	end
	local chosen = Frame.schedule(candidates, settings.budget, settings.maxWait)

	local rigs = table.clone(frame.rigs)
	for _, extension in frame.extensions do
		local stepFn = extension.step
		if stepFn == nil then
			continue
		end
		local order = rigs
		local readsFn = extension.reads
		if readsFn ~= nil then
			local reading: { [Rig]: { Rig } } = {}
			local any = false
			for _, rig in rigs do
				if extension.cosmetic and not chosen[rig] then
					continue
				end
				local ok, models = pcall(readsFn, rig)
				if not ok then
					report(frame, extension, "reads", models)
					continue
				end
				for _, model in models or {} do
					local other = frame.byModel[model]
					if other ~= nil and other ~= rig then
						local list = reading[rig]
						if list == nil then
							list = {}
							reading[rig] = list
						end
						table.insert(list, other)
						any = true
					end
				end
			end
			if any then
				order = Frame.sequence(rigs, function(rig: Rig): { Rig }?
					return reading[rig]
				end)
			end
		end
		for _, rig in order do
			if extension.cosmetic then
				if chosen[rig] then
					call(frame, extension, "step", stepFn, rig, rig.pending, rig.owed)
				end
			else
				call(frame, extension, "step", stepFn, rig, dt, false)
			end
		end
	end
	for _, rig in rigs do
		if chosen[rig] then
			rig.pending = 0
			rig.waited = 0
			rig.owed = false
		elseif rig.visible then
			rig.waited += 1
		end
	end
end

return Frame
