local ApexTrack = require(script.Parent.ApexTrack)
local Frame = require(script.Parent.Frame)
local Movement = require(script.Parent.Movement)
local Props = require(script.Parent.Props)
local Joint = require(script.Parent.Parent.Core.Joint)
local Path = require(script.Parent.Parent.Core.Path)
local Sidecar = require(script.Parent.Parent.Core.Sidecar)
local Types = require(script.Parent.Parent.Core.Types)
local Pose = require(script.Parent.Parent.Shared.Pose)

local Pivots = {}

Pivots.NAME = "pivots"

type Rest = {
	rest: CFrame,
	written: CFrame?,
}

type Slot = {
	base: CFrame,
	owners: { Item },
}

type Item = {
	address: string,
	path: string,
	track: Types.JointTrack,
	instance: any,
	rootPart: any,
	outside: boolean,
	known: Rest,
	slot: Slot,
	live: ApexTrack.Live,
	play: Play,
}

type Play = {
	active: boolean,
	items: { Item },
	options: { presets: { [string]: Types.EasingPreset }?, fps: number? },
	carry: CFrame?,
}

local rests: { [any]: Rest } = setmetatable({}, { __mode = "k" }) :: any
local anchors: { [any]: Rest } = setmetatable({}, { __mode = "k" }) :: any
local slots: { [any]: Slot } = setmetatable({}, { __mode = "k" }) :: any

local NEAR = 1e-3

local function near(a: CFrame, b: CFrame): boolean
	local x = { a:GetComponents() }
	local y = { b:GetComponents() }
	for index = 1, 12 do
		if math.abs(x[index] - y[index]) > NEAR then
			return false
		end
	end
	return true
end

local function rootCFrame(rootPart: any): CFrame?
	local ok, cframe = pcall(function()
		return rootPart.CFrame
	end)
	return if ok and typeof(cframe) == "CFrame" then cframe else nil
end

local function put(item: Item, world: CFrame)
	if pcall(Joint.pivotTo, item.instance, world) then
		item.known.written = world
	end
end

local function playOf(live: ApexTrack.Live): Play?
	return live.data[Pivots.NAME]
end

local function sortedKeys(map: { [string]: any }): { string }
	local out: { string } = {}
	for key in map do
		table.insert(out, key)
	end
	table.sort(out)
	return out
end

local function worldAt(item: Item, t: number, play: Play): CFrame?
	local pose = Pose.evaluate(item.track, t, play.options :: any)
	if item.outside then
		return item.known.rest * pose
	end
	local root = rootCFrame(item.rootPart)
	if root == nil then
		return nil
	end
	local world = root * item.known.rest * pose
	local carry = play.carry
	return if carry ~= nil then carry:Inverse() * world else world
end

local function claim(
	address: string,
	pivot: Sidecar.Pivot,
	instance: any,
	rootPart: any,
	live: ApexTrack.Live,
	play: Play
): Item?
	local outside = Path.inWorkspace(pivot.path) ~= nil
	local ok, world = pcall(Joint.pivotOf, instance)
	local root = if outside then CFrame.identity else rootCFrame(rootPart)
	if not ok or root == nil then
		return nil
	end
	local kept = if outside then anchors else rests
	local known = kept[instance]
	if known == nil or known.written == nil or not near(world, known.written :: CFrame) then
		known = { rest = root:ToObjectSpace(world), written = nil }
		kept[instance] = known
	end
	local slot = slots[instance]
	if slot == nil then
		slot = { base = world, owners = {} }
		slots[instance] = slot
	end
	local item: Item = {
		address = address,
		path = pivot.path,
		track = { rotationMode = pivot.rotationMode, channels = pivot.channels },
		instance = instance,
		rootPart = rootPart,
		outside = outside,
		known = known :: Rest,
		slot = slot :: Slot,
		live = live,
		play = play,
	}
	table.insert((slot :: Slot).owners, item)
	return item
end

local function release(item: Item, outcome: ApexTrack.Outcome, final: CFrame?)
	local slot = item.slot
	local owners = slot.owners
	local at = table.find(owners, item)
	if at == nil then
		return
	end
	local writer = at == #owners
	table.remove(owners, at)
	local alone = #owners == 0
	if outcome == "Final" then
		if writer and final ~= nil then
			put(item, final)
		end
	elseif outcome == "Revert" and alone then
		put(item, slot.base)
	end
	if alone and slots[item.instance] == slot then
		slots[item.instance] = nil
	end
end

function Pivots.began(live: ApexTrack.Live)
	local pivots = live.sidecar.pivots
	local root = live.rig
	if pivots == nil or root == nil or next(pivots) == nil or Props.onServer() then
		live.data[Pivots.NAME] = nil
		return
	end
	local rootPart = Movement.rootPartOf(root)
	local play: Play = {
		active = true,
		items = {},
		options = { presets = live.sidecar.presets, fps = live.sidecar.fps },
		carry = nil,
	}
	for _, address in sortedKeys(pivots) do
		local pivot = pivots[address]
		if rootPart == nil and Path.inWorkspace(pivot.path) == nil then
			continue
		end
		local instance = Props.find(root, pivot.path)
		if instance == nil then
			continue
		end
		local ok, part = pcall(Joint.movedPartOf, instance)
		if not ok or part == nil then
			live.warnOnce(
				`pivots:class:{live.label}:{pivot.path}`,
				`ApexEngine: {live.label} moves {pivot.path}, which is not a part or a model with a PrimaryPart here, so it stays where it is.`
			)
			continue
		end
		local item = claim(address, pivot, instance, rootPart, live, play)
		if item ~= nil then
			table.insert(play.items, item)
		end
	end
	live.data[Pivots.NAME] = play
end

function Pivots.step(rig: Frame.Rig, _dt: number, _catchUp: boolean)
	for _, live in rig.lives do
		local play = playOf(live)
		if play == nil or not play.active or live.phase ~= "Playing" then
			continue
		end
		play.carry = Movement.carryOf(live)
		for _, item in play.items do
			local slot = item.slot
			if slot.owners[#slot.owners] == item then
				local world = worldAt(item, live.time, play)
				if world ~= nil then
					put(item, world)
				end
			end
		end
	end
end

function Pivots.stopped(
	live: ApexTrack.Live,
	reason: ApexTrack.EndReason,
	policy: Types.InterruptPolicy
)
	local play = playOf(live)
	if play == nil or not play.active then
		return
	end
	play.active = false
	local finish = if live.speed < 0 then 0 else live.sidecar.length
	local outcome = ApexTrack.outcome(reason, policy, nil)
	for _, item in play.items do
		local final = if outcome == "Final" then worldAt(item, finish, play) else nil
		release(item, outcome, final)
	end
end

function Pivots.moves(rig: Frame.Rig, address: string): boolean
	for _, live in rig.lives do
		local pivots = live.sidecar.pivots
		if pivots ~= nil and pivots[address] ~= nil then
			return true
		end
	end
	return false
end

local function standing(writer: Item): CFrame?
	local ok, pivot, part = pcall(function()
		return Joint.pivotOf(writer.instance), Joint.movedPartOf(writer.instance)
	end)
	if not ok or part == nil then
		return nil
	end
	local offset = pivot:Inverse() * part.CFrame
	local owner = writer.play
	if owner.active and writer.live.phase == "Playing" then
		owner.carry = Movement.carryOf(writer.live)
		local world = worldAt(writer, writer.live.time, owner)
		if world ~= nil then
			return world * offset
		end
	end
	return pivot * offset
end

function Pivots.partWorld(rig: Frame.Rig, address: string): CFrame?
	for _, live in rig.lives do
		local play = playOf(live)
		if play == nil or not play.active then
			continue
		end
		for _, item in play.items do
			if item.address == address then
				return standing(item.slot.owners[#item.slot.owners] or item)
			end
		end
	end
	return nil
end

local units: { [any]: { [string]: any } } = setmetatable({}, { __mode = "k" }) :: any

function Pivots.unitOf(model: any, address: string): any?
	local known = units[model]
	local kept = if known ~= nil then known[address] else nil
	local ok, found = pcall(function()
		if kept ~= nil and kept.Name == address and kept:IsDescendantOf(model) then
			return kept
		end
		local named = model:FindFirstChild(address, true)
		if named == nil or Joint.movedPartOf(named) ~= nil then
			return named
		end
		for _, descendant in model:GetDescendants() do
			if descendant.Name == address and Joint.movedPartOf(descendant) ~= nil then
				return descendant
			end
		end
		return nil
	end)
	local unit = if ok then found else nil
	if unit ~= nil then
		units[model] = known or {}
		units[model][address] = unit
	elseif known ~= nil then
		known[address] = nil
	end
	return unit
end

function Pivots.unitWorld(unit: any): CFrame?
	local slot = slots[unit]
	local writer = if slot ~= nil then slot.owners[#slot.owners] else nil
	if writer ~= nil then
		return standing(writer)
	end
	local ok, part = pcall(Joint.movedPartOf, unit)
	return if ok and part ~= nil then part.CFrame else nil
end

function Pivots.places(rig: Frame.Rig): { Vector3 }?
	local out: { Vector3 }? = nil
	for _, live in rig.lives do
		local play = playOf(live)
		if play == nil or not play.active then
			continue
		end
		for _, item in play.items do
			local ok, position = pcall(function()
				return (Joint.movedPartOf(item.instance) :: BasePart).CFrame.Position
			end)
			if ok and typeof(position) == "Vector3" then
				out = out or {}
				table.insert(out :: { Vector3 }, position)
			end
		end
	end
	return out
end

Pivots.extension = {
	name = Pivots.NAME,
	stage = "props",
	cosmetic = false,
	began = Pivots.began,
	stopped = Pivots.stopped,
	step = Pivots.step,
	places = Pivots.places,
} :: Frame.Extension

return Pivots
