--!strict

local ApexTrack = require(script.Parent.ApexTrack)
local Frame = require(script.Parent.Frame)
local HeadSwap = require(script.Parent.HeadSwap)
local Interpolate = require(script.Parent.Parent.Core.Interpolate)
local Path = require(script.Parent.Parent.Core.Path)
local PropRegistry = require(script.Parent.Parent.Core.PropRegistry)
local Sidecar = require(script.Parent.Parent.Core.Sidecar)
local Types = require(script.Parent.Parent.Core.Types)
local Interp = require(script.Parent.Parent.Shared.Interp)
local StateEval = require(script.Parent.Parent.Shared.StateEval)

local Props = {}

Props.NAME = "props"

export type Compiled = {
	class: string,
	property: string,
	type: Types.PropValueType,
	track: Types.PropTrack,
	values: { any },
	channel: any?,
	fallback: Types.Interp,
	fades: boolean,
}

export type SampleOptions = {
	presets: { [string]: Types.EasingPreset }?,
	fps: number?,
}

type Slot = {
	base: any,
	owners: { Item },
	last: any,
	writable: any,
}

type Item = {
	path: string,
	property: string,
	compiled: Compiled,
	instance: any,
	slot: Slot,
	scaled: boolean,
	head: boolean,
	twins: { any }?,
	noFade: boolean?,
	fading: boolean?,
}

type Sound = {
	path: string,
	cues: { Types.SoundCue },
	instance: any,
	started: boolean,
}

type Play = {
	active: boolean,
	time: number?,
	speed: number,
	at: number,
	items: { Item },
	sounds: { Sound },
	options: SampleOptions,
	made: { any },
}

local slots: { [any]: { [string]: Slot } } = setmetatable({}, { __mode = "k" }) :: any
local owned: { [any]: { users: number, keep: boolean } } = setmetatable({}, { __mode = "k" }) :: any

Props.FADE_NAME = "ApexFade"

local COPIED =
	{ "Face", "Color3", "ZIndex", "StudsPerTileU", "StudsPerTileV", "OffsetStudsU", "OffsetStudsV" }

function Props.newInstance(className: string): any
	return Instance.new(className)
end

function Props.lighting(): any?
	local ok, lighting = pcall(function()
		return game:GetService("Lighting")
	end)
	return if ok then lighting else nil
end

function Props.workspace(): any?
	local ok, workspace = pcall(function()
		return game:GetService("Workspace")
	end)
	return if ok then workspace else nil
end

function Props.editing(): boolean
	local ok, editing = pcall(function()
		return not game:GetService("RunService"):IsRunning()
	end)
	return ok and editing == true
end

function Props.showsLook(live: ApexTrack.Live): boolean
	if live.showsLook == true or Props.editing() then
		return true
	end
	local ok, mine = pcall(function()
		local player = game:GetService("Players").LocalPlayer
		return player ~= nil and player.Character == live.rig
	end)
	return ok and mine == true
end

local UNIT: Interp.Channel = { keys = { { t = 0, v = 0 }, { t = 1, v = 1 } } }
Interp.recalcHandles(UNIT.keys)

function Props.compile(class: string, property: string, track: Types.PropTrack): Compiled
	local valueType = track.type
	local enumType = PropRegistry.enumOf(class, property)
	local values: { any } = {}
	local fades = false
	for index, key in track.keys do
		values[index] = PropRegistry.decode(valueType, key.v, enumType)
		fades = fades or (key.fade ~= nil and key.fade > 0)
	end
	return {
		class = class,
		property = property,
		type = valueType,
		track = track,
		values = values,
		channel = if valueType == "number"
			then { keys = track.keys, interp = track.interp }
			else nil,
		fallback = track.interp or (if valueType == "number" then "Bezier" else "Linear"),
		fades = fades and property == "Texture" and valueType == "string",
	}
end

function Props.fadeAt(compiled: Compiled, t: number): (any?, any?, number?)
	if not compiled.fades then
		return nil, nil, nil
	end
	local keys = compiled.track.keys
	for index = #keys, 2, -1 do
		local key = keys[index]
		if key.t <= t then
			local fade = key.fade
			if fade == nil or fade <= 0 or t >= key.t + fade then
				return nil, nil, nil
			end
			return compiled.values[index - 1], compiled.values[index], (t - key.t) / fade
		end
	end
	return nil, nil, nil
end

local function fraction(
	a: Types.PropKey,
	b: Types.PropKey,
	t: number,
	fallback: Types.Interp,
	presets: { [string]: Types.EasingPreset }?
): number
	local duration = b.t - a.t
	if duration <= 0 then
		return 1
	end
	local x = (t - a.t) / duration
	if a.preset ~= nil and presets ~= nil then
		local preset = presets[a.preset]
		if preset ~= nil and preset.points ~= nil and #preset.points >= 2 then
			return math.clamp(Interp.presetAt(preset :: any, x), 0, 1)
		end
	end
	local mode = a.interp or fallback
	if mode == "Constant" then
		return 0
	elseif mode == "Linear" then
		return x
	elseif mode == "Bezier" then
		return math.clamp(Interp.evaluate(UNIT, x), 0, 1)
	end
	return math.clamp(Interp.ease(mode, a.easing, t - a.t, 0, 1, duration, a.params), 0, 1)
end

function Props.sample(compiled: Compiled, t: number, options: SampleOptions?): any
	local keys = compiled.track.keys
	local count = #keys
	if count == 0 then
		return nil
	end
	local values = compiled.values
	if t <= keys[1].t then
		return values[1]
	end
	if t >= keys[count].t then
		return values[count]
	end
	if compiled.channel ~= nil then
		return Interp.evaluate(compiled.channel, t, options :: any)
	end
	local lo, hi = 1, count
	while hi - lo > 1 do
		local mid = (lo + hi) // 2
		if keys[mid].t <= t then
			lo = mid
		else
			hi = mid
		end
	end
	local a = values[lo]
	if PropRegistry.stepped(compiled.type) then
		return a
	end
	local b = values[lo + 1]
	if a == nil or b == nil then
		return a
	end
	local presets = if options ~= nil then options.presets else nil
	local alpha = fraction(keys[lo], keys[lo + 1], t, compiled.fallback, presets)
	if alpha <= 0 then
		return a
	elseif alpha >= 1 then
		return b
	end
	return Interpolate.lerp(compiled.type, a, b, alpha)
end

function Props.resolve(root: any, path: string): any?
	local ok, found = pcall(function()
		local node = root
		for _, name in Path.split(path) do
			if node == nil then
				return nil
			end
			node = node:FindFirstChild(name)
		end
		return node
	end)
	return if ok then found else nil
end

function Props.find(root: any, path: string): any?
	local below = Path.inWorkspace(path)
	if below == nil then
		return Props.resolve(root, path)
	end
	local workspace = Props.workspace()
	return if workspace ~= nil then Props.resolve(workspace, below) else nil
end

local function index(instance: any, property: string): any
	return instance[property]
end

local function assign(instance: any, property: string, value: any)
	instance[property] = value
end

local MIN_SCALE = 0.01

local function getScale(instance: any, _property: string): any
	return instance:GetScale()
end

local function scaleTo(instance: any, _property: string, value: any)
	instance:ScaleTo(math.max(value, MIN_SCALE))
end

local function shownHead(instance: any, _property: string): any
	return HeadSwap.shown(instance)
end

local function read(item: Item): (boolean, any)
	if item.head then
		return true, HeadSwap.shown(item.instance)
	end
	return pcall(if item.scaled then getScale else index, item.instance, item.property)
end

local function put(item: Item, value: any): boolean
	if item.head then
		return HeadSwap.show(item.instance, value)
	end
	return (pcall(if item.scaled then scaleTo else assign, item.instance, item.property, value))
end

local function isA(instance: any, class: string): boolean
	return instance:IsA(class)
end

local function isFileMesh(instance: any): boolean
	local ok, yes = pcall(function()
		return instance:IsA("SpecialMesh") and instance.MeshType == Enum.MeshType.FileMesh
	end)
	return ok and yes == true
end

local function nameOf(instance: any): string
	local ok, name = pcall(index, instance, "Name")
	return if ok then tostring(name) else "the rig"
end

local function write(live: ApexTrack.Live, item: Item, value: any)
	local slot = item.slot
	if item.head then
		if not HeadSwap.show(item.instance, value) then
			live.warnOnce(
				`props:head:{live.label}:{item.path}:{value}`,
				`ApexEngine: {live.label} swaps {item.path} to the head '{value}', but {item.path} has no MeshPart named that in its {HeadSwap.FOLDER} folder, so it keeps the head it shows.`
			)
		end
		slot.last = value
		return
	end
	local kind = typeof(value)
	local state = slot.writable
	if state == false then
		return
	elseif state == kind then
		if item.scaled then
			scaleTo(item.instance, item.property, value)
		else
			item.instance[item.property] = value
		end
	else
		if not put(item, value) then
			slot.writable = false
			live.warnOnce(
				`props:write:{live.label}:{item.path}:{item.property}`,
				`ApexEngine: {live.label} cannot set {item.path}'s {item.property}, so that prop track is skipped.`
			)
			return
		end
		slot.writable = kind
	end
	slot.last = value
end

local function destroy(instance: any)
	pcall(function()
		instance:Destroy()
	end)
end

local function makeTwins(item: Item): { any }?
	local out = {}
	local ok = pcall(function()
		local main = item.instance
		for _ = 1, 2 do
			local twin = Props.newInstance(main.ClassName)
			twin.Name = Props.FADE_NAME
			twin.Archivable = false
			for _, property in COPIED do
				pcall(function()
					twin[property] = main[property]
				end)
			end
			twin.Transparency = 1
			table.insert(out, twin)
			twin.Parent = main.Parent
		end
	end)
	if ok then
		return out
	end
	for _, twin in out do
		destroy(twin)
	end
	return nil
end

local function hideTwins(item: Item)
	if not item.fading then
		return
	end
	item.fading = false
	for _, twin in item.twins or {} do
		pcall(assign, twin, "Transparency", 1)
	end
end

local function dropTwins(item: Item)
	for _, twin in item.twins or {} do
		destroy(twin)
	end
	item.twins = nil
end

local function crossfade(
	live: ApexTrack.Live,
	item: Item,
	from: any,
	to: any,
	share: number
): boolean
	if item.noFade then
		return false
	end
	local twins = item.twins or makeTwins(item)
	if twins == nil then
		item.noFade = true
		return false
	end
	item.twins = twins
	item.fading = true
	local ok, clear = pcall(index, item.instance, "Transparency")
	local shown = 1 - (if ok and type(clear) == "number" then clear else 0)
	pcall(function()
		twins[1].Texture = from
		twins[1].Transparency = 1 - shown * (1 - share)
		twins[2].Texture = to
		twins[2].Transparency = 1 - shown * share
	end)
	if item.slot.last ~= "" then
		write(live, item, "")
	end
	return true
end

local function claim(path: string, compiled: Compiled, instance: any): Item?
	local property = compiled.property
	local scaled = compiled.class == "Model" and property == "Scale"
	local head = compiled.class == "BasePart" and property == HeadSwap.PROPERTY
	local row = slots[instance]
	if row == nil then
		row = {}
		slots[instance] = row
	end
	local slot = (row :: { [string]: Slot })[property]
	if slot == nil then
		local ok, value =
			pcall(if head then shownHead elseif scaled then getScale else index, instance, property)
		if not ok then
			return nil
		end
		slot = { base = value, owners = {}, last = value, writable = nil }
		(row :: { [string]: Slot })[property] = slot :: Slot
	end
	local item: Item = {
		path = path,
		property = property,
		compiled = compiled,
		instance = instance,
		slot = slot :: Slot,
		scaled = scaled,
		head = head,
	}
	table.insert((slot :: Slot).owners, item)
	return item
end

local function release(item: Item, outcome: ApexTrack.Outcome, final: any)
	dropTwins(item)
	local slot = item.slot
	local owners = slot.owners
	local at = table.find(owners, item)
	if at == nil then
		return
	end
	local writer = at == #owners
	table.remove(owners, at)
	local alone = #owners == 0
	if outcome == "Final" then
		if final ~= nil then
			if writer then
				put(item, final)
			end
			slot.base = final
		end
	elseif outcome == "Revert" then
		if alone then
			put(item, slot.base)
		end
	elseif writer and not alone then
		local ok, value = read(item)
		if ok then
			slot.base = value
		end
	end
	if alone then
		local row = slots[item.instance]
		if row ~= nil and row[item.property] == slot then
			row[item.property] = nil
			if next(row) == nil then
				slots[item.instance] = nil
			end
		end
	elseif writer then
		slot.last = nil
	end
end

local function playSound(sound: any)
	sound:Play()
end

local function stopSound(sound: any)
	sound:Stop()
end

local function cue(sound: Sound, action: Types.SoundAction)
	if action == "Play" then
		if pcall(playSound, sound.instance) then
			sound.started = true
		end
	else
		pcall(stopSound, sound.instance)
		sound.started = false
	end
end

local function sweepCues(play: Play, from: number, to: number)
	for _, sound in play.sounds do
		for _, at in StateEval.crossed(sound.cues, from, to) do
			cue(sound, sound.cues[at].action)
		end
	end
end

local function stopsLater(cues: { Types.SoundCue }, time: number?): boolean
	local after = time or -math.huge
	for _, soundCue in cues do
		if soundCue.t > after and soundCue.action == "Stop" then
			return true
		end
	end
	return false
end

export type Hold = Item

function Props.hold(
	path: string,
	class: string,
	property: string,
	valueType: Types.PropValueType,
	instance: any
): Hold?
	return claim(path, Props.compile(class, property, { type = valueType, keys = {} }), instance)
end

function Props.set(live: ApexTrack.Live, hold: Hold, value: any)
	local slot = hold.slot
	if slot.owners[#slot.owners] == hold and value ~= slot.last then
		write(live, hold, value)
	end
end

function Props.letGo(hold: Hold, outcome: ApexTrack.Outcome, final: any)
	release(hold, outcome, final)
end

function Props.onServer(): boolean
	local ok, server = pcall(function()
		local runService = game:GetService("RunService")
		return runService:IsServer() and not runService:IsClient()
	end)
	return ok and server == true
end

local function playOf(live: ApexTrack.Live): Play?
	return live.data[Props.NAME]
end

local function sortedKeys(map: { [string]: any }): { string }
	local out: { string } = {}
	for key in map do
		table.insert(out, key)
	end
	table.sort(out)
	return out
end

local function makeLayer(root: any, path: string, layer: Types.FaceLayer): any?
	local names = Path.split(path)
	local name = table.remove(names)
	local parent = if #names == 0 then root else Props.resolve(root, table.concat(names, "/"))
	if parent == nil or name == nil then
		return nil
	end
	local ok, made = pcall(function()
		if not parent:IsA("BasePart") then
			return nil
		end
		local decal = Props.newInstance("Decal")
		decal.Name = name
		decal.Archivable = false
		decal.Face = (Enum.NormalId :: any)[layer.face]
		decal.ZIndex = layer.zIndex
		decal.Texture = ""
		decal.Parent = parent
		return decal
	end)
	if ok and made ~= nil then
		owned[made] = { users = 0, keep = false }
		return made
	end
	return nil
end

local LOOK_NAMES: { [string]: string } = {
	["@Atmosphere"] = "ApexAtmosphere",
	["@Grade"] = "ApexGrade",
	["@Bloom"] = "ApexBloom",
	["@Focus"] = "ApexFocus",
}

function Props.lookTarget(path: string, className: string): any?
	local lighting = Props.lighting()
	if lighting == nil then
		return nil
	end
	if path == "@Lighting" then
		return lighting
	end
	local name = LOOK_NAMES[path]
	if name == nil then
		return nil
	end
	local ok, found = pcall(function()
		local own = lighting:FindFirstChild(name)
		if own ~= nil and own:IsA(className) then
			return own
		end
		if path ~= "@Grade" then
			return lighting:FindFirstChildOfClass(className)
		end
		return nil
	end)
	if ok and found ~= nil then
		return found
	end
	local built, effect = pcall(function()
		local instance = Props.newInstance(className)
		instance.Name = name
		instance.Archivable = false
		instance.Parent = lighting
		return instance
	end)
	if built and effect ~= nil then
		owned[effect] = { users = 0, keep = false }
		return effect
	end
	return nil
end

local function leave(instance: any, kept: boolean)
	local entry = owned[instance]
	if entry == nil then
		return
	end
	entry.users -= 1
	entry.keep = entry.keep or kept
	if entry.users <= 0 then
		owned[instance] = nil
		if not entry.keep then
			destroy(instance)
		end
	end
end

function Props.began(live: ApexTrack.Live)
	local props = live.sidecar.props
	local root = live.rig
	if props == nil or root == nil or next(props) == nil or Props.onServer() then
		live.data[Props.NAME] = nil
		return
	end
	local play: Play = {
		active = true,
		time = nil,
		speed = live.speed,
		at = live.seenClock,
		items = {},
		sounds = {},
		options = { presets = live.sidecar.presets, fps = live.sidecar.fps },
		made = {},
	}
	for _, path in sortedKeys(props) do
		local target = props[path]
		local instance
		if path == "@Lighting" or LOOK_NAMES[path] ~= nil then
			if not Props.showsLook(live) then
				continue
			end
			instance = Props.lookTarget(path, target.className)
		else
			instance = Props.find(root, path)
		end
		if
			instance == nil
			and target.layer ~= nil
			and target.className == "Decal"
			and Path.inWorkspace(path) == nil
		then
			instance = makeLayer(root, path, target.layer)
		end
		if instance == nil then
			continue
		end
		local entry = owned[instance]
		if entry ~= nil then
			entry.users += 1
			table.insert(play.made, instance)
		end
		local ok, fits = pcall(isA, instance, target.className)
		if not (ok and fits) then
			local named, className = pcall(index, instance, "ClassName")
			local actual = if named then tostring(className) else "something else"
			local where = if Path.inWorkspace(path) ~= nil
				then "in the Workspace"
				else `on {nameOf(root)}`
			live.warnOnce(
				`props:class:{live.label}:{path}`,
				`ApexEngine: {live.label} animates {path} as a {target.className}, but {where} it is a {actual}, so its prop tracks are skipped.`
			)
			continue
		end
		for _, property in sortedKeys(target.properties) do
			local track = target.properties[property]
			if
				property == "Scale"
				and target.className == "DataModelMesh"
				and (live.scale or 1) ~= 1
				and Path.inWorkspace(path) == nil
				and isFileMesh(instance)
			then
				track = Sidecar.scaledProp(track, live.scale)
			end
			local compiled = Props.compile(target.className, property, track)
			local item = claim(path, compiled, instance)
			if item == nil then
				live.warnOnce(
					`props:read:{live.label}:{path}:{property}`,
					`ApexEngine: {live.label} animates {path}'s {property}, which it does not have here, so that prop track is skipped.`
				)
			else
				table.insert(play.items, item)
			end
		end
		if target.cues ~= nil and #target.cues > 0 then
			table.insert(play.sounds, {
				path = path,
				cues = target.cues,
				instance = instance,
				started = false,
			})
		end
	end
	live.data[Props.NAME] = play
end

function Props.step(rig: Frame.Rig, dt: number, catchUp: boolean)
	for _, live in rig.lives do
		local play = playOf(live)
		if play == nil or not play.active or live.phase ~= "Playing" then
			continue
		end
		local t = live.time
		for _, item in play.items do
			local slot = item.slot
			if slot.owners[#slot.owners] == item then
				local from, to, share = Props.fadeAt(item.compiled, t)
				if share ~= nil and crossfade(live, item, from, to, share) then
					continue
				end
				if item.twins ~= nil then
					hideTwins(item)
				end
				local value = Props.sample(item.compiled, t, play.options)
				if value ~= nil and value ~= slot.last then
					write(live, item, value)
				end
			elseif item.twins ~= nil then
				hideTwins(item)
			end
		end
		if #play.sounds > 0 and not catchUp then
			local travel = StateEval.travel({
				from = play.time,
				to = t,
				speed = live.speed,
				lastSpeed = play.speed,
				dt = dt,
				looped = live.looped,
				length = live.sidecar.length,
				late = live.late,
			})
			if travel == "Forward" then
				sweepCues(play, play.time or -math.huge, t)
			end
		end
		play.time = t
		play.speed = live.speed
		play.at = live.seenClock
	end
end

function Props.stopped(
	live: ApexTrack.Live,
	reason: ApexTrack.EndReason,
	policy: Types.InterruptPolicy
)
	local play = playOf(live)
	if play == nil or not play.active then
		return
	end
	play.active = false
	local length = live.sidecar.length

	if reason == "Completed" then
		if #play.sounds > 0 and play.speed >= 0 then
			local travel = StateEval.travel({
				from = play.time,
				to = length,
				speed = live.seenSpeed,
				lastSpeed = play.speed,
				dt = live.stoppedClock - play.at,
				looped = false,
				length = length,
				late = live.late,
			})
			if travel == "Forward" then
				sweepCues(play, play.time or -math.huge, math.huge)
			end
		end
	elseif policy == "Revert" then
		for _, sound in play.sounds do
			if sound.started then
				cue(sound, "Stop")
			end
		end
	elseif policy == "Complete" then
		for _, sound in play.sounds do
			if sound.started and stopsLater(sound.cues, play.time) then
				cue(sound, "Stop")
			end
		end
	end

	local finish = if play.speed < 0 then 0 else length
	local kept: { [any]: boolean } = {}
	for _, item in play.items do
		local outcome = ApexTrack.outcome(reason, policy, item.compiled.track.onEnd)
		local final = if outcome == "Final"
			then Props.sample(item.compiled, finish, play.options)
			else nil
		release(item, outcome, final)
		if outcome == "Final" then
			kept[item.instance] = true
		end
	end
	for _, instance in play.made do
		leave(instance, kept[instance] == true)
	end
end

Props.extension = {
	name = Props.NAME,
	stage = "props",
	cosmetic = true,
	began = Props.began,
	stopped = Props.stopped,
	step = Props.step,
} :: Frame.Extension

return Props
