RigState.HOME_C0 = "Apex_HomeC0"

RigState.SNAPSHOT_VERSION = 1

local MAX_DEPTH = 16

RigState.PARENT = table.freeze({ kind = "Parent" }) :: Types.SpaceTarget

export type Transition = {
	from: Types.SpaceTarget,
	fromValue: CFrame?,
	fromCapture: boolean?,
	start: number,
	duration: number,
}

export type Entry = {
	target: Types.SpaceTarget,
	value: CFrame?,
	capture: boolean?,
	transition: Transition?,
}

export type Held = {
	target: Types.SpaceTarget,
	value: CFrame,
}

export type State = {
	model: any,
	joints: { [string]: Entry },
	spaceChanged: Signal.Signal,
	registry: Registry,
	published: string?,
	handle: any?,
}

export type Registry = {
	states: { [any]: State },
	clock: () -> number,
	warnOnce: (key: string, message: string) -> (),
	wake: (model: any) -> (),
	check: ((state: State, joint: string, target: Types.SpaceTarget) -> string?)?,
}

export type Config = {
	clock: () -> number,
	warnOnce: ((key: string, message: string) -> ())?,
	wake: ((model: any) -> ())?,
}

export type SetOptions = {
	value: CFrame?,
	capture: boolean?,
	blend: number?,
	now: number?,
}

local WORDS: { [string]: boolean } = { Parent = true, World = true, RigRoot = true }

function RigState.same(a: Types.SpaceTarget, b: Types.SpaceTarget): boolean
	return a.kind == b.kind and a.joint == b.joint and a.slot == b.slot
end

function RigState.nameOf(target: Types.SpaceTarget): string
	if target.kind == "Joint" then
		return target.joint or "?"
	end
	return target.kind
end

local function copyTarget(target: Types.SpaceTarget): Types.SpaceTarget
	return { kind = target.kind, joint = target.joint, slot = target.slot }
end

function RigState.parse(value: any): (Types.SpaceTarget?, string?)
	if type(value) == "string" then
		if value == "" then
			return nil, "a space cannot be an empty name"
		end
		if WORDS[value] then
			return { kind = value :: any }, nil
		end
		return { kind = "Joint", joint = value }, nil
	end
	if type(value) == "table" then
		local kind = value.kind
		if kind == "Joint" then
			if type(value.joint) ~= "string" or value.joint == "" then
				return nil,
					'a Joint space must name its joint, as { kind = "Joint", joint = "LeftHand" }'
			end
			return { kind = "Joint", joint = value.joint }, nil
		elseif type(kind) == "string" and WORDS[kind] then
			return { kind = kind :: any }, nil
		end
		return nil,
			`a space table's kind must be "Parent", "World", "RigRoot" or "Joint", not {tostring(
				kind
			)}`
