function RigState.registry(config: Config): Registry
	local warned: { [string]: boolean } = {}
	return {
		states = setmetatable({}, { __mode = "k" }) :: any,
		clock = config.clock,
		warnOnce = config.warnOnce or function(key: string, message: string)
			if not warned[key] then
				warned[key] = true
				warn(message)
			end
		end,
		wake = config.wake or function() end,
		check = nil,
	}
