function RigState.held(state: State): { [string]: Held }
	local out: { [string]: Held } = {}
	for joint, entry in state.joints do
		if entry.target.kind ~= "Parent" and entry.value ~= nil then
			out[joint] = { target = entry.target, value = entry.value :: CFrame }
