--!strict
--!native
--!optimize 2

local AnchorMath = {}

export type CFrameData = { number }

export type AnchorKind = "Authored" | "Part" | "Slot"

export type SceneAnchor = {
	kind: AnchorKind,
	cframe: CFrameData?,
	part: string?,
	slot: string?,
}

export type Slot = {
	placement: CFrameData,
	[string]: any,
}

export type Scene = {
	slots: { [string]: Slot },
	anchor: SceneAnchor,
	[string]: any,
}

export type Lookup = {
	part: ((path: string) -> CFrame?)?,
	slotRoot: ((slot: string) -> CFrame?)?,
}

export type Override = {
	cframe: CFrame?,
	slot: string?,
}

export type Resolved = {
	origin: CFrame,
	slots: { [string]: CFrame },
	fixed: string?,
}

AnchorMath.BLEND = 0.15

function AnchorMath.toData(cframe: CFrame): CFrameData
	return { cframe:GetComponents() }
end

function AnchorMath.fromData(data: CFrameData): CFrame
	return CFrame.new(table.unpack(data, 1, 12))
end

function AnchorMath.placementOf(origin: CFrame, rootWorld: CFrame): CFrame
	return origin:Inverse() * rootWorld
end

function AnchorMath.worldOf(origin: CFrame, placement: CFrame): CFrame
	return origin * placement
end

function AnchorMath.originFromSlot(rootWorld: CFrame, placement: CFrame): CFrame
	return rootWorld * placement:Inverse()
end

function AnchorMath.authoredOrigin(anchor: SceneAnchor): CFrame
	local data = anchor.cframe
	return if data ~= nil then AnchorMath.fromData(data) else CFrame.identity
end

function AnchorMath.centre(roots: { CFrame }): CFrame
	if #roots == 0 then
		return CFrame.identity
	end
	local x, z, low = 0, 0, math.huge
	for _, root in roots do
		local position = root.Position
		x += position.X
		z += position.Z
		low = math.min(low, position.Y)
	end
	return CFrame.new(x / #roots, low, z / #roots)
end

local function fromSlot(scene: Scene, slot: string, lookup: Lookup?): (CFrame?, string?)
	local entry = scene.slots[slot]
	if entry == nil then
		return nil, `The scene is anchored to the slot '{slot}', which it does not have.`
	end
	local root = if lookup ~= nil and lookup.slotRoot ~= nil then lookup.slotRoot(slot) else nil
	if root == nil then
		return nil,
			`The scene is anchored to the slot '{slot}', but no rig was given to play it, so there is nothing to place the scene from.`
	end
	return AnchorMath.originFromSlot(root, AnchorMath.fromData(entry.placement)), nil
end

function AnchorMath.origin(
	scene: Scene,
	lookup: Lookup?,
	override: Override?
): (CFrame?, string?, string?)
	if override ~= nil then
		if override.cframe ~= nil then
			return override.cframe, nil, nil
		elseif override.slot ~= nil then
			local origin, problem = fromSlot(scene, override.slot, lookup)
			return origin, if origin then override.slot else nil, problem
		end
	end
	local anchor = scene.anchor
	if anchor.kind == "Part" then
		local path = anchor.part or ""
		local found = if lookup ~= nil and lookup.part ~= nil then lookup.part(path) else nil
		if found == nil then
			return nil,
				nil,
				`The scene is anchored to the map part '{path}', and this place has no part there. Add it, or pass another anchor.`
		end
		return found, nil, nil
	elseif anchor.kind == "Slot" then
		local slot = anchor.slot or ""
		local origin, problem = fromSlot(scene, slot, lookup)
		return origin, if origin then slot else nil, problem
	end
	return AnchorMath.authoredOrigin(anchor), nil, nil
end

function AnchorMath.placements(scene: Scene, origin: CFrame): { [string]: CFrame }
	local out: { [string]: CFrame } = {}
	for name, slot in scene.slots do
		out[name] = origin * AnchorMath.fromData(slot.placement)
	end
	return out
end

function AnchorMath.resolve(
	scene: Scene,
	lookup: Lookup?,
	override: Override?
): (Resolved?, string?)
	local origin, fixed, problem = AnchorMath.origin(scene, lookup, override)
	if origin == nil then
		return nil, problem
	end
	return { origin = origin, slots = AnchorMath.placements(scene, origin), fixed = fixed }, nil
end

function AnchorMath.blendWeight(elapsed: number, duration: number?): number
	local span = duration or AnchorMath.BLEND
	if span <= 0 then
		return 1
	end
	local u = math.clamp(elapsed / span, 0, 1)
	return u * u * (3 - 2 * u)
end

function AnchorMath.blend(from: CFrame, target: CFrame, elapsed: number, duration: number?): CFrame
	local weight = AnchorMath.blendWeight(elapsed, duration)
	if weight >= 1 then
		return target
	end
	return from:Lerp(target, weight)
end

return AnchorMath
