--!strict

local Modifiers = require(script.Parent.Modifiers)

local ChainKeys = {}

export type Key = {
	family: string,
	setting: string?,
	axis: number?,
	label: string,
	low: number,
	high: number,
	aim: boolean,
	range: string,
}

ChainKeys.LIST = table.freeze({
	table.freeze({
		family = "ikPlant",
		label = "Planting",
		low = 0,
		high = 1,
		aim = false,
		range = "it runs from 0 (not planted) to 1 (never below its plant)",
	}),
	table.freeze({
		family = "ikTurn",
		label = "IK turn",
		low = 0,
		high = 1,
		aim = false,
		range = "it runs from 0 (FK's turn) to 1 (all of IK's)",
	}),
	table.freeze({
		family = "ikMove",
		label = "IK move",
		low = 0,
		high = 1,
		aim = false,
		range = "it runs from 0 (where FK puts it) to 1 (all of IK's move)",
	}),
	table.freeze({
		family = "ikLean",
		label = "Lean",
		low = 0,
		high = 1,
		aim = true,
		range = "it runs from 0 (it slides in) to 1 (it leans fully)",
	}),
	table.freeze({
		family = "ikFold",
		setting = "foldShare",
		label = "Fold share",
		low = 0,
		high = 1,
		aim = true,
		range = "it runs from 0 (a rigid limb) to 1",
	}),
	table.freeze({
		family = "ikStretch",
		setting = "stretch",
		label = "Stretch",
		low = 1,
		high = math.huge,
		aim = false,
		range = "it is 1 (none) or more, times the chain's length",
	}),
	table.freeze({
		family = "ikSlideIn",
		setting = "slideIn",
		label = "Slide in",
		low = 0,
		high = 1,
		aim = true,
		range = "it runs from 0 (off) to 1 (on)",
	}),
	table.freeze({
		family = "ikRoll",
		setting = "roll",
		label = "Roll",
		low = 0,
		high = 1,
		aim = true,
		range = "it runs from 0 (off) to 1 (on)",
	}),
	table.freeze({
		family = "ikTipX",
		setting = "tip",
		axis = 1,
		label = "Tip X",
		low = -math.huge,
		high = math.huge,
		aim = true,
		range = "it is studs on the limb's part",
	}),
	table.freeze({
		family = "ikTipY",
		setting = "tip",
		axis = 2,
		label = "Tip Y",
		low = -math.huge,
		high = math.huge,
		aim = true,
		range = "it is studs on the limb's part",
	}),
	table.freeze({
		family = "ikTipZ",
		setting = "tip",
		axis = 3,
		label = "Tip Z",
		low = -math.huge,
		high = math.huge,
		aim = true,
		range = "it is studs on the limb's part",
	}),
}) :: { Key }

ChainKeys.FAMILIES = table.freeze((function()
	local out = {}
	for _, key in ChainKeys.LIST do
		table.insert(out, key.family)
	end
	return out
end)()) :: { string }

ChainKeys.TIP = table.freeze({ "ikTipX", "ikTipY", "ikTipZ" }) :: { string }

local BY_FAMILY: { [string]: Key } = {}
for _, key in ChainKeys.LIST do
	BY_FAMILY[key.family] = key
end

function ChainKeys.of(family: string): Key?
	return BY_FAMILY[family]
end

function ChainKeys.is(family: string): boolean
	return BY_FAMILY[family] ~= nil
end

function ChainKeys.labelOf(family: string, solver: string?): string
	local key = BY_FAMILY[family]
	if key == nil then
		return family
	end
	if family == "ikStretch" and solver == "Aim" then
		return "Slide"
	end
	return key.label
end

function ChainKeys.reads(family: string, solver: string?): boolean
	local key = BY_FAMILY[family]
	return key ~= nil and (not key.aim or solver == "Aim")
end

function ChainKeys.clamp(family: string, value: number): number
	local key = BY_FAMILY[family]
	if key == nil then
		return value
	end
	return math.clamp(value, key.low, key.high)
end

function ChainKeys.channelOf(doc: any, chain: string, family: string): Modifiers.Channel?
	local chains = doc[family]
	return if type(chains) == "table" then chains[chain] else nil
end

function ChainKeys.keyed(doc: any, chain: string): boolean
	for _, family in ChainKeys.FAMILIES do
		if ChainKeys.channelOf(doc, chain, family) ~= nil then
			return true
		end
	end
	return false
end

function ChainKeys.valueAt(
	doc: any,
	chain: string,
	family: string,
	t: number,
	options: Modifiers.EvalOptions?
): number?
	local channel = ChainKeys.channelOf(doc, chain, family)
	if channel == nil then
		return nil
	end
	return ChainKeys.clamp(family, Modifiers.evaluate(channel, t, options))
end

function ChainKeys.rigValue(spec: any, family: string, tipPoint: Vector3?): number
	if family == "ikPlant" then
		return 0
	elseif family == "ikTurn" or family == "ikMove" or family == "ikLean" then
		return 1
	elseif family == "ikFold" then
		return math.clamp(spec.foldShare or 0, 0, 1)
	elseif family == "ikStretch" then
		return math.max(spec.stretch or 1, 1)
	elseif family == "ikSlideIn" then
		return if spec.slideIn == true then 1 else 0
	elseif family == "ikRoll" then
		return if spec.roll == false then 0 else 1
	end
	local key = BY_FAMILY[family]
	if key ~= nil and key.axis ~= nil and tipPoint ~= nil then
		local axis = key.axis :: number
		return if axis == 1 then tipPoint.X elseif axis == 2 then tipPoint.Y else tipPoint.Z
	end
	return 0
end

return ChainKeys
