--!strict
--!native
--!optimize 2

local Pose = require(script.Parent.Pose)

local Fabrik = {}

export type JointLimit = {
	x: { number }?,
	y: { number }?,
	z: { number }?,
}

export type Link = {
	parentOffset: CFrame,
	childOffset: CFrame,
	transform: CFrame?,
	limit: JointLimit?,
	stiffness: number?,
}

export type Chain = {
	parentWorld: CFrame,
	links: { Link },
}

export type Settings = {
	pole: Vector3?,
	poleAngle: number?,
	stretch: number?,
	softness: number?,
	orientTip: (boolean | number)?,
	bend: Vector3?,
	iterations: number?,
	tolerance: number?,
	tip: CFrame?,
	share: number?,
	slideIn: (boolean | number)?,
	length: Vector3?,
	lean: number?,
}

export type Result = {
	transforms: { CFrame },
	reached: boolean,
	distance: number,
	stretch: number,
	passes: number,
}

Fabrik.ITERATIONS = 20

Fabrik.TOLERANCE = 1e-3

Fabrik.BEND = Vector3.new(0, 0, -1)

local NUDGE = 0.05

local STALL = 1e-7

local CRAWL = 0.9

local EPSILON = 1e-6

local abs, atan2, sin, pi = math.abs, math.atan2, math.sin, math.pi

local function unit(v: Vector3): Vector3?
	local length = v.Magnitude
	if length < EPSILON then
		return nil
	end
	return v / length
end

local function perpendicular(v: Vector3): Vector3
	local other = if abs(v.X) < 0.9 then Vector3.xAxis else Vector3.yAxis
	return v:Cross(other).Unit
end

local function across(v: Vector3, axis: Vector3): Vector3?
	return unit(v - axis * v:Dot(axis))
end

local function arc(a: Vector3, b: Vector3): CFrame
	local axis = a:Cross(b)
	local sine = axis.Magnitude
	local cosine = a:Dot(b)
	if sine < EPSILON then
		if cosine > 0 then
			return CFrame.identity
		end
		return CFrame.fromAxisAngle(perpendicular(a), pi)
	end
	return CFrame.fromAxisAngle(axis / sine, atan2(sine, cosine))
end

function Fabrik.clamp(rotation: CFrame, limit: JointLimit): CFrame
	local angles = Pose.toEuler(rotation, "XYZ")
	local changed = false
	local function clampAxis(value: number, range: { number }?): number
		if range == nil then
			return value
		end
		local low, high = range[1], range[2]
		if value < low then
			changed = true
			return low
		elseif value > high then
			changed = true
			return high
		end
		return value
	end
	local rx = clampAxis(angles.rx, limit.x)
	local ry = clampAxis(angles.ry, limit.y)
	local rz = clampAxis(angles.rz, limit.z)
	if not changed then
		return rotation
	end
	return Pose.fromValues("XYZ", { rx = rx, ry = ry, rz = rz })
end

function Fabrik.within(rotation: CFrame, limit: JointLimit, slack: number?): boolean
	local angles = Pose.toEuler(rotation, "XYZ")
	local give = slack or 1e-4
	for axis, value in { x = angles.rx, y = angles.ry, z = angles.rz } do
		local range = (limit :: any)[axis]
		if range ~= nil and (value < range[1] - give or value > range[2] + give) then
			return false
		end
	end
	return true
end

function Fabrik.frames(chain: Chain, transforms: { CFrame }?): { CFrame }
	local frames: { CFrame } = {}
	local parentEnd = chain.parentWorld
	for index, link in chain.links do
		local transform = if transforms then transforms[index] else link.transform
		local frame = parentEnd * link.parentOffset * (transform or CFrame.identity)
		frames[index] = frame
		parentEnd = frame * link.childOffset:Inverse()
	end
	return frames
end

function Fabrik.solve(chain: Chain, target: CFrame, settings: Settings?): Result
	local options: Settings = settings or {}
	local links = chain.links
	local count = #links
	assert(count >= 2, "Fabrik.solve takes a chain of at least two joints")
	local goal = target.Position
	local tolerance = options.tolerance or Fabrik.TOLERANCE
	local iterations = options.iterations or Fabrik.ITERATIONS

	local offsets: { Vector3 } = {}
	local start: { CFrame } = {}
	for index, link in links do
		local transform = link.transform or CFrame.identity
		offsets[index] = transform.Position
		start[index] = transform.Rotation
	end
	local between: { CFrame } = {}
	local bones: { Vector3 } = {}
	local lengths: { number } = {}
	local total = 0
	for index = 1, count - 1 do
		between[index] = links[index].childOffset:Inverse() * links[index + 1].parentOffset
		bones[index] = between[index] * offsets[index + 1]
		lengths[index] = bones[index].Magnitude
		total += lengths[index]
	end

	local rotations = table.clone(start)
	local bases: { CFrame } = table.create(count)
	local pivots: { Vector3 } = table.create(count)

	local function place(from: number)
		for index = from, count do
			if index == 1 then
				bases[1] = chain.parentWorld * links[1].parentOffset * CFrame.new(offsets[1])
			else
				local parent = index - 1
				bases[index] = bases[parent]
					* rotations[parent]
					* between[parent]
					* CFrame.new(offsets[index])
			end
			pivots[index] = bases[index].Position
		end
	end
	place(1)
	local root = pivots[1]
	local away = goal - root
	local distance = away.Magnitude

	local scale = 1
	local stretch = options.stretch or 1
	if stretch > 1 and distance > total and total >= EPSILON then
		scale = math.min(stretch, distance / total)
		for index = 1, count - 1 do
			bones[index] *= scale
			lengths[index] *= scale
			offsets[index + 1] = between[index]:PointToObjectSpace(bones[index])
		end
		total *= scale
		place(2)
	end

	local function aim(index: number, point: Vector3): CFrame
		local rotation = start[index]
		local want = unit(bases[index]:VectorToObjectSpace(point - pivots[index]))
		if lengths[index] >= EPSILON and want ~= nil then
			local from = (start[index] * bones[index]) / lengths[index]
			rotation = arc(from, want) * start[index]
		end
		local link = links[index]
		local stiffness = link.stiffness or 0
		if stiffness > 0 then
			rotation = start[index]:Lerp(rotation, 1 - math.min(stiffness, 1))
		end
		if link.limit then
			rotation = Fabrik.clamp(rotation, link.limit)
		end
		return rotation
	end

	local passes = 0
	local axis = unit(away) or unit(pivots[count] - root) or Vector3.yAxis
	if total < EPSILON then
		passes = 0
	elseif distance >= total - EPSILON then
		for index = 1, count - 1 do
			rotations[index] = aim(index, goal)
			place(index + 1)
		end
		passes = 1
	elseif count == 2 then
		rotations[1] = aim(1, goal)
		place(2)
		passes = 1
	else
		local function bendOf(): Vector3
			local sum = Vector3.zero
			for index = 2, count - 1 do
				local offset = pivots[index] - root
				sum += offset - axis * offset:Dot(axis)
			end
			return sum / (count - 2)
		end
		local side: Vector3? = if options.pole then across(options.pole - root, axis) else nil
		if side ~= nil then
			side = side * math.cos(options.poleAngle or 0)
				+ axis:Cross(side) * math.sin(options.poleAngle or 0)
		end
		local points = table.clone(pivots)
		local bend = unit(bendOf())
		if bend ~= nil and side ~= nil then
			local angle = atan2(axis:Dot(bend:Cross(side)), bend:Dot(side))
			local base = bases[1].Rotation
			rotations[1] = base:Inverse() * CFrame.fromAxisAngle(axis, angle) * base * rotations[1]
			place(1)
			points = table.clone(pivots)
		elseif bend == nil then
			local toward = side
			if toward == nil then
				local hint = (bases[1] * rotations[1]):VectorToWorldSpace(
					options.bend or Fabrik.BEND
				)
				toward = across(hint, axis) or perpendicular(axis)
			end
			for index = 2, count - 1 do
				local along = (index - 1) / (count - 1)
				points[index] += (toward :: Vector3) * (NUDGE * total * sin(pi * along))
			end
		end

		local limited = false
		for _, link in links do
			limited = limited or link.limit ~= nil
		end

		local gap = (pivots[count] - goal).Magnitude
		while passes < iterations and gap > tolerance do
			passes += 1
			points[count] = goal
			for index = count - 1, 1, -1 do
				local back = unit(points[index] - points[index + 1])
					or unit(pivots[index] - pivots[index + 1])
					or perpendicular(axis)
				points[index] = points[index + 1] + back * lengths[index]
			end
			for index = 1, count - 1 do
				rotations[index] = aim(index, points[index + 1])
				place(index + 1)
			end
			points = table.clone(pivots)
			local now = (pivots[count] - goal).Magnitude
			local stalled = gap - now < STALL or (limited and now > CRAWL * gap)
			gap = now
			if stalled then
				break
			end
		end

		while limited and passes < iterations and gap > tolerance do
			passes += 1
			local before = gap
			for index = count - 1, 1, -1 do
				local base = bases[index]
				local toTip = unit(base:VectorToObjectSpace(pivots[count] - pivots[index]))
				local toGoal = unit(base:VectorToObjectSpace(goal - pivots[index]))
				if toTip ~= nil and toGoal ~= nil then
					local was = rotations[index]
					local rotation = arc(toTip, toGoal) * was
					local link = links[index]
					local stiffness = link.stiffness or 0
					if stiffness > 0 then
						rotation = start[index]:Lerp(rotation, 1 - math.min(stiffness, 1))
					end
					if link.limit then
						rotation = Fabrik.clamp(rotation, link.limit)
					end
					rotations[index] = rotation
					place(index + 1)
					local now = (pivots[count] - goal).Magnitude
					if now > gap then
						rotations[index] = was
						place(index + 1)
					else
						gap = now
					end
				end
			end
			if before - gap < STALL then
				break
			end
		end
	end

	if options.orientTip ~= false then
		local rotation = bases[count].Rotation:Inverse() * target.Rotation
		local link = links[count]
		local stiffness = link.stiffness or 0
		if stiffness > 0 then
			rotation = start[count]:Lerp(rotation, 1 - math.min(stiffness, 1))
		end
		if link.limit then
			rotation = Fabrik.clamp(rotation, link.limit)
		end
		rotations[count] = rotation
	end

	local transforms: { CFrame } = table.create(count)
	for index = 1, count do
		transforms[index] = CFrame.new(offsets[index]) * rotations[index]
	end
	local gap = (pivots[count] - goal).Magnitude
	return {
		transforms = transforms,
		reached = gap <= tolerance,
		distance = gap,
		stretch = scale,
		passes = passes,
	}
end

return Fabrik
]=====],
    ["UhhhhhhReanim/System/runtime/steve110/main/apex_engine/Shared/IkFk.lua"] = [=====[
--!strict
--!native
--!optimize 2

local Aim = require(script.Parent.Aim)
local Fabrik = require(script.Parent.Fabrik)
local Modifiers = require(script.Parent.Modifiers)
local Pose = require(script.Parent.Pose)
local TwoBone = require(script.Parent.TwoBone)

local IkFk = {}

export type Solver = "TwoBone" | "FABRIK" | "Aim"

export type Chain = TwoBone.Chain
export type Settings = TwoBone.Settings
export type Result = TwoBone.Result

export type Snap = {
	target: CFrame,
	pole: Vector3,
	transforms: { CFrame },
	residual: number,
	residualPosition: number,
	blend: number,
}

local EPSILON = 1e-6

function IkFk.weight(
	channel: Modifiers.Channel?,
	t: number,
	options: Modifiers.EvalOptions?
): number
	if channel == nil then
		return 0
	end
	return math.clamp(Modifiers.evaluate(channel, t, options), 0, 1)
end

function IkFk.blend(fk: CFrame, ik: CFrame, w: number, move: number?): CFrame
	if move == nil or move == w then
		if w <= 0 then
			return fk
		elseif w >= 1 then
			return ik
		end
		return fk:Lerp(ik, w)
	end
	local turn = if w <= 0
		then fk.Rotation
		elseif w >= 1 then ik.Rotation
		else fk.Rotation:Lerp(ik.Rotation, w)
	local at = if move <= 0
		then fk.Position
		elseif move >= 1 then ik.Position
		else fk.Position:Lerp(ik.Position, move)
	return CFrame.new(at) * turn
end

function IkFk.pose(fk: { CFrame }, ik: { CFrame }, w: number, move: number?): { CFrame }
	local out: { CFrame } = table.create(#fk)
	for index, transform in fk do
		out[index] = IkFk.blend(transform, ik[index] or transform, w, move)
	end
	return out
end

local function atOrigin(chain: Chain): (Chain, Vector3)
	local origin = chain.parentWorld.Position
	return { parentWorld = chain.parentWorld - origin, links = chain.links }, origin
end

function IkFk.solve(chain: Chain, solver: Solver, target: CFrame, settings: Settings?): Result
	local near, origin = atOrigin(chain)
	local goal = target - origin
	local options = settings
	if settings ~= nil and settings.pole ~= nil then
		options = table.clone(settings)
		options.pole = settings.pole - origin
	end
	if solver == "TwoBone" then
		return TwoBone.solve(near, goal, options)
	elseif solver == "Aim" then
		return Aim.solve(near, goal, options)
	end
	return Fabrik.solve(near, goal, options)
end

local function posedAs(chain: Chain, transforms: { CFrame }): Chain
	local links = table.create(#chain.links)
	for index, link in chain.links do
		local copy = table.clone(link)
		copy.transform = transforms[index]
		links[index] = copy
	end
	return { parentWorld = chain.parentWorld, links = links }
end

function IkFk.evaluate(
	chain: Chain,
	solver: Solver,
	fk: { CFrame },
	target: CFrame,
	w: number,
	settings: Settings?,
	move: number?
): { CFrame }
	if w <= 0 and (move == nil or move <= 0) then
		return fk
	end
	local ik = IkFk.solve(posedAs(chain, fk), solver, target, settings).transforms
	return IkFk.pose(fk, ik, w, move)
end

function IkFk.snapFk(
	shown: { CFrame },
	rotationModes: { Pose.RotationMode },
	previous: { Pose.Values }?
): { Pose.Values }
	local out: { Pose.Values } = table.create(#shown)
	for index, transform in shown do
		out[index] = Pose.toValues(
			transform,
			rotationModes[index],
			if previous then previous[index] else nil
		)
	end
	return out
end

local function bendNear(
	chain: Chain,
	solver: Solver,
	settings: Settings?
): (Vector3, Vector3, Vector3, Vector3)
	if solver == "TwoBone" and #chain.links == 3 then
		local side, axis, root, middle = TwoBone.bendOf(chain, settings)
		return side, axis, root, middle - side * (middle - root):Dot(side)
	end
	local frames = Fabrik.frames(chain)
	local count = #frames
	local root = frames[1].Position
	local tip = frames[count].Position
	local line = tip - root
	if line.Magnitude < EPSILON then
		line = frames[2].Position - root
	end
	local axis = if line.Magnitude >= EPSILON then line.Unit else Vector3.yAxis
	local sum = Vector3.zero
	local along = 0
	for index = 2, count - 1 do
		local offset = frames[index].Position - root
		sum += offset - axis * offset:Dot(axis)
		along += offset:Dot(axis)
	end
	local level = root + axis * (if count > 2 then along / (count - 2) else 0)
	if sum.Magnitude >= EPSILON then
		return sum.Unit, axis, root, level
	end
	local hint = frames[1]:VectorToWorldSpace((settings and settings.bend) or Fabrik.BEND)
	local side = hint - axis * hint:Dot(axis)
	if side.Magnitude < EPSILON then
		local other = if math.abs(axis.X) < 0.9 then Vector3.xAxis else Vector3.yAxis
		side = axis:Cross(other)
	end
	return side.Unit, axis, root, level
end

local function bendOf(
	chain: Chain,
	solver: Solver,
	settings: Settings?
): (Vector3, Vector3, Vector3, Vector3)
	local near, origin = atOrigin(chain)
	local side, axis, root, level = bendNear(near, solver, settings)
	return side, axis, root + origin, level + origin
end

local function residuals(chain: Chain, a: { CFrame }, b: { CFrame }): (number, number)
	local turned = 0
	for index, transform in a do
