	for index, frame in framesA do
		moved = math.max(moved, (frame.Position - framesB[index].Position).Magnitude)
	end
	return turned, moved
end

function IkFk.snapIk(chain: Chain, solver: Solver, settings: Settings?, shown: { CFrame }?): Snap
	local onScreen: { CFrame } = shown or table.create(#chain.links)
	if shown == nil then
		for index, link in chain.links do
			onScreen[index] = link.transform or CFrame.identity
