local function elasticBlend(
	time: number,
	change: number,
	duration: number,
	amplitude: number,
	s: number
): number
	local f = 1
	if change ~= 0 then
		local reach = abs(s)
		if amplitude ~= 0 then
			f *= amplitude / abs(change)
		else
			f = 0
		end
