--!strict
--!native
--!optimize 2

local Interp = require(script.Parent.Interp)

local Modifiers = {}

export type Kind = "Noise" | "Cycles" | "Stepped" | "Limits" | "Envelope" | "Generator"

export type Blend = "Replace" | "Add" | "Subtract" | "Multiply"

export type Extend = "Repeat" | "RepeatOffset" | "RepeatMirrored" | "None"

export type GeneratorMode = "Expanded" | "Factorised" | "Function"

export type Fn = "Sin" | "Cos" | "Tan" | "Sqrt" | "Ln" | "Sinc"

export type Range = { from: number, to: number, blendIn: number?, blendOut: number? }

export type EnvelopePoint = { t: number, min: number, max: number }

export type Modifier = {
	kind: Kind,
	bakeRate: number?,
	mute: boolean?,
	influence: number?,
	range: Range?,
	[string]: any,
}

export type Channel = {
	keys: { Interp.Key },
	modifiers: { Modifier }?,
	interp: Interp.Interp?,
}

export type EvalOptions = Interp.EvalOptions

Modifiers.KINDS = { "Noise", "Cycles", "Stepped", "Limits", "Envelope", "Generator" }
Modifiers.BLENDS = { "Replace", "Add", "Subtract", "Multiply" }
Modifiers.EXTENDS = { "Repeat", "RepeatOffset", "RepeatMirrored", "None" }
Modifiers.GENERATOR_MODES = { "Expanded", "Factorised", "Function" }
Modifiers.FUNCTIONS = { "Sin", "Cos", "Tan", "Sqrt", "Ln", "Sinc" }

Modifiers.DEFAULTS = table.freeze({
	Noise = table.freeze({
		scale = 1 / 24,
		strength = 1,
		phase = 1,
		offset = 0,
		depth = 0,
		lacunarity = 2,
		roughness = 0.5,
		blend = "Replace",
	}),
	Cycles = table.freeze({
		beforeMode = "Repeat",
		afterMode = "Repeat",
		beforeCount = 0,
		afterCount = 0,
	}),
	Stepped = table.freeze({
		step = 2 / 24,
		offset = 0,
	}),
	Limits = table.freeze({}),
	Envelope = table.freeze({
		reference = 0,
		min = -1,
		max = 1,
		points = table.freeze({}),
	}),
	Generator = table.freeze({
		mode = "Expanded",
		additive = false,
		coefficients = table.freeze({ 0, 1 }),
		factors = table.freeze({ table.freeze({ 1, 0 }) }),
		fn = "Sin",
		amplitude = 1,
		phaseMultiplier = 1,
		phaseOffset = 0,
		valueOffset = 0,
	}),
})

Modifiers.MAX_NOISE_DEPTH = 16

local NOISE = Modifiers.DEFAULTS.Noise
local CYCLES = Modifiers.DEFAULTS.Cycles
local STEPPED = Modifiers.DEFAULTS.Stepped
local ENVELOPE = Modifiers.DEFAULTS.Envelope
local GENERATOR = Modifiers.DEFAULTS.Generator

local function set(list: { string }): { [string]: boolean }
	local out = {}
	for _, name in list do
		out[name] = true
	end
	return out
end

local KNOWN_KIND = set(Modifiers.KINDS)
local KNOWN_BLEND = set(Modifiers.BLENDS)
local KNOWN_EXTEND = set(Modifiers.EXTENDS)
local KNOWN_MODE = set(Modifiers.GENERATOR_MODES)
local KNOWN_FN = set(Modifiers.FUNCTIONS)

local abs, floor, ceil, fmod = math.abs, math.floor, math.ceil, math.fmod
local min, max = math.min, math.max
local pi = math.pi

local MOD = 4294967296
local bxor, lrotate, band = bit32.bxor, bit32.lrotate, bit32.band

local SEED2 = 0xdeadbeef + 8 + 13

local function hash2(kx: number, ky: number): number
	local a = (SEED2 + kx % MOD) % MOD
	local b = (SEED2 + ky % MOD) % MOD
	local c = SEED2
	c = (bxor(c, b) - lrotate(b, 14)) % MOD
	a = (bxor(a, c) - lrotate(c, 11)) % MOD
	b = (bxor(b, a) - lrotate(a, 25)) % MOD
	c = (bxor(c, b) - lrotate(b, 16)) % MOD
	a = (bxor(a, c) - lrotate(c, 4)) % MOD
	b = (bxor(b, a) - lrotate(a, 14)) % MOD
	c = (bxor(c, b) - lrotate(b, 24)) % MOD
	return c
end

local function gradient(h: number, x: number, y: number): number
	h = band(h, 7)
	local u: number, v: number
	if h < 4 then
		u, v = x, 2 * y
	else
		u, v = y, 2 * x
	end
	if band(h, 1) ~= 0 then
		u = -u
	end
	if band(h, 2) ~= 0 then
		v = -v
	end
	return u + v
end

local function fade(t: number): number
	return t * t * t * (t * (t * 6 - 15) + 10)
end

local function perlin(x: number, y: number): number
	local nudgeX = if abs(x) >= 1000000 then 0.5 else 0
	local nudgeY = if abs(y) >= 1000000 then 0.5 else 0
	x = fmod(x, 100000) + nudgeX
	y = fmod(y, 100000) + nudgeY
	local ix, iy = floor(x), floor(y)
	local fx, fy = x - ix, y - iy
	local u, v = fade(fx), fade(fy)
	local n00 = gradient(hash2(ix, iy), fx, fy)
	local n10 = gradient(hash2(ix + 1, iy), fx - 1, fy)
	local n01 = gradient(hash2(ix, iy + 1), fx, fy - 1)
	local n11 = gradient(hash2(ix + 1, iy + 1), fx - 1, fy - 1)
	local bottom = n00 * (1 - u) + n10 * u
	local top = n01 * (1 - u) + n11 * u
	return ((1 - v) * bottom + v * top) * 0.6616
end

local function fbm(
	x: number,
	y: number,
	depth: number,
	roughness: number,
	lacunarity: number
): number
	local scale, amplitude, total, sum = 1, 1, 0, 0
	for _ = 0, depth do
		sum += perlin(scale * x, scale * y) * amplitude
		total += amplitude
		amplitude *= roughness
		scale *= lacunarity
	end
	return 0.5 * sum / total + 0.5
end

local NOISE_X_OFFSET = 0.61803398874

function Modifiers.noiseAt(modifier: Modifier, t: number): number
	local size = modifier.scale or NOISE.scale
	local inverse = if size == 0 then 0 else 1 / size
	local depth = modifier.depth or NOISE.depth
	depth = max(0, min(floor(depth), Modifiers.MAX_NOISE_DEPTH))
	return fbm(
		(t - (modifier.offset or NOISE.offset)) * inverse + NOISE_X_OFFSET,
		modifier.phase or NOISE.phase,
		depth,
		modifier.roughness or NOISE.roughness,
		modifier.lacunarity or NOISE.lacunarity
	)
end

local SNAP = 1e-9

local function snapped(q: number): (number, boolean)
	local nearest = floor(q + 0.5)
	if abs(q - nearest) < SNAP then
		return nearest, true
	end
	return q, false
end

local function cyclesTime(modifier: Modifier, keys: { Interp.Key }, t: number): (number, number)
	local n = #keys
	if n == 0 then
		return t, 0
	end
	local first, last = keys[1], keys[n]
	local side, mode, count, origin = 0, "None", 0, 0
	if t < first.t then
		mode = modifier.beforeMode or CYCLES.beforeMode
		side, count, origin = -1, modifier.beforeCount or 0, first.t
	elseif t > last.t then
		mode = modifier.afterMode or CYCLES.afterMode
		side, count, origin = 1, modifier.afterCount or 0, last.t
	end
	if side == 0 or mode == "None" then
		return t, 0
	end
	local span = last.t - first.t
	if span == 0 then
		return t, 0
	end
	local q, onBoundary = snapped((t - origin) / span)
	local cycle = side * q
	if count ~= 0 and cycle > count then
		return t, 0
	end
	local offset = 0
	if mode == "RepeatOffset" then
		offset = (if side < 0 then floor(q) else ceil(q)) * (last.v - first.v)
	end
	local within = if onBoundary then 0 else fmod(t - origin, span)
	local mirrored = mode == "RepeatMirrored"
	local read: number
	if within == 0 then
		read = if side == 1 then last.t else first.t
		if mirrored and floor(cycle) % 2 == 1 then
			read = if side == 1 then first.t else last.t
		end
	elseif mirrored and floor(cycle + 1) % 2 == 1 then
		read = (if side < 0 then first.t else last.t) - within
	else
		read = first.t + within
	end
	if read < first.t then
		read += span
	end
	return read, offset
end

local function steppedTime(modifier: Modifier, t: number): number
	local startTime, endTime = modifier.startTime, modifier.endTime
	if startTime ~= nil and t < startTime then
		return t
	end
	if endTime ~= nil and t > endTime then
		return t
	end
	local step = modifier.step or STEPPED.step
	if step <= 0 then
		return t
	end
	local offset = modifier.offset or STEPPED.offset
	local q = snapped((t - offset) / step)
	local block = if q >= 0 then floor(q) else ceil(q)
	return block * step + offset
end

local function limitsTime(modifier: Modifier, t: number): number
	local minTime, maxTime = modifier.minTime, modifier.maxTime
	if minTime ~= nil and t < minTime then
		return minTime
	end
	if maxTime ~= nil and t > maxTime then
		return maxTime
	end
	return t
end

local function envelopeValue(modifier: Modifier, value: number, t: number): number
	local points = modifier.points
	if points == nil or #points == 0 then
		return value
	end
	local n = #points
	local low: number, high: number
	if points[1].t >= t then
		low, high = points[1].min, points[1].max
	elseif points[n].t <= t then
		low, high = points[n].min, points[n].max
	else
		low, high = points[n].min, points[n].max
		for i = 1, n - 1 do
			local a, b = points[i], points[i + 1]
			if a.t <= t and b.t >= t then
				local span = b.t - a.t
				if span > 0 then
					local u = (t - a.t) / span
					low = a.min + (b.min - a.min) * u
					high = a.max + (b.max - a.max) * u
				else
					low, high = b.min, b.max
				end
				break
			end
		end
	end
	local reference = modifier.reference or ENVELOPE.reference
	local bandLow = modifier.min or ENVELOPE.min
	local bandHigh = modifier.max or ENVELOPE.max
	if bandHigh == bandLow then
		return value
	end
	local fraction = (value - (reference + bandLow)) / (bandHigh - bandLow)
	return low + fraction * (high - low)
end

local FLT_EPSILON = 1.1920929e-07

local function generatorValue(modifier: Modifier, value: number, t: number): number
	local additive = modifier.additive == true
	local mode = modifier.mode or GENERATOR.mode
	local generated: number
	if mode == "Function" then
		local arg = (modifier.phaseMultiplier or GENERATOR.phaseMultiplier) * t
			+ (modifier.phaseOffset or GENERATOR.phaseOffset)
		local fn = modifier.fn or GENERATOR.fn
		local y: number
		if fn == "Sin" then
			y = math.sin(arg)
		elseif fn == "Cos" then
			y = math.cos(arg)
		elseif fn == "Sinc" then
			y = if abs(arg) < 0.0001 then 1 else math.sin(pi * arg) / (pi * arg)
		elseif fn == "Tan" then
			if abs(fmod(arg - pi / 2, pi)) < FLT_EPSILON then
				return if additive then value else 0
			end
			y = math.tan(arg)
		elseif fn == "Sqrt" then
			if arg <= 0 then
				return if additive then value else 0
			end
			y = math.sqrt(arg)
		elseif fn == "Ln" then
			if arg <= 1 then
				return if additive then value else 0
			end
			y = math.log(arg)
		else
			return value
		end
		generated = (modifier.amplitude or GENERATOR.amplitude) * y
			+ (modifier.valueOffset or GENERATOR.valueOffset)
	elseif mode == "Factorised" then
		local factors = modifier.factors or GENERATOR.factors
		if #factors == 0 then
			return value
		end
		generated = 1
		for _, factor in factors do
			generated *= factor[1] * t + factor[2]
		end
	else
		local coefficients = modifier.coefficients or GENERATOR.coefficients
		if #coefficients < 2 then
			return value
		end
		generated = 0
		local power = 1
		for _, coefficient in coefficients do
			generated += coefficient * power
			power *= t
		end
	end
	return if additive then value + generated else generated
end

local function noiseValue(modifier: Modifier, value: number, t: number): number
	local noise = Modifiers.noiseAt(modifier, t)
	local strength = modifier.strength or NOISE.strength
	local blend = modifier.blend or NOISE.blend
	if blend == "Add" then
		return value + noise * strength
	elseif blend == "Subtract" then
		return value - noise * strength
	elseif blend == "Multiply" then
		return value * noise * strength
	end
	return value + (noise - 0.5) * strength
end

local function inRange(modifier: Modifier, t: number): boolean
	local range = modifier.range
	return range == nil or (range.from <= t and range.to >= t)
end

local function influenceAt(modifier: Modifier, t: number): number
	local influence = modifier.influence or 1
	local range = modifier.range
	if range ~= nil then
		local from, to = range.from, range.to
		if t < from or t > to then
			return 0
		end
		local blendIn, blendOut = range.blendIn or 0, range.blendOut or 0
		if blendIn ~= 0 and t <= from + blendIn then
			return influence * (t - from) / blendIn
		end
		if blendOut ~= 0 and t >= to - blendOut then
			return influence * (to - t) / blendOut
		end
	end
	return influence
end

local TIME_KIND: { [string]: boolean } = { Cycles = true, Stepped = true, Limits = true }

local CYCLIC_OPTIONS: EvalOptions = { cyclic = true }

local keyOptions: EvalOptions = {}

local function withCyclic(options: EvalOptions, cyclic: boolean): EvalOptions
	keyOptions.presets = options.presets
	keyOptions.smoothing = options.smoothing
	keyOptions.leading = options.leading
	keyOptions.fps = options.fps
	keyOptions.cyclic = cyclic
	return keyOptions
end

function Modifiers.isCyclic(channel: Channel): boolean
	local stack = channel.modifiers
	local first = if stack ~= nil then stack[1] else nil
	if first == nil or first.kind ~= "Cycles" or first.mute == true or first.range ~= nil then
		return false
	end
	if first.influence ~= nil and first.influence ~= 1 then
		return false
	end
	if (first.beforeCount or 0) ~= 0 or (first.afterCount or 0) ~= 0 then
		return false
	end
	local before = first.beforeMode or CYCLES.beforeMode
	local after = first.afterMode or CYCLES.afterMode
	return (before == "Repeat" or before == "RepeatOffset")
		and (after == "Repeat" or after == "RepeatOffset")
end

function Modifiers.recalcHandles(channel: Channel, options: Interp.HandleOptions?)
	local merged: { [string]: any } = {}
	if options ~= nil then
		for name, value in options :: { [string]: any } do
			merged[name] = value
		end
	end
	merged.cyclic = Modifiers.isCyclic(channel)
	Interp.recalcHandles(channel.keys, merged :: any)
end

local function keyOptionsFor(channel: Channel, options: EvalOptions?): EvalOptions?
	local cyclic = Modifiers.isCyclic(channel)
	if options == nil then
		if cyclic then
			return CYCLIC_OPTIONS
		end
		return nil
	end
	if (options.cyclic == true) == cyclic then
		return options
	end
	return withCyclic(options, cyclic)
end

function Modifiers.evaluate(channel: Channel, t: number, options: EvalOptions?): number
	local stack = channel.modifiers
	if stack == nil or #stack == 0 then
		return Interp.evaluate(
			channel,
			t,
			if options ~= nil and options.cyclic == true
				then withCyclic(options, false)
				else options
		)
	end
	local keys = channel.keys
	local count = #stack

	local time = t
	local cycleOffset = 0
	for i = count, 1, -1 do
		local modifier = stack[i]
		local kind = modifier.kind
		if TIME_KIND[kind] and modifier.mute ~= true and inRange(modifier, time) then
			local remapped: number
			if kind == "Cycles" then
				if i ~= 1 then
					continue
				end
				remapped, cycleOffset = cyclesTime(modifier, keys, time)
			elseif kind == "Stepped" then
				remapped = steppedTime(modifier, time)
			else
				remapped = limitsTime(modifier, time)
			end
			local influence = influenceAt(modifier, time)
			time = influence * remapped + (1 - influence) * time
		end
	end

	local value = Interp.evaluate(channel, time, keyOptionsFor(channel, options))

	for i = 1, count do
		local modifier = stack[i]
		local kind = modifier.kind
		if kind ~= "Stepped" and modifier.mute ~= true and inRange(modifier, time) then
			local result: number
			if kind == "Noise" then
				result = noiseValue(modifier, value, time)
			elseif kind == "Cycles" then
				if i ~= 1 then
					continue
				end
				result = value + cycleOffset
			elseif kind == "Limits" then
				result = value
				local minValue, maxValue = modifier.minValue, modifier.maxValue
				if minValue ~= nil and result < minValue then
					result = minValue
				end
				if maxValue ~= nil and result > maxValue then
					result = maxValue
				end
			elseif kind == "Envelope" then
				result = envelopeValue(modifier, value, time)
			elseif kind == "Generator" then
				result = generatorValue(modifier, value, time)
			else
				continue
			end
			local influence = influenceAt(modifier, time)
			value = influence * result + (1 - influence) * value
		end
	end
	return value
end

local CLAMP_WIDTH = 1e-9

function Modifiers.clampKnots(
	channel: Channel,
	from: number,
	to: number,
	rate: number,
	options: EvalOptions?,
	into: { number }?
): { number }
	local out: { number } = into or {}
	local stack = channel.modifiers
	if stack == nil or not (to > from) or not (rate > 0) then
		return out
	end
	for _, modifier in stack do
		local kind = modifier.kind
		if modifier.mute == true then
			continue
		elseif
			kind == "Cycles"
			or kind == "Stepped"
			or (kind == "Limits" and (modifier.minTime ~= nil or modifier.maxTime ~= nil))
		then
			return out
		end
	end
	for index, modifier in stack do
		local low, high = modifier.minValue, modifier.maxValue
		if modifier.kind ~= "Limits" or modifier.mute == true or (low == nil and high == nil) then
			continue
		end
		local below: Channel = {
			keys = channel.keys,
			interp = channel.interp,
			modifiers = table.move(stack, 1, index - 1, 1, {}),
		}
		local range = modifier.range
		local lo = if range ~= nil then max(from, range.from) else from
		local hi = if range ~= nil then min(to, range.to) else to
		if not (hi > lo) then
			continue
		end
		local function clamps(t: number): number
			local value = Modifiers.evaluate(below, t, options)
			return if low ~= nil and value < low
				then -1
				elseif high ~= nil and value > high then 1
				else 0
		end
		local function locate(l: number, r: number, before: (state: number) -> boolean)
			while r - l > CLAMP_WIDTH do
				local m = (l + r) / 2
				if before(clamps(m)) then
					l = m
				else
					r = m
				end
			end
			table.insert(out, (l + r) / 2)
		end
		local count = max(1, ceil((hi - lo) * rate - 1e-9))
		local t0, state0 = lo, clamps(lo)
		for step = 1, count do
			local t1 = if step == count then hi else lo + (hi - lo) * step / count
			local state1 = clamps(t1)
			if state0 ~= state1 and state0 ~= 0 then
				locate(t0, t1, function(state: number): boolean
					return state == state0
				end)
			end
			if state0 ~= state1 and state1 ~= 0 then
				locate(t0, t1, function(state: number): boolean
					return state ~= state1
				end)
			end
			t0, state0 = t1, state1
		end
	end
	return out
end

local function finite(x: any): boolean
	return type(x) == "number" and x == x and x ~= math.huge and x ~= -math.huge
end

local function whole(x: any): boolean
	return finite(x) and x % 1 == 0
end

local function optionalNumber(m: Modifier, field: string, what: string): string?
	local x = m[field]
	if x ~= nil and not finite(x) then
		return `{what} '{field}' must be a number`
	end
	return nil
end

local function optionalAtLeast(m: Modifier, field: string, least: number, what: string): string?
	local x = m[field]
	if x ~= nil and not (finite(x) and x >= least) then
		return `{what} '{field}' must be a number, {least} or more`
	end
	return nil
end

local function optionalName(
	m: Modifier,
	field: string,
	known: { [string]: boolean },
	list: { string },
	what: string
): string?
	local x = m[field]
	if x ~= nil and not (type(x) == "string" and known[x]) then
		return `{what} '{field}' must be one of {table.concat(list, ", ")}`
	end
	return nil
end

local function optionalCount(m: Modifier, field: string, what: string): string?
	local x = m[field]
	if x ~= nil and not (whole(x) and x >= 0) then
		return `{what} '{field}' must be a whole number, 0 or more (0 repeats forever)`
	end
	return nil
end

local function firstProblem(...: string?): string?
	for i = 1, select("#", ...) do
		local problem = select(i, ...)
		if problem ~= nil then
			return problem
		end
	end
	return nil
end

local function orderedPair(m: Modifier, low: string, high: string, what: string): string?
	local a, b = m[low], m[high]
	if a ~= nil and b ~= nil and a > b then
		return `{what} '{low}' is after its '{high}'`
	end
	return nil
end

local function validateNoise(m: Modifier): string?
	local what = "a Noise modifier's"
	local problem = firstProblem(
		optionalAtLeast(m, "scale", 0, what),
		optionalNumber(m, "strength", what),
		optionalNumber(m, "phase", what),
		optionalNumber(m, "offset", what),
		optionalAtLeast(m, "lacunarity", 0, what),
		optionalAtLeast(m, "roughness", 0, what),
		optionalName(m, "blend", KNOWN_BLEND, Modifiers.BLENDS, what)
	)
	if problem ~= nil then
		return problem
	end
	local depth = m.depth
	if
		depth ~= nil and not (whole(depth) and depth >= 0 and depth <= Modifiers.MAX_NOISE_DEPTH)
	then
		return `{what} 'depth' must be a whole number from 0 to {Modifiers.MAX_NOISE_DEPTH}`
	end
	return nil
end

local function validateCycles(m: Modifier): string?
	local what = "a Cycles modifier's"
	return firstProblem(
		optionalName(m, "beforeMode", KNOWN_EXTEND, Modifiers.EXTENDS, what),
		optionalName(m, "afterMode", KNOWN_EXTEND, Modifiers.EXTENDS, what),
		optionalCount(m, "beforeCount", what),
		optionalCount(m, "afterCount", what)
	)
end

local function validateStepped(m: Modifier): string?
	local what = "a Stepped modifier's"
	local step = m.step
	if step ~= nil and not (finite(step) and step > 0) then
		return `{what} 'step' must be a number of seconds greater than 0`
	end
	return firstProblem(
		optionalNumber(m, "offset", what),
		optionalNumber(m, "startTime", what),
		optionalNumber(m, "endTime", what),
		orderedPair(m, "startTime", "endTime", what)
	)
end

local function validateLimits(m: Modifier): string?
	local what = "a Limits modifier's"
	return firstProblem(
		optionalNumber(m, "minTime", what),
		optionalNumber(m, "maxTime", what),
		optionalNumber(m, "minValue", what),
		optionalNumber(m, "maxValue", what),
		orderedPair(m, "minTime", "maxTime", what),
		orderedPair(m, "minValue", "maxValue", what)
	)
end

local function validateEnvelope(m: Modifier): string?
	local what = "an Envelope modifier's"
	local problem = firstProblem(
		optionalNumber(m, "reference", what),
		optionalNumber(m, "min", what),
		optionalNumber(m, "max", what)
	)
	if problem ~= nil then
		return problem
	end
	if (m.min or ENVELOPE.min) == (m.max or ENVELOPE.max) then
		return `{what} 'min' and 'max' must differ: the band they make is what is rescaled`
	end
	local points = m.points
	if points == nil then
		return nil
	end
	if type(points) ~= "table" then
		return `{what} 'points' must be a list`
	end
	local previous = -math.huge
	for i, point in points do
		if
			type(point) ~= "table"
			or not (finite(point.t) and finite(point.min) and finite(point.max))
		then
			return `{what} point {i} must have numbers for its time, 'min' and 'max'`
		end
		if point.t <= previous then
			return `{what} points must be in increasing time (point {i} is at {point.t} s)`
		end
		previous = point.t
	end
	return nil
end

local function validateGenerator(m: Modifier): string?
	local what = "a Generator modifier's"
	local problem = firstProblem(
		optionalName(m, "mode", KNOWN_MODE, Modifiers.GENERATOR_MODES, what),
		optionalName(m, "fn", KNOWN_FN, Modifiers.FUNCTIONS, what),
		optionalNumber(m, "amplitude", what),
		optionalNumber(m, "phaseMultiplier", what),
		optionalNumber(m, "phaseOffset", what),
		optionalNumber(m, "valueOffset", what)
	)
	if problem ~= nil then
		return problem
	end
	if m.additive ~= nil and type(m.additive) ~= "boolean" then
		return `{what} 'additive' must be true or false`
	end
	local coefficients = m.coefficients
	if coefficients ~= nil then
		if type(coefficients) ~= "table" or #coefficients < 2 then
			return `{what} 'coefficients' must list at least two numbers (a constant and a slope)`
		end
		for i, c in coefficients do
			if not finite(c) then
				return `{what} coefficient {i} must be a number`
			end
		end
	end
	local factors = m.factors
	if factors ~= nil then
		if type(factors) ~= "table" or #factors < 1 then
			return `{what} 'factors' must list at least one pair`
		end
		for i, factor in factors do
			if type(factor) ~= "table" or not (finite(factor[1]) and finite(factor[2])) then
				return `{what} factor {i} must be a pair of numbers a, b - the factor (a t + b)`
			end
		end
	end
	return nil
end

local VALIDATE: { [string]: (Modifier) -> string? } = {
	Noise = validateNoise,
	Cycles = validateCycles,
	Stepped = validateStepped,
	Limits = validateLimits,
	Envelope = validateEnvelope,
	Generator = validateGenerator,
}

function Modifiers.validate(modifier: any): (boolean, string?)
	if type(modifier) ~= "table" then
		return false, `a modifier must be a table, got {type(modifier)}`
	end
	local kind = modifier.kind
	if type(kind) ~= "string" or not KNOWN_KIND[kind] then
		return false,
			`a modifier's 'kind' must be one of {table.concat(Modifiers.KINDS, ", ")}, got {tostring(
				kind
			)}`
	end
