local Interp = require(script.Parent.Interp)
local Modifiers = require(script.Parent.Modifiers)
local Movement = require(script.Parent.Movement)
local Pose = require(script.Parent.Pose)

local MovementFold = {}

export type Spec = {
	joint: string,
	rest: CFrame,
	keys: { Movement.MovementKey },
}

export type Options = {
	presets: { [string]: any }?,
	fps: number?,
}

export type FlatTrack = {
	rotationMode: Pose.RotationMode,
	channels: {
		[string]: {
			keys: { { t: number, v: number, interp: string } },
			bakeRate: number?,
			steep: { number }?,
		},
	},
	sample: (t: number) -> CFrame,
