	if a.interp == "Cubic" then
		local _, w1, wLeft, wRight = NativeCurve.cubicBasis(u, 1)
		u = w1 + wLeft * (a.rightTangent or 0) + wRight * (b.leftTangent or 0)
	end
	return slerp(a.w, a.x, a.y, a.z, b.w, b.x, b.y, b.z, u)
end

