	if t <= first.t then
		return first.w, first.x, first.y, first.z
	end
	local last = keys[n]
	if t >= last.t then
		return last.w, last.x, last.y, last.z
	end
	local i = segmentOf(keys, t)
	return NativeCurve.rotationSegment(keys[i], keys[i + 1], t)
