local Interp = require(script.Parent.Interp)
local NativeCurve = require(script.Parent.NativeCurve)

local NativeKeys = {}

function NativeKeys.toDocument(native: { NativeCurve.Key }): { Interp.Key }
	local out: { Interp.Key } = table.create(#native)
	for index, key in native do
		out[index] = { t = key.t, v = key.v }
	end
	for index, key in native do
		local target = out[index]
		if key.interp == "Constant" then
			target.interp = "Constant"
		elseif key.interp == "Linear" then
			target.interp = "Linear"
		else
			target.interp = "Bezier"
