--!strict
--!native
--!optimize 2

local Interp = require(script.Parent.Interp)

local PathSpline = {}

export type Shape = "Auto" | "Vector" | "Aligned" | "Free"

export type Face = "Turn" | "Slope" | "Own"

export type Forward = "Front" | "Back" | "Left" | "Right"

export type Point = {
	t: number,
	cframe: { number }?,
	shape: string?,
	shapeIn: { number }?,
	shapeOut: { number }?,
	face: string?,
	lean: number?,
	turn: number?,
	interp: Interp.Interp?,
	easing: Interp.Easing?,
	params: Interp.Params?,
	handles: { number }?,
}

export type Built = {
	points: { Point },
	positions: { Vector3 },
	ins: { Vector3 },
	outs: { Vector3 },
	lengths: { number },
	at: { number },
	total: number,
	arcs: { { number } },
	arriving: { Vector3 },
	leaving: { Vector3 },
	radius: { number },
	ups: { [number]: { Vector3 } },
	twist: { [number]: number },
}

PathSpline.PIECES = 16

PathSpline.DEFAULT_TURN = 0.2

PathSpline.GRAVITY = 196.2

PathSpline.MAX_LEAN = math.rad(60)

PathSpline.DEFAULT_HANDLES = table.freeze({ 1 / 3, 0, 2 / 3, 1 })

PathSpline.SHAPES = table.freeze({ "Auto", "Vector", "Aligned", "Free" })
PathSpline.FACES = table.freeze({ "Turn", "Slope", "Own" })
PathSpline.FORWARDS = table.freeze({ "Front", "Back", "Left", "Right" })

local NEAR = 1e-6
local CORNER = 1e-3
local LEAN_REACH = 0.5
local TAU = 2 * math.pi

local FIXES: { [string]: CFrame } = {
	Front = CFrame.identity,
	Back = CFrame.Angles(0, math.pi, 0),
	Left = CFrame.Angles(0, -math.pi / 2, 0),
	Right = CFrame.Angles(0, math.pi / 2, 0),
}

local function wrapped(angle: number): number
	return (angle + math.pi) % TAU - math.pi
end

local function smooth(u: number): number
	local x = math.clamp(u, 0, 1)
	return x * x * (3 - 2 * x)
end

function PathSpline.cframeOf(point: Point): CFrame
	local data = point.cframe
	if data == nil then
		return CFrame.identity
	end
	return CFrame.new(table.unpack(data, 1, 12))
end

local function positionOf(point: Point): Vector3
	local data = point.cframe
	if data == nil then
		return Vector3.zero
	end
	return Vector3.new(data[1], data[2], data[3])
end

local function vectorOf(data: { number }?): Vector3?
	if data == nil then
		return nil
	end
	return Vector3.new(data[1], data[2], data[3])
end

function PathSpline.headingOf(look: Vector3): number?
	if look.X * look.X + look.Z * look.Z < 1e-12 then
		return nil
	end
	return math.atan2(-look.X, -look.Z)
end

function PathSpline.forwardFix(forward: string?): CFrame
	return FIXES[forward or "Front"] or CFrame.identity
end

function PathSpline.handles(points: { Point }, index: number): (Vector3, Vector3)
	local point = points[index]
	local here = positionOf(point)
	local previous, following = points[index - 1], points[index + 1]
	local back = if previous ~= nil then here - positionOf(previous) else nil
	local ahead = if following ~= nil then positionOf(following) - here else nil
	local shape = point.shape or "Auto"
	if shape == "Vector" then
		return if back ~= nil then -back / 3 else Vector3.zero,
			if ahead ~= nil then ahead / 3 else Vector3.zero
	end
	local into = if back ~= nil then vectorOf(point.shapeIn) else nil
	local out = if ahead ~= nil then vectorOf(point.shapeOut) else nil
	if
		(shape == "Aligned" or shape == "Free")
		and (into ~= nil or back == nil)
		and (out ~= nil or ahead == nil)
	then
		return into or Vector3.zero, out or Vector3.zero
	end
	local way: Vector3? = nil
	local backward = back ~= nil and back.Magnitude > NEAR
	local forward = ahead ~= nil and ahead.Magnitude > NEAR
	if backward and forward then
		local halving = (back :: Vector3).Unit + (ahead :: Vector3).Unit
		way = if halving.Magnitude > NEAR then halving.Unit else (ahead :: Vector3).Unit
	elseif forward then
		way = (ahead :: Vector3).Unit
	elseif backward then
		way = (back :: Vector3).Unit
	end
	if way == nil then
		return Vector3.zero, Vector3.zero
	end
	return if back ~= nil then -way * (back.Magnitude / 3) else Vector3.zero,
		if ahead ~= nil then way * (ahead.Magnitude / 3) else Vector3.zero
end

local function bezier(p0: Vector3, p1: Vector3, p2: Vector3, p3: Vector3, u: number): Vector3
	local v = 1 - u
	return p0 * (v * v * v) + p1 * (3 * v * v * u) + p2 * (3 * v * u * u) + p3 * (u * u * u)
end

local function slope(p0: Vector3, p1: Vector3, p2: Vector3, p3: Vector3, u: number): Vector3
	local v = 1 - u
	return (p1 - p0) * (3 * v * v) + (p2 - p1) * (6 * v * u) + (p3 - p2) * (3 * u * u)
end

function PathSpline.piece(built: Built, index: number): (Vector3, Vector3, Vector3, Vector3)
	local p0, p3 = built.positions[index], built.positions[index + 1]
	return p0, p0 + built.outs[index], p3 + built.ins[index + 1], p3
end

local function tangentOf(built: Built, index: number, u: number): Vector3
	local p0, p1, p2, p3 = PathSpline.piece(built, index)
	local way = slope(p0, p1, p2, p3, u)
	if way.Magnitude > NEAR then
		return way.Unit
	end
	local nudged = slope(p0, p1, p2, p3, math.clamp(u, 0.01, 0.99))
	if nudged.Magnitude > NEAR then
		return nudged.Unit
	end
	local chord = p3 - p0
	if chord.Magnitude > NEAR then
		return chord.Unit
	end
	return PathSpline.cframeOf(built.points[index]).LookVector
end

local function lookOf(built: Built, index: number): Vector3
	return PathSpline.cframeOf(built.points[index]).LookVector
end

local function carriedUp(up: Vector3, along: Vector3): Vector3?
	local flat = up - along * up:Dot(along)
	if flat.Magnitude < NEAR then
		return nil
	end
	return flat.Unit
end

