	local own = PathSpline.cframeOf(built.points[index])
	return carriedUp(own.UpVector, along)
		or carriedUp(Vector3.yAxis, along)
		or carriedUp(-own.LookVector, along)
		or Vector3.xAxis
end

local function rolled(up: Vector3, axis: Vector3, angle: number): Vector3
	return CFrame.fromAxisAngle(axis, angle):VectorToWorldSpace(up)
end

local function signedAngle(from: Vector3, to: Vector3, axis: Vector3): number
	return math.atan2(from:Cross(to):Dot(axis), from:Dot(to))
end

local function carryUps(built: Built, index: number)
	local pieces = PathSpline.PIECES
	local ups: { Vector3 } = table.create(pieces + 1)
	local up = upOf(built, index, tangentOf(built, index, 0))
	ups[1] = up
	for k = 1, pieces do
		local along = tangentOf(built, index, k / pieces)
		up = carriedUp(up, along) or up
		ups[k + 1] = up
	end
	local ending = tangentOf(built, index, 1)
	built.ups[index] = ups
	built.twist[index] = signedAngle(up, upOf(built, index + 1, ending), ending)
end

function PathSpline.build(points: { Point }): Built
	local n = #points
	local pieces = PathSpline.PIECES
	local built: Built = {
		points = points,
		positions = table.create(n),
		ins = table.create(n),
		outs = table.create(n),
		lengths = table.create(math.max(n - 1, 0)),
		at = table.create(n),
		total = 0,
		arcs = table.create(math.max(n - 1, 0)),
		arriving = table.create(n),
		leaving = table.create(n),
		radius = table.create(n, 0),
		ups = {},
		twist = {},
	}
	for index = 1, n do
		built.positions[index] = positionOf(points[index])
		local into, out = PathSpline.handles(points, index)
		built.ins[index] = into
		built.outs[index] = out
	end
	local distance = 0
	for index = 1, n do
		built.at[index] = distance
		if index == n then
			break
		end
		local p0, p1, p2, p3 = PathSpline.piece(built, index)
		local arc: { number } = table.create(pieces + 1)
		arc[1] = 0
		local last = p0
		local length = 0
		for k = 1, pieces do
			local here = bezier(p0, p1, p2, p3, k / pieces)
			length += (here - last).Magnitude
			arc[k + 1] = length
			last = here
		end
		built.arcs[index] = arc
		built.lengths[index] = length
		distance += length
	end
	built.total = distance
	for index = 1, n do
		built.leaving[index] = if index < n
			then tangentOf(built, index, 0)
			else lookOf(built, index)
		built.arriving[index] = if index > 1
			then tangentOf(built, index - 1, 1)
			else built.leaving[index]
		if index == n and index > 1 then
			built.leaving[index] = built.arriving[index]
		end
	end
	for index = 2, n - 1 do
		local into, out = built.arriving[index], built.leaving[index]
		if into:Dot(out) > math.cos(CORNER) then
			continue
		end
		local point = points[index]
		local before = points[index - 1].t
		local after = points[index + 1].t
		local inLength, outLength = built.lengths[index - 1], built.lengths[index]
		local inSpeed = if point.t - before > NEAR then inLength / (point.t - before) else 0
		local outSpeed = if after - point.t > NEAR then outLength / (after - point.t) else 0
		local speed = (inSpeed + outSpeed) / 2
		local turn = point.turn or PathSpline.DEFAULT_TURN
		built.radius[index] = math.min(turn * speed / 2, inLength / 2, outLength / 2)
	end
	for index = 1, n - 1 do
		if points[index].face == "Slope" then
			carryUps(built, index)
		end
