end

function PathSpline.locate(built: Built, s: number): (number, number)
	local n = #built.points
	if n < 2 then
		return 1, 0
	end
	local at = built.at
	local low, high = 1, n - 1
	while low < high do
		local middle = (low + high + 1) // 2
		if at[middle] <= s then
			low = middle
		else
			high = middle - 1
		end
	end
	local index = low
	local into = math.clamp(s - at[index], 0, built.lengths[index])
	local arc = built.arcs[index]
	local pieces = PathSpline.PIECES
	local k = 1
	while k < pieces and arc[k + 1] < into do
		k += 1
	end
	local from, to = arc[k], arc[k + 1]
	local part = if to - from > NEAR then (into - from) / (to - from) else 0
	return index, math.clamp((k - 1 + part) / pieces, 0, 1)
end

function PathSpline.positionAt(built: Built, s: number): Vector3
	local n = #built.points
	if n == 0 then
		return Vector3.zero
	elseif n == 1 then
		return built.positions[1]
	end
	local index, u = PathSpline.locate(built, math.clamp(s, 0, built.total))
	local p0, p1, p2, p3 = PathSpline.piece(built, index)
	return bezier(p0, p1, p2, p3, u)
end

function PathSpline.directionAt(built: Built, s: number): Vector3
	local n = #built.points
	if n < 2 then
		return if n == 1 then lookOf(built, 1) else -Vector3.zAxis
	end
	local at = math.clamp(s, 0, built.total)
	for index = 2, n - 1 do
		local radius = built.radius[index]
		local mark = built.at[index]
		if radius > NEAR and math.abs(at - mark) < radius then
			local share = smooth((at - mark + radius) / (2 * radius))
			local into, out = built.arriving[index], built.leaving[index]
