	return PathSpline.headingOf(PathSpline.directionAt(built, s))
		or PathSpline.headingOf(lookOf(built, index))
		or 0
end

function PathSpline.leanAt(built: Built, s: number, speed: number, lean: number): number
	if lean <= 0 or speed <= 0 then
		return 0
	end
	local index = PathSpline.locate(built, s)
	local reach = LEAN_REACH
	local before = math.max(s - reach, 0)
	local after = math.min(s + reach, built.total)
	if after - before <= NEAR then
		return 0
	end
	local turning = wrapped(headingAt(built, after, index) - headingAt(built, before, index))
		/ (after - before)
	local angle = lean * math.atan(speed * speed * turning / PathSpline.GRAVITY)
	return math.clamp(angle, -PathSpline.MAX_LEAN, PathSpline.MAX_LEAN)
end

local function slopeUp(built: Built, index: number, u: number, along: Vector3): Vector3
	local ups = built.ups[index]
	if ups == nil then
		return carriedUp(Vector3.yAxis, along) or Vector3.xAxis
	end
	local pieces = PathSpline.PIECES
	local scaled = u * pieces
	local k = math.clamp(math.floor(scaled), 0, pieces - 1)
	local up = ups[k + 1]:Lerp(ups[k + 2], scaled - k)
	up = carriedUp(up, along) or carriedUp(Vector3.yAxis, along) or Vector3.xAxis
