	return CFrame.new(position) * CFrame.Angles(0, heading, 0) * CFrame.Angles(0, 0, bank) * fix
end

function PathSpline.share(point: Point, elapsed: number, duration: number): number
	local mode = point.interp or "Linear"
	if mode == "Constant" then
		return 0
	elseif duration <= 0 then
		return 1
	elseif mode == "Linear" then
		return math.clamp(elapsed / duration, 0, 1)
	elseif mode == "Bezier" then
		local handles = point.handles or PathSpline.DEFAULT_HANDLES
		return Interp.bezier(
			0,
			0,
			handles[1],
			handles[2],
			handles[3],
			handles[4],
			1,
			1,
			math.clamp(elapsed / duration, 0, 1)
		)
	end
	return Interp.ease(
		mode,
		point.easing,
		math.clamp(elapsed, 0, duration),
		0,
		1,
		duration,
		point.params
