end

function PathSpline.speed(point: Point, elapsed: number, duration: number, length: number): number
	if duration <= 0 or length <= 0 or point.interp == "Constant" then
		return 0
	end
	local step = math.min(1 / 240, duration / 4)
	local from = math.max(elapsed - step, 0)
	local to = math.min(elapsed + step, duration)
	if to - from <= 0 then
		return 0
	end
	local gone = PathSpline.share(point, to, duration) - PathSpline.share(point, from, duration)
	return math.abs(gone) * length / (to - from)
end

local function stretchAt(points: { Point }, t: number): number
	local low, high = 1, #points - 1
	while low < high do
		local middle = (low + high + 1) // 2
		if points[middle].t <= t then
			low = middle
		else
			high = middle - 1
		end
	end
	return low
end

function PathSpline.distanceAt(built: Built, t: number): number
	local points = built.points
	local n = #points
	if n < 2 or t <= points[1].t then
		return 0
	elseif t >= points[n].t then
		return built.total
	end
	local index = stretchAt(points, t)
	local point = points[index]
	local duration = points[index + 1].t - point.t
	local share = PathSpline.share(point, t - point.t, duration)
	return math.clamp(built.at[index] + share * built.lengths[index], 0, built.total)
end

