	local points = built.points
	local n = #points
	if n < 2 or t < points[1].t or t > points[n].t then
		return 0
	end
	local index = stretchAt(points, t)
	local point = points[index]
	local duration = points[index + 1].t - point.t
	return PathSpline.speed(point, t - point.t, duration, built.lengths[index])
end

function PathSpline.at(built: Built, t: number, forward: string?): CFrame
	return PathSpline.frameAt(
		built,
		PathSpline.distanceAt(built, t),
		PathSpline.speedAt(built, t),
		forward
	)
end

return PathSpline
