--!strict
--!native
--!optimize 2

local Modifiers = require(script.Parent.Modifiers)

local Pose = {}

export type Order = "XYZ" | "XZY" | "YXZ" | "YZX" | "ZXY" | "ZYX"

export type RotationMode = Order | "Quaternion"

export type JointTrack = {
	rotationMode: RotationMode,
	channels: { [string]: Modifiers.Channel },
	spaces: any?,
}

export type Values = {
	px: number?,
	py: number?,
	pz: number?,
	rx: number?,
	ry: number?,
	rz: number?,
	qw: number?,
	qx: number?,
	qy: number?,
	qz: number?,
}

export type Euler = { rx: number, ry: number, rz: number }

Pose.ORDERS = { "XYZ", "XZY", "YXZ", "YZX", "ZXY", "ZYX" }
Pose.ROTATION_MODES = { "XYZ", "XZY", "YXZ", "YZX", "ZXY", "ZYX", "Quaternion" }
Pose.POSITION_CHANNELS = { "px", "py", "pz" }
Pose.EULER_CHANNELS = { "rx", "ry", "rz" }
Pose.QUATERNION_CHANNELS = { "qw", "qx", "qy", "qz" }

local sin, cos, atan2, sqrt, abs = math.sin, math.cos, math.atan2, math.sqrt, math.abs
local floor = math.floor
local pi = math.pi
local TAU = 2 * pi

type Axes = { first: number, second: number, third: number, parity: number }

local AXES: { [string]: Axes } = {}
for _, order in Pose.ORDERS do
	local index = { X = 1, Y = 2, Z = 3 }
	local a, b, c = index[order:sub(1, 1)], index[order:sub(2, 2)], index[order:sub(3, 3)]
	AXES[order] = { first = a, second = b, third = c, parity = if b % 3 + 1 == c then 1 else -1 }
end

function Pose.isRotationMode(name: any): boolean
	return type(name) == "string" and (name == "Quaternion" or AXES[name] ~= nil)
end

local function turn(
	m00: number,
	m01: number,
	m02: number,
	m10: number,
	m11: number,
	m12: number,
	m20: number,
	m21: number,
	m22: number,
	axis: number,
	angle: number
): (number, number, number, number, number, number, number, number, number)
	if angle == 0 then
		return m00, m01, m02, m10, m11, m12, m20, m21, m22
	end
	local c, s = cos(angle), sin(angle)
	if axis == 1 then
		return m00,
			m01 * c + m02 * s,
			m02 * c - m01 * s,
			m10,
			m11 * c + m12 * s,
			m12 * c - m11 * s,
			m20,
			m21 * c + m22 * s,
			m22 * c - m21 * s
	elseif axis == 2 then
		return m00 * c - m02 * s,
			m01,
			m02 * c + m00 * s,
			m10 * c - m12 * s,
			m11,
			m12 * c + m10 * s,
			m20 * c - m22 * s,
			m21,
			m22 * c + m20 * s
	end
	return m00 * c + m01 * s,
		m01 * c - m00 * s,
		m02,
		m10 * c + m11 * s,
		m11 * c - m10 * s,
		m12,
		m20 * c + m21 * s,
		m21 * c - m20 * s,
		m22
end

local function angleOf(axis: number, rx: number, ry: number, rz: number): number
	return if axis == 1 then rx elseif axis == 2 then ry else rz
end

local function eulerFrame(
	order: string,
	px: number,
	py: number,
	pz: number,
	rx: number,
	ry: number,
	rz: number
): CFrame
	local axes = AXES[order] or AXES.XYZ
	local first, second, third = axes.first, axes.second, axes.third
	local m00, m01, m02, m10, m11, m12, m20, m21, m22 = 1, 0, 0, 0, 1, 0, 0, 0, 1
	m00, m01, m02, m10, m11, m12, m20, m21, m22 =
		turn(m00, m01, m02, m10, m11, m12, m20, m21, m22, first, angleOf(first, rx, ry, rz))
	m00, m01, m02, m10, m11, m12, m20, m21, m22 =
		turn(m00, m01, m02, m10, m11, m12, m20, m21, m22, second, angleOf(second, rx, ry, rz))
	m00, m01, m02, m10, m11, m12, m20, m21, m22 =
		turn(m00, m01, m02, m10, m11, m12, m20, m21, m22, third, angleOf(third, rx, ry, rz))
	return CFrame.new(px, py, pz, m00, m01, m02, m10, m11, m12, m20, m21, m22)
end

local function quaternionFrame(
	px: number,
	py: number,
	pz: number,
	w: number,
	x: number,
	y: number,
	z: number
): CFrame
	local length = sqrt(w * w + x * x + y * y + z * z)
	if length == 0 then
		return CFrame.new(px, py, pz)
	end
	w, x, y, z = w / length, x / length, y / length, z / length
	return CFrame.new(
		px,
		py,
		pz,
		1 - 2 * (y * y + z * z),
		2 * (x * y - w * z),
		2 * (x * z + w * y),
		2 * (x * y + w * z),
		1 - 2 * (x * x + z * z),
		2 * (y * z - w * x),
		2 * (x * z - w * y),
		2 * (y * z + w * x),
		1 - 2 * (x * x + y * y)
	)
end

function Pose.fromValues(rotationMode: RotationMode, values: Values): CFrame
	local px, py, pz = values.px or 0, values.py or 0, values.pz or 0
	if rotationMode == "Quaternion" then
		return quaternionFrame(
			px,
			py,
			pz,
			values.qw or 0,
			values.qx or 0,
			values.qy or 0,
			values.qz or 0
		)
	end
	return eulerFrame(rotationMode, px, py, pz, values.rx or 0, values.ry or 0, values.rz or 0)
end

local function at(
	channels: { [string]: Modifiers.Channel },
	name: string,
	t: number,
	options: Modifiers.EvalOptions?,
	rest: number
): number
	local channel = channels[name]
	return if channel ~= nil then Modifiers.evaluate(channel, t, options) else rest
end

function Pose.evaluate(track: JointTrack, t: number, options: Modifiers.EvalOptions?): CFrame
	local channels = track.channels
	local px = at(channels, "px", t, options, 0)
	local py = at(channels, "py", t, options, 0)
	local pz = at(channels, "pz", t, options, 0)
	if track.rotationMode == "Quaternion" then
		return quaternionFrame(
			px,
			py,
			pz,
			at(channels, "qw", t, options, 1),
			at(channels, "qx", t, options, 0),
			at(channels, "qy", t, options, 0),
			at(channels, "qz", t, options, 0)
		)
	end
	return eulerFrame(
		track.rotationMode,
		px,
		py,
		pz,
		at(channels, "rx", t, options, 0),
		at(channels, "ry", t, options, 0),
		at(channels, "rz", t, options, 0)
	)
end

local GIMBAL = 1e-6

local function nearest(angle: number, target: number): number
	return angle + TAU * floor((target - angle) / TAU + 0.5)
end

local function matrixOf(cf: CFrame): { { number } }
	local _, _, _, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
	return { { r00, r01, r02 }, { r10, r11, r12 }, { r20, r21, r22 } }
end

local function firstAngle(m: { { number } }, axes: Axes, b: number, c: number): number
	local m00, m01, m02 = m[1][1], m[1][2], m[1][3]
	local m10, m11, m12 = m[2][1], m[2][2], m[2][3]
	local m20, m21, m22 = m[3][1], m[3][2], m[3][3]
	m00, m01, m02, m10, m11, m12, m20, m21, m22 =
		turn(m00, m01, m02, m10, m11, m12, m20, m21, m22, axes.third, -c)
	m00, m01, m02, m10, m11, m12, m20, m21, m22 =
		turn(m00, m01, m02, m10, m11, m12, m20, m21, m22, axes.second, -b)
	local rows = { { m00, m01, m02 }, { m10, m11, m12 }, { m20, m21, m22 } }
	local p = axes.first % 3 + 1
	local q = p % 3 + 1
	return atan2(rows[q][p], rows[p][p])
end

local rotation: { number } = table.create(9, 0)

local function eulerOf(
	cf: CFrame,
	order: Order,
	continuous: boolean,
	prx: number,
	pry: number,
	prz: number
): (number, number, number)
	local axes = AXES[order] or AXES.XYZ
	local i, j, k, e = axes.first, axes.second, axes.third, axes.parity
	local m = rotation
	local _, _, _, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
	m[1], m[2], m[3], m[4], m[5], m[6], m[7], m[8], m[9] =
		r00, r01, r02, r10, r11, r12, r20, r21, r22
	local row = (i - 1) * 3
	local mii, mij, mik = m[row + i], m[row + j], m[row + k]
	local cosB = sqrt(mii * mii + mij * mij)
	local b = atan2(e * mik, cosB)
	local a: number, c: number
	local both: boolean
	if cosB < GIMBAL then
		c = if continuous then angleOf(k, prx, pry, prz) else 0
		a = firstAngle(matrixOf(cf), axes, b, c)
		if continuous then
			a = nearest(a, angleOf(i, prx, pry, prz))
			b = nearest(b, angleOf(j, prx, pry, prz))
		end
		both = false
	else
		a = atan2(-e * m[(j - 1) * 3 + k], m[(k - 1) * 3 + k])
		c = atan2(-e * mij, mii)
		both = true
	end

	if continuous then
		local ta, tb, tc =
			angleOf(i, prx, pry, prz), angleOf(j, prx, pry, prz), angleOf(k, prx, pry, prz)
		local a1, b1, c1 = nearest(a, ta), nearest(b, tb), nearest(c, tc)
		local cost1 = abs(a1 - ta) + abs(b1 - tb) + abs(c1 - tc)
		local bestCost = if cost1 < math.huge then cost1 else math.huge
		if both then
			local a2, b2, c2 = nearest(a + pi, ta), nearest(pi - b, tb), nearest(c + pi, tc)
			local cost2 = abs(a2 - ta) + abs(b2 - tb) + abs(c2 - tc)
			if cost2 < bestCost then
				a1, b1, c1 = a2, b2, c2
			end
		end
		a, b, c = a1, b1, c1
	end

	local rx = if i == 1 then a elseif j == 1 then b else c
	local ry = if i == 2 then a elseif j == 2 then b else c
	local rz = if i == 3 then a elseif j == 3 then b else c
	return rx, ry, rz
end

function Pose.toEuler(cf: CFrame, order: Order, previous: Euler?): Euler
	local rx: number, ry: number, rz: number
	if previous ~= nil then
		rx, ry, rz = eulerOf(cf, order, true, previous.rx, previous.ry, previous.rz)
	else
		rx, ry, rz = eulerOf(cf, order, false, 0, 0, 0)
	end
	return { rx = rx, ry = ry, rz = rz }
end

local function quaternionOf(cf: CFrame, previous: Values?): (number, number, number, number)
	local _, _, _, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
	local trace = r00 + r11 + r22
	local w: number, x: number, y: number, z: number
	if trace > 0 then
		local s = 2 * sqrt(1 + trace)
		w = s / 4
		x = (r21 - r12) / s
		y = (r02 - r20) / s
		z = (r10 - r01) / s
	elseif r00 > r11 and r00 > r22 then
		local s = 2 * sqrt(1 + r00 - r11 - r22)
		w = (r21 - r12) / s
		x = s / 4
		y = (r01 + r10) / s
		z = (r02 + r20) / s
	elseif r11 > r22 then
		local s = 2 * sqrt(1 + r11 - r00 - r22)
		w = (r02 - r20) / s
		x = (r01 + r10) / s
		y = s / 4
		z = (r12 + r21) / s
	else
		local s = 2 * sqrt(1 + r22 - r00 - r11)
		w = (r10 - r01) / s
		x = (r02 + r20) / s
		y = (r12 + r21) / s
		z = s / 4
	end
	local length = sqrt(w * w + x * x + y * y + z * z)
	w, x, y, z = w / length, x / length, y / length, z / length
	local flip: boolean
	if previous ~= nil then
		local dot = w * (previous.qw or 0)
			+ x * (previous.qx or 0)
			+ y * (previous.qy or 0)
			+ z * (previous.qz or 0)
		flip = dot < 0
	else
		flip = w < 0
	end
	if flip then
		return -w, -x, -y, -z
	end
	return w, x, y, z
end

function Pose.toValues(cf: CFrame, rotationMode: RotationMode, previous: Values?): Values
	local position = cf.Position
	if rotationMode == "Quaternion" then
		local w, x, y, z = quaternionOf(cf, previous)
		return { px = position.X, py = position.Y, pz = position.Z, qw = w, qx = x, qy = y, qz = z }
	end
	local rx: number, ry: number, rz: number
	if previous ~= nil then
		rx, ry, rz = eulerOf(
			cf,
			rotationMode :: Order,
			true,
			previous.rx or 0,
			previous.ry or 0,
			previous.rz or 0
		)
	else
		rx, ry, rz = eulerOf(cf, rotationMode :: Order, false, 0, 0, 0)
	end
	return {
		px = position.X,
		py = position.Y,
		pz = position.Z,
		rx = rx,
		ry = ry,
		rz = rz,
	}
end

