local function turnBetween(a: CFrame, b: CFrame): (Vector3, number)
	local _, _, _, a00, a01, a02, a10, a11, a12, a20, a21, a22 = a:GetComponents()
	local _, _, _, b00, b01, b02, b10, b11, b12, b20, b21, b22 = b:GetComponents()
	local d00 = b00 * a00 + b01 * a01 + b02 * a02
	local d01 = b00 * a10 + b01 * a11 + b02 * a12
	local d02 = b00 * a20 + b01 * a21 + b02 * a22
	local d10 = b10 * a00 + b11 * a01 + b12 * a02
	local d11 = b10 * a10 + b11 * a11 + b12 * a12
	local d12 = b10 * a20 + b11 * a21 + b12 * a22
	local d20 = b20 * a00 + b21 * a01 + b22 * a02
	local d21 = b20 * a10 + b21 * a11 + b22 * a12
	local d22 = b20 * a20 + b21 * a21 + b22 * a22
	local w, x, y, z
	local trace = d00 + d11 + d22
	if trace > 0 then
		local s = math.sqrt(trace + 1) * 2
		w, x, y, z = s / 4, (d21 - d12) / s, (d02 - d20) / s, (d10 - d01) / s
	elseif d00 > d11 and d00 > d22 then
		local s = math.sqrt(1 + d00 - d11 - d22) * 2
		w, x, y, z = (d21 - d12) / s, s / 4, (d01 + d10) / s, (d02 + d20) / s
	elseif d11 > d22 then
		local s = math.sqrt(1 + d11 - d00 - d22) * 2
		w, x, y, z = (d02 - d20) / s, (d01 + d10) / s, s / 4, (d12 + d21) / s
	else
		local s = math.sqrt(1 + d22 - d00 - d11) * 2
		w, x, y, z = (d10 - d01) / s, (d02 + d20) / s, (d12 + d21) / s, s / 4
	end
	if w < 0 then
		w, x, y, z = -w, -x, -y, -z
	end
	local sine = math.sqrt(x * x + y * y + z * z)
	if sine < EPSILON then
		return Vector3.zero, 0
	end
	return Vector3.new(x / sine, y / sine, z / sine), 2 * math.atan2(sine, w)
end

