function ReleaseMath.window(t: number, length: number, rate: number): (number, number)
	local h = 1 / math.max(rate, EPSILON)
	local before = math.max(t - h, 0)
	if t - before > EPSILON then
		return before, t
	end
	if t + h <= length + EPSILON then
		return t, t + h
	end
	return 0, length
end

