	local from, to = ReleaseMath.window(t, length, rate)
	local a, b = worldAt(from), worldAt(to)
	if a == nil or b == nil then
		return nil
	end
	local dt = to - from
	if dt <= EPSILON then
		return { linear = Vector3.zero, angular = Vector3.zero }
	end
	return {
		linear = ((b :: CFrame).Position - (a :: CFrame).Position) / dt,
		angular = ReleaseMath.angularBetween(a :: CFrame, b :: CFrame, dt),
