local function hierarchyOf(rig: Rig, addresses: { string }): { string }
	local order: { string } = {}
	local seen: { [string]: boolean } = {}
	local function visit(address: string)
		if seen[address] then
			return
		end
		seen[address] = true
		local parent = rig.joints[address].parent
		if parent ~= nil and rig.joints[parent] ~= nil then
			visit(parent)
		end
		table.insert(order, address)
	end
	for _, address in addresses do
		visit(address)
	end
	return order
end

local function restOf(rig: Rig, hierarchy: { string }): ({ [string]: CFrame }, { [string]: CFrame })
	local pivots: { [string]: CFrame } = {}
	local worlds: { [string]: CFrame } = {}
	for _, address in hierarchy do
		local joint = rig.joints[address]
		local parent = joint.parent
		local parentWorld = (if parent ~= nil then worlds[parent] else nil)
			or joint.parentWorld
			or rig.root
		local pivot = parentWorld * joint.parentOffset
		pivots[address] = pivot
		worlds[address] = pivot * joint.childOffset:Inverse()
	end
	return pivots, worlds
end

local function restOfControl(control: Control, pivots: { [string]: CFrame }, root: CFrame): CFrame?
	local pivot: CFrame
	if control.joint ~= nil then
		local found = pivots[control.joint]
		if found == nil then
			return nil
		end
		pivot = found
	else
		pivot = root
	end
	local offset = control.offset
	if offset ~= nil then
		return pivot * CFrame.new(offset[1], offset[2], offset[3])
	end
	return pivot
end

function RigSolve.restPivots(rig: Rig): { [string]: CFrame }
	local pivots = restOf(rig, hierarchyOf(rig, sortedKeys(rig.joints)))
	return pivots
end

function RigSolve.controlRest(rig: Rig, name: string): CFrame?
	local controlRig = rig.controlRig
	local control = if controlRig ~= nil then controlRig.controls[name] else nil
	if control == nil then
		return nil
	end
	return restOfControl(control, RigSolve.restPivots(rig), rig.root)
end

local function chainProblem(
	name: string,
	chain: Chain,
	rig: Rig,
	controls: { [string]: ControlPlan },
	claimed: { [string]: ChainPlan }
): string?
	local links = chain.joints
	if chain.solver == "Aim" then
		if #links ~= 1 then
			return `The IK chain '{name}' aims one joint, so it takes exactly one; it has {#links}.`
		end
	elseif chain.solver == "TwoBone" and #links ~= 3 then
		return `The IK chain '{name}' solves two bones, so it takes exactly three joints; it has {#links}.`
	elseif #links < 2 then
		return `The IK chain '{name}' needs at least two joints.`
	end
	for index, address in links do
		local joint = rig.joints[address]
		if joint == nil then
			return `The IK chain '{name}' needs '{address}', which this rig does not have.`
		end
		if index > 1 and joint.parent ~= links[index - 1] then
			return `The IK chain '{name}' is not one limb: '{address}' does not hang from '{links[index - 1]}'.`
		end
		local other = claimed[address]
		if other ~= nil then
			return `'{address}' is in both the IK chains '{other.name}' and '{name}', so only '{other.name}' solves it.`
		end
	end
	if controls[chain.target] == nil then
		return `The IK chain '{name}' reaches for '{chain.target}', which this rig cannot place.`
	end
	return nil
end

local function tipOf(chain: Chain, rig: Rig, pivots: { [string]: CFrame }): CFrame?
	if chain.solver ~= "Aim" then
		return nil
	end
	local address = chain.joints[#chain.joints]
	local joint = if address ~= nil then rig.joints[address] else nil
	local pivot = if address ~= nil then pivots[address] else nil
	local controlRig = rig.controlRig
	local control = if controlRig ~= nil then controlRig.controls[chain.target] else nil
	if joint == nil or pivot == nil or control == nil then
		return nil
	end
	local rest = restOfControl(control, pivots, rig.root)
	if rest == nil then
		return nil
	end
	local onPivot = pivot:Inverse() * rest
	local point = chain.tip
	if point == nil then
		return onPivot
	end
	local on = joint.childOffset:Inverse() * Vector3.new(point[1], point[2], point[3])
	return CFrame.new(on) * onPivot.Rotation
end

local function tipRestOf(chain: Chain, rig: Rig, tip: CFrame?): TipRest?
	if chain.solver ~= "Aim" or tip == nil then
		return nil
	end
	local joint = rig.joints[chain.joints[#chain.joints]]
	if joint == nil then
		return nil
	end
	local given = chain.tip
	return {
		point = if given ~= nil
			then Vector3.new(given[1], given[2], given[3])
			else joint.childOffset * tip.Position,
		turn = tip.Rotation,
		part = joint.childOffset,
	}
