end

local fonts: { [string]: Enum.Font | false } = {}

local function namedFont(name: string): Enum.Font?
	local found: (Enum.Font | false)? = fonts[name]
	if found == nil then
		local ok, font = pcall(function()
			return (Enum.Font :: any)[name]
		end)
		local named: Enum.Font | false = if ok and typeof(font) == "EnumItem"
			then font :: Enum.Font
			else false
		fonts[name] = named
		found = named
	end
	return if found == false then nil else found :: Enum.Font
end

local function fontFor(name: string?, style: string, speaker: boolean): Enum.Font
	local heavy = speaker or style == "Title"
	if name == nil or name == "Gotham" then
		if style == "Title" and not speaker then
			return Enum.Font.GothamBlack
		end
		return if speaker then Enum.Font.GothamBold else Enum.Font.GothamMedium
	elseif name == "BuilderSans" then
		return if heavy then Enum.Font.BuilderSansBold else Enum.Font.BuilderSansMedium
	elseif name == "SourceSans" then
		return if heavy then Enum.Font.SourceSansBold else Enum.Font.SourceSansSemibold
	elseif name == "Arial" then
		return if heavy then Enum.Font.ArialBold else Enum.Font.Arial
	end
	return namedFont(name) or Enum.Font.GothamMedium
end

local function put(canvas: Canvas, instance: Instance, property: string, value: any)
	local written = canvas.written[instance]
	if written == nil then
		written = {}
		canvas.written[instance] = written
	end
	if written[property] ~= value then
		(instance :: any)[property] = value
		written[property] = value
	end
end

local function frame(canvas: Canvas, name: string, parent: Instance): Instance
	local made = canvas.make("Frame")
	made.Name = name
	local any = made :: any
	any.BackgroundTransparency = 1
	any.BorderSizePixel = 0
	any.Active = false
	made.Parent = parent
	return made
end

local function child(canvas: Canvas, className: string, parent: Instance): Instance
	local made = canvas.make(className)
	made.Parent = parent
	return made
end

function ScreenDraw.gui(name: string, order: number, make: Make?): Instance
	local gui = (make or defaultMake)("ScreenGui")
	gui.Name = name
	gui.Archivable = false
	local any = gui :: any
	any.ResetOnSpawn = false
	any.IgnoreGuiInset = true
	any.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	any.DisplayOrder = order
	return gui
end

function ScreenDraw.new(parent: Instance, options: Options?): Canvas
	local given: Options = options or {}
	local canvas: Canvas = {
		root = nil :: any,
		make = given.make or defaultMake,
		smallest = given.smallest or ScreenDraw.SMALLEST_TEXT,
		groups = {},
		bands = {},
		bars = {},
		cover = nil,
		lines = {},
		written = {},
	}
	local root = frame(canvas, "ApexScreen", parent)
	local any = root :: any
	any.Size = UDim2.fromScale(1, 1)
	any.ClipsDescendants = true
	canvas.root = root
	return canvas
end

local function group(canvas: Canvas, name: string): Instance
	local found = canvas.groups[name]
	if found ~= nil then
		return found
	end
	local made = frame(canvas, name, canvas.root)
	local any = made :: any
	any.Size = UDim2.fromScale(1, 1)
	any.ZIndex = table.find(GROUPS, name) or 1
	canvas.groups[name] = made
	return made
end

local function showGroup(canvas: Canvas, name: string, shown: boolean): Instance?
	if not shown then
		local found = canvas.groups[name]
		if found ~= nil then
			put(canvas, found, "Visible", false)
		end
		return nil
	end
	local made = group(canvas, name)
	put(canvas, made, "Visible", true)
	return made
end

local function drawEdges(canvas: Canvas, look: ScreenEval.Look, size: Vector2)
	local amount = look.edges
	local holder = showGroup(canvas, "Edges", amount > 0)
	if holder == nil then
		return
	end
	local depth = math.max(look.edgeSize * size.Y, 0)
	local tone = color3(look.edgeColor, BLACK)
	for index, band in BANDS do
		local piece = canvas.bands[index]
		if piece == nil then
			piece = frame(canvas, band.name, holder)
			local any = piece :: any
			any.AnchorPoint = band.anchor
			any.Position = band.position
			local fade = canvas.make("UIGradient")
			local fadeAny = fade :: any
			fadeAny.Transparency = NumberSequence.new(BAND_FADE)
			fadeAny.Rotation = band.rotation
			fade.Parent = piece
			canvas.bands[index] = piece
		end
		local across = band.name == "Top" or band.name == "Bottom"
		put(
			canvas,
			piece,
			"Size",
			if across then UDim2.new(1, 0, 0, depth) else UDim2.new(0, depth, 1, 0)
		)
		put(canvas, piece, "BackgroundColor3", tone)
		put(canvas, piece, "BackgroundTransparency", 1 - amount)
	end
end

local function drawBars(canvas: Canvas, share: number, rgb: { number })
	local holder = showGroup(canvas, "Bars", share > 0)
	if holder == nil then
		return
	end
	local tone = color3(rgb, BLACK)
	for index = 1, 2 do
		local piece = canvas.bars[index]
		if piece == nil then
			piece = frame(canvas, if index == 1 then "Top" else "Bottom", holder)
			local any = piece :: any
			any.BackgroundTransparency = 0
			if index == 2 then
				any.AnchorPoint = Vector2.new(0, 1)
				any.Position = UDim2.fromScale(0, 1)
			end
			canvas.bars[index] = piece
		end
		put(canvas, piece, "Size", UDim2.fromScale(1, share))
		put(canvas, piece, "BackgroundColor3", tone)
	end
end

local function drawFade(canvas: Canvas, amount: number, rgb: { number })
	local holder = showGroup(canvas, "Fade", amount > 0)
	if holder == nil then
		return
	end
	local cover = canvas.cover
	if cover == nil then
		cover = frame(canvas, "Cover", holder)
		local any = cover :: any
		any.Size = UDim2.fromScale(1, 1)
		canvas.cover = cover
	end
	local piece = cover :: Instance
	put(canvas, piece, "BackgroundColor3", color3(rgb, BLACK))
	put(canvas, piece, "BackgroundTransparency", 1 - amount)
end

local function label(canvas: Canvas, name: string, parent: Instance, order: number): Instance
	local made = canvas.make("TextLabel")
	made.Name = name
	local any = made :: any
	any.BackgroundTransparency = 1
	any.BorderSizePixel = 0
	any.Active = false
	any.TextWrapped = true
	any.TextStrokeColor3 = BLACK
	any.AutoLocalize = true
	any.LayoutOrder = order
	any.Text = ""
	made.Parent = parent
	return made
end

local function line(canvas: Canvas, index: number, holder: Instance): Line
	local found = canvas.lines[index]
	if found ~= nil then
		return found
	end
	local made = frame(canvas, "Line", holder)
	local layout = child(canvas, "UIListLayout", made)
	local layoutAny = layout :: any
	layoutAny.SortOrder = Enum.SortOrder.LayoutOrder
	layoutAny.FillDirection = Enum.FillDirection.Vertical
	layoutAny.VerticalAlignment = Enum.VerticalAlignment.Top
	local stroke = child(canvas, "UIStroke", made)
	local strokeAny = stroke :: any
	strokeAny.Color = WHITE
	strokeAny.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	local speaker = label(canvas, "Speaker", made, 1)
	local text = label(canvas, "Text", made, 2)
	local entry: Line = {
		frame = made,
		speaker = speaker,
		text = text,
		layout = layout,
		padding = child(canvas, "UIPadding", made),
		corner = child(canvas, "UICorner", made),
		stroke = stroke,
		limit = child(canvas, "UISizeConstraint", made),
		speakerLimit = child(canvas, "UISizeConstraint", speaker),
		textLimit = child(canvas, "UISizeConstraint", text),
		clip = nil,
	}
	canvas.lines[index] = entry
	return entry
end

local function textSizes(canvas: Canvas, style: StyleLook, scale: number, height: number)
	local textSize = math.max(
		math.floor(height * ScreenDraw.TEXT_SHARE * style.text * scale + 0.5),
		canvas.smallest
	)
	return textSize, math.max(math.floor(textSize * style.speaker + 0.5), 1)
end

local function drawLabel(
	canvas: Canvas,
	piece: Instance,
	limit: Instance,
	style: StyleLook,
	room: number,
	writing: { [string]: any }
)
	if style.hug then
		put(canvas, piece, "Size", UDim2.new())
		put(canvas, piece, "AutomaticSize", Enum.AutomaticSize.XY)
		put(canvas, limit, "MaxSize", Vector2.new(math.max(room, 1), math.huge))
	else
		put(canvas, piece, "Size", UDim2.fromScale(1, 0))
		put(canvas, piece, "AutomaticSize", Enum.AutomaticSize.Y)
		put(canvas, limit, "MaxSize", HUGE)
	end
	put(
		canvas,
		piece,
		"TextXAlignment",
		if style.left then Enum.TextXAlignment.Left else Enum.TextXAlignment.Center
	)
	for property, value in writing do
		put(canvas, piece, property, value)
	end
end

local function drawLine(
	canvas: Canvas,
	entry: Line,
	each: ScreenEval.Line,
	bars: number,
	size: Vector2
)
	local style = STYLES[each.style] or STYLES.Plain
	local alpha = each.alpha
	local hidden = 1 - alpha
	local textSize, speakerSize = textSizes(canvas, style, each.scale, size.Y)
	local padX = if style.box ~= nil then math.floor(textSize * 0.7 + 0.5) else 0
	local padY = if style.box ~= nil then math.floor(textSize * 0.45 + 0.5) else 0
	local width = math.floor(size.X * style.width + 0.5)
	local block = entry.frame

	put(canvas, block, "Visible", true)
	put(canvas, block, "LayoutOrder", each.clip)
	if each.x ~= nil and each.y ~= nil then
		put(canvas, block, "AnchorPoint", Vector2.new(0.5, 0.5))
		put(canvas, block, "Position", UDim2.fromScale(each.x, each.y))
	elseif style.middle then
		put(canvas, block, "AnchorPoint", Vector2.new(0.5, 0.5))
		put(canvas, block, "Position", UDim2.fromScale(0.5, 0.5))
	else
		local gap = math.floor(size.Y * ScreenDraw.GAP + 0.5)
		put(canvas, block, "AnchorPoint", Vector2.new(0.5, 1))
		put(canvas, block, "Position", UDim2.new(0.5, 0, 1 - bars, -gap))
	end
	if style.hug then
		put(canvas, block, "Size", UDim2.new())
		put(canvas, block, "AutomaticSize", Enum.AutomaticSize.XY)
		put(canvas, entry.limit, "MinSize", Vector2.zero)
	else
		put(canvas, block, "Size", UDim2.fromOffset(width, 0))
		put(canvas, block, "AutomaticSize", Enum.AutomaticSize.Y)
		local least = if style.lines > 0
			then math.floor(speakerSize * 1.3 + textSize * 1.25 * style.lines + padY * 2 + 0.5)
			else 0
		put(canvas, entry.limit, "MinSize", Vector2.new(0, least))
	end
	put(canvas, entry.limit, "MaxSize", HUGE)

	local box = style.box
	put(canvas, block, "BackgroundColor3", BOX_COLOR)
	put(canvas, block, "BackgroundTransparency", if box ~= nil then 1 - (1 - box) * alpha else 1)
	put(
		canvas,
		entry.corner,
		"CornerRadius",
		UDim.new(0, if box ~= nil then math.floor(textSize * 0.4 + 0.5) else 0)
	)
	put(canvas, entry.stroke, "Enabled", style.border)
	put(canvas, entry.stroke, "Thickness", math.max(math.floor(textSize / 12 + 0.5), 1))
	put(canvas, entry.stroke, "Transparency", 1 - BORDER * alpha)
	put(canvas, entry.padding, "PaddingLeft", UDim.new(0, padX))
	put(canvas, entry.padding, "PaddingRight", UDim.new(0, padX))
	put(canvas, entry.padding, "PaddingTop", UDim.new(0, padY))
	put(canvas, entry.padding, "PaddingBottom", UDim.new(0, padY))
	put(
		canvas,
		entry.layout,
		"HorizontalAlignment",
		if style.left then Enum.HorizontalAlignment.Left else Enum.HorizontalAlignment.Center
	)
	put(canvas, entry.layout, "Padding", UDim.new(0, math.floor(textSize * 0.15 + 0.5)))

	local room = width - padX * 2
	local stroke = if style.outline then 1 - alpha * STROKE else 1
	local speaker = each.speaker
	put(canvas, entry.speaker, "Visible", speaker ~= nil)
	if speaker ~= nil then
		drawLabel(canvas, entry.speaker, entry.speakerLimit, style, room, {
			Text = speaker,
			Font = fontFor(each.font, each.style, true),
			TextSize = speakerSize,
			TextColor3 = color3(each.speakerColor, SPEAKER_COLOR),
			TextTransparency = hidden,
			TextStrokeTransparency = stroke,
		})
	end
	drawLabel(canvas, entry.text, entry.textLimit, style, room, {
		Text = each.text,
		Font = fontFor(each.font, each.style, false),
		TextSize = textSize,
		TextColor3 = color3(each.color, WHITE),
		TextTransparency = hidden,
		TextStrokeTransparency = stroke,
		MaxVisibleGraphemes = if each.shown ~= nil then each.shown else -1,
	})
end

local function drawSubtitles(canvas: Canvas, look: ScreenEval.Look, size: Vector2)
	local lines = look.lines
	local holder = showGroup(canvas, "Subtitles", #lines > 0)
	local shown = 0
	if holder ~= nil then
		for _, each in lines do
			shown += 1
			local entry = line(canvas, shown, holder)
			entry.clip = each.clip
			drawLine(canvas, entry, each, look.bars, size)
		end
	end
	for index = shown + 1, #canvas.lines do
		local entry = canvas.lines[index]
		entry.clip = nil
		put(canvas, entry.frame, "Visible", false)
	end
end

function ScreenDraw.draw(canvas: Canvas, look: ScreenEval.Look, size: Vector2): boolean
	put(canvas, canvas.root, "Visible", true)
	drawEdges(canvas, look, size)
	drawBars(canvas, look.bars, look.barColor)
	drawFade(canvas, look.fade, look.fadeColor)
	drawSubtitles(canvas, look, size)
	return not ScreenEval.quiet(look)
end

function ScreenDraw.lineBounds(canvas: Canvas, clip: number): (Vector2?, Vector2?)
	for _, entry in canvas.lines do
		if entry.clip == clip then
			local block = entry.frame :: any
			return block.AbsolutePosition, block.AbsoluteSize
		end
	end
	return nil, nil
end

function ScreenDraw.lineAt(canvas: Canvas, point: Vector2): number?
	for index = #canvas.lines, 1, -1 do
		local entry = canvas.lines[index]
		local clip = entry.clip
		if clip == nil then
			continue
		end
		local block = entry.frame :: any
		local corner, extent = block.AbsolutePosition, block.AbsoluteSize
		local offset = point - corner
		if offset.X >= 0 and offset.Y >= 0 and offset.X <= extent.X and offset.Y <= extent.Y then
			return clip
		end
	end
	return nil
end

function ScreenDraw.hide(canvas: Canvas)
	put(canvas, canvas.root, "Visible", false)
	for _, entry in canvas.lines do
		entry.clip = nil
	end
end

function ScreenDraw.destroy(canvas: Canvas)
	local root = canvas.root
	pcall(function()
		root:Destroy()
	end)
	table.clear(canvas.groups)
	table.clear(canvas.bands)
	table.clear(canvas.bars)
	table.clear(canvas.lines)
	canvas.cover = nil
	table.clear(canvas.written)
end

return ScreenDraw
