--!strict

local ScreenEval = {}

export type Kind = "Bars" | "Fade" | "Edges" | "Subtitle"
export type Style = "Plain" | "Box" | "Dialogue" | "Title"
export type Reveal = "Fade" | "Typewriter" | "Words"

export type Clip = {
	kind: Kind,
	t: number,
	len: number,
	fadeIn: number?,
	fadeOut: number?,
	size: number?,
	color: { number }?,
	amount: number?,
	text: string?,
	speaker: string?,
	speakerColor: { number }?,
	style: Style?,
	scale: number?,
	font: string?,
	x: number?,
	y: number?,
	reveal: Reveal?,
	speed: number?,
}

export type Line = {
	text: string,
	speaker: string?,
	style: Style,
	scale: number,
	font: string?,
	color: { number }?,
	speakerColor: { number }?,
	x: number?,
	y: number?,
	alpha: number,
	shown: number?,
	clip: number,
}

export type Look = {
	bars: number,
	barColor: { number },
	fade: number,
	fadeColor: { number },
	edges: number,
	edgeColor: { number },
	edgeSize: number,
	lines: { Line },
}

ScreenEval.DEFAULT_BAR_SIZE = 0.12

ScreenEval.DEFAULT_EDGE_SIZE = 0.4

ScreenEval.TYPE_SPEED = 30
ScreenEval.WORD_SPEED = 4

local BLACK = table.freeze({ 0, 0, 0 })

function ScreenEval.blank(): Look
	return {
		bars = 0,
		barColor = BLACK,
		fade = 0,
		fadeColor = BLACK,
		edges = 0,
		edgeColor = BLACK,
		edgeSize = ScreenEval.DEFAULT_EDGE_SIZE,
		lines = {},
	}
end

local function smooth(x: number): number
	return x * x * (3 - 2 * x)
end

function ScreenEval.weight(clip: Clip, time: number): number
	local into = time - clip.t
	if into < 0 or into >= clip.len then
		return 0
	end
	local rise = clip.fadeIn or 0
	local fall = clip.fadeOut or 0
	local x = 1
	if rise > 0 then
		x = math.min(x, into / rise)
	end
	if fall > 0 then
		x = math.min(x, (clip.len - into) / fall)
	end
	return smooth(math.clamp(x, 0, 1))
end

local function wordEnds(text: string): { number }
	local ends: { number } = {}
	local count = 0
	local inWord = false
	for _, code in utf8.codes(text) do
		count += 1
		local space = code == 32 or code == 9 or code == 10 or code == 13
		if space and inWord then
			table.insert(ends, count - 1)
		end
		inWord = not space
	end
	if inWord then
		table.insert(ends, count)
	end
	return ends
end

function ScreenEval.speedOf(clip: Clip): number?
	if clip.reveal == "Typewriter" then
		return clip.speed or ScreenEval.TYPE_SPEED
	elseif clip.reveal == "Words" then
		return clip.speed or ScreenEval.WORD_SPEED
	end
	return nil
end

function ScreenEval.shownAt(clip: Clip, into: number): number?
	local speed = ScreenEval.speedOf(clip)
	local text = clip.text or ""
	if speed == nil or text == "" then
		return nil
	end
	local steps = math.floor(math.max(into, 0) * speed + 1e-6)
	if clip.reveal == "Typewriter" then
		return if steps >= (utf8.len(text) or #text) then nil else steps
	end
	local ends = wordEnds(text)
	if steps + 1 >= #ends then
		return nil
	end
	return ends[steps + 1]
end

function ScreenEval.typingTime(clip: Clip): number
	local speed = ScreenEval.speedOf(clip)
	local text = clip.text or ""
	if speed == nil or text == "" then
		return 0
	end
	if clip.reveal == "Typewriter" then
		return (utf8.len(text) or #text) / speed
	end
	return math.max(#wordEnds(text) - 1, 0) / speed
end

function ScreenEval.at(clips: { Clip }?, time: number, into: Look?): Look
	local look = into or ScreenEval.blank()
	look.bars, look.barColor = 0, BLACK
	look.fade, look.fadeColor = 0, BLACK
	look.edges, look.edgeColor, look.edgeSize = 0, BLACK, ScreenEval.DEFAULT_EDGE_SIZE
	local count = 0
	for index, clip in clips or {} do
		if clip.t > time then
			break
		end
		local weight = ScreenEval.weight(clip, time)
		if weight <= 0 then
			continue
		end
		local kind = clip.kind
		if kind == "Bars" then
			local bars = (clip.size or ScreenEval.DEFAULT_BAR_SIZE) * weight
			if bars > look.bars then
				look.bars = bars
				look.barColor = clip.color or BLACK
			end
		elseif kind == "Fade" then
			local fade = (clip.amount or 1) * weight
			if fade > look.fade then
				look.fade = fade
				look.fadeColor = clip.color or BLACK
			end
		elseif kind == "Edges" then
			local edges = (clip.amount or 1) * weight
			if edges > look.edges then
				look.edges = edges
				look.edgeColor = clip.color or BLACK
				look.edgeSize = clip.size or ScreenEval.DEFAULT_EDGE_SIZE
			end
		elseif kind == "Subtitle" then
			local text = clip.text or ""
			if text == "" then
				continue
			end
			count += 1
			local line = look.lines[count]
			if line == nil then
				line = { text = text, style = "Plain", scale = 1, alpha = 0, clip = index }
				look.lines[count] = line
			end
			local placed = clip.x ~= nil and clip.y ~= nil
			line.text = text
			line.speaker = if clip.speaker ~= "" then clip.speaker else nil
			line.style = clip.style or "Plain"
			line.scale = clip.scale or 1
			line.font = clip.font
			line.color = clip.color
			line.speakerColor = clip.speakerColor
			line.x = if placed then clip.x else nil
			line.y = if placed then clip.y else nil
			line.alpha = weight
			line.shown = ScreenEval.shownAt(clip, time - clip.t)
			line.clip = index
		end
	end
	for index = #look.lines, count + 1, -1 do
		look.lines[index] = nil
	end
	return look
end

function ScreenEval.quiet(look: Look): boolean
	return look.bars <= 0 and look.fade <= 0 and look.edges <= 0 and #look.lines == 0
end

function ScreenEval.finish(clips: { Clip }?): number
	local latest = 0
	for _, clip in clips or {} do
		latest = math.max(latest, clip.t + clip.len)
	end
	return latest
end

return ScreenEval
