--!strict

local SlotCheck = {}

export type Requirement = {
	kind: "R15" | "R6" | "Signature",
	joints: { string }?,
}

SlotCheck.R15_JOINTS = table.freeze({
	"LowerTorso",
	"UpperTorso",
	"Head",
	"LeftUpperArm",
	"LeftLowerArm",
	"LeftHand",
	"RightUpperArm",
	"RightLowerArm",
	"RightHand",
	"LeftUpperLeg",
	"LeftLowerLeg",
	"LeftFoot",
	"RightUpperLeg",
	"RightLowerLeg",
	"RightFoot",
})

SlotCheck.R6_JOINTS = table.freeze({
	"Torso",
	"Head",
	"Left Arm",
	"Right Arm",
	"Left Leg",
	"Right Leg",
})

SlotCheck.LIST_LIMIT = 4

function SlotCheck.listOf(names: { string }): string
	local limit = SlotCheck.LIST_LIMIT
	local shown: { string } = {}
	for index = 1, math.min(#names, limit) do
		table.insert(shown, `'{names[index]}'`)
	end
	if #names > limit then
		return `{table.concat(shown, ", ")} and {#names - limit} more`
	elseif #shown <= 1 then
		return shown[1] or ""
	end
	return `{table.concat(shown, ", ", 1, #shown - 1)} and {shown[#shown]}`
end

function SlotCheck.jointsOf(requirement: Requirement): { string }
	if requirement.kind == "R15" then
		return SlotCheck.R15_JOINTS
	elseif requirement.kind == "R6" then
		return SlotCheck.R6_JOINTS
	end
	return requirement.joints or {}
end

function SlotCheck.missing(requirement: Requirement, present: { [string]: any }): { string }
	local absent: { string } = {}
	for _, address in SlotCheck.jointsOf(requirement) do
		if present[address] == nil then
			table.insert(absent, address)
		end
	end
	return absent
end

function SlotCheck.check(requirement: Requirement, present: { [string]: any }): (boolean, string?)
	local absent = SlotCheck.missing(requirement, present)
	if #absent == 0 then
		return true, nil
	end
	local list = SlotCheck.listOf(absent)
	if requirement.kind == "R15" or requirement.kind == "R6" then
		return false,
			`This slot needs an {requirement.kind} character, and this rig is not one: it has no {list}.`
	end
	return false, `This rig cannot play the slot: it has no {list}, which the animation moves.`
end

function SlotCheck.describe(requirement: Requirement): string
	if requirement.kind == "R15" or requirement.kind == "R6" then
		return `any {requirement.kind} character`
	end
	local joints = requirement.joints or {}
	if #joints == 1 then
		return `a rig with the joint {SlotCheck.listOf(joints)}`
	end
	return `a rig with the joints {SlotCheck.listOf(joints)}`
end

return SlotCheck
