--!strict

local Interp = require(script.Parent.Interp)

local SoundPlay = {}

SoundPlay.DEFAULT_VOLUME = 0.5
SoundPlay.DRIFT = 0.12
SoundPlay.SETTLE = 0.3
SoundPlay.MIN_LEFT = 0.02

export type Fade = {
	len: number,
	interp: string?,
	easing: string?,
	params: { [string]: number }?,
	preset: string?,
}

export type Clip = {
	t: number,
	len: number,
	from: number?,
	volume: number?,
	fadeIn: Fade?,
	fadeOut: Fade?,
}

export type Track = {
	name: string,
	id: string,
	source: string?,
	duration: number,
	volume: number?,
	speed: number?,
	clips: { Clip },
}

export type Backend = {
	start: (track: Track, clip: Clip, position: number, speed: number, volume: number) -> any?,
	set: (handle: any, volume: number, speed: number) -> (),
	seek: (handle: any, position: number) -> (),
	position: (handle: any) -> number?,
	pause: (handle: any) -> (),
	resume: (handle: any, position: number) -> (),
	stop: (handle: any) -> (),
}

export type Voice = {
	track: number,
	clip: number,
	handle: any,
	free: boolean,
	at: number,
	rate: number,
	settled: number,
	paused: boolean,
}

export type Player = {
	tracks: { Track },
	backend: Backend,
	presets: { [string]: any }?,
	voices: { Voice },
	time: number?,
}

export type Step = {
	time: number,
	speed: number,
	dt: number,
	length: number,
	jumped: boolean?,
	wrapped: boolean?,
}

local UNIT: Interp.Channel = { keys = { { t = 0, v = 0 }, { t = 1, v = 1 } } }
Interp.recalcHandles(UNIT.keys)

function SoundPlay.new(tracks: { Track }, backend: Backend, presets: { [string]: any }?): Player
	return { tracks = tracks, backend = backend, presets = presets, voices = {}, time = nil }
end

function SoundPlay.shape(fade: Fade, x: number, presets: { [string]: any }?): number
	if x <= 0 then
		return 0
	elseif x >= 1 then
		return 1
	end
	if fade.preset ~= nil and presets ~= nil then
		local preset = presets[fade.preset]
		if preset ~= nil and preset.points ~= nil and #preset.points >= 2 then
			return math.clamp(Interp.presetAt(preset, x), 0, 1)
		end
	end
	local mode = fade.interp or "Linear"
	if mode == "Linear" then
		return x
	elseif mode == "Constant" then
		return 0
	elseif mode == "Bezier" then
		return math.clamp(Interp.evaluate(UNIT, x), 0, 1)
	end
	return math.clamp(
		Interp.ease(mode :: any, fade.easing :: any, x, 0, 1, 1, fade.params :: any),
		0,
		1
	)
end

function SoundPlay.fadeAt(clip: Clip, at: number, presets: { [string]: any }?): number
	local gain = 1
	local fadeIn = clip.fadeIn
	if fadeIn ~= nil and fadeIn.len > 0 and at < fadeIn.len then
		gain *= SoundPlay.shape(fadeIn, at / fadeIn.len, presets)
	end
	local fadeOut = clip.fadeOut
	if fadeOut ~= nil and fadeOut.len > 0 then
		local start = clip.len - fadeOut.len
		if at > start then
			gain *= 1 - SoundPlay.shape(fadeOut, (at - start) / fadeOut.len, presets)
		end
	end
	return gain
end

function SoundPlay.volumeAt(
	track: Track,
	clip: Clip,
	at: number,
	presets: { [string]: any }?
): number
	return (track.volume or SoundPlay.DEFAULT_VOLUME)
		* (clip.volume or 1)
		* SoundPlay.fadeAt(clip, at, presets)
end

function SoundPlay.positionAt(track: Track, clip: Clip, at: number): number
	return (clip.from or 0) + at * (track.speed or 1)
end

function SoundPlay.clipAt(clips: { Clip }, t: number): number?
	local low, high = 1, #clips
	local found: number? = nil
	while low <= high do
		local middle = (low + high) // 2
		if clips[middle].t <= t then
			found = middle
			low = middle + 1
		else
			high = middle - 1
		end
	end
	if found ~= nil then
		local clip = clips[found]
		if t < clip.t + clip.len then
			return found
		end
	end
	return nil
end

local function stopVoice(player: Player, voice: Voice)
	pcall(player.backend.stop, voice.handle)
end

local function refresh(player: Player, voice: Voice, at: number, speed: number)
	local track = player.tracks[voice.track]
	local clip = track.clips[voice.clip]
	pcall(
		player.backend.set,
		voice.handle,
		SoundPlay.volumeAt(track, clip, at, player.presets),
		(track.speed or 1) * speed
	)
end

local function tickFree(player: Player, dt: number)
	local voices = player.voices
	local index = 1
	while index <= #voices do
		local voice = voices[index]
		if voice.free then
			voice.at += dt * voice.rate
			local clip = player.tracks[voice.track].clips[voice.clip]
			if voice.at >= clip.len then
				stopVoice(player, voice)
				table.remove(voices, index)
				continue
			end
			refresh(player, voice, voice.at, voice.rate)
		end
		index += 1
	end
end

local function synced(player: Player, track: number): (Voice?, number?)
	for index, voice in player.voices do
		if not voice.free and voice.track == track then
			return voice, index
		end
	end
	return nil, nil
end

local function release(player: Player, voice: Voice, at: number, rate: number)
	local clip = player.tracks[voice.track].clips[voice.clip]
	if at >= clip.len or rate <= 0 then
		stopVoice(player, voice)
		local index = table.find(player.voices, voice)
		if index ~= nil then
			table.remove(player.voices, index)
		end
		return
	end
	voice.free = true
	voice.at = at
	voice.rate = rate
	if voice.paused then
		voice.paused = false
		pcall(
			player.backend.resume,
			voice.handle,
			SoundPlay.positionAt(player.tracks[voice.track], clip, at)
		)
	end
end

function SoundPlay.step(player: Player, step: Step)
	tickFree(player, step.dt)
	local t = step.time
	local speed = step.speed
	local previous = player.time
	for index, track in player.tracks do
		local want = if speed >= 0 then SoundPlay.clipAt(track.clips, t) else nil
		local voice = synced(player, index)
		if voice ~= nil and (voice.clip ~= want or step.wrapped == true) then
			local clip = track.clips[voice.clip]
			local runsOver = clip.t + clip.len > step.length
			if step.wrapped == true and runsOver and previous ~= nil then
				release(player, voice, step.length - clip.t + t, if speed > 0 then speed else 1)
			else
				stopVoice(player, voice)
				table.remove(player.voices, table.find(player.voices, voice) :: number)
			end
			voice = nil
		end
		if want == nil then
			continue
		end
		local clip = track.clips[want]
		local at = t - clip.t
		local position = SoundPlay.positionAt(track, clip, at)
		if voice == nil then
			if speed > 0 and clip.len - at > SoundPlay.MIN_LEFT then
				local ok, handle = pcall(
					player.backend.start,
					track,
					clip,
					position,
					(track.speed or 1) * speed,
					SoundPlay.volumeAt(track, clip, at, player.presets)
				)
				if ok and handle ~= nil then
					table.insert(player.voices, {
						track = index,
						clip = want,
						handle = handle,
						free = false,
						at = at,
						rate = speed,
						settled = 0,
						paused = false,
					})
				end
			end
			continue
		end
		local live = voice :: Voice
		live.at = at
		live.rate = speed
		if speed == 0 then
			if not live.paused then
				live.paused = true
				pcall(player.backend.pause, live.handle)
			end
			continue
		end
		if live.paused then
			live.paused = false
			live.settled = 0
			pcall(player.backend.resume, live.handle, position)
		elseif step.jumped == true then
			live.settled = 0
			pcall(player.backend.seek, live.handle, position)
		else
			live.settled += step.dt
			if live.settled >= SoundPlay.SETTLE then
				local ok, heard = pcall(player.backend.position, live.handle)
				if
					ok
					and type(heard) == "number"
					and math.abs(heard - position) > SoundPlay.DRIFT * (track.speed or 1)
				then
					live.settled = 0
					pcall(player.backend.seek, live.handle, position)
				end
			end
		end
		refresh(player, live, at, speed)
	end
	player.time = t
end

function SoundPlay.playOut(player: Player, rate: number?)
	local speed = if rate ~= nil and rate > 0 then rate else 1
	for _, voice in table.clone(player.voices) do
		if not voice.free then
			release(player, voice, voice.at, speed)
		end
	end
end

function SoundPlay.stop(player: Player)
	for _, voice in player.voices do
		stopVoice(player, voice)
	end
	table.clear(player.voices)
	player.time = nil
end

function SoundPlay.tick(player: Player, dt: number)
	tickFree(player, dt)
end

function SoundPlay.busy(player: Player): boolean
	return #player.voices > 0
end

return SoundPlay
