--!strict

local Modifiers = require(script.Parent.Modifiers)

local StateEval = {}

StateEval.BEGIN = ".Begin"
StateEval.END = ".End"

StateEval.SLACK = 0.1

export type StateValue = string | number | boolean

export type Payload = { [string]: StateValue }

export type Span = {
	t: number,
	len: number,
	payload: Payload?,
}

export type Step = {
	t: number,
	value: StateValue,
	payload: Payload?,
}

export type StateTrack = {
	name: string,
	kind: "Span" | "Stepped" | "Curve",
	spans: { Span }?,
	steps: { Step }?,
	curve: Modifiers.Channel?,
	nativeMarkers: boolean?,
}

export type EvalOptions = Modifiers.EvalOptions

export type SpanEdge = {
	began: boolean,
	t: number,
	index: number,
	payload: Payload?,
}

export type Travel = "Forward" | "Backward" | "Jump"

export type Sighting = {
	from: number?,
	to: number,
	speed: number,
	lastSpeed: number?,
	dt: number,
	looped: boolean,
	length: number,
	late: boolean?,
}

export type NativeMarker = {
	name: string,
	t: number,
	value: string,
}

function StateEval.spanAt(track: StateTrack, t: number): number?
	local spans = track.spans
	if spans == nil then
		return nil
	end
	local lo, hi, found = 1, #spans, 0
	while lo <= hi do
		local mid = (lo + hi) // 2
		if spans[mid].t <= t then
			found = mid
			lo = mid + 1
		else
			hi = mid - 1
		end
	end
	if found == 0 then
		return nil
	end
	local span = spans[found]
	return if t < span.t + span.len then found else nil
end

function StateEval.stepAt(track: StateTrack, t: number): number?
	local steps = track.steps
	if steps == nil then
		return nil
	end
	local lo, hi, found = 1, #steps, 0
	while lo <= hi do
		local mid = (lo + hi) // 2
		if steps[mid].t <= t then
			found = mid
			lo = mid + 1
		else
			hi = mid - 1
		end
	end
	return if found == 0 then nil else found
end

function StateEval.curveAt(track: StateTrack, t: number, options: EvalOptions?): number
	local curve = track.curve
	if curve == nil then
		return 0
	end
	return Modifiers.evaluate(curve, t, options)
end

function StateEval.valueAt(
	track: StateTrack,
	t: number,
	options: EvalOptions?
): (StateValue?, Payload?)
	if track.kind == "Span" then
		local index = StateEval.spanAt(track, t)
		if index == nil then
			return false, nil
		end
		return true, (track.spans :: { Span })[index].payload
	elseif track.kind == "Stepped" then
		local index = StateEval.stepAt(track, t)
		if index == nil then
			return nil, nil
		end
		local step = (track.steps :: { Step })[index]
		return step.value, step.payload
	end
	return StateEval.curveAt(track, t, options), nil
end

function StateEval.idleValue(track: StateTrack): StateValue?
	return if track.kind == "Span" then false else nil
end

type Part = {
	lo: number,
	hi: number,
	down: boolean,
}

local function partsOf(from: number, to: number, reverse: boolean?): { Part }
	if reverse then
		if to <= from then
			return { { lo = to, hi = from, down = true } }
		end
		return {
			{ lo = -math.huge, hi = from, down = true },
			{ lo = to, hi = math.huge, down = true },
		}
	end
	if to >= from then
		return { { lo = from, hi = to, down = false } }
	end
	return {
		{ lo = from, hi = math.huge, down = false },
		{ lo = -math.huge, hi = to, down = false },
	}
end

local function inside(part: Part, x: number): boolean
	return part.lo < x and x <= part.hi
end

function StateEval.spanEdges(
	track: StateTrack,
	from: number,
	to: number,
	reverse: boolean?
): { SpanEdge }
	local out: { SpanEdge } = {}
	local spans = track.spans
	if spans == nil or #spans == 0 then
		return out
	end
	for _, part in partsOf(from, to, reverse) do
		local found: { SpanEdge } = {}
		for index, span in spans do
			local start, finish = span.t, span.t + span.len
			if inside(part, start) then
				table.insert(
					found,
					{ began = not part.down, t = start, index = index, payload = span.payload }
				)
			end
			if inside(part, finish) then
				table.insert(
					found,
					{ began = part.down, t = finish, index = index, payload = span.payload }
				)
			end
		end
		local down = part.down
		table.sort(found, function(a: SpanEdge, b: SpanEdge): boolean
			if a.t ~= b.t then
				return if down then a.t > b.t else a.t < b.t
			end
			if a.began ~= b.began then
				return not a.began
			end
			return if down then a.index > b.index else a.index < b.index
		end)
		table.move(found, 1, #found, #out + 1, out)
	end
	return out
end

function StateEval.crossed(
	moments: { any },
	from: number,
	to: number,
	reverse: boolean?
): { number }
	local out: { number } = {}
	for _, part in partsOf(from, to, reverse) do
		if part.down then
			for index = #moments, 1, -1 do
				if inside(part, moments[index].t) then
					table.insert(out, index)
				end
			end
		else
			for index = 1, #moments do
				if inside(part, moments[index].t) then
					table.insert(out, index)
				end
			end
		end
	end
	return out
end

function StateEval.travel(sighting: Sighting): Travel
	local speed = sighting.speed
	local last = sighting.lastSpeed or speed
	local direction = if speed ~= 0 then speed else last
	local reach = math.max(math.abs(speed), math.abs(last)) * math.max(sighting.dt, 0)
		+ StateEval.SLACK
	local to, length = sighting.to, sighting.length
	local from = sighting.from
	local backward = direction < 0
	if from == nil then
		if sighting.late then
			return "Jump"
		end
		if backward then
			return if to >= length - reach then "Backward" else "Jump"
		end
		return if to <= reach then "Forward" else "Jump"
	end
	local round = sighting.looped and length > 0
	if backward then
		if to <= from then
			return if from - to <= reach then "Backward" else "Jump"
		end
		return if round and from + (length - to) <= reach then "Backward" else "Jump"
	end
	if to >= from then
		return if to - from <= reach then "Forward" else "Jump"
	end
	return if round and (length - from) + to <= reach then "Forward" else "Jump"
end

local function jsonNumber(n: number): string
	if n % 1 == 0 and math.abs(n) < 2 ^ 53 then
		return string.format("%d", n)
	end
	for _, precision in { "%.7g", "%.10g", "%.14g", "%.15g", "%.16g" } do
		local text = string.format(precision, n)
		if tonumber(text) == n then
			return text
		end
	end
	return string.format("%.17g", n)
end

local ESCAPES: { [string]: string } = {
	['"'] = '\\"',
	["\\"] = "\\\\",
	["\b"] = "\\b",
	["\f"] = "\\f",
	["\n"] = "\\n",
	["\r"] = "\\r",
	["\t"] = "\\t",
}

local function jsonString(text: string): string
	local escaped = string.gsub(text, '[%c"\\]', function(char: string): string
		return ESCAPES[char] or string.format("\\u%04x", string.byte(char))
	end)
	return `"{escaped}"`
end

function StateEval.encodePayload(payload: Payload?): string
	if payload == nil then
		return ""
	end
	local names: { string } = {}
	for name in payload do
		table.insert(names, name)
	end
	if #names == 0 then
		return ""
	end
	table.sort(names)
	local parts: { string } = {}
	for _, name in names do
		local value = payload[name]
		local text = if type(value) == "string"
			then jsonString(value)
			elseif type(value) == "number" then jsonNumber(value)
			else tostring(value)
		table.insert(parts, `{jsonString(name)}:{text}`)
	end
	return "{" .. table.concat(parts, ",") .. "}"
end

function StateEval.nativeMarkers(states: { StateTrack }?): { NativeMarker }
	type Entry = { marker: NativeMarker, order: number, ending: boolean }
	local entries: { Entry } = {}
	for _, state in states or {} do
		if state.kind ~= "Span" or state.nativeMarkers ~= true then
			continue
		end
		for _, span in state.spans or {} do
			local value = StateEval.encodePayload(span.payload)
			table.insert(entries, {
				marker = { name = state.name .. StateEval.BEGIN, t = span.t, value = value },
				order = #entries + 1,
				ending = false,
			})
			table.insert(entries, {
				marker = {
					name = state.name .. StateEval.END,
					t = span.t + span.len,
					value = value,
				},
				order = #entries + 1,
				ending = true,
			})
		end
	end
	table.sort(entries, function(a: Entry, b: Entry): boolean
		if a.marker.t ~= b.marker.t then
			return a.marker.t < b.marker.t
		end
		if a.ending ~= b.ending then
			return a.ending
		end
		return a.order < b.order
	end)
	local out: { NativeMarker } = {}
	for _, entry in entries do
		table.insert(out, entry.marker)
	end
	return out
end

return StateEval
