    ["UhhhhhhReanim/System/runtime/steve110/main/apex_engine.lua"] = [=====[
--!strict

local Sidecar = require(script.Core.Sidecar)
local JointGraph = require(script.Core.JointGraph)
local Registry = require(script.Runtime.Registry)
local ApexTrack = require(script.Runtime.ApexTrack)
local Frame = require(script.Runtime.Frame)
local Props = require(script.Runtime.Props)
local Pivots = require(script.Runtime.Pivots)
local RigState = require(script.Runtime.RigState)
local Spaces = require(script.Runtime.Spaces)
local States = require(script.Runtime.States)
local Movement = require(script.Runtime.Movement)
local Scene = require(script.Scene)
local Releases = require(script.Runtime.Releases)
local Sounds = require(script.Runtime.Sounds)

local IDLE_GRACE = 2

local REGISTRY_NAME = "ApexAnimations"

export type Context = {
	rigStates: RigState.Registry,
	hold: (model: any, on: boolean, name: string?) -> (),
	clock: () -> number,
	warnOnce: (key: string, message: string) -> (),
	server: () -> boolean,
	graphOf: ((model: any) -> any)?,
	topology: (Spaces.Topology | false)?,
}

export type Maker = (context: Context) -> { Frame.Extension }

local EXTENSIONS: { Frame.Extension | Maker } = {
	Spaces.extensions :: Maker,
	Props.extension,
	Pivots.extension,
	Sounds.extensions :: Maker,
	States.extension,
	(function(context: Context): { Frame.Extension }
		return {
			Movement.new({
				warn = function(message: string)
					context.warnOnce(message, message)
				end,
			}),
		}
	end) :: Maker,
	Releases.extension,
}

export type Services = {
	RunService: any,
	Workspace: any,
	ReplicatedStorage: any,
	Players: any?,
}

export type CreateOptions = {
	services: Services?,
	require: ((module: any) -> any)?,
	warn: ((message: string) -> ())?,
	defer: ((fn: () -> ()) -> ())?,
	clock: (() -> number)?,
	newAnimation: ((id: number | string, name: string) -> any)?,
	newWaker: (() -> any)?,
	getClip: ((assetId: number) -> any)?,
	extensions: { Frame.Extension | Maker }?,
	settings: { [string]: number }?,
	server: boolean?,
	studio: boolean?,
	graphOf: ((model: any) -> any)?,
	jointsOf: ((model: any) -> { [string]: any })?,
	topology: (Spaces.Topology | false)?,
}

--[=[
	@interface StartOptions
	@within ApexEngine
	.registry Instance? -- the folder of animation modules, nil is ReplicatedStorage.ApexAnimations
]=]
export type StartOptions = {
	registry: Instance?,
}

--[=[
	@interface SceneOptions
	@within ApexEngine
	.anchor (CFrame | BasePart | Bone | Attachment | Model | string)? -- where the scene plays; a slot's name keeps that rig where it stands
	.camera Camera? -- the camera the scene drives, given back when it stops
	.screen boolean? -- draws the Screen row; nil draws it when a camera is given
	.screenOrder number? -- the Screen row's DisplayOrder
	.look boolean? -- shows the scene's look; nil shows it when a camera is given
]=]

local function create(options: CreateOptions?)
	local config: CreateOptions = options or {}
	--[=[
		@class ApexEngine

		Plays the enhanced parts of Apex animations: spaces, state tracks, prop tracks, the
		movement track and scenes. Native animations never need it.
	]=]
	local ApexEngine = {}

	--[=[
		@prop ENGINE_VERSION string
		@within ApexEngine
		@readonly

		This engine's release. Apex Animator's Update Engine compares it with its own copy.
	]=]
	ApexEngine.ENGINE_VERSION = "0.5.1"

	--[=[
		@prop FORMAT_VERSION number
		@within ApexEngine
		@readonly

		The newest sidecar format this engine reads. Modules exported in a newer one are refused.
	]=]
	ApexEngine.FORMAT_VERSION = Sidecar.FORMAT

	--[=[
		@prop IDLE_GRACE number
		@within ApexEngine
		@readonly

		Seconds the per-frame connection stays up once nothing is playing.
	]=]
	ApexEngine.IDLE_GRACE = IDLE_GRACE

	local warnFn: (message: string) -> () = config.warn or warn
	local clock: () -> number = config.clock or os.clock
	local warned: { [string]: boolean } = {}
	local services: Services? = config.services
	local started = false
	local frame: Frame.Frame? = nil
	local registry: Registry.Registry? = nil
	local rigStates: RigState.Registry? = nil
	local appearedRigs: { [any]: boolean } = setmetatable({}, { __mode = "k" }) :: any
	local connection: any = nil
	local waker: { event: any, connection: any }? = nil
	local idleSince: number? = nil
	local drawsFrames = false
	local lives: { [any]: ApexTrack.Live } = setmetatable({}, { __mode = "kv" }) :: any
	local scenes: { [Scene.Scene]: boolean } = {}

	local function warnOnce(key: string, message: string)
		if warned[key] then
			return
		end
		warned[key] = true
		warnFn(message)
	end

	local function getServices(): Services
		if services == nil then
			services = {
				RunService = game:GetService("RunService"),
				Workspace = game:GetService("Workspace"),
				ReplicatedStorage = game:GetService("ReplicatedStorage"),
				Players = game:GetService("Players"),
			}
		end
		return services :: Services
	end

	local function newAnimation(id: number | string, name: string): any
		if config.newAnimation ~= nil then
			return config.newAnimation(id, name)
		end
		local animation = Instance.new("Animation")
		animation.Name = name
		animation.AnimationId = if type(id) == "number"
			then string.format("rbxassetid://%d", id)
			else id
		return animation
	end

	local function readView(): Frame.View?
		if not drawsFrames then
			return nil
		end
		local ok, camera = pcall(function()
			return getServices().Workspace.CurrentCamera
		end)
		return if ok then Frame.view(camera) else nil
	end

	local function disconnect()
		idleSince = nil
		if connection ~= nil then
			connection:Disconnect()
			connection = nil
		end
	end

	local serverCached: boolean? = config.server
	local function isServer(): boolean
		if serverCached == nil then
			local ok, client = pcall(function()
				return getServices().RunService:IsClient()
			end)
			serverCached = not (ok and client == true)
		end
		return serverCached :: boolean
	end

	local studioCached: boolean? = config.studio
	local function isStudio(): boolean
		if studioCached == nil then
			local ok, studio = pcall(function()
				return getServices().RunService:IsStudio()
			end)
			studioCached = ok and studio == true
		end
		return studioCached :: boolean
	end

	local function playIdOf(module: any, sidecar: Sidecar.Sidecar): (number | string)?
		local ok, raw = pcall(function()
			return module:GetAttribute(Registry.TEMP_ATTRIBUTE)
		end)
		local tempId = if ok then Registry.tempIdOf(raw) else nil
		if tempId ~= nil and isStudio() then
			return tempId
		end
		return sidecar.assetId
	end

	local function onFrame(dt: number)
		local pass = frame :: Frame.Frame
		Frame.step(pass, dt, readView())
		for scene in table.clone(scenes) do
			Scene.step(scene, dt)
		end
		if not Frame.idle(pass) or next(scenes) ~= nil then
			idleSince = nil
			return
		end
		local now = clock()
		if idleSince == nil then
			idleSince = now
		elseif now - (idleSince :: number) >= IDLE_GRACE then
			disconnect()
		end
	end

	local function link()
		if connection ~= nil and connection.Connected then
			return
		end
		local runService = getServices().RunService
		local ok, client = pcall(function()
			return runService:IsClient()
		end)
		drawsFrames = ok and client == true
		connection = Frame.event(runService):Connect(onFrame)
	end

	local function makeWaker()
		local ok, made = pcall(function()
			local event = if config.newWaker ~= nil
				then config.newWaker()
				else Instance.new("BindableEvent")
			return { event = event, connection = event.Event:Connect(link) }
		end)
		waker = if ok then made else nil
	end

	local function connect()
		idleSince = nil
		if connection ~= nil and connection.Connected then
			return
		end
		connection = nil
		local wake = waker
		if wake ~= nil and wake.connection.Connected then
			wake.event:Fire()
		else
			link()
		end
	end

	local function attach(
		animator: any,
		track: any,
		sidecar: Sidecar.Sidecar,
		label: string
	): ApexTrack.Live
		local live = ApexTrack.new({
			track = track,
			animator = animator,
			rig = Registry.rigOf(animator),
			sidecar = sidecar,
			label = label,
			hooks = Frame.hooks(frame :: Frame.Frame),
			clock = clock,
			warnOnce = warnOnce,
		})
		lives[track] = live
		return live
	end

	local function observedSlots(live: ApexTrack.Live): Spaces.Slots?
		local scene = live.sidecar.scene
		if scene == nil then
			return nil
		end
		return {
			label = `the scene '{scene.name}'`,
			resolve = function(slot: string): any?
				local id = scene.assets[slot]
				local tempId = if scene.temps ~= nil then scene.temps[slot] else nil
				if id == nil and tempId == nil then
					return nil
				end
				local best: any? = nil
				local gap = math.huge
				for _, other in lives do
					local same = (id ~= nil and other.sidecar.assetId == id)
						or (tempId ~= nil and Registry.trackTempId(other.track) == tempId)
					if other ~= live and same and other.phase ~= "Idle" and other.rig ~= nil then
						local apart = math.abs(other.time - live.time)
						if apart < gap then
							best, gap = other.rig, apart
						end
					end
				end
				return best
			end,
		}
	end

	local function onTrack(animator: any, track: any, late: boolean)
		local live = lives[track]
		if live == nil then
			local sidecar, entry = (registry :: Registry.Registry):resolve(animator, track)
			if sidecar == nil or entry == nil then
				return
			end
			live = attach(animator, track, sidecar, entry.label)
			Spaces.bindSlots(live :: ApexTrack.Live, observedSlots(live :: ApexTrack.Live))
		end
		local known = live :: ApexTrack.Live
		ApexTrack.markPlayed(known, late)
		if known.pending ~= nil then
			Frame.add(frame :: Frame.Frame, known)
			connect()
		end
	end

	local function isFocus(model: any): boolean
		for scene in scenes do
			if Scene.holds(scene, model) then
				return true
			end
		end
		local players = services and services.Players
		if players == nil then
			return false
		end
		local ok, mine = pcall(function()
			local player = players.LocalPlayer
			return player ~= nil and player.Character == model
		end)
		return ok and mine == true
	end

	local function holdRig(model: any, on: boolean, name: string?)
		local pass = frame
		if pass == nil or model == nil then
			return
		end
		Frame.hold(pass, model, name or Spaces.NAME, on)
		if on then
			connect()
		end
	end

	local function appeared(model: any)
		if model == nil or appearedRigs[model] then
			return
		end
		appearedRigs[model] = true
		if not isServer() then
			RigState.appeared(rigStates :: RigState.Registry, model)
		end
	end

	local function ensure()
		if frame ~= nil then
			return
		end
		local states = RigState.registry({
			clock = clock,
			warnOnce = warnOnce,
			wake = function(model: any)
				holdRig(model, true)
			end,
		})
		rigStates = states
		local context: Context = {
			rigStates = states,
			hold = holdRig,
			clock = clock,
			warnOnce = warnOnce,
			server = isServer,
			graphOf = config.graphOf,
			topology = config.topology,
		}
		local extensions: { Frame.Extension } = {}
		for _, item in config.extensions or EXTENSIONS do
			if type(item) == "function" then
				for _, made in (item :: Maker)(context) do
					table.insert(extensions, made)
				end
			else
				table.insert(extensions, item :: Frame.Extension)
			end
		end
		frame = Frame.new({
			extensions = extensions,
			settings = config.settings,
			clock = clock,
			warn = warnFn,
			focus = isFocus,
		})
		registry = Registry.new({
			onTrack = onTrack,
			onAnimator = function(animator: any)
				appeared(Registry.rigOf(animator))
			end,
			onAnimatorGone = function(animator: any)
				local model = Registry.rigOf(animator)
				if model ~= nil then
					appearedRigs[model] = nil
				end
			end,
			require = config.require,
			warn = warnFn,
			defer = config.defer,
			getClip = config.getClip,
		})
		makeWaker()
	end

	--[=[
		@within ApexEngine

		Enhances every play of an animation whose module is in the registry folder, however it
		is played. Call it on the server and on every client. Calls after the first do nothing.

		@param options StartOptions?
	]=]
	function ApexEngine.Start(first: any, second: any?)
		local startOptions: StartOptions? = if first == ApexEngine then second else first
		ensure()
		local s = getServices()
		local folder: any = startOptions and startOptions.registry
		if folder == nil then
			local ok, found = pcall(function()
				return s.ReplicatedStorage:FindFirstChild(REGISTRY_NAME)
			end)
			folder = if ok then found else nil
		end
		local reg = registry :: Registry.Registry
		if started then
			if folder ~= nil and reg.folder ~= nil and folder ~= reg.folder then
				local asked = Registry.labelOf(nil, folder)
				local kept = Registry.labelOf(nil, reg.folder)
				warnOnce(
					"start:twice",
					`ApexEngine: Start was called again with another registry folder ({asked}); the engine keeps using {kept}. Keep to one registry folder.`
				)
			end
			return
		end
		started = true
		if folder ~= nil then
			reg:setFolder(folder)
		else
			warnOnce(
				"start:nofolder",
				`ApexEngine: there is no registry folder (ReplicatedStorage.{REGISTRY_NAME}), so no animation is enhanced by itself - only ApexEngine.LoadAnimation plays enhanced. Apex Animator's Install Engine creates the folder.`
			)
		end
		reg:watch(s.Workspace)
	end

	local function animatorOf(target: any): any
		local kind = typeof(target)
		local wanted = "a Humanoid, an AnimationController, an Animator or a rig Model"
		if kind ~= "Instance" and kind ~= "table" then
			error(`ApexEngine.LoadAnimation needs {wanted}, not a {kind}`, 3)
		end
		if target:IsA("Animator") then
			return target
		end
		local holder = target
		if target:IsA("Model") then
			holder = target:FindFirstChildOfClass("Humanoid")
				or target:FindFirstChildOfClass("AnimationController")
			if holder == nil then
				error(
					`ApexEngine.LoadAnimation: {target.Name} has no Humanoid or AnimationController to play on`,
					3
				)
			end
		elseif not (target:IsA("Humanoid") or target:IsA("AnimationController")) then
			error(`ApexEngine.LoadAnimation needs {wanted}, not a {target.ClassName}`, 3)
		end
		local animator = holder:FindFirstChildOfClass("Animator")
		if animator == nil then
			error(
				`ApexEngine.LoadAnimation: {holder.Name} has no Animator. Add one under it (on the server, so the animation replicates).`,
				3
			)
		end
		return animator
	end

	--[=[
		@within ApexEngine

		Loads an animation onto a rig and returns its enhanced track. The module needn't be in
		the registry. In Studio an unpublished animation plays from its temporary copy.

		@param target Humanoid | AnimationController | Animator | Model -- the rig that plays it
		@param module ModuleScript -- the animation's module
		@return ApexTrack
		@error string -- the rig has no Animator, or the module can't be read or has nothing to play
	]=]
	function ApexEngine.LoadAnimation(first: any, second: any, third: any?): any
		local target, module = first, second
		if first == ApexEngine then
			target, module = second, third
		end
		ensure()
		local animator = animatorOf(target)
		local moduleKind = typeof(module)
		if moduleKind ~= "Instance" and moduleKind ~= "table" then
			error(
				`ApexEngine.LoadAnimation needs the animation's ModuleScript as its second argument, not a {moduleKind}`,
				2
			)
		end
		local reg = registry :: Registry.Registry
		local label = reg:label(module)
		local sidecar, problem = reg:load(module)
		if sidecar == nil then
			error(`ApexEngine.LoadAnimation: {label} cannot be used: {problem}.`, 2)
		end
		local loaded = sidecar :: Sidecar.Sidecar
		local playId = playIdOf(module, loaded)
		if playId == nil then
			local why = if isStudio()
				then "Publish it from Apex Animator, or export it to play it in Studio from a temporary copy."
				else "Publish it from Apex Animator: a temporary copy only plays in Studio."
			error(
				`ApexEngine.LoadAnimation: {label} has not been published yet, so there is no animation to play. {why}`,
				2
			)
		end
		local track = animator:LoadAnimation(newAnimation(playId :: any, loaded.name))
		local live = lives[track] or attach(animator, track, loaded, label)
		reg:watchAnimator(animator)
		return ApexTrack.handle(live)
	end

	local sceneContext: Scene.Context = {
		loadTrack = function(
			animator: any,
			sidecar: Sidecar.Sidecar,
			label: string,
			id: number | string
		): ApexTrack.Live
			local track = animator:LoadAnimation(newAnimation(id, sidecar.name))
			local live = lives[track] or attach(animator, track, sidecar, label);
			(registry :: Registry.Registry):watchAnimator(animator)
			return live
		end,
		studio = isStudio,
		jointsOf = config.jointsOf
			or function(model: any): { [string]: any }
				local ok, graph =
					pcall(config.graphOf or JointGraph.build, model, { pivots = true })
				return if ok and graph ~= nil then graph.byAddress else {}
			end,
		workspace = function(): any
			return getServices().Workspace
		end,
		playerGui = function(): any?
			if isServer() then
				return nil
			end
			local players = getServices().Players
			if players == nil then
				return nil
			end
			local ok, gui = pcall(function()
				local player = players.LocalPlayer
				return if player ~= nil then player:FindFirstChildOfClass("PlayerGui") else nil
			end)
			return if ok then gui else nil
		end,
		add = function(scene: Scene.Scene)
			scenes[scene] = true
			connect()
		end,
		remove = function(scene: Scene.Scene)
			scenes[scene] = nil
		end,
		warn = warnOnce,
	}

	--[=[
		@within ApexEngine

		Loads a scene onto one rig per slot. Nothing plays until the scene's Play.

		@param module ModuleScript -- the scene's module
		@param bindings { [string]: Model } -- a rig for each slot, as { SlotName = model }
		@param options SceneOptions?
		@return ApexScene
		@error string -- a slot, a rig or the anchor can't be used
	]=]
	function ApexEngine.LoadScene(first: any, second: any, third: any?, fourth: any?): any
		local module, bindings, sceneOptions = first, second, third
		if first == ApexEngine then
			module, bindings, sceneOptions = second, third, fourth
		end
		ensure()
		local moduleKind = typeof(module)
		if moduleKind ~= "Instance" and moduleKind ~= "table" then
			error(
				`ApexEngine.LoadScene needs the scene's ModuleScript as its first argument, not a {moduleKind}`,
				2
			)
		end
		local label = (registry :: Registry.Registry):label(module)
		local requireFn: (module: any) -> any = config.require or require
		local ok, value = pcall(requireFn, module)
		if not ok then
			error(
				`ApexEngine.LoadScene: {label} cannot be used: it could not be loaded: {tostring(
					value
				)}.`,
				2
			)
		end
		local scene, problem = Scene.new(sceneContext, value, bindings, sceneOptions, label)
		if scene == nil then
			error(problem, 2)
		end
		return Scene.handle(scene :: Scene.Scene)
	end

	--[=[
		@within ApexEngine

		Returns the enhanced track for a Roblox AnimationTrack, whoever played it.

		@param animationTrack AnimationTrack
		@return ApexTrack? -- nil when the engine is not following that track
	]=]
	function ApexEngine.GetTrack(first: any, second: any?): any?
		local track = if first == ApexEngine then second else first
		local live = lives[track]
		return if live ~= nil then ApexTrack.handle(live) else nil
	end

	local function rigOfTarget(target: any): any
		local kind = typeof(target)
		local wanted = "a rig Model, a Humanoid, an AnimationController or an Animator"
		if kind ~= "Instance" and kind ~= "table" then
			error(`ApexEngine.GetRigState needs {wanted}, not a {kind}`, 3)
		end
		local model: any = nil
		if target:IsA("Model") then
			model = target
		elseif target:IsA("Animator") then
			model = Registry.rigOf(target)
		elseif target:IsA("Humanoid") or target:IsA("AnimationController") then
			model = target.Parent
		else
			error(`ApexEngine.GetRigState needs {wanted}, not a {target.ClassName}`, 3)
		end
		if model == nil then
			error(`ApexEngine.GetRigState: {target.Name} is not in a rig`, 3)
		end
		return model
	end

	--[=[
		@within ApexEngine

		Returns a rig's state: which space each joint is in. Each rig has one, shared by every
		animation playing on it.

		@param target Model | Humanoid | AnimationController | Animator
		@return RigState
		@error string -- the target is not in a rig
	]=]
	function ApexEngine.GetRigState(first: any, second: any?): any
		local target = if first == ApexEngine then second else first
		ensure()
		local model = rigOfTarget(target)
		appeared(model)
		return RigState.handle(RigState.get(rigStates :: RigState.Registry, model))
	end

	function ApexEngine._connected(): boolean
		return connection ~= nil
	end

	ApexEngine._create = create

	return ApexEngine
end

return create(nil)
