local storeFolded = {}
for path in pairs(StoreBlobs) do
    local key = path:lower()
    if storeFolded[key] then storeFolded[key] = false else storeFolded[key] = path end
end
local folded = {}
for path in pairs(Blobs) do
    local key = path:lower()
    if folded[key] then folded[key] = false else folded[key] = path end
end
local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local digits = {}
for index = 1, #alphabet do digits[alphabet:byte(index)] = index - 1 end

return function(context)
    local now, blockedUntil = context.Clock or os.clock, 0
    local Assets = {}
    local function storeEntry(url)
        local ref, path = tostring(url):match("^https://raw%.githubusercontent%.com/STEVE%-916%-create/Uhhhhhh%-Store/([^/]+)/(.+)$")
        if not ref then
            ref, path = tostring(url):match("^https://raw%.githubusercontent%.com/STEVE%-916%-create/Uhhhhhh/([^/]+)/community/(.+)$")
            if ref ~= Revision and ref ~= "main" and ref ~= "master" then return nil end
        elseif ref ~= StoreRevision and ref ~= "main" and ref ~= "master" then return nil end
        path = path:gsub("%%(%x%x)", function(hex) return string.char(tonumber(hex, 16)) end)
        local canonical = StoreBlobs[path] and path or storeFolded[path:lower()]
        if not canonical then return nil end
        return StoreBlobs[canonical], canonical
    end
    function Assets.RawCandidate(url)
        local entry, path = storeEntry(url)
        if not entry then return nil end
        path = path:gsub("([^%w%-%._~/])", function(char) return string.format("%%%02X", char:byte()) end)
        return "https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh-Store/" .. StoreRevision .. "/" .. path
    end
    function Assets.Resolve(url)
        if context.Recovery then
            local sha,size,repository=context.Recovery.Blob(url)
            if sha then return sha,size,repository end
        end
        local store = storeEntry(url)
        if store then return store[1], store[2], "STEVE-916-create/Uhhhhhh-Store" end
        local ref, path = tostring(url):match("^https://raw%.githubusercontent%.com/STEVE%-916%-create/Uhhhhhh/([^/]+)/(.+)$")
        if ref ~= Revision and ref ~= "main" and ref ~= "master" then return nil end
        path = path:gsub("%%(%x%x)", function(hex) return string.char(tonumber(hex, 16)) end)
        local entry = Blobs[path] or Blobs[folded[path:lower()]]
        if not entry then return nil end
        return entry[1], entry[2], "STEVE-916-create/Uhhhhhh"
    end
    function Assets.DecodeBase64(content, expected)
        if type(content) ~= "string" or type(expected) ~= "number" or expected < 0 or expected > 64000000 then return nil, "invalid blob size" end
        local bytes = buffer.create(expected)
        local count, accumulator, bits, padding = 0, 0, 0, 0
        for index = 1, #content do
            local code = content:byte(index)
            local digit = digits[code]
            if digit ~= nil then
                if padding > 0 then return nil, "base64 data after padding" end
                accumulator = accumulator * 64 + digit
                bits += 6
                if bits >= 8 then
                    bits -= 8
                    local power = 2 ^ bits
                    local byte = math.floor(accumulator / power)
                    accumulator %= power
                    if count >= expected then return nil, "blob size mismatch" end
                    buffer.writeu8(bytes, count, byte)
                    count += 1
                end
            elseif code == 61 then
                padding += 1
                if padding > 2 then return nil, "invalid base64 padding" end
            elseif code ~= 9 and code ~= 10 and code ~= 13 and code ~= 32 then return nil, "invalid base64 character" end
            if context.Yield and index % 65536 == 0 then context.Yield() end
        end
        if count ~= expected or accumulator ~= 0 or bits == 6
            or (padding > 0 and padding ~= bits / 2) then return nil, "blob size/padding mismatch" end
        return buffer.tostring(bytes)
    end
    function Assets.Fetch(url, seen)
        local sha, size, repository = Assets.Resolve(url)
        if not sha then return nil end
        if seen and seen[sha] then return nil end
        if seen then seen[sha] = true end
        if now() < blockedUntil then return nil, "GitHub blob fallback is cooling down after a rate limit" end
        local response, reason = context.Fetch("https://api.github.com/repos/" .. repository .. "/git/blobs/" .. sha, nil, 1)
        if not response then
            if tostring(reason):find("403", 1, true) or tostring(reason):find("429", 1, true) then blockedUntil = now() + 600 end
            return nil, reason
        end
        local ok, blob = pcall(context.DecodeJson, response)
        if not ok or type(blob) ~= "table" or blob.sha ~= sha or blob.size ~= size or blob.encoding ~= "base64" then
            return nil, "GitHub returned different or unavailable blob metadata"
        end
        return Assets.DecodeBase64(blob.content, size)
    end
    return Assets
end
