-- Movement follows the displayed view, including game-owned cameras and VR.
local Basis={}
local function valid(pose)
    if typeof(pose)~="CFrame"then return false end
    for _,n in ipairs({pose:GetComponents()})do
        if n~=n or math.abs(n)==math.huge then return false end
    end
    return true
end
function Basis.Movement(camera,fallback)
    if camera then
        local ok,rendered=pcall(function()return camera:GetRenderCFrame()end)
        if ok and valid(rendered)then return rendered end
        if valid(camera.CFrame)then return camera.CFrame end
    end
    return valid(fallback)and fallback or CFrame.identity
end
function Basis.Managed(camera,humanoid,sceneActive,mode,localScriptable)
    if not camera or not humanoid or sceneActive or mode=="Game"then return false end
    if mode=="Reanimator"then return true end
    return camera.CameraSubject==humanoid and (localScriptable or camera.CameraType~=Enum.CameraType.Scriptable)
end
return Basis
