-- Independent controller-only adaptation of Nooby's camera-relative flight.
return function(ctx)
    local saved=type(ctx.SaveData.ControllerFlight)=="table"and ctx.SaveData.ControllerFlight or {}ctx.SaveData.ControllerFlight=saved
    local function finite(n)return type(n)=="number"and n==n and math.abs(n)<math.huge end
    saved.Speed=finite(saved.Speed)and math.clamp(saved.Speed,5,300)or 50
    local keys={"None","F","Y","O","I"}
    saved.Key=table.find(keys,saved.Key)and saved.Key or "F"
    local api={Enabled=false,Settings=saved,Keys=keys,Up=false,Down=false,Status="off"}
    local state,connections=nil,{}
    local create=ctx.Create or Instance.new
    local function cleanup()
        local old=state state=nil ctx.Reanimate.FlightActive=false
        if not old then return end
        if old.Connection then old.Connection:Disconnect()end
        if old.Velocity then old.Velocity:Destroy()end
        if old.Attachment then old.Attachment:Destroy()end
        pcall(function()
            if old.Humanoid.Parent then
                if old.Humanoid.PlatformStand==true then old.Humanoid.PlatformStand=old.PlatformStand end
                if old.Humanoid.AutoRotate==false then old.Humanoid.AutoRotate=old.AutoRotate end
            end
        end)
    end
    function api.SetEnabled(on)
        on=on==true
        if on and not ctx.Reanimate.Character then return false,"start reanimation first :D"end
        if on and ctx.Reanimate.EditorInputCaptured then return false,"leave the editor before flying"end
        api.Enabled=on ctx.Reanimate.Fly=on api.Up=false api.Down=false
        if not on then cleanup()end
        api.Status=on and "ready — E / jump = up, Q = down"or "off"
        if api.Changed then api.Changed(on)end
        return true
    end
    function api.SetSpeed(value)
        if not finite(value)then return false end
        saved.Speed=math.clamp(value,5,300)return true
    end
    function api.Step(dt)
        if not api.Enabled then return end
        local reanimate=ctx.Reanimate local rig=reanimate.Character
        if not rig or not rig.Parent or reanimate.EditorInputCaptured or reanimate.SceneCameraActive then
            api.SetEnabled(false)return
        end
        if not finite(dt)or dt<0 then cleanup()api.Status="waiting for a valid frame"return end
        local humanoid=rig:FindFirstChildOfClass("Humanoid")
        local root=rig:FindFirstChild("HumanoidRootPart")
        if not humanoid or not root or humanoid.Health<=0 or humanoid.Sit then
            cleanup()api.Status="waiting for a living, standing controller"return
        end
        if not state or state.Rig~=rig or state.Root~=root then
            cleanup()
            state={Rig=rig,Root=root,Humanoid=humanoid,PlatformStand=humanoid.PlatformStand,
                AutoRotate=humanoid.AutoRotate,Current=Vector3.zero}
            local attachment=create("Attachment")state.Attachment=attachment
            attachment.Name="_UhhhhhhFlightAttachment"attachment.Parent=root
            local velocity=create("LinearVelocity")state.Velocity=velocity
            velocity.Name="_UhhhhhhControllerFlight"velocity.Attachment0=attachment
            velocity.RelativeTo=Enum.ActuatorRelativeTo.World
            velocity.VelocityConstraintMode=Enum.VelocityConstraintMode.Vector
            velocity.ForceLimitsEnabled=false velocity.VectorVelocity=Vector3.zero velocity.Parent=root
            state.Connection=rig.Destroying:Once(function()api.SetEnabled(false)end)
            humanoid.PlatformStand=true humanoid.AutoRotate=false
        end
        local input=ctx.Input
        local blocked=input:GetFocusedTextBox()~=nil or ctx.MenuOpen and ctx.MenuOpen()
        local move=blocked and Vector3.zero or reanimate.Control.Move
        local basis=reanimate.Camera:GetMovementCFrame()
        local vertical=0
        if not blocked then
            if api.Up or input:IsKeyDown(Enum.KeyCode.E)or reanimate.Control.Jump then vertical+=1 end
            if api.Down or input:IsKeyDown(Enum.KeyCode.Q)then vertical-=1 end
        end
        local direction=basis:VectorToWorldSpace(Vector3.new(move.X,0,move.Z))+Vector3.new(0,vertical,0)
        if not finite(direction.X)or not finite(direction.Y)or not finite(direction.Z)then direction=Vector3.zero end
        if direction.Magnitude>1 then direction=direction.Unit end
        state.Current=state.Current:Lerp(direction*saved.Speed,1-math.exp(-14*math.min(dt,.1)))
        state.Velocity.VectorVelocity=state.Current humanoid.Jump=false
        reanimate.FlightActive=true api.Status="flying — E / jump = up, Q = down"
    end
    function api.Destroy()
        api.SetEnabled(false)
        for _,connection in ipairs(connections)do connection:Disconnect()end table.clear(connections)
    end
    if ctx.RunService then table.insert(connections,ctx.RunService.PreSimulation:Connect(function(dt)
        local ok,reason=pcall(api.Step,dt)
        if not ok then api.SetEnabled(false)api.Status="flight stopped: "..tostring(reason)end
    end))end
    if ctx.Input.InputBegan then table.insert(connections,ctx.Input.InputBegan:Connect(function(input,processed)
        if processed or ctx.Reanimate.EditorInputCaptured or ctx.Input:GetFocusedTextBox()
            or ctx.MenuOpen and ctx.MenuOpen()then return end
        if saved.Key~="None"and input.KeyCode==Enum.KeyCode[saved.Key]then api.SetEnabled(not api.Enabled)end
    end))end
    if ctx.Input.WindowFocusReleased then table.insert(connections,ctx.Input.WindowFocusReleased:Connect(function()api.SetEnabled(false)end))end
    return api
end
