-- Independent adaptation of Nooby's .6s / 60-stud NaN-to-velocity fallback.
-- Reference: Elliot12-wq/Uh-reanimation-modded-by-nooby, blob
-- 6ab2b34f56cb07a0db5bb6bb83df2bbad3323070. This is not true NaN state.
local Fallback={Window=.6,Distance=60,Velocity=16384}
local function finite(n)return type(n)=="number"and n==n and math.abs(n)<math.huge end
function Fallback.ValidPosition(p)
    return typeof(p)=="Vector3"and finite(p.X)and finite(p.Y)and finite(p.Z)
end
function Fallback.ValidPose(pose)
    if typeof(pose)~="CFrame"then return false end
    for _,component in ipairs({pose:GetComponents()})do if not finite(component)then return false end end
    return true
end
function Fallback.Contact(target,now,position,enabled)
    target._NaNContact=false
    if not enabled then target._NaNFallback=nil return false end
    if not finite(now)or not Fallback.ValidPosition(position)then return false end
    local state=target._NaNFallback
    if not state then
        state={Start=now,Origin=position,Escalated=false}target._NaNFallback=state
    end
    if not state.Escalated and now-state.Start>=Fallback.Window
        and (position-state.Origin).Magnitude<Fallback.Distance then state.Escalated=true end
    target._NaNContact=not state.Escalated
    return target._NaNContact
end
function Fallback.Duration(explicit,normal,enabled,profile)
    if finite(explicit)then return math.max(0,explicit)end -- a caller's timeout remains authoritative
    if not finite(normal)or normal<0 then normal=.5 end
    if not enabled and profile=="Weak"then return .4 end
    if not enabled and profile=="Contact"then return math.max(normal,2)end
    return enabled and math.max(normal,Fallback.Window+1)or normal
end
function Fallback.ApplyProfile(root,pose,now,profile)
    if not Fallback.ValidPose(pose)or not finite(now)then return false end
    local linear,angular,offset,rotation
    if profile=="Weak"then
        linear=Vector3.new(math.sin(now*25)*26,-4,math.cos(now*25)*26)
        angular=Vector3.new(0,30,0)offset=Vector3.new(0,-2,0)rotation=CFrame.Angles(0,now*10,0)
    elseif profile=="Contact"then
        local sign=math.floor(now*120)%2==0 and 1 or -1
        linear=Vector3.new(0,-16384*sign,0)angular=Vector3.one*16384
        offset=Vector3.new(0,sign*.2,0)rotation=CFrame.Angles(now*31,now*47,0)
    else return false end
    root.CFrame=CFrame.new(pose.Position+offset)*rotation
    root.Velocity,root.RotVelocity=linear,angular
    root.AssemblyLinearVelocity,root.AssemblyAngularVelocity=linear,angular
    return true
end
function Fallback.ApplyRoot(root,pose,now,contact)
    if not Fallback.ValidPose(pose)or not finite(now)then return false end
    if contact then
        local orbit=Vector3.new(math.sin(now*40)*.15,0,math.cos(now*40)*.15)
