    ["UhhhhhhReanim/System/runtime/steve110/main/head_tracking.lua"] = [=====[

-- Tracking is solved in body space, then converted through the actual Neck
-- frames. R6's rotated C0/C1 must never receive raw torso-space Euler angles.
local Tracking = {}
function Tracking.Finite(frame)
    if typeof(frame) ~= "CFrame" then return false end
    local x,y,z,a,b,c,d,e,f,g,h,i = frame:GetComponents()
    return x==x and y==y and z==z and a==a and b==b and c==c
        and d==d and e==e and f==f and g==g and h==h and i==i
        and math.abs(x)<math.huge and math.abs(y)<math.huge and math.abs(z)<math.huge
        and math.abs(a)<math.huge and math.abs(b)<math.huge and math.abs(c)<math.huge
        and math.abs(d)<math.huge and math.abs(e)<math.huge and math.abs(f)<math.huge
        and math.abs(g)<math.huge and math.abs(h)<math.huge and math.abs(i)<math.huge
end
function Tracking.Solve(torso, c0, c1, animation, camera, headset, scale, strength, blend)
    if not Tracking.Finite(torso) or not Tracking.Finite(c0) or not Tracking.Finite(c1)
        or not Tracking.Finite(animation) then return nil, "Invalid Neck pose" end
    strength = math.clamp(tonumber(strength) or 1, 0, 1)
    if strength~=strength then strength=1 end
    local delta, source = CFrame.identity, "Camera"
    if Tracking.Finite(headset) then
        scale = tonumber(scale) or 1
        if scale ~= scale or math.abs(scale) == math.huge then scale = 1 end
        delta = CFrame.new(headset.Position * math.max(scale, .05)) * headset.Rotation
        source = "VR headset"
    elseif Tracking.Finite(camera) then
        local look = torso:VectorToObjectSpace(camera.LookVector)
        -- Fold the rear camera hemisphere instead of clamping +/-pi to the
        -- neck limits. The old branch cut snapped from full left to full right
        -- when the camera crossed the avatar's front. Forward tracking keeps
        -- its original basis; a front-facing camera now mirrors it smoothly.
        local yaw = math.clamp(math.atan2(-look.X, math.abs(look.Z)), -math.rad(85), math.rad(85))
        if look.X * look.X + look.Z * look.Z < 1e-10 then yaw = 0 end
        local pitch = math.clamp(math.asin(math.clamp(look.Y, -1, 1)), -math.rad(75), math.rad(75))
        delta = CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0)
    end
    delta = CFrame.identity:Lerp(delta, strength)
    local base = c0 * (blend and animation or CFrame.identity) * c1:Inverse()
    -- Rotate at the current head centre, preserving dance/neck translation.
    -- No hard-coded half-unit pivot and no accumulating previous tracking pose.
    local desired = CFrame.new(base.Position + delta.Position) * delta.Rotation * base.Rotation
    return c0:Inverse() * desired * c1, source
end
return Tracking
