return function(deps)
    local states,catalog,names,byFile={},nil,{},{}
    local registry=deps.Require and deps.Require("main/market_providers")({Builtins=Providers,Saved=deps.Saved or {},
        Changed=function()catalog=nil if deps.Save then deps.Save()end end})
    local Providers=registry and registry.Providers or Providers
    local function enabled(p)return not registry or registry.Enabled(p)end
    local function treeList(p,tree)
        assert(type(tree)=="table"and type(tree.tree)=="table"and not tree.truncated,"incomplete repository tree")
        local rows={}
        for _,entry in ipairs(tree.tree)do
            local path=entry.path local lower=type(path)=="string"and path:lower()or ""
            if entry.type=="blob"and path:sub(1,#p.Prefix)==p.Prefix
                and (lower:match("%.lua$")or lower:match("%.luau$")or lower:match("%.txt$"))
                and not lower:match("readme%.txt$")then
                local relative=path:sub(#p.Prefix+1)
                table.insert(rows,"name = "..relative:gsub("%.[^.]+$","")
                    .."\ndesc = "..path.." · "..(p.Name or p.Repo).." (read module credits for author)\nfile = "..relative)
            end
        end
        table.sort(rows)return table.concat(rows,"\n\n").."\n"
    end
    if deps.Recovery and deps.Recovery.Configure then
        deps.Recovery.Configure({Providers=Providers,Fetch=deps.Fetch,Decode=deps.Decode,Snapshots=deps.Snapshots})
    end
    local function safePath(path)
        if type(path) ~= "string" or path == "" or path:sub(1,1)=="/" or path:find("\\",1,true) then return false end
        for segment in path:gmatch("[^/]+") do if segment == "." or segment == ".." then return false end end
        return not path:find("[%c]")
    end
    local function encode(path) return (path:gsub("[^%w%-%._~/]",function(c) return string.format("%%%02X",string.byte(c)) end)) end
    local function raw(p, revision, path)
        return "https://raw.githubusercontent.com/"..p.Repo.."/"..revision.."/"..encode(p.Prefix..path)
    end
    local function parse(p,revision,body)
        local result, row, seen = {}, {}, {}
        local function flush()
            local path = row.path or row.file
            if row.name and row.name~="" and safePath(path) then
                local folder = row.type == "folder" or path:sub(-1)=="/"
                local file = "Market/"..p.Id.."/"..path
                if not seen[file] then
                    seen[file]=true
                    table.insert(result,{Name=row.name,User=row.user and row.user~=""and row.user or nil,Description=row.desc or "",Cost=row.cost,
                        Type=folder and "folder" or "file",Path=path,File=file,Provider=p.Id,Repo=p.Repo,
                        Revision=revision,NeedsContext=p.Format=="tree",Source=not folder and raw(p,revision,path) or nil})
                end
            end
            row={}
        end
        body=body:gsub("^\239\187\191",""):gsub("\r","")
        for line in (body.."\n"):gmatch("([^\n]*)\n") do
            if line:match("^%s*$") then flush() else
                local key,value=line:match("^([%w_]+)%s*=%s?(.*)$")
                if key then row[key]=value:gsub("\\n","\n") end
            end
        end
        flush()
        return result
    end
    local function state(p,refresh)
        local s=states[p.Id]
        if s and not refresh then return s end
        local revision,body,reason
        local ok,err=pcall(function()
            local metadata,failure=deps.Fetch("https://api.github.com/repos/"..p.Repo.."/commits/"..encode(p.Branch or "main"),nil,1)
            assert(metadata,failure)
            local commit=deps.Decode(metadata)
            assert(type(commit)=="table" and type(commit.sha)=="string" and #commit.sha==40 and commit.sha:match("^%x+$"),"invalid commit response")
            revision=commit.sha
            if p.Format=="tree"then
                local bytes;bytes,failure=deps.Fetch("https://api.github.com/repos/"..p.Repo.."/git/trees/"..revision.."?recursive=1",nil,1)
                assert(bytes,failure)body=treeList(p,deps.Decode(bytes))
            else body,failure=deps.Fetch(raw(p,revision,p.ListPath or "list.txt"),nil,1)end
            assert(type(body)=="string" and #parse(p,revision,body)>0,failure or "empty catalog")
        end)
        if ok then
            s={Revision=revision,List=body,Paths=s and s.Revision==revision and s.Paths or nil,Fresh=true}
        else
            s=s or (deps.Saved and deps.Saved.MarketProviderCache and deps.Saved.MarketProviderCache[p.Id]) or {Revision=p.Revision,List=p.List or ""}
            s.Fresh=false
            s.Error=tostring(err)
        end
        states[p.Id]=s
        if ok and deps.Saved then
            deps.Saved.MarketProviderCache=deps.Saved.MarketProviderCache or {}
            deps.Saved.MarketProviderCache[p.Id]={Revision=s.Revision,List=s.List}
        end
        if deps.Recovery and deps.Recovery.Configure then
            -- Refresh revision metadata without changing the pinned offline list.
            local providers={}
            for _,provider in ipairs(Providers) do
                local current=states[provider.Id]
                table.insert(providers,{Id=provider.Id,Repo=provider.Repo,Prefix=provider.Prefix,
                    Revision=current and current.Revision or provider.Revision})
            end
            deps.Recovery.Configure({Providers=providers})
        end
        return s
    end
    local api={Parse=parse,Providers=Providers,SafePath=safePath,Registry=registry,TreeList=treeList}
    function api.Get(refresh)
        if catalog and not refresh then return catalog,names,byFile end
        catalog,names,byFile={}, {}, {}
        for _,p in ipairs(Providers) do
            if not enabled(p)then continue end
            local s=state(p,refresh)
            for _,item in ipairs(parse(p,s.Revision,s.List)) do
                item.Stale=not s.Fresh
                table.insert(catalog,item)
                names[item.File]=item.Name.." ["..p.Id.."]"; byFile[item.File]=item
                -- Existing flattened STEVE installations keep their update route.
                if p.Id=="STEVE" and item.Type=="file" then
                    local old=item.Path:gsub("/",".")
                    names[old]=item.Name.." [STEVE]"; byFile[old]=item
                end
            end
        end
        return catalog,names,byFile
    end
    function api.LegacyReplacement(filename)
        local p=Providers[1]
        local s=states[p.Id]
        for _,item in ipairs(parse(p,s and s.Revision or p.Revision,s and s.List or p.List)) do
            if item.Type=="file" and item.Path:gsub("/",".")==filename then return item.File end
        end
        return nil
    end
    function api.Status()
        local parts={}
        for _,p in ipairs(Providers) do
            local s=states[p.Id]
            table.insert(parts,p.Id..(not enabled(p)and ": disabled" or s and s.Fresh and ": current" or ": cached catalog (refresh to retry)"))
        end
        return table.concat(parts," | ")
    end
    function api.Folder(item)
        assert((item.Type=="folder" or item.Type=="file") and safePath(item.Path),"invalid pack")
        local p
        for _,provider in ipairs(Providers) do if provider.Id==item.Provider then p=provider break end end
        assert(p,"unknown provider")
        local s=states[p.Id]
        local paths=s and s.Revision==item.Revision and s.Paths or nil
        if not paths then
            local body,err=deps.Fetch("https://api.github.com/repos/"..p.Repo.."/git/trees/"..item.Revision.."?recursive=1",nil,1)
            assert(body,err)
            local tree=deps.Decode(body)
            assert(type(tree)=="table" and type(tree.tree)=="table" and not tree.truncated,"incomplete pack tree")
            if deps.Recovery and deps.Recovery.Register then deps.Recovery.Register(p,item.Revision,tree) end
            paths={}
            for _,entry in ipairs(tree.tree) do if entry.type=="blob" and safePath(entry.path) then table.insert(paths,entry.path) end end
            if s and s.Revision==item.Revision then s.Paths=paths end
        end
        -- A catalog script can live in Modules/ while its media lives in Anims/
        -- or Sounds/. Index its pack directory, but compile only that script.
        local directory=item.Type=="file" and (item.Path:match("^([^/]+)/") or "") or item.Path:gsub("/*$","")
        local prefix=p.Prefix..(p.Format=="tree"and ""or directory..(directory~=""and "/"or ""))
        local modules,assets,basenames={}, {}, {}
        for _,path in ipairs(paths) do
            if path:sub(1,#prefix)==prefix then
                local relative=path:sub(#p.Prefix+1)
                local name=path:match("[^/]+$")
                local lower=name:lower()
                local script=lower:match("%.lua$")or lower:match("%.luau$")or lower:match("%.lua%.txt$")or lower:match("%.luau%.txt$")or (p.Format=="tree"and lower:match("%.txt$"))
                if script and (item.Type=="folder" or path==p.Prefix..item.Path) then
                    table.insert(modules,{File="Market/"..p.Id.."/"..relative,Source=raw(p,item.Revision,relative),Provider=p.Id,
                        Relative=path:sub(#prefix+1)})
                elseif not script then
                    local mapped="Market/"..p.Id.."/"..relative.."@"..raw(p,item.Revision,relative)
                    assets[path:sub(#prefix+1)]=mapped
                    if basenames[name] and basenames[name]~=mapped then basenames[name]=false
                    elseif basenames[name]==nil then basenames[name]=mapped end
                end
            end
        end
        for name,mapped in pairs(basenames) do if mapped then assets[name]=mapped end end
        table.sort(modules,function(a,b) return a.File<b.File end)
        assert(#modules>0,"No modules found in pack")
        return modules,{Assets=assets,Provider=p.Id,Revision=item.Revision},p.Id.."/"..item.Path:gsub("/*$","").."/"..item.Revision
    end
    local caseMaps = setmetatable({}, {__mode = "k"})
    function api.Remap(context,filename)
        if type(filename)~="string"then return filename end
        if context and context.Assets and context.Assets[filename]then return context.Assets[filename]end
        if filename:find("@",1,true)then return filename end
        if context and context.Directory and context.Assets then
            local exact=context.Assets[context.Directory.."/"..filename]
            if exact then return exact end
        end
        if not context or not context.Assets then return filename end
        if context.Assets[filename] then return context.Assets[filename] end
        local folded = caseMaps[context.Assets]
        if not folded then
            folded = {}
            for name, mapped in pairs(context.Assets) do
                local key = name:lower()
                if folded[key] and folded[key] ~= mapped then folded[key] = false
                elseif folded[key] == nil then folded[key] = mapped end
            end
            caseMaps[context.Assets] = folded
        end
        local mapped = context.Directory and folded[(context.Directory .. "/" .. filename):lower()]
            or folded[filename:lower()]
        if mapped then return mapped end
        local recovered=deps.Recovery and deps.Recovery.Resolve(context,filename)
        if recovered then return recovered end
        return filename, true
    end
    return api
end
