    ["UhhhhhhReanim/System/runtime/steve110/main/market_providers.lua"] = [=====[
-- Saved repository settings, shared by the original market and editor library.
local Registry={}
local function safe(path,empty)
    if type(path)~="string"or (path==""and not empty)or path:find("[%c\\?#]")or path:sub(1,1)=="/"then return false end
    for segment in path:gmatch("[^/]+")do if segment=="."or segment==".."then return false end end
    return true
end
function Registry.Validate(value)
    assert(type(value)=="table","enter repository settings")
    local repo=tostring(value.Repo or ""):gsub("^%s+",""):gsub("%s+$","")
    repo=repo:gsub("^https://github%.com/",""):gsub("/+$",""):gsub("%.git$","")
    assert(repo:match("^[%w_.%-]+/[%w_.%-]+$")and not repo:find("%.%."),"use owner/repository or its GitHub URL")
    local branch=tostring(value.Branch or "main")
    assert(safe(branch)and branch:match("^[%w_./%-]+$"),"invalid branch or commit")
    local prefix=tostring(value.Prefix or ""):gsub("/+$","")
    assert(safe(prefix,true),"invalid content folder")if prefix~=""then prefix..="/"end
    local list=tostring(value.ListPath or "list.txt")
    assert(safe(list),"invalid catalog filename")
    local format=value.Format or "list"assert(format=="list"or format=="tree","choose list.txt or repository files")
    local name=tostring(value.Name or repo)assert(#name>0 and #name<=80 and not name:find("%c"),"enter a short marketplace name")
    -- Keep the folder identifier short; compare the full settings on duplicate IDs.
    local identity=repo:lower().."/"..branch.."/"..prefix.."/"..list.."/"..format
    local hashes={5381,52711,104729,130363}
    for i=1,#identity do for j=1,4 do hashes[j]=(hashes[j]*(31+2*j)+identity:byte(i))%4294967296 end end
    local id="Custom_"for _,hash in ipairs(hashes)do id..=string.format("%08x",hash)end
    return {Id=id,Repo=repo,Branch=branch,Prefix=prefix,ListPath=list,Format=format,Name=name,Custom=true,Revision=branch,List=""}
end
return function(deps)
    local saved=deps.Saved local api={Providers={}}
    saved.CustomMarketplaces=type(saved.CustomMarketplaces)=="table"and saved.CustomMarketplaces or {}
    saved.DisabledMarketplaces=type(saved.DisabledMarketplaces)=="table"and saved.DisabledMarketplaces or {}
    function api.Reload()
        table.clear(api.Providers)
        for _,provider in ipairs(deps.Builtins)do table.insert(api.Providers,provider)end
        for _,value in ipairs(saved.CustomMarketplaces)do
            local ok,p=pcall(Registry.Validate,value)if ok then table.insert(api.Providers,p)end
        end
    end
    function api.Add(value)
        local p=Registry.Validate(value)
        assert(#saved.CustomMarketplaces<32,"32 custom marketplaces is the current limit")
        for _,existing in ipairs(api.Providers)do assert(existing.Id~=p.Id,"this repository configuration is already added")end
        table.insert(saved.CustomMarketplaces,p)api.Reload()if deps.Changed then deps.Changed()end return p
    end
    function api.Enabled(p)return saved.DisabledMarketplaces[p.Id]~=true end
    function api.Rename(id,name)
        for _,p in ipairs(saved.CustomMarketplaces)do
            if Registry.Validate(p).Id==id then p.Name=name end
        end
        api.Reload()if deps.Changed then deps.Changed()end
    end
    function api.Enable(id,enabled)
        saved.DisabledMarketplaces[id]=not enabled or nil
        if deps.Changed then deps.Changed()end
    end
    function api.Remove(id)
        local found=false
        for i=#saved.CustomMarketplaces,1,-1 do
            if Registry.Validate(saved.CustomMarketplaces[i]).Id==id then table.remove(saved.CustomMarketplaces,i)found=true end
        end
        assert(found,"built-in sources can be disabled; only custom sources can be removed")
        saved.DisabledMarketplaces[id]=nil api.Reload()if deps.Changed then deps.Changed()end
    end
    api.Validate=Registry.Validate api.Reload()return api
end
