-- Independent live-player tools, inspired by Nooby's player list.
return function(ctx)
    local api={Selected=nil,Watching=false,Status="choose a player"}
    local cameraState,connections=nil,{}
    local function member(player)return player and table.find(ctx.Players:GetPlayers(),player)~=nil end
    local function root(character)
        if not character then return end
        local humanoid=character:FindFirstChildOfClass("Humanoid")
        return humanoid and humanoid.RootPart or character:FindFirstChild("HumanoidRootPart")
            or character:FindFirstChild("Torso")or character:FindFirstChild("UpperTorso")
    end
    local function valid(pose)
        if typeof(pose)~="CFrame"then return false end
        for _,n in ipairs({pose:GetComponents()})do if n~=n or math.abs(n)==math.huge then return false end end
        return true
    end
    function api.Escape(value)return tostring(value):gsub("&","&amp;"):gsub("<","&lt;"):gsub(">","&gt;")end
    function api.List(query)
        query=tostring(query or ""):lower():gsub("^%s+",""):gsub("%s+$",""):gsub("^@","")
        local rows={}
        for _,player in ipairs(ctx.Players:GetPlayers())do if player~=ctx.Player then
            local name,display,id=player.Name:lower(),player.DisplayName:lower(),tostring(player.UserId)
            local rank=query==""and 1 or query==id and 6 or query==name and 5 or query==display and 4
                or name:sub(1,#query)==query and 3 or display:sub(1,#query)==query and 2
                or (name:find(query,1,true)or display:find(query,1,true))and 1
            if rank then table.insert(rows,{Player=player,Rank=rank})end
        end end
        table.sort(rows,function(a,b)
            if a.Rank~=b.Rank then return a.Rank>b.Rank end
            if a.Player.Name~=b.Player.Name then return a.Player.Name:lower()<b.Player.Name:lower()end
            return a.Player.UserId<b.Player.UserId
        end)
        return rows
    end
    function api.Resolve(query)
        if tostring(query or ""):match("^%s*$")then return end
        local rows=api.List(query)
        if #rows==1 or rows[1]and rows[1].Rank>=5 then return rows[1].Player end
    end
    local function homeSubject()
        local rig=ctx.Reanimate.Character or ctx.Player.Character
        return rig and (rig:FindFirstChildOfClass("Humanoid")or root(rig))
    end
    local function releaseCamera()
        local old=cameraState cameraState=nil
        if not old or ctx.Reanimate.SceneCameraActive then return end
        pcall(function()
            if old.Camera.CameraSubject==old.Subject then
                local subject=old.PreviousSubject
                if not subject or not subject.Parent then subject=homeSubject()end
                if subject then old.Camera.CameraSubject=subject end
                if old.Camera.CameraType==Enum.CameraType.Custom then
                    old.Camera.CameraType=old.Type
                    if valid(old.CFrame)then old.Camera.CFrame=old.CFrame end
                end
            end
        end)
    end
    function api.StopWatching(reason)
        api.Watching=false releaseCamera()api.Status=reason or "camera returned"
    end
    function api.Select(player)
        if player~=nil and (player==ctx.Player or not member(player))then return false,"player has left"end
        if api.Selected~=player then api.StopWatching()api.Selected=player end
        api.Status=player and (player.DisplayName.." (@"..player.Name..")")or "choose a player"
        return true
    end
    function api.Step()
        local selected=api.Selected
        if selected and not member(selected)then api.StopWatching("player left")api.Selected=nil return end
        if not api.Watching then return end
        if ctx.Reanimate.EditorInputCaptured or ctx.Reanimate.SceneCameraActive then api.StopWatching("camera released for editor")return end
        local character=selected and selected.Character
        local subject=character and character:FindFirstChildOfClass("Humanoid")
        local camera=ctx.World.CurrentCamera
        if not camera or not subject or not subject.Parent then releaseCamera()api.Status="waiting for their character"return end
        if cameraState and cameraState.Camera==camera and cameraState.Subject==subject
            and (camera.CameraSubject~=subject or camera.CameraType~=Enum.CameraType.Custom)then
            cameraState=nil api.StopWatching("game took camera control")return
        end
        if not cameraState or cameraState.Camera~=camera or cameraState.Subject~=subject then
            releaseCamera()
            cameraState={Camera=camera,Subject=subject,PreviousSubject=camera.CameraSubject,Type=camera.CameraType,CFrame=camera.CFrame}
            camera.CameraSubject=subject camera.CameraType=Enum.CameraType.Custom
        end
        api.Status="watching "..selected.DisplayName
    end
    function api.Watch()
        if not member(api.Selected)then return false,"choose a player first"end
        if ctx.Reanimate.EditorInputCaptured or ctx.Reanimate.SceneCameraActive then return false,"leave the editor before watching"end
        api.Watching=true api.Step()return true
    end
    function api.Goto()
        if ctx.Reanimate.EditorInputCaptured then return false,"leave the editor before teleporting"end
        if not member(api.Selected)then return false,"choose a player first"end
        local mine=root(ctx.Reanimate.Character or ctx.Player.Character)
        local target=root(api.Selected.Character)
        if not mine or not target or not valid(target.CFrame)then return false,"a character is still spawning"end
        mine.CFrame=target.CFrame*CFrame.new(0,0,3)
        mine.AssemblyLinearVelocity=Vector3.zero mine.AssemblyAngularVelocity=Vector3.zero
        return true
    end
    function api.Fling()
        if ctx.Reanimate.EditorInputCaptured then return false,"leave the editor before flinging"end
        if not member(api.Selected)or not api.Selected.Character then return false,"choose a spawned player first"end
        if not ctx.Reanimate.Current or not ctx.Reanimate.Current.Running then return false,"start reanimation first"end
        return ctx.Fling(api.Selected.Character)
    end
    if ctx.RunService then table.insert(connections,ctx.RunService.Heartbeat:Connect(api.Step))end
    table.insert(connections,ctx.Players.PlayerRemoving:Connect(function(player)
        if api.Selected==player then api.StopWatching("player left")api.Selected=nil end
    end))
    function api.Destroy()
        api.StopWatching()
        for _,connection in ipairs(connections)do connection:Disconnect()end table.clear(connections)
    end
    return api
end
