            if joint:IsA("Motor6D") then table.insert(state.Joints,joint) end
        end
        for _,part in ipairs(rig:GetChildren()) do if part:IsA("BasePart") then state.Rest[part.Name]=part.CFrame end end
        state.TargetsDirty=true
