-- Awes955's custom-method tuple API, independently integrated with bounded
-- startup, per-run contexts, tracked resources and the shared stop lifecycle.
return function(deps)
    local root="UhhhhhhReanim/AdministrativeModules/ReanimationMethod/"
    local api={Methods={},Errors={}}
    local taskApi=deps.Task or task
    local clock=deps.Clock or os.clock
    local active
    local reported={}
    local function notify(message) if deps.Notify then deps.Notify(message) end end
    local function errorRecord(file,reason)
        local key=file..":"..tostring(reason)
        if reported[key] then return end
        if #api.Errors>=128 then return end
        reported[key]=true
        table.insert(api.Errors,{File=file,Error=tostring(reason)})
        notify(file..": "..tostring(reason))
        if api.Changed then pcall(api.Changed) end
    end
    local function validFile(path)
        if type(path)~="string" or path:find("%c") then return nil end
        path=path:gsub("\\","/")
        if not path:find("/",1,true) then path=root..path end
        local start=path:find(root,1,true)
        if not start or (start>1 and path:sub(start-1,start-1)~="/") then return nil end
        local file=path:sub(start+#root)
        if file:find("[/:%c]") or file=="" or file:find("..",1,true) then return nil end
        local lower=file:lower()
        if not (lower:match("%.lua$") or lower:match("%.luau$") or lower:match("%.lua%.txt$")) then return nil end
        return file
    end
    local function descriptor(source,file,context)
        local chunk,reason=deps.Compile(source,"@CustomReanimation/"..file)
        assert(type(chunk)=="function",tostring(reason))
        local name,method,extras=chunk(context)
        if type(name)=="table" then
            local value=name name,method,extras=value.Name,value.Start,value
        end
        assert(type(name)=="string" and #name>0 and #name<=80 and not name:find("%c"),"return a short method name")
        assert(type(method)=="function","return a name, start function and optional callbacks")
        extras=type(extras)=="table" and extras or {}
        for _,key in ipairs({"Config","Fling","ShowHitboxes"}) do
            assert(extras[key]==nil or type(extras[key])=="function",key.." must be a function")
        end
        return name,method,extras
    end
    local function immediate(fn,...)
        local thread=coroutine.create(fn)
        local result=table.pack(coroutine.resume(thread,...))
        if coroutine.status(thread)~="dead" then
            if taskApi.cancel then pcall(taskApi.cancel,thread) end
            pcall(coroutine.close,thread)
            error("descriptor and cleanup callbacks must not yield; put waits inside Start",0)
        end
        assert(result[1],tostring(result[2]))
        return table.unpack(result,2,result.n)
    end
    local function makeContext(session)
        local context=table.clone(deps.Context or {})
        context.Player,context.Reanimate,context.UI=deps.Player,deps.Reanimate,deps.UI
        context.Notify=notify
        local function live() return session and active==session and not session.Finished end
        local function requireLive() assert(live(),"this method run has stopped") end
        context.IsStopping=function() return not live() or deps.Reanimate.Current~=session.Backend or deps.Reanimate.Stopping==true end
        context.GetCharacter=function()
            local character=deps.Player.Character
            local humanoid=character and character:FindFirstChildOfClass("Humanoid")
            return character,humanoid,humanoid and humanoid.RootPart
        end
        context.OnStop=function(fn)
            assert(type(fn)=="function","OnStop needs a function")
            requireLive() table.insert(session.Cleanups,fn) return fn
        end
        context.Track=function(resource)
            requireLive()
            context.OnStop(function()
                if typeof(resource)=="RBXScriptConnection" then resource:Disconnect()
                elseif typeof(resource)=="Instance" then resource:Destroy()
                elseif type(resource)=="table" and resource.Disconnect then resource:Disconnect()
                elseif type(resource)=="table" and resource.Destroy then resource:Destroy() end
            end)
            return resource
        end
        context.Connect=function(event,fn)
            requireLive() assert(type(fn)=="function","Connect needs a function")
            return context.Track(event:Connect(function(...)
                if not live() then return end
                local ok,reason=pcall(fn,...)
                if not ok and live() then session.Finish("event error: "..tostring(reason),true) end
            end))
        end
        context.Spawn=function(fn,...)
            requireLive() assert(type(fn)=="function","Spawn needs a function")
            local args=table.pack(...)
            local thread=taskApi.defer(function()
                if not live() then return end
                local ok,reason=pcall(fn,table.unpack(args,1,args.n))
                if not ok and live() then session.Finish("task error: "..tostring(reason),true) end
            end)
            if thread then table.insert(session.Threads,thread) end
            return thread
        end
        context.Ready=function()
            requireLive()
            assert(deps.Reanimate.Character,"create a controller before Ready")
            session.Ready=true session.Backend.Running=true session.Backend.Status="running"
            deps.Reanimate.Starting=false
            return deps.Reanimate.Character
        end
        context.CreateCharacter=function(cf)
            requireLive()
            local result=deps.Reanimate.CreateCharacter(cf)
            if not live() then return nil end
            session.OwnsController=true context.Ready()
            return result or deps.Reanimate.Character
        end
        context.Stop=function(reason) if live() then session.Finish(reason or "stopped") end end
        return context
    end
    local function create(file,source,name,extras)
        local backend={Name=name,File=file,Id=file,IsCustom=true,ManagedLifecycle=true,Running=false,Status="ready"}
        function backend.Config(parent)
            local label=deps.UI.CreateText(parent,"Custom method: "..file,12,Enum.TextXAlignment.Left)
            label.RichText=false
            if extras.Config then
                local ok,reason=pcall(extras.Config,parent)
                if not ok then errorRecord(file,"settings: "..tostring(reason)) end
            end
        end
        function backend.Start()
            if active then deps.Reanimate.Starting=false notify("deanimate the current custom method first") return false end
            local session={Backend=backend,Cleanups={},Threads={},Before=deps.Reanimate.Character,Started=clock()}
            active=session backend.RealCharacter=deps.Player.Character backend.Status="starting"
            local function finish(reason,failed)
                if session.Finished then return end
                session.Finished=true
                if session.Monitor then session.Monitor:Disconnect() end
                for _,thread in ipairs(session.Threads) do
                    if taskApi.cancel and thread~=coroutine.running() then pcall(taskApi.cancel,thread) end
                end
                for i=#session.Cleanups,1,-1 do
                    local ok,why=pcall(immediate,session.Cleanups[i])
                    if not ok then errorRecord(file,"cleanup: "..tostring(why)) end
                end
                table.clear(session.Threads) table.clear(session.Cleanups)
                if deps.Reanimate.Current==backend then
                    if deps.Reanimate.Character and (session.OwnsController or deps.Reanimate.Character~=session.Before) then
                        local ok,why=pcall(deps.Reanimate.DestroyCharacter)
                        if not ok then errorRecord(file,"controller cleanup: "..tostring(why)) end
                    end
                    deps.Reanimate.Starting=false
                end
                if active==session then active=nil end
                backend.Running=false backend.RealCharacter=nil backend.Status=tostring(reason)
                if failed then errorRecord(file,reason) end
                if deps.Complete then deps.Complete(backend) end
            end
            session.Finish=finish
            local timeout=tonumber(extras.StartTimeout) or 30
            if timeout~=timeout then timeout=30 end
            timeout=math.clamp(timeout,1,120)
            session.Monitor=deps.RunService.PreSimulation:Connect(function()
                if deps.Reanimate.Current~=backend or deps.Reanimate.Stopping or (deps.Alive and not deps.Alive()) then
                    finish("stopped")
                elseif not session.Ready and clock()-session.Started>=timeout then finish("startup timed out",true)
                elseif session.Ready and not deps.Reanimate.Character then finish("controller removed") end
            end)
            session.Context=makeContext(session)
            session.Threads[1]=taskApi.defer(function()
                if session.Finished then return end
                local ok,reason=pcall(function()
                    local _,method,runExtras=immediate(descriptor,source,file,session.Context)
                    session.Extras=runExtras method(session.Context)
                    if not session.Finished and not session.Ready then session.Context.Ready() end
                end)
                if not ok and not session.Finished then finish("start: "..tostring(reason),true) end
            end)
            return true
        end
        if extras.Fling then backend.Fling=function(target,duration)
            local session=active
            if not session or session.Backend~=backend or not session.Ready or session.Finished then return false end
            local callback=session.Extras and session.Extras.Fling
            if not callback then return false end
            local ok,result=pcall(callback,target,duration,session.Context)
            if not ok then errorRecord(file,"target callback: "..tostring(result)) return false end
            return result
        end end
        if extras.ShowHitboxes then backend.ShowHitboxes=function(...)
            local session=active
            if not session or session.Backend~=backend or not session.Ready then return end
            local callback=session.Extras and session.Extras.ShowHitboxes
            if callback then
                local ok,reason=pcall(callback,...)
                if not ok then errorRecord(file,"hitboxes: "..tostring(reason)) end
            end
        end end
        return backend
    end
    function api.Reload()
        if active then return false,"deanimate before reloading custom methods" end
        local methods,errors={},{} api.Errors=errors reported={}
        local ok,entries=pcall(deps.List,root)
        if not ok or type(entries)~="table" then return false,"could not read custom method folder" end
        local files,seen={},{}
        for _,path in pairs(entries) do
            local file=validFile(path)
            if file and not seen[file] then seen[file]=true table.insert(files,file) end
        end
        table.sort(files)
        local used={Limb=true,Hats=true,Gelatek=true,["Ragdoll (beta)"]=true,["Tools (beta)"]=true}
        for i,file in ipairs(files) do
            if i>128 then errorRecord(file,"128 custom method limit") break end
            local ran,source,name,method,extras=pcall(function()
                local text=deps.Read(root..file)
                assert(type(text)=="string" and #text<=1024*1024,"custom method exceeds 1 MiB")
                local title,start,options=immediate(descriptor,text,file,makeContext(nil))
                return text,title,start,options
            end)
            if not ran then errorRecord(file,source)
            else
                while used[name] do name=name.." ("..file..")" end
                used[name]=true table.insert(methods,create(file,source,name,extras))
            end
        end
        api.Methods=methods return true
    end
    function api.Combine(builtins,saved)
        local methods,names=table.clone(builtins),{}
        for _,method in ipairs(api.Methods) do table.insert(methods,method) end
        for _,method in ipairs(methods) do table.insert(names,method.Name) end
