        if link:IsA("JointInstance") or link:IsA("WeldConstraint") then
            p0,p1=link.Part0,link.Part1
        elseif link:IsA("Constraint") then
            local ok,a0,a1=pcall(function() return link.Attachment0,link.Attachment1 end)
            if ok then
                p0=a0 and a0:FindFirstAncestorWhichIsA("BasePart")
                p1=a1 and a1:FindFirstAncestorWhichIsA("BasePart")
            end
        end
        local a0,a1=accessoryOf(p0),accessoryOf(p1)
        if not (p0 and p1 and a0~=a1 and (a0 or a1)) then return end
        known[link]=true
        table.insert(s.Links,{Link=link,Parent=link.Parent})
        link.Parent=nil
    end
    function s.Scan()
        local character=s.Character
        if not character or not character.Parent then return end
        table.clear(s.Hats); table.clear(s.Parts)
        local descendants=character:GetDescendants()
        for _,item in ipairs(descendants) do
            if item:IsA("Accessory") and item.Parent==character then
                local handle=item:FindFirstChild("Handle")
                if handle and handle:IsA("BasePart") then table.insert(s.Hats,item) end
            elseif item:IsA("BasePart") then
                table.insert(s.Parts,item)
                if accessoryOf(item) then
                    save(item,"CanCollide",false); save(item,"CanTouch",false)
