        for _,hat in ipairs(s.Hats) do
            local handle=hat:FindFirstChild("Handle")
            save(handle,"Massless",handle.Massless)
            save(handle,"CustomPhysicalProperties",handle.CustomPhysicalProperties)
            save(handle,"LocalTransparencyModifier",handle.LocalTransparencyModifier)
            if s.Owns(handle)==true then
