                handle.AssemblyAngularVelocity=Vector3.zero
            end
        end
        s.Dirty=false
    end
    function s.Attach(character)
        s.Character=character
        s.Humanoid=character:FindFirstChildOfClass("Humanoid")
        s.Root=character:FindFirstChild("HumanoidRootPart")
        assert(s.Humanoid and s.Root and s.Humanoid.Health>0,"No death needs a living character")
        save(s.Humanoid,"AutoRotate",false); save(s.Humanoid,"PlatformStand",true)
