-- Root/replication policy ported from the actual native Steve 1.1.0 DEV Limb module.
-- The extension engine keeps its AJU, accessory, body-hide, writer and init hooks.
local Policy = {FlingPower = 32768, ReplicationInterval = 1 / 20}
function Policy.MakeXZFling(velocity)
    local x, z = velocity.X, velocity.Z
    if x < 0 then x = -Policy.FlingPower elseif x > 0 then x = Policy.FlingPower end
    if z < 0 then z = -Policy.FlingPower elseif z > 0 then z = Policy.FlingPower end
    return Vector3.new(x, 0, z)
end
function Policy.RootPose(mode, streaming, veryVoid, void, controllerRoot, torso)
    if streaming and mode < 2 then mode = 2 end
    if mode == 0 then return CFrame.new(veryVoid) end
    if mode == 1 then return CFrame.new(void) end
    if mode == 2 then return CFrame.new(controllerRoot.Position + Vector3.new(0, -12, 0)) end
    if mode == 3 then return controllerRoot.CFrame end
    return torso.CFrame
end
function Policy.RootVelocity(mode, controllerRoot, customMagnitude, customDirection)
    if mode == 0 then return Vector3.zero end
    if mode == 1 then return controllerRoot.Velocity end
    if mode == 2 then return controllerRoot.Velocity * 5 end
    if mode == 3 then return Policy.MakeXZFling(controllerRoot.Velocity) + Vector3.new(0, Policy.FlingPower, 0) end
    local direction = Vector3.yAxis
    if customDirection == 2 then direction = -Vector3.yAxis end
    if customDirection == 3 then direction = controllerRoot.CFrame.LookVector end
    if customDirection == 4 then direction = -controllerRoot.CFrame.LookVector end
    return direction * customMagnitude -- preserved modded mode, migrated to index 4
end
function Policy.RootJitter(time)
    return Vector3.new(0, 0, ((math.floor(time * 20) % 3) - 1) * 0.005)
end
function Policy.OwnedRoot(root)
    local ok, result = pcall(function() return not root:IsGrounded() and root.ReceiveAge == 0 end)
    return ok and result
end
function Policy.SkidFling(step, angle)
    local offsets = {{0,1.5,0}, {0,-1.5,0}, {2.25,1.5,-2.25}, {-2.25,-1.5,2.25}, {0,1.5,0}, {0,-1.5,0}}
    return CFrame.new(unpack(offsets[step])) * CFrame.Angles(math.rad(angle), 0, 0)
end
function Policy.Predict(time, target)
    local cf, velocity = target.CFrame, target.Velocity
    local duration = math.sin(time * 15) + 1
    local predicted = cf * CFrame.Angles(1.57, 0, 0) + Vector3.new(0, 1, 0)
    predicted += velocity * duration + Vector3.new(0, -workspace.Gravity * 0.5 * duration * duration + math.sin(time * 60), 0)
    if predicted.Position.Y < cf.Position.Y - 1 then
        predicted = predicted.Rotation + Vector3.new(predicted.Position.X, cf.Position.Y - 1, predicted.Position.Z)
    end
    return predicted, Policy.MakeXZFling(velocity)
end
return Policy
