-- Local-avatar followers. Tool layout follows the supplied Tool.lua; loose-body
-- assembly checks follow testing734/Awes' ragdoll module. No damage/touch loop.
return function(ctx)
    local CollisionGuard=require(script.Parent.collision_guard)
    local Player,Reanimate,RunService=ctx.Player,ctx.Reanimate,ctx.RunService
    local limbs={"Head","Torso","Left Arm","Right Arm","Left Leg","Right Leg"}
    local drive={"Torso","Head","Left Arm","Right Arm","Left Leg","Right Leg","HumanoidRootPart"}
    local aliases=ctx.R15Body
    local settings=ctx.SaveData.LooseBody or {} ctx.SaveData.LooseBody=settings
    local function create(kind)
        local backend={Name=kind=="tools" and "Tools (beta)" or "Ragdoll (beta)",Status="ready",Running=false}
        local snapshots,connections,last={}, {},setmetatable({},{__mode="k"})
        local tools,body,serial,accumulator={},nil,0,0
        local collisions=CollisionGuard.new()
        local function save(object,key,value)
            snapshots[object]=snapshots[object] or {}
            if snapshots[object][key]==nil then snapshots[object][key]={object[key]}end
            object[key]=value
        end
        local function restoreBody()
            collisions.Clear()
            for object,properties in pairs(snapshots)do
                for key,value in pairs(properties)do pcall(function()
                    local original=value[1]
                    if key=="Parent"and object:IsA("Tool")and original and not original.Parent then
                        original=Player:FindFirstChild("Backpack")or Player.Character
                    end
                    object[key]=original
                end)end
            end
            table.clear(snapshots)table.clear(last)table.clear(tools)
        end
        local function restore()
            for _,connection in ipairs(connections)do connection:Disconnect()end table.clear(connections)
            restoreBody()
        end
        local function owned(part)
            return not part.Anchored and not part:IsGrounded() and part.ReceiveAge==0
        end
        local function target(part,fake)
            local exact=fake:FindFirstChild(part.Name)
            if exact and exact:IsA("BasePart")then return exact.CFrame end
            local group=aliases and aliases.Groups[part.Name]
            local mapped=group and fake:FindFirstChild(group)
            if mapped then
                local offset=aliases.Offsets[part.Name]or CFrame.identity
                return mapped.CFrame*(CFrame.new(offset.Position*fake:GetScale())*offset.Rotation)
            end
        end
        local function follow(part,cf,dt,visual)
            if not owned(part)then last[part]=nil return false end
            if not visual then
                local velocity=(cf.Position-(last[part]or cf).Position)/math.max(dt,.001)
                local netless=math.clamp(tonumber(Reanimate.NetlessVelocity)or 35,0,1000)
                local flat=Vector3.new(velocity.X,0,velocity.Z)
                if flat.Magnitude>netless then flat=flat.Unit*netless end
                part.AssemblyLinearVelocity=Vector3.new(flat.X,math.max(velocity.Y,netless),flat.Z)
                part.AssemblyAngularVelocity=Vector3.zero last[part]=cf
            end
            part.CFrame=cf return true
        end
        local function prepare(character)
            restoreBody()
            body=character serial+=1 tools={} accumulator=1
            backend.RealCharacter=character
            if not character then return end
            collisions.Bind(character)
            if kind=="ragdoll" and settings.ReleaseMotors then
                assert(ctx.RCDDisabled,"local joint release needs RejectCharacterDeletions disabled")
                local hum=character:FindFirstChildOfClass("Humanoid")
                if hum then save(hum,"RequiresNeck",false)end
                for _,joint in ipairs(character:GetDescendants())do
                    if joint:IsA("Motor6D")and joint.Part0 and joint.Part1
                        and joint.Part0.Parent==character and joint.Part1.Parent==character then save(joint,"Enabled",false)end
                end
            end
        end
        local function collectTools()
            local found,seen={},{}
            for _,parent in pairs({body,Player:FindFirstChild("Backpack")})do
                for _,tool in ipairs(parent:GetChildren())do
                    if tool:IsA("Tool")and not seen[tool]then
                        local handle=tool:FindFirstChild("Handle")
                        if handle and handle:IsA("BasePart")then seen[tool]=true table.insert(found,tool)end
                    end
                end
            end
            table.sort(found,function(a,b)return a.Name<b.Name end)
