                backend.Status=string.format("%d / %d tools following (up to 6); %d not owned",count,total,unowned)
                -- Keep the real shell out of the tool figure. Drive one part
                -- per assembly, rather than fighting the same welded body.
                local root=fake:FindFirstChild("HumanoidRootPart")
                if root then
                    local humanoid=body:FindFirstChildOfClass("Humanoid")
                    if humanoid then save(humanoid,"PlatformStand",true)save(humanoid,"AutoRotate",false)end
                    local seen={}
                    local shell=body:GetChildren()
                    local realRoot=body:FindFirstChild("HumanoidRootPart")
                    if realRoot then table.insert(shell,1,realRoot)end
                    for _,part in ipairs(shell)do if part:IsA("BasePart")then
                        save(part,"LocalTransparencyModifier",1)
                        local assembly=part.AssemblyRootPart or part local cf=target(part,fake)
                        if cf and not seen[assembly]then
                            seen[assembly]=true
                            local y=math.max((ctx.FallenY or -500)+8,root.Position.Y-40)
                            follow(part,CFrame.new(cf.Position.X,y+cf.Position.Y-root.Position.Y,cf.Position.Z)*cf.Rotation,dt,visual)
