                for _,part in ipairs(parts)do
                    local cf=part:IsA("BasePart")and target(part,fake)
                    if cf then
                        total+=1 local assembly=part.AssemblyRootPart or part
                        if used[assembly]then shared+=1
                        else used[assembly]=true if follow(part,cf,dt,visual)then count+=1 else unowned+=1 end end
                    end
                end
                backend.Status=string.format("%d / %d body parts following; %d still joined, %d not owned",count,total,shared,unowned)
            end
            if not visual then
                for _,part in ipairs(fake:GetChildren())do
                    if part:IsA("BasePart")and part.Name~="HumanoidRootPart"then
                        part.Transparency=Reanimate.ShowControllerCharacter and 0
                            or ((count>0 and shared==0 and unowned==0)and 1 or Reanimate.PlaceholderTransparency)
