        end
        backend.Start=function()
            if backend.Running then Reanimate.Starting=false return end
            local ok,reason=xpcall(function()
                local character=Player.Character local root=character and character:FindFirstChild("HumanoidRootPart")
                Reanimate.CreateCharacter(root and root.CFrame)
                prepare(character)backend.Running=true Reanimate.Starting=false
                local failure
                for _,entry in ipairs({{RunService.PreSimulation,false},{RunService.PreRender,true}})do
                    table.insert(connections,entry[1]:Connect(function(dt)
                        if failure or Reanimate.Stopping then return end
                        local success,err=pcall(step,dt,entry[2])if not success then failure=err end
                    end))
                end
                while not Reanimate.Stopping and not failure and ctx.Alive()do RunService.Heartbeat:Wait()end
                if failure then error(failure,0)end
            end,tostring)
            local controller=Reanimate.Character
            local returnRoot=controller and controller:FindFirstChild("HumanoidRootPart")
            local realRoot=body and body:FindFirstChild("HumanoidRootPart")
            if kind=="tools"and returnRoot and realRoot and owned(realRoot)then
                realRoot.CFrame=returnRoot.CFrame realRoot.AssemblyLinearVelocity=Vector3.zero
            end
            restore()backend.Running=false backend.RealCharacter=nil
            Reanimate.DestroyCharacter()Reanimate.Starting=false
            if not ok then backend.Status=tostring(reason)ctx.Notify(backend.Name..": "..tostring(reason))end
            ctx.Complete(backend)
        end
        backend.Config=function(parent)
            ctx.UI.CreateText(parent,kind=="tools"and "uses your handled tools as limbs. equip / unequip once if a game keeps the grip."
                or "ragdoll in the game first, then start. joined or server-owned limbs are shown below.",12,Enum.TextXAlignment.Center)
            if kind=="ragdoll"then
                ctx.UI.CreateSwitch(parent,"Release local motors (RCD off)",settings.ReleaseMotors==true).Changed:Connect(function(value)
                    settings.ReleaseMotors=value==true
                end)
            end
            local label=ctx.UI.CreateText(parent,backend.Status,12,Enum.TextXAlignment.Left)
            local age=0 ctx.Util.LinkDestroyI2C(label,RunService.Heartbeat:Connect(function(dt)
                age+=dt if age>=.5 then age=0 label.Text=backend.Status end
            end))
        end
        backend.ShowHitboxes=function()
            for object in pairs(snapshots)do if object:IsA("BasePart")then pcall(ctx.Util.ShowPartHitbox,object)end end
        end
        if kind=="tools"then backend.SelectionParts=function()
            local rows={}
            for i,tool in ipairs(tools)do
                local handle=tool:FindFirstChild("Handle")
                if handle and handle.Parent then table.insert(rows,{Name=limbs[i],Part=handle})end
            end
            return rows
        end end
        return backend
    end
    return {Ragdoll=create("ragdoll"),Tools=create("tools")}
end
