    ["UhhhhhhReanim/System/runtime/steve110/main/reanimation/method_picker.lua"] = [=====[
-- Uses the existing Steve dropdown and maintenance page; no extra settings page.
return function(ctx)
    local UI,custom,saved=ctx.UI,ctx.Custom,ctx.Saved
    local api={}
    local methods,names,index=custom.Combine(ctx.Builtins,saved)
    local select,label
    local canvas=UI.CreateCanvas(ctx.ConfigParent)
    local function choose(value)
        api.Selected=methods[value] or methods[1]
        saved.SelectedReanimator=value
        saved.SelectedReanimatorFile=api.Selected.IsCustom and api.Selected.File or nil
        saved.SelectedReanimatorName=api.Selected.Name
        ctx.Clear(canvas) api.Selected.Config(canvas)
        if ctx.Changed then ctx.Changed(api.Selected) end
        if ctx.Save then ctx.Save() end
    end
    local function mount(order)
        select,label=UI.CreateDropdown(ctx.Main,"Reanimator",names,index)
        if order then label.Parent.LayoutOrder=order end
        select.Changed:Connect(choose) api.Select=select api.Label=label
    end
    mount()
    if saved.SelectedReanimatorFile and not methods[index].IsCustom then
        ctx.Notify("saved custom method is missing; using Limb")
    end
    choose(index)
    local status=UI.CreateText(ctx.Maintenance,"",12,Enum.TextXAlignment.Left)
    status.RichText=false api.Status=status
    function api.RefreshStatus()
        status.Text=("%d custom reanimation methods | %d load errors"):format(#custom.Methods,#custom.Errors)
        if custom.Errors[1] then status.Text..="\n"..custom.Errors[1].File..": "..custom.Errors[1].Error:sub(1,220) end
    end
    custom.Changed=api.RefreshStatus
    status.Destroying:Once(function()if custom.Changed==api.RefreshStatus then custom.Changed=nil end end)
    local reloading=false
    function api.Reload()
        if reloading then return false end
        if ctx.Reanimate.Current or ctx.Reanimate.Starting then ctx.Notify("deanimate before reloading methods") return false end
        reloading=true
        local ran,ok,reason=pcall(custom.Reload)
        if not ran or not ok then
            reloading=false ctx.Notify(ran and reason or ok) return false
        end
        methods,names,index=custom.Combine(ctx.Builtins,saved)
        local order=label.Parent.LayoutOrder
        label.Parent:Destroy() mount(order) choose(index)
        api.RefreshStatus() reloading=false ctx.Notify("custom methods reloaded :D") return true
    end
    api.ReloadButton=UI.CreateButton(ctx.Maintenance,"Reload Custom Reanimation Methods",18)
    api.ReloadButton.Activated:Connect(api.Reload)
    local help=UI.CreateText(ctx.Maintenance,"drop .lua methods in AdministrativeModules/ReanimationMethod, then reload. Example.lua.example.txt shows the API; rename it only after editing.",11,Enum.TextXAlignment.Left)
    help.RichText=false api.RefreshStatus()
    return api
end
