--!optimize 2
LU_NATIVE_COMPILE = true

local Util = require(script.Parent.util)
local RunService = Util.Service("RunService")

local function callCallback(func, t, dt)
local callback, linkToInstance, alwaysRun = func[1], func[2], func[3]
if not alwaysRun and linkToInstance then
if linkToInstance:IsA("GuiObject") then
if not Util.IsGuiVisible(linkToInstance) then
return
end
end
end
xpcall(callback, function(m)
warn(Util.Traceback("Uhhhhhh :: Render Step Function Error", m, callback, 2))
end, t, dt)
end

local callbackList = {}
local _totalrendertime = 0
RunService:BindToRenderStep("Uhhhhhh_Render" .. Util.RandomString(), Enum.RenderPriority.Last.Value - 69, function(dt)
local profiler=Util.FrameProfiler
local started=profiler and profiler.Begin("UI render")
debug.profilebegin("Uhhhhhh :: Render Step")
local t = _totalrendertime + dt
_totalrendertime = t
for _,func in callbackList do
callCallback(func, t, dt)
end
debug.profileend("Uhhhhhh :: Render Step")
if started then profiler.Finish("UI render",started) end
end)

return function(callback, linkToInstance, alwaysRun)
assert(callback)
local func = {callback, linkToInstance, alwaysRun or false}
table.insert(callbackList, func)
if linkToInstance then
linkToInstance.Destroying:Once(function()
local i = table.find(callbackList, func)
if i then table.remove(callbackList, i) end
end)
end
callCallback(func, _totalrendertime, 0.001)
return callback
end
