-- Steve's Roserika sunset adapted to the retained Mainframe page.
return function(context)
    local Util, parent, music = context.Util, context.Parent, context.Music
    local demo = Util.Instance("Frame", parent)
    demo.Name = "RoserikaSunset"
    demo.Size = UDim2.new(1, 0, 0, 170)
    demo.LayoutOrder = #parent:GetChildren()
    demo.BackgroundTransparency = 1
    demo.ClipsDescendants = true
    local sky = Util.Instance("Frame", demo)
    sky.AnchorPoint = Vector2.new(0.5, 0)
    sky.Position = UDim2.new(0.5, 0, 0, 0)
    sky.Size = UDim2.new(1, 0, 0, 90)
    sky.BackgroundTransparency = 1
    sky.ClipsDescendants = true
    local sea = Util.Instance("Frame", demo)
    sea.Position = UDim2.fromOffset(0, 90)
    sea.Size = UDim2.new(1, 0, 0, 80)
    sea.BackgroundColor3 = Color3.new(0, 0.1, 0.3)
    sea.BackgroundTransparency, sea.BorderSizePixel = 0.5, 0
    local seaGradient = Util.Instance("UIGradient", sea)
    seaGradient.Rotation, seaGradient.Transparency = 90, NumberSequence.new(0, 1)
    local sun = Util.Instance("Frame", sky)
    sun.AnchorPoint = Vector2.new(0.5, 0.5)
    sun.Position = UDim2.new(0.5, 0, 0, 90)
    sun.Size = UDim2.fromOffset(90, 90)
    sun.BackgroundColor3, sun.BorderSizePixel = Color3.new(1, 0.2, 0), 0
    sun.ZIndex = 3
    Util.Instance("UICorner", sun).CornerRadius = UDim.new(1, 0)
    local halo = sun:Clone()
    halo.Size = UDim2.fromOffset(120, 120)
    halo.BackgroundColor3, halo.BackgroundTransparency, halo.ZIndex = Color3.new(1, 0.5, 0), 0.3, 2
    halo.Parent = sky
    local sunScale, haloScale = Util.Instance("UIScale", sun), Util.Instance("UIScale", halo)
    local bars, reflections = {}, {}
    for i = 1, 36 do
        local bar = Util.Instance("Frame", sky)
        bar.AnchorPoint = Vector2.new(0, 1)
        bar.Position, bar.Size = UDim2.new((i - 1) / 36, 0, 0, 90), UDim2.new(1 / 36, -1, 0, 8)
        bar.BackgroundTransparency, bar.BorderSizePixel = 0.7, 0
        bar.BackgroundColor3 = Color3.new(1, 0.1, 0.1)
        table.insert(bars, bar)
        local line = Util.Instance("Frame", sea)
        line.AnchorPoint = Vector2.new(0.5, 0.5)
        line.Position = UDim2.new(0.5, 0, 0, i * 2 - 1)
        line.Size = UDim2.fromOffset((1 - i / 60) * 180, 1)
        line.BackgroundTransparency, line.BorderSizePixel = 0.2, 0
        line.BackgroundColor3 = Color3.new(1, 0.1, 0.1)
        table.insert(reflections, line)
    end
    local title = Util.Instance("TextLabel", demo)
    title.BackgroundTransparency = 1
    title.Size, title.Position = UDim2.new(1, 0, 0, 20), UDim2.fromOffset(0, 138)
    title.Font, title.TextSize = context.Font or Enum.Font.Code, 12
    title.TextColor3, title.Text, title.ZIndex = Color3.new(1, 1, 1), tostring(music.Name or ""), 4
    if context.Theme then
        context.Theme.ApplyLabel(title)
    end
    title.RichText, title.TextTruncate = false, Enum.TextTruncate.AtEnd
    local function setMusicName(name)
        name = tostring(name or "")
        if title.Text ~= name then title.Text = name end
    end
    local elapsed, history = 0, 0
    context.Render(function(_, dt)
        if Util.IsGuiVisible and not Util.IsGuiVisible(demo) then return end
        elapsed += dt
        local loudness = math.clamp(music.PlaybackLoudness / 1000, 0, 1.5)
        sunScale.Scale = math.max(1 + loudness / 2, sunScale.Scale - dt * 4)
        haloScale.Scale = sunScale.Scale + (haloScale.Scale - sunScale.Scale) * math.exp(-8 * dt)
        history += dt
        if history >= 1 / 30 then
            history %= 1 / 30
            for i = 1, #bars - 1 do bars[i].Size = bars[i + 1].Size end
            bars[#bars].Size = UDim2.new(1 / 36, -1, 0, 2 + loudness * 180)
            for i, line in ipairs(reflections) do
                local wave = 0.55 + 0.45 * math.sin(elapsed * (1 + i / 60) + i * 1.618)
                line.Size = UDim2.new((1 - i / 60) * 0.5 * wave, 0, 0, 1)
            end
        end
    end, demo)
    return demo, setMusicName
end
