-- Index real native control captions as their existing factories create them.
return function(ctx)
    local UI,nav=ctx.UI,ctx.Navigation
    local page=UI.CreatePage()page.Name="Settings_Search"
    local records=setmetatable({},{__mode="k"})
    local search={Page=page,Records=records,Pool={}}
    UI.Workspace.RegisterRoot("settings/search","Find settings",page,Color3.new(.9,.55,.22))
    UI.CreateButton(page,"&lt; Back",18).Activated:Connect(function()
        UI.Workspace.Back(page,UI.Workspace.Pages[page].Parent or ctx.Main)
    end)
    UI.CreateText(page,"<b>FIND A SETTING</b>",17,Enum.TextXAlignment.Left)
    local box=UI.CreateTextbox(page,"","Search names or categories",14)
    local status=UI.CreateText(page,"Type a setting name, or browse a category below.",11,Enum.TextXAlignment.Left)
    local results=UI.CreateCanvas(page)
    search.Box,search.Status=box,status
    local function clean(value)
        return tostring(value):gsub("<.->",""):gsub("&gt;",">"):gsub("&lt;","<"):gsub("&amp;","&")
    end
    local function titleOf(target)
        local current=target local visited={}
        while current and not visited[current]do
            visited[current]=true
            for _,entry in pairs(nav.Entries)do if not entry.Hidden and entry.Page==current then return entry.Title end end
            local state=UI.Workspace.Pages[current]current=state and state.Parent
        end
        local owner=UI.Workspace.Owners[target]
        return owner and owner.Name or (target.Name~="Frame"and target.Name or "Other settings")
    end
    local function open(record)
        UI.Workspace.Open(record.Page,page)
        -- Root tabs normally restore their last child. A search result needs
        -- its exact page so its control can be scrolled into view.
        if UI.Workspace.CurrentPage~=record.Page then UI.Workspace.Back(UI.Workspace.CurrentPage,record.Page)end
        if record.Page~=ctx.Main then UI.Workspace.Pages[record.Page].Parent=page end
        if record.Anchor then task.defer(function()
            if not record.Anchor.Parent or UI.Workspace.CurrentPage~=record.Page then return end
            if record.Page:IsA("ScrollingFrame")then
                local y=record.Page.CanvasPosition.Y+record.Anchor.AbsolutePosition.Y-record.Page.AbsolutePosition.Y-10
                record.Page.CanvasPosition=Vector2.new(record.Page.CanvasPosition.X,math.max(0,y))
            end
        end)end
    end
    function search.Refresh()
        if not page.Visible then return end
        local tokens={}for token in box.Text:lower():gmatch("%S+")do table.insert(tokens,token)end
        local matches={}
        local function add(record)
            local text=(record.Title.." "..record.Category):lower()
            for _,token in ipairs(tokens)do if not text:find(token,1,true)then return end end
            table.insert(matches,record)
        end
        for _,entry in pairs(nav.Entries)do
            if not entry.Hidden then add({Title=entry.Title,Category="Category",Page=entry.Page})end
        end
        if #tokens>0 then for anchor,record in pairs(records)do
            if anchor.Parent then
                local target=UI.Workspace.ResolvePage(record.Parent)
                if target and target~=page then add({Title=record.Title,Category=titleOf(target),Page=target,Anchor=anchor})end
            end
        end end
        table.sort(matches,function(a,b)
            local aa,bb=a.Category.." / "..a.Title,b.Category.." / "..b.Title
            return aa:lower()<bb:lower()
        end)
        local shown=math.min(60,#matches)
        status.Text=string.format("%d result%s%s",#matches,#matches==1 and ""or "s",#matches>shown and " — first 60 shown; narrow your search"or "")
        for i=1,shown do
            local pooled=search.Pool[i]
            if not pooled then
                pooled={}search.Pool[i]=pooled
                local button,label=UI.CreateButton(results,"",14)
                pooled.Button,pooled.Label=button,label or button
                local row=pooled.Button
                while row.Parent and row.Parent~=results do row=row.Parent end
                pooled.Row=row
                pooled.Button.Activated:Connect(function()open(pooled.Record)end)
            end
            pooled.Record=matches[i]pooled.Row.Visible=true
            pooled.Label.Text=matches[i].Category.." / "..matches[i].Title.." >"
        end
        for i=shown+1,#search.Pool do search.Pool[i].Row.Visible=false end
    end
    function search.Open(from)
        UI.Workspace.Open(page,from or ctx.Main)search.Refresh()
    end
    local queued=false
    box:GetPropertyChangedSignal("Text"):Connect(function()
        if queued then return end queued=true task.defer(function()queued=false if page.Parent then search.Refresh()end end)
    end)
    page:GetPropertyChangedSignal("Visible"):Connect(search.Refresh)
    for _,kind in ipairs({"Switch","Slider","Dropdown","Textbox","TextBox"})do
        local name="Create"..kind local original=UI[name]
        if original then UI[name]=function(parent,...)
            local args=table.pack(...)local out=table.pack(original(parent,...))
            local caption=(kind=="Textbox"or kind=="TextBox")and args[2]or args[1]
            if type(caption)=="string"and #caption>0 then
                for i=1,out.n do
                    local anchor=out[i]
                    if typeof(anchor)=="Instance"and anchor:IsA("GuiObject")then
                        records[anchor]={Parent=parent,Title=clean(caption)}break
                    end
                end
            end
            return table.unpack(out,1,out.n)
        end end
    end
    return search
end
