-- Large retained asset browser. Browsing never owns the playback lifetime.
return function(studio)
    local ctx,layout=studio.Context,studio.Layout
    local model=ctx.Require("main/studio_catalog")()
    local view={Model=model,Pool={},Source="local",Tracks={},ScrollRestore=false}
    local root=studio.Panel(studio.Body,"AssetBrowserMode") root.Size=UDim2.fromScale(1,1)
    local sources=studio.Scroll(root,"AssetSources")sources.BackgroundTransparency=0 ctx.Theme.ApplyFrame(sources,{Depthed=true})
    local results=studio.Panel(root,"AssetResults")
    local details=studio.Panel(root,"AssetDetails")
    local info=studio.Scroll(details,"AssetInfo")
    view.Root,view.Details=root,details
    studio.Label(sources,"LIBRARY",12,8,170,24,14)
    local sourceButtons={}
    local choices={{"Local files","local"},{"Marketplace","market"},{"Loaded animations","loaded"},{"Playing now","playing"},{"Favorites","favorites"},{"Hidden","hidden"}}
    for i,choice in ipairs(choices) do
