    ["UhhhhhhReanim/System/runtime/steve110/main/studio_catalog.lua"] = [=====[
-- Browser state is retained independently of the compact Mainframe's pages.
return function()
    local catalog={States={},Rows={},Filtered={},Serial=0,Key="local"}
    local function prepare(state,rows)
        state.Rows,state.Search,state.ById=rows,{},{}
        for _,row in ipairs(rows)do
            table.insert(state.Search,{Row=row,Name=row.Name:lower(),Text=(row.Name.." "..(row.Description or "").." "..(row.Source or "").." "..row.Kind):lower()})
            state.ById[row.Id]=row
        end
        table.sort(state.Search,function(a,b)return a.Name==b.Name and a.Row.Id<b.Row.Id or a.Name<b.Name end)
        state.Filtered=nil
    end
    function catalog.State(key)
        key=key or catalog.Key
        if not catalog.States[key] then catalog.States[key]={Query="",Scroll=0} end
        return catalog.States[key]
    end
    function catalog.SelectSource(key)
        catalog.Serial+=1 catalog.Key=key
        local state=catalog.State() catalog.Rows=state.Rows or {} catalog.Filter(state.Query)
        return state
    end
    function catalog.Set(rows)
        catalog.Rows=rows prepare(catalog.State(),rows)
        catalog.Filter(catalog.State().Query)
    end
    function catalog.Filter(query)
        local state=catalog.State() state.Query=query or ""
        if not state.Search then prepare(state,catalog.Rows)end
        local tokens={} for token in state.Query:lower():gmatch("%S+") do table.insert(tokens,token) end
        local normalized=table.concat(tokens," ")
        if state.Filtered and state.Normalized==normalized then catalog.Filtered=state.Filtered return state.Filtered end
        local filtered={}
        for _,entry in ipairs(state.Search) do
            local text=entry.Text
            local matches=true
            for _,token in ipairs(tokens) do if not text:find(token,1,true) then matches=false break end end
            if matches then table.insert(filtered,entry.Row) end
        end
        state.Filtered,state.Normalized=filtered,normalized
        catalog.Filtered=filtered
        return filtered
    end
    function catalog.Pick(id)
        catalog.State().Selected=id
        return catalog.Selected()
    end
    function catalog.Selected()
        local state=catalog.State()
        return state.ById and state.ById[state.Selected]
    end
    function catalog.File(name)
        return {Id="file/"..name,Name=name,Kind=(name:match("%.([^.]+)$") or "file"):upper(),
            Source="Workspace",File=name,Description="UhhhhhhReanim/Anims/"..name}
    end
    function catalog.Pack(item)
        return {Id="pack/"..item.File.."@"..tostring(item.Revision or ""),Name=item.Name,
            Kind=item.Type=="folder" and "PACK" or "ADD-ON",Source=item.Provider,
            Description=item.Description or "",Pack=item,Author=item.User}
    end
    function catalog.Module(module)
        local stream=module._UhhhhhhStream
        local pack=stream and stream.Descriptor and stream.Descriptor.Pack
        return {Id="module/"..tostring(module.Hash or module.InternalName or module),Name=module.Name,
            Kind=module.ModuleType,Source=module._UhhhhhhSource or "Built-in",Description=module.Description or "",Module=module,
            Author=module.Author or module.User or (pack and pack.User)}
    end
    return catalog
end
