    end
    local function identity(t,name)return string.format("%.9f/%s",t,name)end
    function editor:BeginDocumentGesture()
        assert(not self.Gesture,"finish the current gesture first")
        local before=self:State()self.Track=Files.Canonical(self.Track)
        self.Gesture={Kind="Document",Before=before,Dirty=false}self:Changed()
    end
    function editor:UpdateDocumentGesture(update)
        assert(self.Gesture and self.Gesture.Kind=="Document","no document gesture")
        update(self.Track)self.Gesture.Dirty=true self:Changed()
    end
    function editor:Layer(index)
        if self.Gesture then self:EndGesture(false)end
        local s=doc.Ensure(self.Track)
        assert(index>=0 and index%1==0 and index<=#s.Layers,"choose a layer")
        -- Layer selection is navigation, not an edit to the animation.
        s.ActiveLayer=index self:Changed()
    end
    function editor:AddLayer(name,blend,source)
        self:Edit(function(track)
            local s=doc.Ensure(track)
            local keys=source and Files.Canonical(source).Keyframes or {}
            table.insert(s.Layers,{Name=name or "Layer "..(#s.Layers+1),Blend=blend or "Override",Weight=1,
                Muted=false,Solo=false,Keyframes=keys,Curves={},Mask={}})
            s.ActiveLayer=#s.Layers
        end)
    end
    function editor:UpdateLayer(index,values)
        self:Edit(function(track)
            local layer=assert(doc.Ensure(track).Layers[index],"choose an animation layer")
            for _,key in ipairs({"Name","Blend","Weight","Muted","Solo","Mask"})do
                if values[key]~=nil then layer[key]=values[key]end
            end
        end)
    end
    function editor:RemoveLayer(index)
        self:Edit(function(track)local s=doc.Ensure(track)
            assert(s.Layers[index],"choose an animation layer")table.remove(s.Layers,index)s.ActiveLayer=math.min(index,#s.Layers)
        end)
    end
    function editor:ReorderLayer(index,offset)
        self:Edit(function(track)local s=doc.Ensure(track)
            local to=math.clamp(index+offset,1,#s.Layers)
            local layer=assert(table.remove(s.Layers,index),"choose a layer")table.insert(s.Layers,to,layer)s.ActiveLayer=to
        end)
    end
    function editor:BakeLayers()
        local baked=Files.Bake(self.Track)
        self:Edit(function(track)
            track.Keyframes=baked.Keyframes
            local s=doc.Ensure(track)s.Layers={}s.Curves={}s.ActiveLayer=0
        end)
    end
    function editor:SelectionEntries(selection)
        local selected={}for _,ref in ipairs(selection)do
            for _,k in ipairs(self:Keys())do if math.abs(ref.Time-k.Time)<1e-7 then
                for _,p in ipairs(k.Poses)do if not ref.Joint or ref.Joint==p.Name then
                    local id=identity(k.Time,p.Name)local existing=selected[id]
                    selected[id]={Time=k.Time,Pose=p,Name=k.Name,Whole=ref.Joint==nil or(existing and existing.Whole)}
                end end
            end end
            for name,row in pairs(doc.Curves(self.Track,false))do if not ref.Joint or ref.Joint==name then
