    local function floating(name,panel,grip)
        studio.Drag(grip,function()
            if panel.Parent~=root then return nil end -- The narrow-window Values drawer is modal.
            local p,s=panel.Position,panel.AbsoluteSize
            local bounds=studio.Floating[name]
            if not bounds then
                bounds={X=p.X.Offset,Y=p.Y.Offset,W=name=="Timeline"and math.min(s.X,900)or s.X,H=s.Y}
                studio.Floating[name]=bounds
            end
            panel.ZIndex=140
            return {X=bounds.X,Y=bounds.Y}
        end,function(start,delta)
            local bounds=studio.Floating[name]
            bounds.X,bounds.Y=start.X+delta.X,start.Y+delta.Y
            view:Layout(view.Width,view.Height)view:DrawTimeline()
        end)
    end
    floating("Joints",joints,jointGrip)floating("Values",values,valuesGrip)floating("Timeline",timeline,timeTitle)
    viewport.InputBegan:Connect(function(input)
        if not view.Picking or not studio.Visible or studio.Mode~="editor"then return end
        if studio.Modal or studio.Popup or studio.MakerDock or(view.Workbench and view.Workbench.Tab=="IK")then return end
        if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
        if view.TransformDrag then return end -- Another finger cannot replace a captured gesture.
        local point=view:Point(input)
        local vp,vs=viewport.AbsolutePosition,viewport.AbsoluteSize
        if point.Y<vp.Y+(view.CaptionHeight or 90)or point.X<vp.X or point.X>vp.X+vs.X or point.Y>vp.Y+vs.Y then return end
        view:DrawGizmo()
        if view.NativeGizmo then
            local axis=view.NativeGizmo.HitTest(point,function(world)return view:Project(world)end,
                input.UserInputType==Enum.UserInputType.Touch and 18 or 9)
            if axis then
                studio.Run(function()view:StartTransform(input,axis)end)return
            end
        end
        for _,button in pairs(view.Handles)do
            local p,s=button.AbsolutePosition,button.AbsoluteSize
            if button.Visible and point.X>=p.X and point.X<=p.X+s.X
                and point.Y>=p.Y and point.Y<=p.Y+s.Y then return end
        end
        studio.Run(function()
            assert(ctx.SelectionParts and ctx.Camera,"World limb picking is unavailable")
            local camera=assert(ctx.Camera(),"Camera is unavailable")
            local ray=view:Ray(point)
            local hit=ctx.Require("main/studio_selection").Nearest(ctx.SelectionParts(editor.DetectedRig),ray.Origin,ray.Direction)
            assert(hit,"No body part under the pointer; start reanimation or use the joint tree")
            assert(table.find(editor:Joints(),hit.Name),"Body part does not belong to this clip's rig")
            view:SelectJoint(hit.Name,hit.Part)
            view:StartTransform(input)
            return "Selected "..hit.Name
        end)
    end)
    local dragging,scrubQueued,pendingTime,releaseScrub
    function view:CancelScrub(commit)
        if commit and pendingTime then at(pendingTime)end
        if releaseScrub then releaseScrub()releaseScrub=nil end
        dragging=nil pendingTime=nil
    end
    local function pointerTime(input)
        pendingTime=math.clamp((view:Point(input).X-grid.AbsolutePosition.X+grid.CanvasPosition.X-8)/view.Zoom,0,editor.Track.Time)
        if scrubQueued then return end
        scrubQueued=true
        task.defer(function()
            scrubQueued=false
            if pendingTime and root.Parent and studio.Visible and studio.Mode=="editor"then at(pendingTime)end
        end)
    end
    scrub.InputBegan:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            studio.CancelInteractions()dragging=input releaseScrub=studio.HoldScroll(studio.Body)pointerTime(input)
        end
    end)
    studio.Connect(root,ctx.Input.InputChanged,function(input)
        local drag=view.TransformDrag
        if drag and (input==drag.Input or (drag.Input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseMovement))then
            local ok=studio.Run(function()view:MoveTransform(input)end)
            if not ok then view:FinishTransform(false)end
        elseif studio.Visible and studio.Mode=="editor"then
            view:DrawGizmo()
            if view.NativeGizmo and input.UserInputType==Enum.UserInputType.MouseMovement then
                view.HoverAxis=view.NativeGizmo.HitTest(view:Point(input),function(world)return view:Project(world)end,9)
            end
        end
        if dragging and studio.Visible and studio.Mode=="editor" and (input.UserInputType==Enum.UserInputType.MouseMovement or input==dragging) then
            studio.Run(function()pointerTime(input)end)
        end
    end)
    studio.Connect(root,ctx.Input.InputEnded,function(input)
        if input==dragging then view:CancelScrub(true)end
        local drag=view.TransformDrag
        if drag and (input==drag.Input or (drag.Input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1))then
            studio.Run(function()view:MoveTransform(input)end)view:FinishTransform(true)
        end
    end)
    if ctx.Input.WindowFocusReleased then studio.Connect(root,ctx.Input.WindowFocusReleased,function()
        view:CancelScrub()view:FinishTransform(false)
    end) end
    function view:LayoutValues(width,height)
        self.ValueLabelWidths=self.ValueLabelWidths or setmetatable({},{__mode="k"})
        studio.Rect(valuesGrip,10,0,width-20,24)
        for i,tab in ipairs(tabs) do studio.Rect(tab,6+(i-1)*(width-12)/3,28,(width-18)/3,26) end
        studio.Rect(form,0,60,width,math.max(0,height-102))
        studio.Rect(keyButton,8,height-34,width-16,26) keyButton.Visible=self.Inspector=="joint"
        local column=(width-24)/3
        for group,prefix in ipairs({"p","r"}) do
            local y=53+(group-1)*76
            for i,axis in ipairs({"x","y","z"}) do
                studio.Rect(self.AxisLabels[prefix..axis],10+(i-1)*column,y+22,column-5,16)
                studio.Rect(self.Fields[prefix..axis],10+(i-1)*column,y+40,column-6,26)
            end
        end
        studio.Rect(self.StyleButton,82,232,math.max(80,width-94),26)
        studio.Rect(self.DirectionButton,10,267,width-20,26)
        studio.Rect(poseForm,0,0,width,315) studio.Rect(clipForm,0,0,width,300)
        studio.Rect(eventsForm,0,0,width,160+#editor.Track.Markers*32)
        studio.Rect(clipName,10,34,width-20,26) studio.Rect(eventName,10,34,width-20,26)
        studio.Rect(eventValue,10,68,width-20,26)
        studio.Rect(applyClip,10,134,width-20,26)studio.Rect(addEvent,10,104,width-20,26)
        studio.Rect(fps,10,94,math.min(90,(width-28)/2),26)
        studio.Rect(loop,18+math.min(90,(width-28)/2),94,width-28-math.min(90,(width-28)/2),26)
        studio.Rect(duration,10,203,(width-28)/2,26)studio.Rect(retime,18+(width-28)/2,203,(width-28)/2,26)
        studio.Rect(eventList,0,146,width,#editor.Track.Markers*32)
        for _,parent in ipairs({poseForm,clipForm,eventsForm})do for _,label in ipairs(parent:GetChildren())do
            if label:IsA("TextLabel")then
                local p,s=label.Position,label.Size
                local axis=false for _,candidate in pairs(self.AxisLabels)do if candidate==label then axis=true break end end
                if not axis and p.X.Scale==0 and s.X.Scale==0 then
                    self.ValueLabelWidths[label]=self.ValueLabelWidths[label]or s.X.Offset
                    studio.Rect(label,p.X.Offset,p.Y.Offset,math.max(0,math.min(self.ValueLabelWidths[label],width-p.X.Offset-10)),s.Y.Offset)
                end
            end
        end end
    end
    function view:ShowValues()
        if self.Bounds and self.Bounds.Right>0 and not studio.Options.HideValues then
            values.Visible=true return
        end
        studio.Dialog("Values",510,function(panel)
            values.Parent=panel values.Visible=true studio.Rect(values,10,42,panel.AbsoluteSize.X-20,420)
            self:LayoutValues(panel.AbsoluteSize.X-20,420)
            studio.Button(panel,"Close",panel.AbsoluteSize.X-114,466,100,studio.CloseDialog)
            studio.DialogCleanup=function()values.Parent=root self:Layout(self.Width,self.Height)end
        end)
    end
    studio.BindLayout(values,function(width,height)view:LayoutValues(width,height)view:DrawEvents()end)
    function view:SetSelectionVisible(visible)
        if self.SelectionBox then self.SelectionBox.Visible=visible and self.SelectionBox.Adornee~=nil end
        if not visible then
            for _,button in pairs(self.Handles)do button.Visible=false end
            if self.NativeGizmo then self.NativeGizmo.Hide()end
        else self:DrawGizmo()end
    end
    function view:SelectJoint(name,pickedPart)
        self:FinishTransform(false)
        self.Selected=name self.Inspector="joint"
        -- Reveal a clicked joint even when its parent was collapsed.
        for _,joint in ipairs(editor:Hierarchy())do self.Collapsed[joint.Name]=nil end
        updatePose() self:Refresh()
        self:UpdateSelection(pickedPart)
    end
    function view:UpdateSelection(pickedPart)
        local name=self.Selected
        self.OutlinedJoint=name
        if ctx.SelectionParts then
            local part=pickedPart
            if not part then
                for _,entry in ipairs(ctx.SelectionParts(editor.DetectedRig))do if entry.Name==name then part=entry.Part break end end
            end
            if part then
                if not self.SelectionBox then
                    self.SelectionBox=ctx.Util.Instance("SelectionBox",ctx.ScreenGui)
                    self.SelectionBox.Name="EditorSelectedJoint"self.SelectionBox.LineThickness=.035
                    self.SelectionBox.Color3=Color3.fromRGB(255,188,66)self.SelectionBox.SurfaceTransparency=1
                end
                self.SelectionBox.Adornee=part self:SetSelectionVisible(studio.Visible and studio.Mode=="editor")
            elseif self.SelectionBox then self.SelectionBox.Visible=false end
        end
    end
    function view:DrawTree()
        if not studio.Visible or studio.Mode~="editor"then return end
        local valid,visible={},{}
        for _,name in ipairs(editor:Joints())do valid[name]=true end
        for name,pooled in pairs(self.TreePool)do
            if not valid[name]then
                studio.Destroy(pooled.Button)if pooled.Collapse then studio.Destroy(pooled.Collapse)end self.TreePool[name]=nil
            end
        end
        local query=jointSearch.Text:lower() local count=0
        for _,joint in ipairs(self:JointRows(query~="")) do
            local name,depth=joint.Name,math.min(joint.Depth,6)
            if name:lower():find(query,1,true) then
                local x=4+depth*10
                visible[name]=true
                local pooled=self.TreePool[name]
                if not pooled then
                    local row=studio.Button(tree,name,0,0,100,function()self:SelectJoint(name)end,"Joint_"..name)
                    studio.FontSize(row,12)row.TextXAlignment=Enum.TextXAlignment.Left
                    pooled={Button=row}self.TreePool[name]=pooled
                end
                if joint.Children>0 then
                    if not pooled.Collapse then pooled.Collapse=studio.Button(tree,"",0,0,20,function()
                        self.Collapsed[name]=not self.Collapsed[name] self:DrawTree() self:DrawTimeline()
                    end,"Collapse_"..name)end
                    pooled.Collapse.Text=self.Collapsed[name]and "▸"or "▾"pooled.Collapse.Visible=true
                    studio.Rect(pooled.Collapse,x,count*29,20,26)
                elseif pooled.Collapse then pooled.Collapse.Visible=false end
                local row=pooled.Button row.Visible=true
                studio.Rect(row,x+20,count*29,math.max(0,self.Bounds.Left-x-38),26)
                studio.Opacity(row,name==self.Selected and 0 or .65)
                count+=1
            end
        end
        for name,pooled in pairs(self.TreePool)do if not visible[name]then
            pooled.Button.Visible=false if pooled.Collapse then pooled.Collapse.Visible=false end
        end end
        tree.CanvasSize=UDim2.fromOffset(0,count*29)
    end
    function view:JointRows(expanded)
        local out,skip={},nil
        for _,joint in ipairs(editor:Hierarchy()) do
            if skip and joint.Depth<=skip then skip=nil end
            if not skip then
                table.insert(out,joint)
                if not expanded and self.Collapsed[joint.Name] then skip=joint.Depth end
            end
        end
        return out
    end
    function view:DrawTimeline()
        if not self.Width or not root.Parent or not root.Visible or not studio.Visible or studio.Mode~="editor" then return end
        local all=self:JointRows() local rows=#all+1
        local canvasWidth=math.max(grid.AbsoluteSize.X,editor.Track.Time*self.Zoom+80)
        grid.CanvasSize=UDim2.fromOffset(canvasWidth,rows*layout.JointRowHeight)
        names.CanvasSize=UDim2.fromOffset(0,rows*layout.JointRowHeight)
        studio.ClampScroll(grid)studio.ClampScroll(names)
        local first,last=layout.VirtualRange(rows,layout.JointRowHeight,grid.CanvasPosition.Y,grid.AbsoluteSize.Y)
        local from=(grid.CanvasPosition.X-8)/self.Zoom local to=(grid.CanvasPosition.X+grid.AbsoluteSize.X-8)/self.Zoom
        local used,labels=0,0
        local function keyWidget(t,row,name,count)
            used+=1 local pooled=self.KeyPool[used]
            if not pooled then
                local button=studio.Button(grid,"◆",0,0,14,function()
                    if pooled then
                        if pooled.PointerActivated then pooled.PointerActivated=nil return end
                        at(pooled.Time,pooled.Joint)
                    end
                end,"TimelineKey")
                studio.FontSize(button,12)pooled={Button=button} self.KeyPool[used]=pooled
                button.InputBegan:Connect(function(input)
                    if view.KeySelection then studio.Run(function()view.KeySelection.BeginKey(pooled,input)end)end
                end)
            end
            pooled.Time,pooled.Joint=t,name
            local button=pooled.Button
            button.Text=self.KeySelection and self.KeySelection.IsSelected(t,name)and "◈"or (count>1 and "◇"or "◆")
            local displayed=self.KeySelection and self.KeySelection.PreviewTime(t,name)or t
            studio.Opacity(button,1) button.Visible=true
            studio.Rect(button,8+displayed*self.Zoom-7,(row-1)*layout.JointRowHeight+3,14,19)
        end
        for row=first,last do
            labels+=1 local pooled=self.LabelPool[labels]
            if not pooled then
                local label=studio.Node("TextButton",names,"TrackLabel") studio.FontSize(label,12)label.Text=""
                label.Activated:Connect(function()if pooled.Joint then studio.Run(function()view:SelectJoint(pooled.Joint)end)end end)
                pooled={Button=label} self.LabelPool[labels]=pooled
            end
            local label=pooled.Button
            local joint=all[row-1] local name=joint and joint.Name
            pooled.Joint=name
            label.Text=joint and (string.rep("  ",math.min(joint.Depth,6))..name) or "All joints" label.Visible=true
            studio.Rect(label,8,(row-1)*layout.JointRowHeight,self.Bounds.LabelWidth-16,layout.JointRowHeight)
            local line=self.RowLines[labels]
            if not line then
                line=studio.Node("Frame",grid,"TrackGuide") line.BackgroundTransparency=.88
                line.ZIndex=grid.ZIndex ctx.Theme.ApplyFrame(line,{FillText=true}) self.RowLines[labels]=line
            end
            line.Visible=true studio.Rect(line,0,row*layout.JointRowHeight-1,canvasWidth,1)
            local samples=name and editor.TimelineIndex[name] or editor.TimelineFrames
            for _,key in ipairs(layout.Keys(samples,from,to,self.Zoom)) do keyWidget(key.Time,row,name,key.Count) end
        end
        for i=used+1,#self.KeyPool do self.KeyPool[i].Button.Visible=false end
        for i=labels+1,#self.LabelPool do self.LabelPool[i].Button.Visible=false end
        for i=labels+1,#self.RowLines do self.RowLines[i].Visible=false end
        local minimum=64/self.Zoom
        local power=10^math.floor(math.log10(minimum))local step=power*10
        for _,multiple in ipairs({1,2,5,10})do if power*multiple>=minimum then step=power*multiple break end end
        local ticks=0
        for i=math.floor(from/step),math.ceil(to/step) do
            local t=i*step
            ticks+=1 local label=self.RulerPool[ticks]
            if not label then label=studio.Label(ruler,"",0,0,55,22,11,"RulerTick")self.RulerPool[ticks]=label end
            label.Visible=true label.Text=string.format("%.1f",t)
            studio.Rect(label,t*self.Zoom-grid.CanvasPosition.X+11,0,55,22)
        end
        for i=ticks+1,#self.RulerPool do self.RulerPool[i].Visible=false end
        self:Tick()
    end
    function view:Tick()
        if not studio.Visible or studio.Mode~="editor" then return end
        clock.Text=string.format("%.3f / %.3f s",editor.Time,editor.Track.Time)
        if ctx.Input:GetFocusedTextBox()~=seek then seek.Text=string.format("%.3f",editor.Time) end
        frameLabel.Text=string.format("Frame %d · %g fps",math.round(editor.Time*editor.FPS),editor.FPS)
        studio.Rect(playhead,8+editor.Time*self.Zoom,0,2,math.max(grid.AbsoluteSize.Y,grid.CanvasSize.Y.Offset))
        self:DrawGizmo()
    end
    function view:DrawEvents()
        if not studio.Visible or studio.Mode~="editor"then return end
        local used=0
        if self.Inspector=="events" then
            local first,last=layout.VirtualRange(#editor.Track.Markers,32,math.max(0,form.CanvasPosition.Y-146),form.AbsoluteSize.Y)
            for i=first,last do
                used+=1 local marker=editor.Track.Markers[i] local pooled=self.EventPool[used]
                if not pooled then
                    local seek=studio.Button(eventList,"",8,0,200,function()at(pooled.Time)end)
                    local remove=studio.Button(eventList,"×",0,0,30,function()
                        editor:Edit(function(track)ctx.Files.Track.removeMarker(track,pooled.Index)end)refresh()
                    end)
                    pooled={Seek=seek,Remove=remove} self.EventPool[used]=pooled
                end
                pooled.Index,pooled.Time=i,marker.Time
                pooled.Seek.Text=string.format("%.2f  %s",marker.Time,marker.Name)
                pooled.Seek.Visible=true pooled.Remove.Visible=true
                local width=values.AbsoluteSize.X
                studio.Rect(pooled.Seek,8,(i-1)*32,math.max(80,width-62),26)
                studio.Rect(pooled.Remove,width-46,(i-1)*32,30,26)
            end
        end
        for i=used+1,#self.EventPool do self.EventPool[i].Seek.Visible=false self.EventPool[i].Remove.Visible=false end
    end
    function view:Refresh()
        local all=editor:Joints()
        if not table.find(all,self.Selected) then self.Selected=all[1] end
        self.Loop=editor.Track.Looped~=false
        clipName.Text=editor.Track.Name fps.Text=tostring(editor.FPS) duration.Text=tostring(editor.Track.Time)
        loop.Text="Loop: "..(self.Loop and "On" or "Off")
        poseForm.Visible=self.Inspector=="joint" clipForm.Visible=self.Inspector=="clip" eventsForm.Visible=self.Inspector=="events"
        form.CanvasSize=UDim2.fromOffset(0,self.Inspector=="events" and (160+#editor.Track.Markers*32) or 330)
        if self.Document~=editor.DocumentSerial then self.Document=editor.DocumentSerial self.RotationRefs={} self:Command("fit",true) end
        if self.OutlinedJoint~=self.Selected then self:UpdateSelection()end
        updatePose() self:DrawTree() self:DrawTimeline() self:Layout(self.Width,self.Height) self:Tick() self:DrawEvents()
        if self.Workbench then self.Workbench.Refresh()end
    end
    function view:Command(command,noRefresh)
        if self.KeySelection and table.find({"select-all","copy-keys","paste-keys","duplicate-selected","delete-selected"},command)then
            return self.KeySelection.Command(command)
        end
        if command=="tool-select"then return self:SetTool("Select")
        elseif command=="tool-move"then return self:SetTool("Move")
        elseif command=="tool-rotate"then return self:SetTool("Rotate")end
        self:FinishTransform(false)
        if command=="undo" then editor:Undo()
        elseif command=="redo" then editor:Undo(true)
        elseif command=="copy" then
            assert(self.Selected,"Select a joint") local cf,pose=editor:PoseAt(self.Selected,editor.Time) self.Clipboard={cf,pose}
        elseif command=="paste" then
            assert(self.Selected and self.Clipboard,"Copy a joint pose first") local cf,p=table.unpack(self.Clipboard)
            editor:SetPose(self.Selected,cf,p.EasingStyle,p.EasingDirection,p.Weight,self.PoseParent)
        elseif command=="move"or command=="duplicate"then
            local joint=self.Selected
            local title=command=="move"and "Move key"or "Duplicate key"
            studio.Dialog(title,300,function(panel)
                studio.Label(panel,"Source time (seconds)",14,42,460,22,12)
                local from=studio.Box(panel,tostring(editor.Time),"Source seconds",14,68,220,"KeySourceTime")
                studio.Label(panel,"Destination frame",14,100,460,22,12)
                local destination=studio.Box(panel,tostring(math.round(editor.Time*editor.FPS)+1),"Frame number",14,126,220,"KeyDestinationFrame")
                local scope
                scope=studio.Button(panel,"Scope: "..(joint or "whole frame"),14,166,460,function()
                    if joint then joint=nil else joint=self.Selected end
                    scope.Text="Scope: "..(joint or "whole frame")
                end,"KeyScope")
                studio.Button(panel,"Cancel",250,218,108,studio.CloseDialog,"CancelKeyTransfer")
                studio.Button(panel,title,370,218,110,function()
                    local frame=tonumber(destination.Text)
                    assert(frame and frame>=0 and frame%1==0,"enter a nonnegative frame number")
                    editor:TransferKey(tonumber(from.Text),frame/editor.FPS,joint,command=="duplicate")
                    studio.CloseDialog()refresh()
                    return title.." applied at frame "..frame
                end,"ApplyKeyTransfer")
            end)
            return
        elseif command=="key" then
            assert(self.Selected,"Select a joint") local values={}
            for _,axis in ipairs({"px","py","pz","rx","ry","rz"}) do
                local n=tonumber(self.Fields[axis].Text) assert(n and n==n and math.abs(n)<1e10,"Invalid "..axis)
                values[axis]=axis:sub(1,1)=="r" and math.rad(n) or n
            end
            local weight=tonumber(self.Fields.weight.Text)
            assert(weight and weight==weight and weight>=0 and weight<1e10,"Invalid pose weight")
            editor:SetPose(self.Selected,ctx.Files.GetApex().Frame(values),self.Style,self.Direction,weight,self.PoseParent)
            self.RotationRefs[self.Selected]=values
        elseif command=="delete" then editor:DeleteKey(self.Selected)
        elseif command=="delete-frame" then editor:DeleteKey()
        elseif command=="previous" then editor:Adjacent(false)
        elseif command=="next" then editor:Adjacent(true)
        elseif command=="clip" then self.Inspector="clip" self:ShowValues()
        elseif command=="events" then self.Inspector="events" self:ShowValues()
        elseif command=="fit" then
            self.AutoFit=true
