-- Small responsive forms. Reflow existing controls so resizing never loses input.
return function(studio,parent,options)
    options=options or {}
    local api={Rows={},Padding=options.Padding or 8,Gap=options.Gap or 8,Height=0}
    function api.Item(object,minimum,weight)
        return {Object=object,Min=minimum or 80,Weight=weight or 1}
    end
    function api:Row(items,height)
        table.insert(self.Rows,{Items=items,Height=height or 28})return items
    end
    function api:Space(height)table.insert(self.Rows,{Space=height or 6})end
    function api:Note(text,height,name)
        local label=studio.Label(parent,text,0,0,0,height or 42,12,name)
        label.TextWrapped=true label.TextYAlignment=Enum.TextYAlignment.Top
        local entry=api.Item(label,1)entry.AutoText=true
        self:Row({entry},height or 42)return label
    end
    function api:Field(caption,control,minimum,weight)
        local frame=studio.Node("Frame",parent,"Field_"..control.Name)
        local title=studio.Label(frame,caption,0,0,0,18,11)
        local surface=studio.Surfaces[control]or control surface.Parent=frame
        return {Object=frame,Min=minimum or 90,Weight=weight or 1,
            Layout=function(width)studio.Rect(title,0,0,width,18)studio.Rect(control,0,22,width,28)end}
    end
    function api:Layout(width)
        local gap,padding=self.Gap,self.Padding
        local available=math.max(1,width-padding*2-(parent:IsA("ScrollingFrame")and 8 or 0))
        local y=padding
        for _,row in ipairs(self.Rows)do
            if row.Space then y+=row.Space else
                local first=1
                while first<=#row.Items do
                    local last,minWidth,totalWeight=first-1,0,0
                    while last<#row.Items do
                        local nextItem=row.Items[last+1]
                        local nextWidth=minWidth+(last>=first and gap or 0)+math.min(available,nextItem.Min)
                        if last>=first and nextWidth>available then break end
                        last+=1 minWidth=nextWidth totalWeight+=nextItem.Weight
                    end
                    local extra=math.max(0,available-minWidth)local x=padding
                    local rowHeight=row.Height
                    for i=first,last do
                        local item=row.Items[i]
                        if item.AutoText and studio.Context.MeasureText then
                            local object=item.Object
                            local ok,size=pcall(studio.Context.MeasureText,object.Text,object.TextSize,available)
                            if ok and size then rowHeight=math.max(rowHeight,math.ceil(size.Y)+4)end
                        end
                    end
                    for i=first,last do
                        local item=row.Items[i]
                        local w=math.min(available,item.Min)+extra*item.Weight/math.max(1,totalWeight)
                        studio.Rect(item.Object,math.round(x),y,math.max(1,math.floor(w)),rowHeight)
                        if item.Layout then item.Layout(math.max(1,math.floor(w)))end
                        x+=w+gap
                    end
                    y+=rowHeight+gap first=last+1
                end
            end
        end
        self.Height=y
        if parent:IsA("ScrollingFrame")then parent.CanvasSize=UDim2.fromOffset(0,y)end
        return y
    end
    studio.BindLayout(parent,function(w)api:Layout(w)end)
    return api
end
