-- Actual adornment shapes extracted from the supplied Studio gizmo model.
-- They decorate a private, non-colliding pivot, never the physical avatar.
return function(ctx)
    local template=ctx.Require("main/gizmo_template")
    local picking=ctx.Require("main/studio_gizmo_pick")
    local api={Items={},Proxies={},Visible=false}
    local folder=ctx.New("Folder",ctx.Parent)folder.Name="UhhhhhhStudioGizmos"
    local objects,records={},template.Objects
    local ok,reason=pcall(function()
        for id,record in pairs(records)do
            local object=ctx.New(record.Class)
            objects[id]=object
            for key,value in pairs(record.Props)do
                if key~="Adornee"then
                    if key=="CFrame"then value=CFrame.new(table.unpack(value))
                    elseif key=="Color3"then value=Color3.new(table.unpack(value))
                    elseif key=="Size"then value=Vector3.new(table.unpack(value))end
                    object[key]=value
                end
            end
            if record.Class=="Part"then
                object.Anchored=true object.Transparency=1 object.CanCollide=false object.CanTouch=false object.CanQuery=false
                object.CastShadow=false object.Parent=ctx.World table.insert(api.Proxies,object)
            end
        end
        for id,record in pairs(records)do
            local object=objects[id]
            if record.Class~="Part"then object.Parent=objects[tostring(record.Parent)]or folder end
            if record.Props.Adornee then object.Adornee=objects[tostring(record.Props.Adornee)]end
            if record.Class:find("HandleAdornment",1,true)then
                local axis,mode
                local ancestor=record
                while ancestor do
                    local name=ancestor.Props.Name or ""
                    axis=axis or name:match("^([XYZ])Axis")
                    mode=mode or (name=="Move_Gizmos"and "Move"or name=="Rot_Gizmos"and "Rotate"or name=="Size_Gizmos"and "Size")
                    ancestor=records[tostring(ancestor.Parent)]
                end
                object.Visible=false
                local props=picking.Properties(record.Class,record.Props,axis,mode)
                table.insert(api.Items,{Object=object,Axis=axis,Mode=mode,Props=props,
                    Lines=picking.Shape(record.Class,props)})
            end
        end
    end)
    if not ok then
        for _,object in pairs(objects)do pcall(function()object:Destroy()end)end
        folder:Destroy()error("gizmo creation failed: "..tostring(reason),0)
    end
    function api.Hide()
        if not api.Visible then return end
        api.Visible=false for _,item in ipairs(api.Items)do item.Object.Visible=false end
    end
    function api.Set(pivot,scale,mode,axis,highlight)
        if api.Visible and api.Pivot==pivot and api.Scale==scale and api.Mode==mode and api.Axis==axis and api.Highlight==highlight then return end
        api.Pivot,api.Scale,api.Mode,api.Axis,api.Highlight=pivot,scale,mode,axis,highlight
        api.Visible=true
        for _,part in ipairs(api.Proxies)do part.CFrame=pivot end
        for _,item in ipairs(api.Items)do
            local object,p=item.Object,item.Props
            object.Visible=item.Mode==mode and (axis=="Free"or not axis or item.Axis==axis)
            if object.Visible then
                local cf=CFrame.new(table.unpack(p.CFrame))object.CFrame=CFrame.new(cf.Position*scale)*cf.Rotation
                for _,key in ipairs({"Radius","InnerRadius","Height"})do if p[key]then object[key]=p[key]*scale end end
                if p.Size then object.Size=Vector3.new(table.unpack(p.Size))*scale end
                local color=Color3.new(table.unpack(p.Color3))
                object.Color3=item.Axis==highlight and color:Lerp(Color3.new(1,1,1),.45)or color
            end
        end
    end
    function api.HitTest(point,project,tolerance)
        if not api.Visible then return nil end
        return picking.Hit(api.Items,api.Pivot,api.Scale,api.Mode,point,project,tolerance or 9)
    end
    function api.Destroy()
        api.Hide()folder:Destroy()for _,part in ipairs(api.Proxies)do part:Destroy()end
    end
    return api
end
