-- Pick the rendered adornment geometry in GUI pixels. Native adornment mouse
-- signals can be swallowed by the editor's active viewport; touch has none.
local Pick={}
function Pick.Properties(kind,source,axis,mode)
    local props=table.clone(source)
    if kind=="CylinderHandleAdornment"and mode=="Rotate"then
        -- This model is a set of visual templates, not a working dragger. Its
        -- ring transforms don't share the move arrows' labeled axis frame.
        local basis=axis=="X"and CFrame.Angles(0,math.pi/2,0)
            or axis=="Y"and CFrame.Angles(-math.pi/2,0,0)or CFrame.identity
        local position=CFrame.new(table.unpack(source.CFrame)).Position
        props.CFrame={(CFrame.new(position)*basis):GetComponents()}
    end
    return props
end
function Pick.Distance(point,a,b)
    local x,y=b.X-a.X,b.Y-a.Y
    local length=x*x+y*y
    local t=length>1e-8 and math.clamp(((point.X-a.X)*x+(point.Y-a.Y)*y)/length,0,1)or 0
    local dx,dy=point.X-a.X-t*x,point.Y-a.Y-t*y
    return math.sqrt(dx*dx+dy*dy),t
end
function Pick.Shape(kind,p)
    local cf=CFrame.new(table.unpack(p.CFrame))
    local lines={}
    local function point(x,y,z)return cf:PointToWorldSpace(Vector3.new(x,y,z))end
    local function line(a,b)table.insert(lines,{a,b})end
    if kind=="CylinderHandleAdornment"then
        local radius=((p.Radius or 1)+(p.InnerRadius or p.Radius or 1))*.5
        local angle=math.rad(p.Angle or 360)
        for i=0,71 do
            local a,b=i/72*angle,(i+1)/72*angle
            line(point(math.cos(a)*radius,math.sin(a)*radius,0),point(math.cos(b)*radius,math.sin(b)*radius,0))
        end
    elseif kind=="ConeHandleAdornment"then
        local height,radius=p.Height or 1,p.Radius or .2
        local tip=point(0,0,-height/2)
        for i=0,7 do
            local a,b=i/8*math.pi*2,(i+1)/8*math.pi*2
            local first=point(math.cos(a)*radius,math.sin(a)*radius,height/2)
            line(tip,first)line(first,point(math.cos(b)*radius,math.sin(b)*radius,height/2))
        end
    elseif kind=="BoxHandleAdornment"then
        local size=p.Size or {1,1,1}local vertices={}
        for x=-1,1,2 do for y=-1,1,2 do for z=-1,1,2 do
            table.insert(vertices,point(x*size[1]/2,y*size[2]/2,z*size[3]/2))
        end end end
        for _,pair in ipairs({{1,2},{1,3},{1,5},{2,4},{2,6},{3,4},{3,7},{4,8},{5,6},{5,7},{6,8},{7,8}})do
            line(vertices[pair[1]],vertices[pair[2]])
        end
    end
    return lines
end
function Pick.Hit(items,pivot,scale,mode,point,project,tolerance)
    local best,score,depth=nil,math.huge,math.huge
    for _,item in ipairs(items)do
        if item.Mode==mode and item.Axis and (not item.Object or item.Object.Visible)
            and not (item.Props.Name or ""):match("^Bright")then
            for _,line in ipairs(item.Lines)do
                local a=project(pivot:PointToWorldSpace(line[1]*scale))
                local b=project(pivot:PointToWorldSpace(line[2]*scale))
                if a and b and a.Z>.01 and b.Z>.01 then
                    local distance,t=Pick.Distance(point,a,b)
                    local z=a.Z+(b.Z-a.Z)*t
                    if distance<=tolerance and (distance<score-.25 or (math.abs(distance-score)<=.25 and z<depth))then
                        best,score,depth=item.Axis,distance,z
                    end
                end
            end
        end
    end
    return best,score
end
return Pick
