-- Original CCD authoring solver. It edits poses, never physical avatar joints.
local IK={Chains={
    R6={{Name="Left arm",Joints={"Left Arm"}},{Name="Right arm",Joints={"Right Arm"}},
        {Name="Left leg",Joints={"Left Leg"}},{Name="Right leg",Joints={"Right Leg"}}},
    R15={{Name="Left arm",Joints={"LeftUpperArm","LeftLowerArm","LeftHand"}},
        {Name="Right arm",Joints={"RightUpperArm","RightLowerArm","RightHand"}},
        {Name="Left leg",Joints={"LeftUpperLeg","LeftLowerLeg","LeftFoot"}},
        {Name="Right leg",Joints={"RightUpperLeg","RightLowerLeg","RightFoot"}}}}}
local function turn(a,b)
    if a.Magnitude<1e-8 or b.Magnitude<1e-8 then return CFrame.identity end
    a,b=a.Unit,b.Unit local dot=math.clamp(a:Dot(b),-1,1)local axis=a:Cross(b)
    if axis.Magnitude<1e-8 then
        if dot>0 then return CFrame.identity end
        axis=a:Cross(math.abs(a.Y)<.8 and Vector3.yAxis or Vector3.xAxis)
    end
    return CFrame.fromAxisAngle(axis.Unit,math.acos(dot))
end
function IK.Forward(info,poses)
    local map={}for _,j in ipairs(info.Joints)do map[j.Name]=j end
    local world,visiting={},{}
    local function calc(name)
        if world[name]then return world[name]end
        local j=map[name]if not j then return nil end
        assert(not visiting[name],"cyclic rig joints")visiting[name]=true
        local parent=map[j.Parent]and calc(j.Parent)or j.ParentWorld
        local pose=poses[name]or CFrame.identity
        world[name]=parent*j.C0*(CFrame.new(pose.Position*(info.Scale or 1))*pose.Rotation)*j.C1:Inverse()
        visiting[name]=nil return world[name]
    end
    for name in pairs(map)do calc(name)end
    return world,map
end
function IK.EndPoint(info,poses,chain)
    local world,map=IK.Forward(info,poses)local name=chain.Joints[#chain.Joints]
    local j=assert(map[name],"this rig has no "..name)
    return world[name]:PointToWorldSpace(Vector3.new(0,-j.Size.Y/2,0))
end
function IK.Solve(info,original,chain,target,weight)
    local poses=table.clone(original)
    for _,name in ipairs(chain.Joints)do poses[name]=poses[name]or CFrame.identity end
    for iteration=1,18 do
