-- Shared by the live Roblox workspace and its source-derived layout renders.
local Layout={RowHeight=30,JointRowHeight=25}
local function rect(x,y,w,h) return {X=x,Y=y,W=math.max(0,w),H=math.max(0,h)} end
function Layout.Editor(w,h,options)
    options=options or {}
    local left=(options.HideJoints or w<620)and 0 or (w<1050 and 174 or 218)
    local right=options.HideValues and 0 or (w<940 and 0 or (w<1100 and 246 or 282))
    local top=w<500 and 98 or(w<700 and 66 or 36)
    local timeline=options.HideTimeline and 0 or math.min(math.clamp(math.floor(h*.35),120,270),math.max(0,h-top-118))
    if options.Authoring and timeline>0 then timeline=math.min(math.max(240,math.floor(h*.48)),math.max(0,h-top-118))end
    local upper=math.max(0,h-top-timeline-6)
    if upper<200 then right=0 end
    return {Toolbar=rect(0,0,w,top),Joints=rect(0,top+4,left,upper),
        Viewport=rect(left>0 and left+6 or 0,top+4,w-left-right-(left>0 and 6 or 0)-(right>0 and 6 or 0),upper),
        Values=rect(w-right,top+4,right,upper),Timeline=rect(0,h-timeline,w,timeline),
        Left=left,Right=right,LabelWidth=math.min(math.max(left,132),math.min(218,w*.34))}
end
function Layout.Shell(w,h)
    local menuHeight=w<570 and 62 or 30
    local toolY=42+menuHeight
    local bodyY=toolY+36
    return {MenuHeight=menuHeight,ToolY=toolY,BodyY=bodyY,BodyHeight=math.max(0,h-bodyY-28)}
end
function Layout.Maker(w,h)
    if w<600 then
        local dock=math.max(90,math.floor(h*.66))
        return rect(0,0,w,dock),rect(0,dock+8,w,math.max(0,h-dock-8))
    end
    local dock=math.min(510,math.max(320,math.floor(w*.48)))
    return rect(0,0,dock,h),rect(dock+8,0,w-dock-8,h)
end
function Layout.Browser(w,h)
    local left=w<600 and 0 or(w<900 and 160 or 206)
    local right=w<800 and 0 or (w<1100 and 250 or 294)
    return {Sources=rect(0,0,left,h),Results=rect(left>0 and left+6 or 0,0,w-left-right-(left>0 and 6 or 0)-(right>0 and 6 or 0),h),
        Details=rect(w-right,0,right,h),Left=left,Right=right}
end
function Layout.VirtualRange(count,rowHeight,scroll,viewHeight)
    local first=math.max(1,math.floor(math.max(0,scroll)/rowHeight))
    return first,math.min(count,first+math.ceil(math.max(viewHeight,0)/rowHeight)+2)
end
function Layout.Keys(samples,from,to,pixelsPerSecond)
    local lo,hi=1,#samples
    while lo<=hi do local mid=math.floor((lo+hi)/2) if samples[mid].Time<from then lo=mid+1 else hi=mid-1 end end
    local out,last,bucket={},nil,nil
    for i=lo,#samples do
        local key=samples[i]
        if key.Time>to then break end
        local cell=math.floor((key.Time-from)*pixelsPerSecond/8)
        if cell~=bucket then
            last={Time=key.Time,Count=1} table.insert(out,last) bucket=cell
        else last.Count+=1 end
    end
    return out
end
return Layout
