-- Makers share one data model, preview runtime and export path.
return function(ctx)
    local files,anim=ctx.Files,ctx.AnimLib
    local vfx=ctx.Require("main/studio_vfx")
    local api={States={"idle","walk","run","jump","fall","climb","swim","sit"}}
    function api.New(kind)
        assert(kind=="moveset"or kind=="dance","invalid maker")
        return {Format="Uhhhhhh.Maker",Version=1,Kind=kind,Name=kind=="dance"and "My dance"or "My moveset",
            Author="",Fade=.15,Slots={}}
    end
    function api.Validate(project)
        assert(type(project)=="table"and project.Format=="Uhhhhhh.Maker"and project.Version==1,"invalid maker project")
        local out=api.New(project.Kind)
        out.Name=tostring(project.Name or "")out.Author=tostring(project.Author or "")
        assert(#out.Name>0 and #out.Name<=128 and #out.Author<=128,"enter a name (up to 128 characters)")
        out.Fade=tonumber(project.Fade)or .15 assert(out.Fade>=0 and out.Fade<=2,"blend time must be 0 to 2 seconds")
        assert(type(project.Slots)=="table","invalid maker slots")
        for key,entry in pairs(project.Slots)do
            assert(key=="dance"or table.find(api.States,key),"invalid movement slot")
            assert(project.Kind=="dance"and key=="dance"or project.Kind=="moveset"and key~="dance","clip slot does not belong to this maker")
            assert(type(entry)=="table","invalid clip assignment")
            local speed=tonumber(entry.Speed)or 1 assert(speed>0 and speed<=4,"clip speed must be over 0 to 4")
            out.Slots[key]={Track=files.Canonical(entry.Track),Speed=speed,Looped=entry.Looped~=false}
        end
        return out
    end
    function api.Assign(project,slot,track,speed,looped)
        assert(slot=="dance"or table.find(api.States,slot),"choose a movement state")
        local nextProject=api.Validate(project)
        nextProject.Slots[slot]={Track=files.Canonical(track),Speed=speed or 1,Looped=looped~=false}
        return api.Validate(nextProject)
    end
    function api.Encode(project)
        local out=api.Validate(project)
        for _,entry in pairs(out.Slots)do entry.Track=files.ToText(entry.Track)end
        return ctx.Encode(out)
    end
    function api.Decode(bytes)
        assert(type(bytes)=="string"and #bytes<=64*1024*1024,"maker project is too large")
        local project=ctx.Decode(bytes)
        assert(type(project)=="table"and type(project.Slots)=="table","invalid maker data")
        for _,entry in pairs(project.Slots)do entry.Track=files.FromText(entry.Track)end
        return api.Validate(project)
    end
    function api.Concat(first,second,gap)
        first,second=files.Canonical(first),files.Canonical(second)
        gap=tonumber(gap)or 0 assert(gap>=0 and gap<=60,"gap must be 0 to 60 seconds")
        local a,b=files.Bake(first),files.Bake(second)local at=a.Time+gap
        -- A boundary belongs to the second clip, so an exact join has one pose per joint.
        if gap==0 then
            for i=#a.Keyframes,1,-1 do if math.abs(a.Keyframes[i].Time-at)<1e-7 then table.remove(a.Keyframes,i)end end
        end
        anim.Track.paste(a,b,at)
        a.Name=first.Name.." + "..second.Name a.Effects=first.Effects or {}a.Attribution=first.Attribution or {}
        for _,effect in ipairs(second.Effects or {})do local e=table.clone(effect)e.At+=at table.insert(a.Effects,e)end
        local seen={}for _,entry in ipairs(a.Attribution)do seen[(entry.Reference or "")..(entry.AssetId or "")..(entry.Source or "")]=true end
        for _,entry in ipairs(second.Attribution or {})do
            local id=(entry.Reference or "")..(entry.AssetId or "")..(entry.Source or "")
            if not seen[id]and #a.Attribution<64 then table.insert(a.Attribution,table.clone(entry))seen[id]=true end
        end
        a.Music=first.Music or second.Music
        if first.Studio or second.Studio then
            local s=files.Document.Ensure(a)s.Length=at+b.Time
            for number,source in ipairs({first,second})do
                local st=source.Studio local offset=number==1 and 0 or at
                if st then
                    for _,key in ipairs(st.Camera)do local k=files.Document.Copy(key)k.Time+=offset
                        for i=#s.Camera,1,-1 do if math.abs(s.Camera[i].Time-k.Time)<1e-7 then table.remove(s.Camera,i)end end
                        table.insert(s.Camera,k)
                    end
                    for _,prop in ipairs(st.Props)do local p=files.Document.Copy(prop)
                        p.Name=p.Name.." / clip "..number
                        p.Start=(p.Start or 0)+offset p.End=(p.End or source.Time)+offset
                        for _,key in ipairs(p.Keys)do key.Time+=offset end table.insert(s.Props,p)
                    end
                end
            end
        end
        return files.Canonical(a)
    end
    function api.BeatMarkers(track,bpm)
        bpm=tonumber(bpm)assert(bpm and bpm>=20 and bpm<=300,"BPM must be 20 to 300")
        track=files.Canonical(track)
        for i=#track.Markers,1,-1 do if track.Markers[i].Source=="Beat grid"then table.remove(track.Markers,i)end end
        local count=math.floor(track.Time/(60/bpm))assert(count<=4000,"beat grid is too large")
        for i=0,count do table.insert(track.Markers,{Time=i*60/bpm,Name="Beat",Value=tostring(i+1),Source="Beat grid"})end
        return files.Canonical(track)
    end
    function api.State(humanoid)
        local state=humanoid:GetState().Name
        if state=="Jumping"then return "jump"end
        if state=="Freefall"or state=="FallingDown"then return "fall"end
        if state=="Climbing"then return "climb"end
        if state=="Swimming"then return "swim"end
        if humanoid.Sit or state=="Seated"then return "sit"end
        if humanoid.MoveDirection.Magnitude<.05 then return "idle"end
        return humanoid.WalkSpeed>18 and "run"or "walk"
    end
