        project=api.Validate(project)options=options or {}
        assert(next(project.Slots),"assign at least one clip first")
        if project.Kind=="moveset"then assert(project.Slots.idle,"assign an idle clip first")end
        local module={Name=project.Name,Description="Made with Uhhhhhh's simple "..project.Kind.." maker. by "..project.Author,
            ModuleType=project.Kind=="dance"and "DANCE"or "MOVESET",Assets={},Config=function()end,
            _UhhhhhhSource="Your maker project",_UhhhhhhMakerProject=project}
        if project.Kind=="dance"and project.Slots.dance then module._UhhhhhhEditableTrack=project.Slots.dance.Track end
        local media={}
        for _,entry in pairs(project.Slots)do
            local music=entry.Track.Music local id=music and music.Id
            if id and not id:match("^%d+$")and not id:match("^rbxassetid://%d+$")and not media[id]then
                media[id]=true table.insert(module.Assets,id)
            end
        end
        local rig,current,effects,sound,previous,fadeAge,clock,slot=nil,nil,nil,nil,nil,0,0,nil
        local scene
        local function dispose()
            if current then current:Destroy(false)current=nil end
            if previous then previous:Destroy(false)previous=nil end
            if effects then effects.Destroy()effects=nil end
            if sound then sound:Destroy()sound=nil end
            if scene then scene.Destroy()scene=nil end
        end
        local function choose(key)
            local entry=project.Slots[key]or project.Slots.idle
            if not entry then return end
            if previous then previous:Destroy(false)previous=nil end
            previous=current
            current=anim.Animator.fromTrack(rig,entry.Track,{Looped=entry.Looped,Speed=entry.Speed,
                UseGlobalPlaybackSpeed=false,UseDanceMusicSync=false,AutoFadeIn=0,MarkerNotifications=false})
            current:Play()slot=key clock=0 fadeAge=0
            if effects then effects.Destroy()end effects=vfx.Runtime(current.rig or rig,entry.Track.Effects or {},ctx.New)
            if scene then scene.Destroy()end
            if files.Scene then scene=files.Scene(current.rig or rig,entry.Track)end
            if sound then sound:Destroy()sound=nil end
            local music=entry.Track.Music
            if music and ctx.SoundId then
                local id=ctx.SoundId(music.Id)
                if id then
                    sound=ctx.New("Sound")sound.Name="UhhhhhhMakerMusic"sound.SoundId=id
                    sound.Volume=music.Volume sound.PlaybackSpeed=music.Speed sound.Looped=entry.Looped
                    sound.Parent=rig:FindFirstChild("HumanoidRootPart")or rig
