-- Guided forms around the ordinary editor. No node graphs or scripting needed.
return function(studio)
    local ctx=studio.Context
    local api={Projects={},DraftSequences={},DraftBytes={}}
    local function tools()return assert(ctx.Makers,"maker tools are unavailable")()end
    local show,vfx
    local function filesDialog()
        local store=assert(tools().Store,"project storage is unavailable")
        studio.Dialog("Open a maker project",390,function(panel)
            local names=store.List()local width=panel.AbsoluteSize.X-28
            local list=studio.Scroll(panel,"MakerProjects")studio.Rect(list,14,46,width,240)
            list.CanvasSize=UDim2.fromOffset(0,#names*33)
            for i,name in ipairs(names)do
                studio.Button(list,name,0,(i-1)*33,width-8,function()
                    local project=tools().Decode(store.Read(name))api.Projects[project.Kind]=project
                    api.Paths=api.Paths or {}api.Paths[project.Kind]=name show(project.Kind)
                end,"MakerProject_"..i)
            end
            studio.Button(panel,"Back",14,306,width,function()show(api.Kind or "moveset")end,"BackToMaker")
        end)
    end
    local function saveProject(project,export)
        local t=tools()local bytes=t.Encode(project)
        if export then
            local folder=t.Store.Export(project,bytes)
            studio.Status("saved module to "..folder.." · reload user modules to use it")return
        end
        studio.Dialog("Save maker project",224,function(panel)
            local width=panel.AbsoluteSize.X-28
            local filename=studio.Box(panel,api.Paths and api.Paths[project.Kind]or project.Name:gsub('[^%w_%-]','_')..".uhmaker.json",
                "Filename.uhmaker.json",14,52,width,"MakerFilename")
            local replace=false local button
            button=studio.Button(panel,"Replace: Off",14,92,180,function()replace=not replace button.Text="Replace: "..(replace and "On"or "Off")end,"ReplaceMaker")
            studio.Button(panel,"Back",14,135,180,function()show(project.Kind)end,"CancelMakerSave")
            studio.Button(panel,"Save",206,135,width-192,function()
                assert(filename.Text:match("%.uhmaker%.json$"),"use a .uhmaker.json filename")
                local path=t.Store.Write(filename.Text,bytes,replace)
                api.Paths=api.Paths or {}api.Paths[project.Kind]=filename.Text
                show(project.Kind)studio.Status("saved "..path)
            end,"ConfirmMakerSave")
        end)
    end
    local function commitBinding()
        local b=api.Binding if not b then return end
        local project=assert(api.Projects[b.Kind],"maker project is missing")
        local slot=assert(project.Slots[b.Slot],"maker slot is missing")
        api.Projects[b.Kind]=tools().Assign(project,b.Slot,studio.Editor().Track,slot.Speed,slot.Looped)
