    ["UhhhhhhReanim/System/runtime/steve110/main/studio_media.lua"] = [=====[
return function(ctx)
    local effects=ctx.Require("main/studio_vfx").Runtime(ctx.Rig,ctx.Track.Effects or {},ctx.New)
    local sound
    local music=ctx.Track.Music
    if music and ctx.SoundId then
        local id=ctx.SoundId(music.Id)
        if id then
            sound=(ctx.New or Instance.new)("Sound")sound.Name="UhhhhhhStudioMusic"sound.SoundId=id
            sound.Volume=music.Volume sound.PlaybackSpeed=music.Speed
            sound.Parent=ctx.Rig:FindFirstChild("HumanoidRootPart")or ctx.Rig
        end
    end
    local scene=ctx.Require("main/studio_scene")({Document=ctx.Document,Track=ctx.Track,Rig=ctx.Rig,New=ctx.New,
        World=ctx.World,Camera=ctx.Camera,CameraOwned=ctx.CameraOwned})
    local api={Effects=effects,Sound=sound,Scene=scene,Last=-1}
    function api.Step(time,playing,cameraEnabled)
        scene.Step(time,cameraEnabled~=false)
        if playing then effects.Step(time)
        elseif math.abs(time-api.Last)>.001 then effects.Reset()effects.Step(time)end
        if sound then
            local position=time*music.Speed+music.Offset
            if math.abs(sound.TimePosition-position)>.25 then sound.TimePosition=position end
            if playing and not sound.IsPlaying then sound:Resume()
            elseif not playing and sound.IsPlaying then sound:Pause()end
        end
        api.Last=time
    end
    function api.Destroy()scene.Destroy()effects.Destroy()if sound then sound:Destroy()end end
    return api
end
