    ["UhhhhhhReanim/System/runtime/steve110/main/studio_pointer.lua"] = [=====[
-- Explicitly pair pointer coordinates and projection for this ScreenGui's inset
-- policy. Mouse samples use the live cursor, including on button release.
return function(ctx)
    local api={}
    function api.Point(input)
        local inset=ctx.Inset and ctx.Inset()or Vector2.zero
        if input.UserInputType~=Enum.UserInputType.Touch and ctx.Mouse then
            local raw=ctx.Mouse()
            return ctx.IgnoreInset and raw or raw-inset
        end
        local point=Vector2.new(input.Position.X,input.Position.Y)
        return ctx.IgnoreInset and point+inset or point
    end
    function api.Ray(point)
        local camera=assert(ctx.Camera(),"camera is unavailable")
        if ctx.IgnoreInset then return camera:ViewportPointToRay(point.X,point.Y)end
        return camera:ScreenPointToRay(point.X,point.Y)
    end
    function api.Project(point)
        local camera=assert(ctx.Camera(),"camera is unavailable")
        if ctx.IgnoreInset then return camera:WorldToViewportPoint(point)end
        return camera:WorldToScreenPoint(point)
    end
    return api
end
