    ["UhhhhhhReanim/System/runtime/steve110/main/studio_recorder.lua"] = [=====[
-- Samples already-playing joint poses. It does not fetch or execute asset code.
return function(ctx)
    local api={}
    function api.Start(options)
        assert(not api.Session,"a recording is already running")
        local fps=tonumber(options.FPS)or 30 local duration=tonumber(options.Duration)or 5
        assert(fps>=1 and fps<=60 and duration>0 and duration<=120,"record 0–120 seconds at 1–60 FPS")
        local track={Name=options.Name or "Recorded animation",FPS=fps,Looped=true,RigType=options.RigType,
            Keyframes={},Markers={},Attribution={{Source="Local pose recording",Reference=options.Source or "Currently playing rig"}}}
        local state={Age=0,Next=0,Total=0,Track=track}
        api.Session=state
        local function sample(t)
            local poses=ctx.Capture()
            assert(type(poses)=="table"and #poses>0,"no animated joints are available; start reanimation first")
            state.Total+=#poses assert(state.Total<=500000,"recording is too large")
            table.insert(track.Keyframes,{Time=t,Poses=poses})
        end
        local function finish(cancelled)
            if api.Session~=state then return end
            api.Session=nil if state.Connection then state.Connection:Disconnect()end
            if not cancelled then
                local at=math.min(state.Age,duration)
                if at>track.Keyframes[#track.Keyframes].Time+1e-7 then
                    local ok,why=pcall(sample,at)
                    if not ok then if ctx.Error then ctx.Error(tostring(why))end return end
                end
                local result=ctx.Files.Canonical(track)
                if ctx.Done then ctx.Done(result)end
                return result
            end
        end
        state.Finish=finish
        local ok,why=pcall(sample,0)
        if not ok then finish(true)error(why,0)end
        state.Next=1/fps
        state.Connection=ctx.Signal:Connect(function(dt)
            local ok,why=pcall(function()
                state.Age+=dt
                if state.Age>=state.Next then
                    sample(math.min(state.Age,duration))state.Next=state.Age+1/fps
                    if ctx.Progress then ctx.Progress(state.Age,duration,#track.Keyframes)end
                end
                if state.Age>=duration then finish(false)end
            end)
            if not ok then finish(true)if ctx.Error then ctx.Error(tostring(why))end end
        end)
        return state
    end
    function api.Stop(cancelled)
        local state=api.Session if state then return state.Finish(cancelled)end
    end
    return api
end
