-- Local, data-only scene previews. Camera ownership is explicitly released.
return function(ctx)
    local doc=ctx.Document local track=ctx.Track local s=track.Studio
    local api={Props={},CameraEnabled=false}
    if not s then function api.Step()end function api.Destroy()end function api.ReleaseCamera()end return api end
    local new=ctx.New or Instance.new
    if ctx.World then
        local folder=new("Folder")folder.Name="UhhhhhhEditorProps"folder.Parent=ctx.World api.Folder=folder
        for i,p in ipairs(s.Props)do
            local part=new("Part")part.Name=p.Name part.Anchored=true part.CanCollide=false part.CanTouch=false part.CanQuery=false
            part.Size=Vector3.new(table.unpack(p.Size))part.Color=Color3.fromHex(p.Color)part.Shape=Enum.PartType[p.Shape]
            part.Transparency=p.Hidden and 1 or .12 part.Parent=folder api.Props[i]=part
        end
    end
    local saved,camera
    function api.ReleaseCamera()
        if saved and camera then
            camera.CameraType=saved.Type camera.CameraSubject=saved.Subject camera.CFrame=saved.CFrame camera.Focus=saved.Focus camera.FieldOfView=saved.FOV
        end
        if saved and ctx.CameraOwned then ctx.CameraOwned(false)end
        saved=nil camera=nil
    end
    function api.Step(t,enabled)
        if ctx.Rig and not ctx.Rig.Parent then
            api.ReleaseCamera()for _,part in ipairs(api.Props)do part.Transparency=1 end return
        end
        for i,p in ipairs(s.Props)do
            local part=api.Props[i]local cf=doc.SampleKeys(p.Keys,t)
            if part then part.Transparency=(p.Hidden or t<(p.Start or 0)or(p.End and t>p.End))and 1 or .12 end
            if part and cf then
                local anchor=p.Anchor~="World"and ctx.Rig:FindFirstChild(p.Anchor,true)
                part.CFrame=anchor and anchor:IsA("BasePart")and anchor.CFrame*cf or cf
            end
        end
        local current=ctx.Camera and ctx.Camera()
        if saved and current~=camera then api.ReleaseCamera()end
        if enabled and current and #s.Camera>0 then
            if not saved then
                camera=current saved={Type=camera.CameraType,Subject=camera.CameraSubject,CFrame=camera.CFrame,Focus=camera.Focus,FOV=camera.FieldOfView}
                if ctx.CameraOwned then ctx.CameraOwned(true)end
            end
            local cf,fov=doc.SampleKeys(s.Camera,t)
            camera.CameraType=Enum.CameraType.Scriptable camera.CFrame=cf camera.Focus=cf*CFrame.new(0,0,-10)camera.FieldOfView=fov
        else api.ReleaseCamera()end
    end
    function api.Destroy()api.ReleaseCamera()if api.Folder then api.Folder:Destroy()end table.clear(api.Props)end
    return api
end
