    ["UhhhhhhReanim/System/runtime/steve110/main/studio_selection.lua"] = [=====[
-- Pick original avatar body bounds without requiring CanQuery or changing it.
local Pick={}
function Pick.Distance(cf,size,origin,direction)
    local inverse=cf:Inverse()
    local o=inverse*CFrame.new(origin)
    local endpoint=inverse*CFrame.new(origin+direction)
    local d=endpoint.Position-o.Position
    local near,far=0,math.huge
    for _,axis in ipairs({"X","Y","Z"})do
        local p,v,half=o.Position[axis],d[axis],size[axis]/2
        if math.abs(v)<1e-9 then if math.abs(p)>half then return nil end
        else
            local a,b=(-half-p)/v,(half-p)/v
            if a>b then a,b=b,a end
            near,far=math.max(near,a),math.min(far,b)
            if near>far then return nil end
        end
    end
    return near
end
function Pick.Nearest(candidates,origin,direction)
    local chosen,distance
    for _,entry in ipairs(candidates)do
        local part=entry.Part
        if part and part.Parent then
            local t=Pick.Distance(part.CFrame,part.Size,origin,direction)
            if t and (not distance or t<distance)then chosen,distance=entry,t end
        end
    end
    return chosen,distance
end
return Pick
