-- Pointer-owned selection and atomic, undoable key dragging.
return function(studio,view,editor)
    local input=studio.Context.Input
    local api={Selection={}}
    local function point(i)return view:Point(i)end
    local function isPointer(i)return i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch end
    local function shift()return input:IsKeyDown(Enum.KeyCode.LeftShift)or input:IsKeyDown(Enum.KeyCode.RightShift)end
    local function ctrl()return input:IsKeyDown(Enum.KeyCode.LeftControl)or input:IsKeyDown(Enum.KeyCode.RightControl)end
    local function matches(a,t,j)return math.abs(a.Time-t)<1e-7 and a.Joint==j end
    function api.IsSelected(t,j)
        for _,a in ipairs(api.Selection)do if matches(a,t,j)then return true end end return false
    end
    function api.PreviewTime(t,j)
        local d=api.Drag
        if d and d.Kind=="keys"and api.IsSelected(t,j)then return t+(d.Delta or 0)end return t
    end
    function api.BeginKey(pooled,i)
        if not isPointer(i)or api.Drag or studio.Modal or studio.Popup then return end
        view:FinishTransform(false)
        local selected=api.IsSelected(pooled.Time,pooled.Joint)
        if ctrl()then
            if selected then for n=#api.Selection,1,-1 do if matches(api.Selection[n],pooled.Time,pooled.Joint)then table.remove(api.Selection,n)end end
            else table.insert(api.Selection,{Time=pooled.Time,Joint=pooled.Joint})end
        elseif shift()then
            if not selected then table.insert(api.Selection,{Time=pooled.Time,Joint=pooled.Joint})end
        elseif not selected then api.Selection={{Time=pooled.Time,Joint=pooled.Joint}}end
        editor:Seek(pooled.Time)
        if pooled.Joint then view:SelectJoint(pooled.Joint)end
        pooled.PointerActivated=true
        api.Drag={Kind="keys",Input=i,Origin=point(i),Delta=0,ReleaseScroll=studio.HoldScroll(view.Grid,studio.Body),Duplicate=input:IsKeyDown(Enum.KeyCode.LeftAlt)or input:IsKeyDown(Enum.KeyCode.RightAlt)}
        view:Refresh()
    end
    local lasso=studio.Node("Frame",view.Grid,"TimelineSelectionBox")
    lasso.BackgroundTransparency=.78 lasso.BackgroundColor3=Color3.fromRGB(255,190,72)lasso.ZIndex=130 lasso.Visible=false
    function api.Cancel()
        if api.Drag and api.Drag.ReleaseScroll then api.Drag.ReleaseScroll()end
        api.Drag=nil lasso.Visible=false if studio.Visible then view:DrawTimeline()end
    end
    function api.All()
        api.Selection={}
        editor:Joints()
        for name,keys in pairs(editor.TimelineIndex)do for _,key in ipairs(keys)do table.insert(api.Selection,{Time=key.Time,Joint=name})end end
        view:DrawTimeline()
    end
    function api.Command(command)
        if command=="select-all"then api.All()
        elseif command=="delete-selected"then editor:DeleteSelection(api.Selection)api.Selection={}view:Refresh()
        elseif command=="copy-keys"then return "copied "..editor:CopySelection(api.Selection).." keys"
        elseif command=="paste-keys"then api.Selection=editor:PasteSelection()view:Refresh()
        elseif command=="duplicate-selected"then api.Selection=editor:TransferSelection(api.Selection,1/editor.FPS,true)view:Refresh()end
    end
    view.Grid.InputBegan:Connect(function(i)
        if not isPointer(i)or api.Drag or studio.Modal or studio.Popup or not studio.Visible then return end
        if i.UserInputType==Enum.UserInputType.Touch then return end -- Empty space stays available for native touch scrolling.
        local p=point(i)
        for _,pooled in ipairs(view.KeyPool)do
            local b=pooled.Button local pos,size=b.AbsolutePosition,b.AbsoluteSize
            if b.Visible and p.X>=pos.X and p.X<=pos.X+size.X and p.Y>=pos.Y and p.Y<=pos.Y+size.Y then return end
        end
        if not shift()and not ctrl()then api.Selection={}end
        api.Drag={Kind="box",Input=i,Origin=p,Before=table.clone(api.Selection),ReleaseScroll=studio.HoldScroll(view.Grid,studio.Body)}
    end)
    studio.Connect(view.Root,input.InputChanged,function(i)
        local d=api.Drag
        if not d or not studio.Visible or studio.Mode~="editor"then return end
        if i~=d.Input and not (d.Input.UserInputType==Enum.UserInputType.MouseButton1 and i.UserInputType==Enum.UserInputType.MouseMovement)then return end
        local p=point(i)
        if d.Kind=="keys"then
            local delta=math.round((p.X-d.Origin.X)/view.Zoom*editor.FPS)/editor.FPS
            if delta~=d.Delta then d.Delta=delta view:DrawTimeline()
                studio.Status((d.Duplicate and "copy "or "move ")..#api.Selection.." keys: "..string.format("%+.3fs",delta))
            end
        else
            local a,b=d.Origin,p local left,top=math.min(a.X,b.X),math.min(a.Y,b.Y)
            local right,bottom=math.max(a.X,b.X),math.max(a.Y,b.Y)
            local grid=view.Grid
            studio.Rect(lasso,left-grid.AbsolutePosition.X+grid.CanvasPosition.X,top-grid.AbsolutePosition.Y+grid.CanvasPosition.Y,right-left,bottom-top)
            lasso.Visible=true api.Selection=table.clone(d.Before)
            local rows=view:JointRows()
            editor:Joints()
            for row,joint in ipairs(rows)do
                local y=grid.AbsolutePosition.Y+row*studio.Layout.JointRowHeight+12-grid.CanvasPosition.Y
                if y>=top and y<=bottom then
                    for _,sample in ipairs(editor.TimelineIndex[joint.Name]or {})do
                        local x=grid.AbsolutePosition.X+8+sample.Time*view.Zoom-grid.CanvasPosition.X
                        if x>=left and x<=right and not api.IsSelected(sample.Time,joint.Name)then
                            table.insert(api.Selection,{Time=sample.Time,Joint=joint.Name})
                        end
                    end
                end
            end
            view:DrawTimeline()
        end
    end)
