-- Pointer-to-pose maths. Only animation data changes; avatar physics stays with its writer.
local Transform={}
local axes={X=Vector3.new(1,0,0),Y=Vector3.new(0,1,0),Z=Vector3.new(0,0,1)}
function Transform.Axis(name,basis)
    local axis=axes[name]
    return axis and (basis and basis:VectorToWorldSpace(axis) or axis)
end
function Transform.Plane(origin,direction,point,normal)
    local denominator=direction:Dot(normal)
    if math.abs(denominator)<1e-7 then return nil end
    local distance=(point-origin):Dot(normal)/denominator
    if distance<0 then return nil end
    return origin+direction*distance
end
local function axisDistance(origin,direction,pivot,axis)
    direction=direction.Unit
    local parallel=axis:Dot(direction)
    local denominator=1-parallel*parallel
    if denominator<1e-5 then return nil end
    local offset=origin-pivot
    return (axis:Dot(offset)-parallel*direction:Dot(offset))/denominator
end
local function snap(value,step)
    return step and step>0 and math.round(value/step)*step or value
end
function Transform.Begin(base,pose,ray,options)
    options=options or {}
    local scale=options.Scale or 1
    assert(scale>0 and scale<1e6,"invalid avatar scale")
    local pivot=base*(CFrame.new(pose.Position*scale)*pose.Rotation)
    local axis=Transform.Axis(options.Axis,options.LocalSpace and pivot or nil)
    local session={Base=base,Pose=pose,Pivot=pivot.Position,Mode=options.Mode or "Move",Axis=axis,
        Snap=options.Snap,Scale=scale,Origin=options.Pointer or Vector2.zero,PreviousAngle=0,Angle=0,
        UnitsPerPixel=options.UnitsPerPixel or .05}
    if session.Mode=="Rotate" then
        assert(axis,"choose X, Y or Z to rotate")
        local point=Transform.Plane(ray.Origin,ray.Direction,session.Pivot,axis)
        session.StartVector=point and (point-session.Pivot).Magnitude>1e-5 and (point-session.Pivot).Unit or nil
    else
        session.Normal=options.ViewNormal or ray.Direction.Unit
        session.StartPoint=Transform.Plane(ray.Origin,ray.Direction,session.Pivot,session.Normal)
        session.StartDistance=axis and axisDistance(ray.Origin,ray.Direction,session.Pivot,axis)
        assert(session.StartPoint,"the limb is behind the camera")
    end
    return session
end
function Transform.Update(session,ray,pointer)
    if session.Mode=="Rotate" then
        local point=Transform.Plane(ray.Origin,ray.Direction,session.Pivot,session.Axis)
        local angle
        if session.StartVector and point and (point-session.Pivot).Magnitude>1e-5 then
            local nextVector=(point-session.Pivot).Unit
            local current=math.atan2(session.Axis:Dot(session.StartVector:Cross(nextVector)),session.StartVector:Dot(nextVector))
            session.Angle+=(current-session.PreviousAngle+math.pi)%(2*math.pi)-math.pi
            session.PreviousAngle=current angle=session.Angle
        else
            local delta=(pointer or session.Origin)-session.Origin
            angle=(delta.X-delta.Y)*.01
        end
        angle=snap(angle,session.Snap and math.rad(15))
        local localAxis=session.Base:VectorToObjectSpace(session.Axis)
        return CFrame.new(session.Pose.Position)*CFrame.fromAxisAngle(localAxis,angle)*session.Pose.Rotation
    end
    local point=Transform.Plane(ray.Origin,ray.Direction,session.Pivot,session.Normal)
    if not point then return nil end
    local delta=point-session.StartPoint
    if session.Axis then
        local distance=axisDistance(ray.Origin,ray.Direction,session.Pivot,session.Axis)
        local amount
        if distance and session.StartDistance then amount=distance-session.StartDistance
        elseif pointer then
            local screenDelta=pointer-session.Origin
            -- A depth axis collapses to a point when viewed end-on. Use an
            -- explicit screen gesture instead of silently producing zero.
            amount=(screenDelta.X-screenDelta.Y)*session.UnitsPerPixel
        else amount=delta:Dot(session.Axis)end
        delta=session.Axis*(snap(amount/session.Scale,session.Snap and .1)*session.Scale)
    end
    delta=session.Base:VectorToObjectSpace(delta)/session.Scale
    if not session.Axis and session.Snap then delta=Vector3.new(snap(delta.X,.1),snap(delta.Y,.1),snap(delta.Z,.1))end
    return CFrame.new(session.Pose.Position+delta)*session.Pose.Rotation
end
return Transform
