-- Visible authoring workspaces, independent of the original Uhhhhhh window.
return function(studio,view,editor)
    local ctx=studio.Context local files=ctx.Files local doc=files.Document
    local api={Tab="Keys",Channel="px",CurveIndex=1,Widgets={}}
    local panel=studio.Panel(view.Root,"AuthoringDock")panel.Visible=false api.Panel=panel
    local contents=studio.Scroll(panel,"AuthoringContents")contents.Size=UDim2.fromScale(1,1)
    contents.ScrollingDirection=Enum.ScrollingDirection.XY api.Contents=contents
    local function rebuild()studio.EnsurePreview()api.Refresh()view:Refresh()end
    local function run(fn)return function()fn()rebuild()end end
    local function label(text,x,y,w,h)return studio.Label(contents,text,x,y,w,h or 24,12)end
    local function button(text,x,y,w,fn,name)return studio.Button(contents,text,x,y,w,fn,name)end
    local function box(value,x,y,w,name)return studio.Box(contents,value,"",x,y,w,name)end
    local function number(text,low,high)
        local n=tonumber(text)assert(n and n==n and n>=low and n<=high,"enter a value from "..low.." to "..high)return n
    end
    function api.Open(tab)
        api.Cancel()
        api.Tab=tab studio.Options.HideTimeline=false
        view:FinishTransform(false)studio.CloseMakerPanel()
        view:Layout(view.Width,view.Height)api.Refresh()
        if studio.RefreshTools then studio.RefreshTools()end
        studio.Status(tab=="Keys"and "Shift+click selects more keys. drag keys to move; Alt+drag copies. drag empty space to box select."
            or tab.." · changes save with your .txt / .json project")
    end
    function api.Layout(bounds)
        studio.Place(panel,bounds)panel.Visible=api.Tab~="Keys"and not studio.Options.HideTimeline
        view.Timeline.Visible=api.Tab=="Keys"and not studio.Options.HideTimeline
        if api.LastWidth~=bounds.W or api.LastHeight~=bounds.H then
            api.LastWidth,api.LastHeight=bounds.W,bounds.H
            if api.Tab~="Keys"then task.defer(function()if panel.Parent then api.Refresh(true)end end)end
        end
    end
    local function drawGraph()
        if not api.Plot then return end
        local joint=view.Selected local c=joint and doc.Channel(editor.Track,joint,api.Channel)
        local keys=c and c.keys or {}local scale=api.Channel:sub(1,1)=="r"and 180/math.pi or 1
        if not api.Drag or not api.Range then
            local lo,hi=-1,1
            if #keys>0 then lo,hi=keys[1].v*scale,keys[1].v*scale
                for _,k in ipairs(keys)do lo=math.min(lo,k.v*scale)hi=math.max(hi,k.v*scale)end
            end
            if c and #keys>0 then for i=0,100 do
                local v=doc.CurveValue(c,i/100*math.max(editor.Track.Time,1),editor.Track)*scale
                lo=math.min(lo,v)hi=math.max(hi,v)
            end end
            local padding=math.max(.5,(hi-lo)*.2)local total=math.max(editor.Track.Time,1)
            local length=math.max(1/editor.FPS,total/(api.GraphZoom or 1))
            local start=math.clamp(editor.Time-length/2,0,math.max(0,total-length))
            api.Range={Low=lo-padding,High=hi+padding,Length=length,Start=start}
        end
        local r=api.Range local w,h=api.Plot.AbsoluteSize.X,api.Plot.AbsoluteSize.Y
        local function xy(t,v)return Vector2.new((t-r.Start)/r.Length*math.max(1,w-24)+12,h-12-(v*scale-r.Low)/(r.High-r.Low)*math.max(1,h-24))end
        api.GraphXY=xy api.GraphScale=scale
        local used=0
        local function line(a,b,color)
            used+=1 local o=api.Widgets[used]
            if not o then o=studio.Node("Frame",api.Plot,"CurveSegment")o.BorderSizePixel=0 o.BackgroundTransparency=0 o.AnchorPoint=Vector2.new(.5,.5)api.Widgets[used]=o end
            local delta=b-a o.Visible=true o.BackgroundColor3=color or Color3.fromRGB(255,189,74)
            o.Position=UDim2.fromOffset((a.X+b.X)/2,(a.Y+b.Y)/2)o.Size=UDim2.fromOffset(delta.Magnitude,2)o.Rotation=math.deg(math.atan2(delta.Y,delta.X))
        end
        local last
        for i=0,100 do
            local t=r.Start+i/100*r.Length local v=c and #keys>0 and doc.CurveValue(c,t,editor.Track)or 0
            local p=xy(t,v)if last then line(last,p)end last=p
        end
        api.GraphPoints=api.GraphPoints or {}local usedDots=0
        api.GraphCurrentKeys=keys
        local function dot(t,v,index,handle)
            local p=xy(t,v)if p.X<0 or p.X>w or p.Y<0 or p.Y>h then return end
            usedDots+=1 local entry=api.GraphPoints[usedDots]
            if not entry then
                local o=studio.Button(api.Plot,"",0,0,16,nil,"CurvePoint")
                entry={Button=o}api.GraphPoints[usedDots]=entry
                o.InputBegan:Connect(function(i)
                    if i.UserInputType~=Enum.UserInputType.MouseButton1 and i.UserInputType~=Enum.UserInputType.Touch then return end
                    if api.Drag then return end
                    studio.Run(function()
                        api.CurveIndex=entry.Index editor:Seek(api.GraphCurrentKeys[entry.Index].t)
                        studio.EnsurePreview()editor:BeginDocumentGesture()
                        api.Drag={Kind="curve",Input=i,Index=entry.Index,Handle=entry.Handle,Origin=view:Point(i),Joint=view.Selected,Channel=api.Channel,ReleaseScroll=studio.HoldScroll(contents,studio.Body)}
                    end)
                end)
            end
            entry.Index,entry.Handle=index,handle
            local o=entry.Button o.Visible=true o.Text=handle and "○"or "◆"
            o.Name=handle and "CurveHandle_"..handle or "CurveKey_"..index
            studio.Rect(o,p.X-7,p.Y-10,16,20)studio.Opacity(o,1)
        end
        local bucket
        for i,k in ipairs(keys)do
            if k.t>=r.Start and k.t<=r.Start+r.Length then
                local cell=math.floor((k.t-r.Start)/r.Length*math.max(1,w)/7)
                if cell~=bucket or i==api.CurveIndex then dot(k.t,k.v,i)bucket=cell end
            end
        end
        local selected=keys[api.CurveIndex]
        if selected then
            local interp=ctx.Require("main/apex_engine/Shared/Interp")
            local left,right=interp.handlesAt(keys,api.CurveIndex)
            for side,offset in pairs({L=left,R=right})do
                local t,v=selected.t+offset[1],selected.v+offset[2]
                line(xy(selected.t,selected.v),xy(t,v),Color3.fromRGB(142,204,255))dot(t,v,api.CurveIndex,side)
            end
            api.CurveValue.Text=string.format("%.4f",selected.v*scale)
            api.CurveTime.Text=string.format("%.4f",selected.t)
        end
        for i=usedDots+1,#api.GraphPoints do api.GraphPoints[i].Button.Visible=false end
        for i=used+1,#api.Widgets do api.Widgets[i].Visible=false end
        api.GraphLegend.Text=string.format("%s · %s | %.2f to %.2f %s | %.2f–%.2fs",joint or "choose a joint",api.Channel,r.Low,r.High,scale==1 and "studs"or "degrees",r.Start,r.Start+r.Length)
    end
    local function graph(w,h)
        local wide=w>=680 local left=wide and 188 or 0
        label("CURVES · select a joint and channel",10,0,w-20)
        local tools=studio.Node("Frame",contents,"CurveTools")
        local toolWidth=wide and 180 or w-20
        studio.Rect(tools,10,34,toolWidth,360)
        local form=studio.Form(tools,{Padding=0,Gap=6})local item=form.Item
        local channels={}
        for _,axis in ipairs(doc.Channels)do
            local control=studio.Button(tools,axis:upper(),0,0,54,function()api.Channel=axis api.CurveIndex=1 api.Refresh()end,"CurveChannel_"..axis)
            studio.Opacity(control,api.Channel==axis and 0 or .48)table.insert(channels,item(control,48))
        end
        form:Row(channels)
        api.CurveTime=studio.Box(tools,editor.Time,"Seconds",0,0,80,"CurveTime")
        api.CurveValue=studio.Box(tools,"0","Value",0,0,86,"CurveValue")
        form:Row({form:Field("Seconds",api.CurveTime,76),form:Field("Value",api.CurveValue,80)},50)
        local function action(text,fn,name,minimum)
            local control=studio.Button(tools,text,0,0,100,fn,name)return item(control,minimum or 150)
        end
        form:Row({action("Key at playhead",run(function()
            local n=number(api.CurveValue.Text,-1e8,1e8)
            editor:KeyCurve(view.Selected,api.Channel,n/(api.Channel:sub(1,1)=="r"and 180/math.pi or 1))
        end),"AddCurveKey"),action("Apply time / value",run(function()
            local t=number(api.CurveTime.Text,0,3600)local v=number(api.CurveValue.Text,-1e8,1e8)/api.GraphScale
            editor:Edit(function(track)
                local c=assert(doc.Channel(track,view.Selected,api.Channel),"add a curve key first")
                local k=assert(c.keys[api.CurveIndex],"select a curve key")
                for i,p in ipairs(c.keys)do assert(i==api.CurveIndex or math.abs(p.t-t)>1e-7,"a key already occupies that time")end
                k.t,k.v=t,v table.sort(c.keys,function(a,b)return a.t<b.t end)
                for i,key in ipairs(c.keys)do if key==k then api.CurveIndex=i break end end
            end)
        end),"ApplyCurveKey")})
        local interpolation
        interpolation=studio.Button(tools,"Interpolation",0,0,150,function()
            local items={}for _,mode in ipairs({"Bezier","Linear","Constant","Sine","Quad","Bounce","Elastic"})do
                table.insert(items,{mode,run(function()editor:Edit(function(track)
                    local c=assert(doc.Channel(track,view.Selected,api.Channel),"add a curve key first")
                    assert(c.keys[api.CurveIndex],"select a curve key").interp=mode
                end)end)})
            end studio.Choices(interpolation,items)
        end,"CurveInterpolation")
        form:Row({item(interpolation,130),action("Delete selected key",run(function()editor:DeleteCurveKey(view.Selected,api.Channel,api.CurveIndex)end),"DeleteCurveKey")})
        form:Row({action("Zoom +",function()api.GraphZoom=math.min(1024,(api.GraphZoom or 1)*2)api.Refresh()end,"GraphZoomIn",70),
            action("Fit",function()api.GraphZoom=1 api.Refresh()end,"GraphFit",70)})
        local toolsHeight=form:Layout(toolWidth)studio.Rect(tools,10,34,toolWidth,toolsHeight)
        local top=wide and 58 or toolsHeight+76
        local plot=studio.Panel(contents,"CurvePlot")
        local plotHeight=math.max(180,h-top-12)
        studio.Rect(plot,left+10,top,w-left-20,plotHeight)api.Plot=plot api.Widgets={}
        api.GraphLegend=label("",left+10,top-24,w-left-20,22)
        contents.CanvasSize=UDim2.fromOffset(0,math.max(34+toolsHeight,top+plotHeight)+12)
        drawGraph()
    end
    local function layers(w,h)
        local s=doc.Ensure(editor.Track)local wide=w>=720
        label("LAYERS · choose the layer you want to edit",10,0,w-20)
        local stackWidth=wide and math.floor(w*.35)or w-20
        local stackHeight=wide and math.max(120,h-48)or math.min(172,math.max(104,(#s.Layers+1)*34+8))
        local list=studio.Scroll(contents,"LayerStack")studio.Rect(list,10,34,stackWidth,stackHeight)
        list.CanvasSize=UDim2.fromOffset(0,(#s.Layers+1)*34)
        local function row(name,index,y)
            local l=s.Layers[index]local chosen=s.ActiveLayer==index
            local choose=studio.Button(list,(chosen and "● "or "○ ")..name,0,y,stackWidth-96,run(function()editor:Layer(index)end),"ChooseLayer_"..index)
            studio.Opacity(choose,chosen and 0 or .48)
            if l then
                studio.Button(list,l.Muted and "M✓"or "M",stackWidth-90,y,38,run(function()editor:UpdateLayer(index,{Muted=not l.Muted})end),"MuteLayer_"..index)
                studio.Button(list,l.Solo and "S✓"or "S",stackWidth-46,y,38,run(function()editor:UpdateLayer(index,{Solo=not l.Solo})end),"SoloLayer_"..index)
            end
        end
        row("Base animation",0,0)for i,l in ipairs(s.Layers)do row(l.Name,i,i*34)end
        local x=wide and stackWidth+22 or 10 local top=wide and 34 or stackHeight+48
        local width=w-x-10
        local controls=studio.Node("Frame",contents,"LayerControls")studio.Rect(controls,x,top,width,400)
        local form=studio.Form(controls,{Padding=0})local item=form.Item
        local function action(text,fn,name,min)return item(studio.Button(controls,text,0,0,100,fn,name),min or 130)end
        form:Row({action("+ Override",run(function()editor:AddLayer()end),"AddOverrideLayer",110),action("+ Additive",run(function()editor:AddLayer(nil,"Additive")end),"AddAdditiveLayer",110)})
        local layer=s.Layers[s.ActiveLayer]
        if layer then
            local name=studio.Box(controls,layer.Name,"Layer name",0,0,150,"LayerName")
            local weight=studio.Box(controls,layer.Weight,"0–1",0,0,76,"LayerWeight")
            form:Row({form:Field("Layer name",name,130,2),form:Field("Weight 0–1",weight,84)},50)
            form:Row({action("Apply name / weight",run(function()editor:UpdateLayer(s.ActiveLayer,{Name=name.Text,Weight=number(weight.Text,0,1)})end),"ApplyLayer",150),
                action(layer.Blend,run(function()editor:UpdateLayer(s.ActiveLayer,{Blend=layer.Blend=="Override"and "Additive"or "Override"})end),"LayerBlend",90)})
            form:Row({action("Only selected limb",run(function()assert(view.Selected,"select a limb")editor:UpdateLayer(s.ActiveLayer,{Mask={[view.Selected]=1}})end),"MaskLayer",144),
                action("All limbs",run(function()editor:UpdateLayer(s.ActiveLayer,{Mask={}})end),"UnmaskLayer",78)})
            form:Row({action("Move up",run(function()editor:ReorderLayer(s.ActiveLayer,-1)end),"LayerUp",76),
                action("Move down",run(function()editor:ReorderLayer(s.ActiveLayer,1)end),"LayerDown",88),
                action("Remove",run(function()editor:RemoveLayer(s.ActiveLayer)end),"RemoveLayer",72)})
        else form:Note("Base edits stay on the original key tracks.",40)end
        form:Row({action("Add playing / selected clip as layer",function()
            studio.ChooseClip(nil,function(track)editor:AddLayer(track.Name,"Override",files.Bake(track))rebuild()end)
