        if not studio.ManageRepositories then studio.ManageRepositories=ctx.Require("main/studio_repositories")(studio)end
        studio.ManageRepositories()
    end
    function studio.CloneModule(module)
        local source=assert(ctx.Sources(),"marketplace is still starting")
        assert(source.Clone,"module copying is unavailable")
        studio.Dialog("Clone module + its media",224,function(panel)
            local width=panel.AbsoluteSize.X-28
            local note=studio.Label(panel,"This copies "..module.Name.." and its declared media into your local workspace. The source credits stay with it.",14,44,width,64,12)
            note.TextWrapped=true
            local owner=studio.Modal
            local copying=false
            studio.Button(panel,"Cancel",14,130,150,studio.CloseDialog,"CancelModuleClone")
            studio.Button(panel,"Clone locally",174,130,width-160,function()
                assert(not copying,"the copy is already running")copying=true
                studio.Status("copying the module...")
                studio.Async(function()
                    local ok,result=pcall(source.Clone,module,function()return not studio.Visible or studio.Modal~=owner end,
                        function(done,total)if studio.Modal==owner then studio.Status("copying media "..done.." / "..total)end end)
                    copying=false assert(ok,result)return result
                end,function(path)
                    if studio.Modal==owner then studio.CloseDialog()end
                    studio.Status("cloned to "..path.." · reload user modules, then edit its clips")
                end,function()return studio.Modal==owner and studio.Visible end)
            end,"ConfirmModuleClone")
        end)
    end
    function studio.EditCopy(row,active,accept)
        local owner=studio.Modal
        studio.Status("reading the clip... one sec")
        studio.Async(function()
            local track,report=studio.SourceTools().Read(row,{FPS=30,
                Cancelled=function()return not studio.Visible or (active and not active())end})
            return {Track=track,Report=report}
        end,function(result)
            if not studio.Visible or (active and not active())then return end
            if studio.Modal==owner then studio.CloseDialog()end
            if accept then accept(result.Track)else
                studio.OpenEditor(result.Track)
                studio.CloneTarget=row.Reference and row.Reference:match("^StudioClones/")and row.Reference or nil
            end
            studio.Status(result.Report or "got it :D this is a copy, the original stays as-is")
        end,function()return studio.Visible and (not active or active())end)
    end
    function studio.ChooseClip(module,accept,characters)
        local rows=studio.SourceTools().List(module)
        if characters and ctx.FetchTracks then
            for _,row in ipairs(ctx.FetchTracks())do table.insert(rows,row)end
        end
        local height=math.max(300,math.min(474,root.AbsoluteSize.Y-24))
        studio.Dialog("Make an editable copy",height,function(panel)
            local width=panel.AbsoluteSize.X>0 and panel.AbsoluteSize.X or math.min(510,root.AbsoluteSize.X-24)
            local owner=studio.Modal
            local search=studio.Box(panel,"","Search clip names / sources",14,45,width-28,"ClipSearch")
            local list=studio.Scroll(panel,"EditableClips")rect(list,12,80,width-24,height-202)
            local note=studio.Label(panel,"",14,height-116,width-28,42,12,"ClipSource")note.TextWrapped=true
            local selected,filtered,pool=nil,{},{}
            local draw
            draw=function()
                list.CanvasSize=UDim2.fromOffset(0,#filtered*34)
                local first,last=studio.Layout.VirtualRange(#filtered,34,list.CanvasPosition.Y,list.AbsoluteSize.Y)
                local used=0
                for i=first,last do
                    used+=1 local pooled=pool[used]
                    if not pooled then
                        local button
                        button=studio.Button(list,"",2,0,width-32,function()
                            selected=pooled.Row note.Text=(selected.Author and ("by "..selected.Author.." · ")or "")..(selected.Source or selected.Name)draw()
                        end,"EditableClip")button.TextXAlignment=Enum.TextXAlignment.Left
                        pooled={Button=button}pool[used]=pooled
                    end
                    pooled.Row=filtered[i]pooled.Button.Visible=true
                    pooled.Button.Text=(pooled.Row.Playing and "[playing] "or "")..pooled.Row.Name
                    rect(pooled.Button,2,(i-1)*34,width-32,28)
                    studio.Opacity(pooled.Button,selected==pooled.Row and 0 or .65)
                end
                for i=used+1,#pool do pool[i].Button.Visible=false end
            end
            local function filter()
                local query=search.Text:lower()filtered={}
                for _,row in ipairs(rows)do
                    if (row.Name.." "..(row.Source or "")):lower():find(query,1,true)then table.insert(filtered,row)end
                end
                draw()
            end
            search:GetPropertyChangedSignal("Text"):Connect(filter)
            studio.Connect(list,list:GetPropertyChangedSignal("CanvasPosition"),draw)
            studio.Button(panel,"Refresh",14,height-66,92,function()studio.ChooseClip(module,accept,characters)end,"RefreshClips")
            studio.Button(panel,"Cancel",width-238,height-66,100,studio.CloseDialog,"CancelClipCopy")
            studio.Button(panel,"Edit a copy",width-128,height-66,114,function()
                assert(selected,"pick a clip first :D")
                studio.EditCopy(selected,function()return studio.Modal==owner end,accept)
            end,"ConfirmClipCopy")
            note.Text=#rows==0 and "no clips yet. play an animation, or choose a module with .anim assets."or "pick the clip u want. movesets can have more than one."
            filter()
        end)
    end
    function studio.Preview(playing)
        assert(ctx.CanPlay(),"Start reanimation before previewing")
        studio.CancelInteractions()
        if studio.MakerPreview then
            studio.MakerPreview.Destroy()studio.MakerPreview=nil
        end
        local editor=studio.Editor() editor.Playing=playing
        ctx.Play(editor:MakeDance()) studio.RefreshEditor()
        return playing and "Playing editor preview" or "Paused at playhead"
    end
    function studio.StopPreview()
        if studio.MakerPreview then
            if ctx.IsSelected(studio.MakerPreview)then ctx.Stop()end
            studio.MakerPreview.Destroy()studio.MakerPreview=nil
        end
        local editor=studio.Edit
        if editor and ctx.IsSelected(editor.Module) then ctx.Stop() end
        if editor then
            editor.Playing=false
            if editor.Media and editor.Media.Scene then editor.Media.Scene.ReleaseCamera()end
        end
        studio.RefreshEditor()
    end
    function studio.Save(extension)
        local editor=studio.Editor()
        studio.Dialog("Save animation to workspace",228,function(panel)
            studio.Label(panel,ctx.Files.Root,14,44,470,22,12)
            local name=studio.Box(panel,studio.SaveName or ("animation."..(extension or "txt")),"Filename",14,73,470,"SaveFilename")
            if extension then name.Text=(name.Text:match("^(.*)%.[^.]+$") or name.Text).."."..extension end
            local replace=false
            local toggle
            toggle=studio.Button(panel,"Replace existing: Off",14,109,222,function()
                replace=not replace toggle.Text="Replace existing: "..(replace and "On" or "Off")
            end,"OverwriteFile")
            studio.Button(panel,"Cancel",256,150,108,studio.CloseDialog,"CancelSave")
            studio.Button(panel,"Save",374,150,110,function()
                local path,losses=ctx.Files.Export(editor.Track,name.Text,replace)
                studio.SaveName=name.Text studio.SavedRevision=editor.Revision studio.CloseDialog()
                studio.RefreshEditor()
                return "Saved "..path..(#losses>0 and "; .txt/.json retain "..table.concat(losses,", ") or "")
            end,"ConfirmSave")
        end)
    end
    function studio.ImportId(accept)
        studio.Dialog("Animation fetcher / Spoofer V2",287,function(panel)
            local id=studio.Box(panel,"","Animation ID or rbxassetid:// ID",14,50,470,"ImportId")
            local method="Auto"
            local select
            select=studio.Button(panel,method,14,89,470,function()
                studio.Choices(select,{{"Auto (try all readers)",function()method="Auto" select.Text=method end},
                    {"AnimationClipProvider (curves / keyframes)",function()method="AnimationClipProvider" select.Text=method end},
                    {"KeyframeSequenceProvider",function()method="KeyframeSequenceProvider" select.Text=method end},
                    {"GetObjects (Animation Spoofer)",function()method="GetObjects" select.Text="GetObjects (Animation Spoofer)" end}})
            end,"ImportMethod")
            studio.Label(panel,"Curve bake FPS",14,122,120,26,12)
            local bakeFPS=studio.Box(panel,"30","1–60 FPS",140,122,90,"ImportBakeFPS")
            studio.Button(panel,"Cancel",256,154,108,studio.CloseDialog)
            studio.Button(panel,"Import",374,154,110,function()
                studio.Status("Loading animation keyframes...")
                local owner=studio.Modal local requestedId,requestedMethod=id.Text,method
                local requestedFPS=tonumber(bakeFPS.Text)
                assert(requestedFPS and requestedFPS>=1 and requestedFPS<=60,"curve bake FPS must be 1 to 60")
                studio.Async(function()
                    local track,report=ctx.Files.FromAsset(requestedId,requestedMethod,{
                        FPS=requestedFPS,
                        Cancelled=function()return studio.Modal~=owner or not studio.Visible end,
                        Progress=function(done,total)if studio.Modal==owner then studio.Status(string.format("Baking native curves: %d%%",math.floor(done/total*100)))end end,
                    })return {Track=track,Report=report}
                end,function(result)
                    if studio.Modal~=owner or not studio.Visible then return end
                    studio.CloseDialog()
                    if type(accept)=="function"then accept(result.Track)else studio.OpenEditor(result.Track)end
                    studio.Status(result.Report or "Imported "..result.Track.Name)
                end,function()return studio.Modal==owner and studio.Visible end)
            end,"ImportAsset")
            studio.Button(panel,"Playing characters / animations...",14,198,470,function()
                studio.ChooseClip(nil,type(accept)=="function"and accept or nil,true)
            end,"FetchCharacterAnimations")
        end)
    end
    function studio.Record()
        assert(ctx.Heartbeat and ctx.RigInfo,"pose recording is unavailable")
        studio.Dialog("Record currently playing motion",298,function(panel)
            local width=panel.AbsoluteSize.X-28
            studio.Label(panel,"Records the reanimated rig's visible joint poses into editable keys. Keep the motion playing while recording.",14,42,width,56,12).TextWrapped=true
            local name=studio.Box(panel,"Recorded animation","Name",14,106,width,"RecordName")
            local duration=studio.Box(panel,"5","Seconds (up to 120)",14,144,width*.6-6,"RecordDuration")
            local fps=studio.Box(panel,"30","FPS (1–60)",20+width*.6,144,width*.4-6,"RecordFPS")
            local owner=studio.Modal
            local recorder=ctx.Require("main/studio_recorder")({Files=ctx.Files,Signal=ctx.Heartbeat,
                Capture=function()
                    local info=assert(ctx.RigInfo(studio.Editor().Track),"start reanimation first")local poses={}
                    for _,j in ipairs(info.Joints)do
                        local cf=j.Transform or CFrame.identity
                        table.insert(poses,{Name=j.Name,Parent=j.Parent,CFrame=cf.Rotation+cf.Position/(info.Scale or 1),
                            Weight=1,EasingStyle="Linear",EasingDirection="InOut"})
                    end
                    return poses
                end,
                Progress=function(age,total,count)if studio.Modal==owner then studio.Status(string.format("recording %.1f / %.1fs · %d frames",age,total,count))end end,
                Done=function(track)
                    if studio.Modal~=owner then return end
                    studio.DialogCleanup=nil studio.CloseDialog()studio.OpenEditor(track)studio.Preview(false)
                    studio.Status("recorded "..#track.Keyframes.." frames. ur copy is ready to edit :D")
                end,Error=function(why)studio.Status(why)end})
            studio.DialogCleanup=function()recorder.Stop(true)end
            studio.Button(panel,"Cancel",14,202,width*.3-6,studio.CloseDialog,"CancelRecording")
            studio.Button(panel,"Stop + keep",20+width*.3,202,width*.3-6,function()assert(recorder.Session,"start recording first")recorder.Stop(false)end,"StopRecording")
            studio.Button(panel,"Record",26+width*.6,202,width*.4-12,function()
                local editor=studio.Editor()editor:Joints()
                recorder.Start({FPS=tonumber(fps.Text),Duration=tonumber(duration.Text),Name=name.Text,RigType=editor.DetectedRig})
                studio.Status("recording... keep the motion playing")
            end,"StartRecording")
        end)
    end
    function studio.Maker(kind)
        if kind=="vfx"and studio.EditorView and studio.EditorView.Workbench.Tab~="Effects"then studio.EditorView.Workbench.Open("Effects")end
        if not studio.MakerUI then studio.MakerUI=ctx.Require("main/studio_makers")(studio)end
        studio.MakerUI.Open(kind)
    end
    local function editorAction(action)
        return function() studio.OpenEditor() return studio.EditorView:Command(action) end
    end
