            {"Select all timeline keys  Ctrl+A",editorAction("select-all")},
            {"Copy timeline keys  Ctrl+C",editorAction("copy-keys")},
            {"Paste timeline keys  Ctrl+V",editorAction("paste-keys")},
            {"Duplicate selected keys  Ctrl+D",editorAction("duplicate-selected")},
            {"Delete selected keys  Delete",editorAction("delete-selected")},
