        View=function()
            local items={}
            for _,item in ipairs({{"Joints panel","HideJoints"},{"Values panel","HideValues"},{"Timeline","HideTimeline"}}) do
                table.insert(items,{(studio.Options[item[2]] and "Show " or "Hide ")..item[1],function()
                    studio.Options[item[2]]=not studio.Options[item[2]] studio.LayoutNow()
                end})
            end
            table.insert(items,{"Fit timeline",editorAction("fit")})
            table.insert(items,{"Reset editor layout",function()
                studio.Dragging=nil
                studio.Floating={} studio.Options={HideJoints=false,HideValues=false,HideTimeline=false}
                body.CanvasPosition=Vector2.zero
                if studio.EditorView then
                    for _,panel in ipairs({studio.EditorView.Joints,studio.EditorView.Values,studio.EditorView.Timeline})do panel.ZIndex=84 end
                end
                root.Position=UDim2.fromScale(.5,.5)root.Size=UDim2.new(1,-28,1,-34)studio.Maximized=false
                studio.LayoutNow()studio.RefreshEditor()
            end})
            table.insert(items,{"Local files",function()studio.OpenBrowser("local")end})
            table.insert(items,{"Marketplace / Streamed",function()studio.OpenBrowser("market")end})
            table.insert(items,{"Favorites",function()studio.OpenBrowser("favorites")end})
            table.insert(items,{"Hidden",function()studio.OpenBrowser("hidden")end})
            return items
        end,
        Animation=function()return {{"Play / Pause  Space",function()return studio.Preview(not studio.Editor().Playing)end},
            {"Moveset maker...",function()studio.Maker("moveset")end},
            {"Dance maker...",function()studio.Maker("dance")end},
            {"VFX maker...",function()studio.Maker("vfx")end},
            {"Select limb  Q",editorAction("tool-select")},{"Move limb  W",editorAction("tool-move")},{"Rotate limb  E",editorAction("tool-rotate")},
            {"Stop preview",studio.StopPreview},{"Previous key",editorAction("previous")},{"Next key",editorAction("next")},
            {"Clip settings",editorAction("clip")},{"Animation events",editorAction("events")}} end,
    }
    local menuButtons={}
    for i,name in ipairs(menuNames) do
        local button
        button=studio.Button(menu,name,(i-1)*86+6,2,80,function()studio.Choices(button,menus[name]())end,"Menu"..name)
        menuButtons[i]=button
    end
    local toolItems={{"Keys","Keys"},{"Curves","Curves"},{"Layers","Layers"},{"IK","IK"},{"Scene","Scene"},
        {"Moveset","moveset"},{"Dance","dance"},{"VFX","vfx"},{"Fetch","fetch"},{"Copy","copy"},{"Record","record"}}
    local toolButtons={}
    for i,entry in ipairs(toolItems)do toolButtons[i]=studio.Button(toolsbar,entry[1],6+(i-1)*102,1,96,function()
        if entry[2]=="record"then studio.Record()
        elseif entry[2]=="fetch"then studio.ImportId()
        elseif entry[2]=="copy"then studio.ChooseClip()
        elseif entry[2]=="moveset"or entry[2]=="dance"or entry[2]=="vfx"then
            studio.OpenEditor()studio.Maker(entry[2])
        else studio.OpenEditor()studio.EditorView.Workbench.Open(entry[2])end
    end,"Tool_"..entry[2])end
    function studio.RefreshTools()
        local active=studio.MakerDock and studio.MakerUI and studio.MakerUI.Kind
            or (studio.Mode=="editor"and studio.EditorView and studio.EditorView.Workbench.Tab)
        for i,entry in ipairs(toolItems)do studio.Opacity(toolButtons[i],entry[2]==active and 0 or .48)end
    end
    studio.ReturnMakerButton=studio.Button(footer,"Apply to maker",0,0,186,function()
        assert(studio.MakerUI and studio.MakerUI.CommitClip,"open a maker slot first")studio.MakerUI.CommitClip()
    end,"ReturnToMaker")
    studio.ReturnMakerButton.Visible=false
    toolsbar.CanvasSize=UDim2.fromOffset(1026,0)
    local editorButton=studio.Button(menu,"Editor",0,2,94,function()studio.OpenEditor()end,"SwitchEditor")
    local browserButton=studio.Button(menu,"Assets",0,2,94,function()studio.OpenBrowser()end,"SwitchAssets")
    local back=studio.Button(header,"Back to Uhhhhhh",0,3,150,function()studio.Hide()end,"ExitStudio")
    local maximize=studio.Button(header,"Maximize",0,3,88,function()
        if studio.Maximized then
            root.Size=studio.NormalSize or UDim2.new(1,-28,1,-34)
            root.Position=studio.NormalPosition or UDim2.fromScale(.5,.5)
        else
            studio.NormalSize,studio.NormalPosition=root.Size,root.Position
            root.Position=UDim2.fromScale(.5,.5)root.Size=UDim2.new(1,-8,1,-8)
        end
        studio.Maximized=not studio.Maximized
        studio.LayoutNow()
    end,"MaximizeStudio")
    local resize=studio.Node("TextButton",root,"ResizeStudio") resize.Text="◢" resize.ZIndex=150 studio.FontSize(resize,18)
    local resizing,resizeStart,resizeSize
    studio.Drag(title,function()return root.AbsolutePosition end,function(start,delta)
        local screen,size=ctx.ScreenGui.AbsoluteSize,root.AbsoluteSize
        local x=math.clamp(start.X+delta.X,4,math.max(4,screen.X-size.X-4))
        local y=math.clamp(start.Y+delta.Y,4,math.max(4,screen.Y-size.Y-4))
        root.Position=UDim2.fromOffset(x+size.X/2,y+size.Y/2)
    end)
    resize.InputBegan:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            studio.CancelInteractions()
            studio.Maximized=false
            resizing=input resizeStart=input.Position resizeSize=root.AbsoluteSize
        end
    end)
    studio.Connect(root,Input.InputChanged,function(input)
        local drag=studio.Dragging
        if drag and studio.Visible and (input.UserInputType==Enum.UserInputType.MouseMovement or input==drag.Input)then
            studio.Run(function()drag.Move(drag.State,input.Position-drag.Origin)end)
        end
        if resizing and (input.UserInputType==Enum.UserInputType.MouseMovement or input==resizing) then
            local delta=input.Position-resizeStart
            local screen=ctx.ScreenGui.AbsoluteSize
            root.Size=UDim2.fromOffset(math.clamp(resizeSize.X+delta.X*2,math.min(640,screen.X-8),screen.X-8),
                math.clamp(resizeSize.Y+delta.Y*2,math.min(400,screen.Y-8),screen.Y-8))
        end
    end)
    studio.Connect(root,Input.InputEnded,function(input)
        if input==resizing then resizing=nil end
        if studio.Dragging and input==studio.Dragging.Input then
            if studio.Dragging.ReleaseScroll then studio.Dragging.ReleaseScroll()end studio.Dragging=nil
        end
    end)
    if Input.WindowFocusReleased then studio.Connect(root,Input.WindowFocusReleased,function()resizing=nil studio.CancelInteractions()end)end
    function studio.FitWindow()
        local screen=ctx.ScreenGui.AbsoluteSize local size=root.AbsoluteSize local position=root.AbsolutePosition
        local w,h=math.min(size.X,math.max(1,screen.X-8)),math.min(size.Y,math.max(1,screen.Y-8))
        local x=math.clamp(position.X,4,math.max(4,screen.X-w-4))
        local y=math.clamp(position.Y,4,math.max(4,screen.Y-h-4))
        if w~=size.X or h~=size.Y then root.Size=UDim2.fromOffset(w,h)end
        if x~=position.X or y~=position.Y or w~=size.X or h~=size.Y then root.Position=UDim2.fromOffset(x+w/2,y+h/2)end
    end
    function studio.LayoutNow()
        studio.FitWindow()
        local width,height=root.AbsoluteSize.X,root.AbsoluteSize.Y
        local previous=studio.LastLayoutSize
        if previous and(previous.X~=width or previous.Y~=height)then studio.CancelInteractions()end
        studio.LastLayoutSize=Vector2.new(width,height)
        local shell=studio.Layout.Shell(width,height)
        rect(header,0,0,width,34) rect(menu,0,38,width,shell.MenuHeight)
        rect(toolsbar,0,shell.ToolY,width,32)
        local toolWidth=math.min(102,math.max(68,(width-12)/#toolButtons))
        for i,button in ipairs(toolButtons)do rect(button,6+(i-1)*toolWidth,1,toolWidth-6,26)end
        toolsbar.CanvasSize=UDim2.fromOffset(12+#toolButtons*toolWidth,0)
        rect(body,0,shell.BodyY,width,shell.BodyHeight) rect(footer,0,height-24,width,24)
        studio.ContentHeight=math.max(420,shell.BodyHeight)
        studio.ContentWidth=math.max(180,width-8)
        body.CanvasSize=UDim2.fromOffset(0,studio.ContentHeight)
        studio.ClampScroll(body)
        local backWidth=width<600 and 76 or 150
        back.Text=width<600 and "Back"or "Back to Uhhhhhh"
        rect(title,12,0,math.max(0,width-backWidth-116),34)
        rect(status,10,0,math.max(0,width-(studio.ReturnMakerButton.Visible and 228 or 32)),24)
        rect(back,width-backWidth-8,4,backWidth,26) rect(maximize,width-backWidth-102,4,88,26)
        maximize.Text=studio.Maximized and "Restore"or "Maximize"
        if shell.MenuHeight>30 then
            studio.Row(menu,menuButtons,6,2,width-12,26)
            rect(editorButton,6,34,(width-18)/2,26)rect(browserButton,12+(width-18)/2,34,(width-18)/2,26)
        else
            studio.Row(menu,menuButtons,6,2,math.min(338,width-222),26)
            rect(editorButton,width-206,2,94,26)rect(browserButton,width-106,2,98,26)
        end
        rect(resize,width-20,height-20,20,20)
        rect(studio.ReturnMakerButton,width-216,0,186,24)
        if studio.EditorView then
            rect(studio.EditorView.Root,0,0,studio.ContentWidth,studio.ContentHeight)
            studio.EditorView:Layout(studio.ContentWidth,studio.ContentHeight)
        end
        if studio.BrowserView then
            rect(studio.BrowserView.Root,0,0,studio.ContentWidth,studio.ContentHeight)
            studio.BrowserView:Layout(studio.ContentWidth,studio.ContentHeight)
        end
        if studio.LayoutMaker then studio.LayoutMaker()end
        if studio.FrameActive and studio.Mode=="editor"then studio.FrameStage()end
        studio.RefreshTools()
    end
    studio.Connect(root,root:GetPropertyChangedSignal("AbsoluteSize"),studio.LayoutNow)
