        ctx.MainWindow.Main.Interactable=studio.MainInteractable~=false
    end
    studio.Connect(root,Input.InputBegan,function(input,processed)
        if not studio.Visible or processed or Input:GetFocusedTextBox() then return end
        local key=input.KeyCode
        if key==Enum.KeyCode.Escape then
            if studio.EditorView and studio.EditorView.KeySelection and studio.EditorView.KeySelection.Drag then
                studio.EditorView.KeySelection.Cancel()return
            end
            if studio.EditorView and studio.EditorView.TransformDrag then
