            end
            if studio.EditorView and studio.EditorView.Workbench and studio.EditorView.Workbench.SceneTools
                and studio.EditorView.Workbench.SceneTools.Drag then studio.EditorView.Workbench.Cancel()return end
            if studio.Popup then studio.CloseMenu()elseif studio.Modal then studio.CloseDialog()
            elseif studio.MakerDock then studio.CloseMakerPanel()studio.RefreshEditor()else studio.Hide()end
            return
        end
        if studio.Modal or studio.Popup then return end
        local control=Input:IsKeyDown(Enum.KeyCode.LeftControl) or Input:IsKeyDown(Enum.KeyCode.RightControl)
            or Input:IsKeyDown(Enum.KeyCode.LeftMeta) or Input:IsKeyDown(Enum.KeyCode.RightMeta)
        if control then
            if key==Enum.KeyCode.O then studio.OpenBrowser("local")
            elseif key==Enum.KeyCode.S then studio.Run(function()
                if studio.MakerDock and studio.MakerUI and studio.MakerUI.Kind~="vfx"then studio.MakerUI.Save()else studio.Save()end
            end)
            elseif studio.Mode=="editor" and key==Enum.KeyCode.Z then studio.Run(editorAction("undo"))
            elseif studio.Mode=="editor" and key==Enum.KeyCode.Y then studio.Run(editorAction("redo")) end
            if studio.Mode=="editor"then
                local commands={[Enum.KeyCode.D]="duplicate-selected",[Enum.KeyCode.A]="select-all",[Enum.KeyCode.C]="copy-keys",[Enum.KeyCode.V]="paste-keys"}
                if commands[key]then studio.Run(editorAction(commands[key]))end
            end
        elseif studio.Mode=="editor"then
            if key==Enum.KeyCode.Delete or key==Enum.KeyCode.Backspace then studio.Run(editorAction("delete-selected"))
            elseif key==Enum.KeyCode.Space then studio.Run(function()return studio.Preview(not studio.Editor().Playing)end)
            elseif key==Enum.KeyCode.Q then studio.Run(editorAction("tool-select"))
            elseif key==Enum.KeyCode.W then studio.Run(editorAction("tool-move"))
            elseif key==Enum.KeyCode.E then studio.Run(editorAction("tool-rotate"))
            elseif key==Enum.KeyCode.X or key==Enum.KeyCode.Y or key==Enum.KeyCode.Z then
                studio.Run(function()studio.EditorView:SetAxis(key==Enum.KeyCode.X and "X"or key==Enum.KeyCode.Y and "Y"or "Z")end)
            end
        end
    end)
    root.Destroying:Once(function()
        studio.FlushDraft()studio.FlushMakerDrafts()
