        studio.Visible=false
        if ctx.FrameRegion then ctx.FrameRegion(nil)end
        studio.UpdateInputCapture()
        if studio.BrowserView then studio.BrowserView:Suspend() end
        if studio.Edit then studio.Edit.OnTick=nil end
        local editor=studio.Edit
        if editor and ctx.IsSelected(editor.Module) then ctx.Stop() end
        if editor then editor.Playing=false end
        ctx.MainWindow.Main.Visible=studio.MainVisible~=false ctx.MainWindow.Main.Interactable=studio.MainInteractable~=false
    end)
    return studio
