end
return _scrsiz
end

function Util.LoopedHSV(h, s, v)
h %= 1
s = math.clamp(s, 0, 1)
v = math.clamp(v, 0, 1)
return Color3.fromHSV(h, s, v)
end

function Util.AreColor3sSimilar(c1, c2, ep)
if not c1 then c1 = Color3.new() end
if not c2 then c2 = Color3.new() end
local h1, s1, v1 = c1:ToHSV()
local h2, s2, v2 = c2:ToHSV()
local h = math.abs(h1 - h2) * 2
if h > 1 then h = 2 - h end
return (h + math.abs(s1 - s2) + math.abs(v1 - v2)) / 3 <= ep
end

