-- Native Steve controls for the reviewed Nooby-inspired utilities. No extra
-- root tabs, remote script hub, FFlag bundle or automatic code execution.
return function(ctx)
    local UI,p,save=ctx.UI,ctx.UI.Navigation.Pages,ctx.Save
    local api={Connections={}}local held={}
    local function connect(event,callback)
        local connection=event:Connect(callback)table.insert(api.Connections,connection)return connection
    end
    local function notice(ok,reason)
        if ok==false then ctx.Notify(reason or "that action is not available with this reanimator")end
    end
    local flight=ctx.Flight
    local toggle=UI.CreateSwitch(p.locomotion,"Fly (E / jump up, Q down)",false)
    local changing=false
    connect(toggle.Changed,function(value)
        if changing then return end
        local ok,reason=flight.SetEnabled(value)
        if not ok then changing=true toggle.Value=false changing=false notice(ok,reason)end
    end)
    flight.Changed=function(on)
        if not on then table.clear(held)end
        if toggle.Value~=on then changing=true toggle.Value=on changing=false end
    end
    local speed=UI.CreateSlider(p.locomotion,"Fly Speed",flight.Settings.Speed,5,300,5)
    connect(speed.Changed,function(value)if flight.SetSpeed(value)then save()end end)
    local key=UI.CreateDropdown(p.locomotion,"Fly Toggle Key",flight.Keys,table.find(flight.Keys,flight.Settings.Key))
    connect(key.Changed,function(value)flight.Settings.Key=flight.Keys[value]or "None"save()end)
    local flightStatus=UI.CreateText(p.locomotion,flight.Status,11,Enum.TextXAlignment.Left)
    UI.CreateText(p.locomotion,"fly moves your controller. touch: minimize the window for Up / Down. editor / lost window focus turns fly off.",10,Enum.TextXAlignment.Left)
    local hud=ctx.Util.Instance("Frame",ctx.ScreenGui)api.TouchHUD=hud
    hud.Name="UhhhhhhFlightTouch"hud.AnchorPoint=Vector2.new(1,1)
    hud.Size=UDim2.fromOffset(96,90)hud.Position=UDim2.new(1,-24,1,-210)
    hud.BackgroundTransparency=1 hud.Visible=false
    local layout=ctx.Util.Instance("UIListLayout",hud)
    layout.FillDirection=Enum.FillDirection.Vertical layout.SortOrder=Enum.SortOrder.LayoutOrder
    layout.Padding=UDim.new(0,4)
    local function hold(label,field)
        local button=UI.CreateButton(hud,label,18)
        connect(button.InputBegan,function(input)
            if not held[field]and (input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch)then
                held[field]=input flight[field]=true
            end
        end)
        connect(button.InputEnded,function(input)if held[field]==input then held[field]=nil flight[field]=false end end)
        return button
    end
    api.Rise=hold("Up (hold)","Up")api.Descend=hold("Down (hold)","Down")
    connect(ctx.Input.InputEnded,function(input)
        for field,captured in pairs(held)do if captured==input then held[field]=nil flight[field]=false end end
    end)
    local names={"Existing styles","Weak (Nooby)","Contact (Nooby)"}
    local values={"Existing","Weak","Contact"}
    local profile=UI.CreateDropdown(p.physics,"Fling Pattern",names,table.find(values,ctx.Limb.TargetFlingProfile)or 1)
    connect(profile.Changed,function(value)
        ctx.Limb.TargetFlingProfile=values[value]or values[1]
        ctx.SaveData.Reanimator.TargetFlingProfile=ctx.Limb.TargetFlingProfile
        if value>1 then
            ctx.Limb.UseNaNFling=false ctx.SaveData.Reanimator.LimbUseNaNFling=false
            if ctx.NaNSwitch then ctx.NaNSwitch.Value=false end
        end
        save()
    end)
    UI.CreateText(p.physics,"Limb + Hats: NaN takes priority. choosing Weak / Contact turns it off. contact is a finite velocity pattern, not true NaN state.",10,Enum.TextXAlignment.Left)
    local detail=UI.CreateSwitch(p.interface,"Low Detail World",false)
    connect(detail.Changed,ctx.Visuals.SetLowDetail)
    local hidden=UI.CreateSwitch(p.interface,"Hide Other Players (local)",false)
    connect(hidden.Changed,ctx.Visuals.SetHidePlayers)
    UI.CreateText(p.interface,"reversible. low detail keeps avatar / tool textures; hidden players stay selectable.",10,Enum.TextXAlignment.Left)
    local performance=UI.CreateText(p.interface,"frame monitor warming up...",11,Enum.TextXAlignment.Left)
    local tools=UI.CreateCollapsable(p.options,"Players & servers")api.Tools=tools
    local query=UI.CreateTextbox(tools,"","Player name / display name / user ID",15)
    local rows={}
    local picker,pickerLabel=UI.CreateCallbackDropdown(tools,"Live Players","Choose",function()
        rows=ctx.Players.List(query.Text)local labels={}
        for i=1,math.min(100,#rows)do
            local player=rows[i].Player labels[i]=ctx.Players.Escape(player.DisplayName).." (@"..ctx.Players.Escape(player.Name)..")"
        end
        if #labels==0 then labels[1]="no matching players"end
        return labels
    end)
    connect(picker.Event,function(index)
        local row=rows[index]
        if row then
            local ok,reason=ctx.Players.Select(row.Player)
            pickerLabel.Text=ok and ctx.Players.Escape(row.Player.Name)or "Choose"
            notice(ok,reason)
        end
    end)
    connect(query:GetPropertyChangedSignal("Text"),function()
        local player=ctx.Players.Resolve(query.Text)ctx.Players.Select(player)
        pickerLabel.Text=player and ctx.Players.Escape(player.Name)or "Choose"
    end)
    local playerStatus=UI.CreateText(tools,ctx.Players.Status,11,Enum.TextXAlignment.Left)
    local function button(label,callback)
        local object=UI.CreateButton(tools,label,18)
        connect(object.Activated,function()local ok,reason=callback()notice(ok,reason)end)
        return object
    end
    api.Goto=button("Go To Player",ctx.Players.Goto)
    api.Watch=button("Watch Player",ctx.Players.Watch)
    button("Stop Watching",function()ctx.Players.StopWatching()return true end)
    api.Fling=button("Fling Selected Player",ctx.Players.Fling)
    button("Stop All Flings",function()ctx.StopFlings()return true end)
    UI.CreateText(tools,"fling uses the active backend's target support. ambiguous names need a list pick. first 100 matches shown; type to narrow.",10,Enum.TextXAlignment.Left)
    UI.CreateSeparator(tools)
    local session=ctx.Session
    local mode=UI.CreateDropdown(tools,"Hop Mode",session.Modes,table.find(session.Modes,session.Settings.Mode))
    connect(mode.Changed,function(value)session.Settings.Mode=session.Modes[value]or session.Modes[1]save()end)
    local visited=UI.CreateSwitch(tools,"Skip Visited Servers (1 hour)",session.Settings.SkipVisited)
    connect(visited.Changed,function(value)session.Settings.SkipVisited=value save()end)
    local function async(label,callback)
        return button(label,function()
            task.spawn(function()local ok,reason=callback()notice(ok,reason)end)return true
        end)
    end
    async("Refresh Public Servers",function()return session.Load(true)end)
    api.Hop=async("Server Hop",session.Hop)
    button("Cancel Server Lookup",session.CancelLookup)
    api.Rejoin=button("Rejoin This Server",session.Rejoin)
    button("Clear Visited Servers",function()session.ClearVisited()return true end)
    local sessionStatus=UI.CreateText(tools,session.Status,11,Enum.TextXAlignment.Left)
    UI.CreateText(tools,"looks at up to 3 public-server pages. reported ping is the server listing's value. hopping / rejoining leaves this session.",10,Enum.TextXAlignment.Left)
    local age,elapsed,samples,peak=0,0,0,0
    connect(ctx.RunService.PreRender,function(dt)
        if type(dt)~="number"or dt~=dt or dt<=0 or dt==math.huge then return end
        age+=dt elapsed+=dt samples+=1 peak=math.max(peak,dt)
        local main=ctx.MainWindow
        hud.Visible=ctx.Input.TouchEnabled and flight.Enabled and (not main or not main.Visible or main.AbsoluteSize.Y<100)
        if age<.5 then return end age=0
        if not ctx.Visible or ctx.Visible(p.locomotion)then flightStatus.Text=ctx.Players.Escape(flight.Status)end
        if not ctx.Visible or ctx.Visible(tools)then
            playerStatus.Text=ctx.Players.Escape(ctx.Players.Status)
            sessionStatus.Text=ctx.Players.Escape(session.Status)
        end
        if not ctx.Visible or ctx.Visible(p.interface)then
            performance.Text=string.format("%.0f FPS | %.1f ms avg | %.1f ms peak | %d visual objects changed",samples/elapsed,elapsed/samples*1000,peak*1000,ctx.Visuals.Count())
        end
        elapsed,samples,peak=0,0,0
    end)
    function api.Destroy()
        flight.Changed=nil
        for _,connection in ipairs(api.Connections)do connection:Disconnect()end table.clear(api.Connections)
        hud:Destroy()
    end
    api.FlySwitch,api.Profile,api.Query,api.Picker,api.Performance=toggle,profile,query,picker,performance
    return api
end
