-- Coalesce high-frequency pointer events; move the window once per rendered frame.
return function(context)
    local Util, Input, Render = context.Util, context.Input, context.Render
    return function(frame, dragobj, content, callbacks)
        local drag, latest, offset, previousInteractable
        local screenGui = frame:FindFirstAncestorWhichIsA("ScreenGui")
        local connections = {}
        local function position(input)
            local screen = Util.GetScreenSize()
            return (Vector2.new(input.Position.X, input.Position.Y) + screenGui.AbsolutePosition) / screen, screen
        end
        local function move()
            if not drag or not latest then return end
            local point, screen = position(latest)
            latest = nil
            local desired = point + offset
            local size = Util.UDim2ToVector2Offset(frame.Size)
            local marginX, marginY = (size.X * .5 - 100) / screen.X, -size.Y * .5 / screen.Y
            frame.Position = Util.Vector2ToUDim2Scale(Vector2.new(
                math.clamp(desired.X, -marginX, 1 + marginX),
                math.clamp(desired.Y, -marginY, 1 - marginY - 31 / screen.Y)
            ))
        end
        local function stop()
            if not drag then return end
            move()
            drag, latest = nil, nil
            if content and content.Parent then content.Interactable = previousInteractable end
            if Util.DraggedWindow == frame then Util.DraggedWindow = nil end
            if frame.Parent and callbacks and callbacks.OnDragStopped then callbacks.OnDragStopped(frame) end
        end
        table.insert(connections, dragobj.InputBegan:Connect(function(input)
            if drag or input.UserInputState ~= Enum.UserInputState.Begin then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local point = position(input)
            offset = Util.UDim2ToVector2Scale(frame.Position) - point
            drag, Util.DraggedWindow = input, frame
            if content then previousInteractable = content.Interactable ~= false content.Interactable = false end
        end))
        table.insert(connections, Input.InputChanged:Connect(function(input)
            if drag and (input.UserInputType == Enum.UserInputType.MouseMovement
                or (input.UserInputType == Enum.UserInputType.Touch and input == drag)) then latest = input end
        end))
        table.insert(connections, Render:Connect(function()
            if drag and (drag.UserInputState == Enum.UserInputState.End
                or drag.UserInputState == Enum.UserInputState.Cancel) then stop() else move() end
        end))
        table.insert(connections, Input.InputEnded:Connect(function(input)
            if not drag then return end
            if input == drag or (drag.UserInputType == Enum.UserInputType.MouseButton1
                and input.UserInputType == Enum.UserInputType.MouseButton1) then stop() end
        end))
        -- Alt-tab, a mobile app switch, or a lost pointer release must never
        -- leave the entire content subtree disabled indefinitely.
        if Input.WindowFocusReleased then
            table.insert(connections, Input.WindowFocusReleased:Connect(stop))
        end
        local function cleanup()
            stop()
            for _, connection in ipairs(connections) do connection:Disconnect() end
            table.clear(connections)
        end
        frame.Destroying:Once(cleanup)
        return cleanup
    end
end
