    local page = SteveWindow.CreateScrollPage()
    page.AnchorPoint = Vector2.new(0.5, 0.5)
    page.Position = UDim2.new(0.5, 0, 0.5, 0)
    page.Visible, page.Interactable = true, true
    if UI.Workspace then UI.Workspace.Track(page) end
    return page
end
