    local page = SteveWindow.CreateItemListPage()
    page.AnchorPoint = Vector2.new(0.5, 0.5)
    page.Position = UDim2.new(0.5, 0, 0.5, 0)
    page.Visible, page.Interactable = true, true
    if UI.Workspace then UI.Workspace.Track(page) end
    return page
end
-- Generic mod/remote cards need a content canvas; built-in modules below use
-- the actual 1.1.0 ItemListItem with its favorite and play buttons.
UI.CreateItemListItem = function(parent)
    local canvas = StevePrefabs.UI.Canvas(parent)
    local button = Util.Instance("TextButton", canvas)
    button.Size = UDim2.new(1, 0, 0, 26)
    button.AutomaticSize = Enum.AutomaticSize.Y
    button.BackgroundTransparency, button.Text = 1, ""
    local list = Util.Instance("UIListLayout", button)
    list.HorizontalAlignment, list.SortOrder = Enum.HorizontalAlignment.Center, Enum.SortOrder.LayoutOrder
    return button
end
