Steve110.Seed("main/reanimation/reanimate", Reanimate)


do
	local AntiflingHumanoids = {}
	local AntiflingBaseParts = {}
	local OnStepped = function()
		local seen = {}
		for part in pairs(AntiflingBaseParts) do
			if part.Parent and part:IsDescendantOf(workspace) then
				if part.CanCollide then part.CanCollide = false end
				local root = part.AssemblyRootPart or part
				if not seen[root] then
					seen[root] = true
					if root.AssemblyLinearVelocity ~= Vector3.zero then root.AssemblyLinearVelocity = Vector3.zero end
					if root.AssemblyAngularVelocity ~= Vector3.zero then root.AssemblyAngularVelocity = Vector3.zero end
				end
			else AntiflingBaseParts[part] = nil end
		end
		for humanoid in pairs(AntiflingHumanoids) do
			if humanoid.Parent and humanoid:IsDescendantOf(workspace) then
				if humanoid.EvaluateStateMachine then humanoid.EvaluateStateMachine = false end
			else AntiflingHumanoids[humanoid] = nil end
		end
	end
	Util.LinkDestroyI2C(SCREENGUI, RunService.PreSimulation:Connect(OnStepped))
	local OnBasePart = function(v)
		if v:IsA("BasePart") then
			v.CanCollide = false
			AntiflingBaseParts[v] = true
		end
		if v:IsA("Humanoid") then
			v.EvaluateStateMachine = false
			AntiflingHumanoids[v] = true
		end
	end
	local OnCharacter = function(character)
		Util.LinkDestroyI2C(character, character.DescendantAdded:Connect(OnBasePart))
		for _, v in character:GetDescendants() do
			OnBasePart(v)
		end
	end
	local OnPlayer = function(player)
		if player == Player then
			return
		end
		Util.LinkDestroyI2C(SCREENGUI, player.CharacterAdded:Connect(OnCharacter))
		if player.Character then
			OnCharacter(player.Character)
		end
	end
	Util.LinkDestroyI2C(SCREENGUI, Players.PlayerAdded:Connect(OnPlayer))
	for _, player in Players:GetPlayers() do
		OnPlayer(player)
	end
end

local HumanoidLASetHookState
if ismissing(hookmetamethod) or ismissing(hookfunction) then
	HumanoidLASetHookState = function(hooked) end
else
	local LoadAnimation_old = nil
	local function LoadAnimation_new(animation)
		local char = Instance.new("Model")
		char.Parent = workspace
		local hum = Instance.new("Humanoid")
		hum.Parent = char
		local anim = LoadAnimation_old(hum, animation)
		hum.Parent = nil
		char:Destroy()
		--warn("LoadAnimation prevented!")
		return anim
	end
	local LoadAnimation_nc = nil
	local _HumanoidDummy = Instance.new("Humanoid")
	local _HumanoidLA = _HumanoidDummy.LoadAnimation
	local newloadanimation = newcclosure(function(self, animation)
		if
			not checkcaller()
			and typeof(self) == "Instance"
			and (self:IsA("Humanoid") or self:IsA("Animator"))
			and typeof(animation) == "Instance"
			and animation:IsA("Animation")
		then
			return LoadAnimation_new(animation)
		end
		return LoadAnimation_old(self, animation)
	end)
	local newnamecall = newcclosure(function(...)
		local method = getnamecallmethod()
		if not checkcaller() and method and (method == "LoadAnimation" or method == "loadAnimation") then
			local self, animation = ...
			if
				typeof(self) == "Instance"
				and (self:IsA("Humanoid") or self:IsA("Animator"))
				and typeof(animation) == "Instance"
				and animation:IsA("Animation")
			then
				return LoadAnimation_new(animation)
			end
		end
		return LoadAnimation_nc(...)
	end)
	HumanoidLASetHookState = function(hooked)
		if hooked then
			if not LoadAnimation_old then
				LoadAnimation_old = hookfunction(_HumanoidLA, clonefunction(newloadanimation))
			end
			if not LoadAnimation_nc then
				LoadAnimation_nc = hookmetamethod(_HumanoidDummy, "__namecall", clonefunction(newnamecall))
			end
		else
			if LoadAnimation_old then
				hookfunction(_HumanoidLA, LoadAnimation_old)
				LoadAnimation_old = nil
			end
			if LoadAnimation_nc then
				hookmetamethod(_HumanoidDummy, "__namecall", LoadAnimation_nc)
				LoadAnimation_nc = nil
			end
		end
	end
end

Util.IsCharacterJoint = function(joint)
	return typeof(joint) == "Instance"
		and (joint:IsA("Motor6D") or joint.ClassName == "AnimationConstraint")
end
Util.GetCharacterJointParts = function(joint)
	if typeof(joint)=="Instance" and joint:IsA("JointInstance") then
		return joint.Part0,joint.Part1
	end
	if joint and (joint.ClassName == "AnimationConstraint" or joint.ClassName == "RigidConstraint") then
		local ok, attachment0, attachment1 = pcall(function()
			return joint.Attachment0, joint.Attachment1
		end)
		if ok and attachment0 and attachment1 then
			return attachment0:FindFirstAncestorWhichIsA("BasePart"),
				attachment1:FindFirstAncestorWhichIsA("BasePart")
		end
		return nil, nil
	end
	local success, part0, part1 = pcall(function()
		return joint.Part0, joint.Part1
	end)
	if success and part0 and part1 then
		return part0, part1
	end
	return nil, nil
end
Util.GetCharacterJointFrames = function(joint)
	if typeof(joint)=="Instance" and joint:IsA("JointInstance") then
		return joint.C0,joint.C1
	end
	if joint and joint.ClassName == "AnimationConstraint" then
		local ok, frame0, frame1 = pcall(function()
			local a0,a1=joint.Attachment0,joint.Attachment1
			if not a0 or not a1 then return nil,nil end
			local p0,p1=a0.Parent,a1.Parent
			-- Standard R15 attachments are already part-local. Only nested
			-- bone attachments need the more expensive world-space conversion.
			if p0 and p1 and p0:IsA("BasePart") and p1:IsA("BasePart") then
				return a0.CFrame,a1.CFrame
			end
			local part0,part1=Util.GetCharacterJointParts(joint)
			return part0.CFrame:ToObjectSpace(a0.WorldCFrame),part1.CFrame:ToObjectSpace(a1.WorldCFrame)
		end)
		if ok and typeof(frame0) == "CFrame" and typeof(frame1) == "CFrame" then
			return frame0, frame1
		end
		return nil, nil
	end
	local success, c0, c1 = pcall(function()
		return joint.C0, joint.C1
	end)
	if success and typeof(c0) == "CFrame" and typeof(c1) == "CFrame" then
		return c0, c1
	end
	return nil, nil
end
Util.CharacterJointReplicationStats = {
	State = "waiting",
	Source = Util.HiddenPropertySetterSource,
	Path = "original R6 writer",
	LastError = nil,
	Attempts = 0,
	Successes = 0,
	Failures = 0,
	VerifiedWrites = 0,
	UnverifiedWrites = 0,
	Joints = setmetatable({}, { __mode = "k" }),
}
Util.IsR15CharacterJoint = function(joint)
	if typeof(joint) ~= "Instance" then
		return false
	end
	local character = joint:FindFirstAncestorOfClass("Model")
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	return humanoid ~= nil and humanoid.RigType == Enum.HumanoidRigType.R15
end
local function FiniteJointPose(value)
	if typeof(value) ~= "CFrame" then return false end
	for _, component in ipairs({value:GetComponents()}) do
		if component ~= component or math.abs(component) == math.huge then return false end
	end
	return true
end
-- Original physical joints reserved by a transport must not acquire a second
-- local-display writer through a module alias or animation helper.
Util.CharacterJointTransportOnly = setmetatable({}, {__mode = "k"})
Util.SetCharacterJointTransform = function(joint, transform, _legacyMotorReplication, preserveLocalDisplay)
	if not Util.IsCharacterJoint(joint) or not FiniteJointPose(transform) then
		return false
	end
	local applied = false
	local transportOnly = preserveLocalDisplay == true or Util.CharacterJointTransportOnly[joint] == true
	if joint:IsA("Motor6D") then
		-- Local display and the two replication channels are separate. R6
		-- needs the full Transform too; DesiredAngle represents only one axis.
		local r15Path = Util.IsR15CharacterJoint(joint)
		local desiredApplied = pcall(function()
			joint.MaxVelocity = 9e9
			local _, _, desiredAngle = transform:ToEulerAngles(Enum.RotationOrder.ZYX)
			joint.DesiredAngle = desiredAngle
			joint:SetDesiredAngle(desiredAngle)
		end)
		applied = applied or desiredApplied
		local axis, angle = transform:ToAxisAngle()
		local offsetSuccess, offsetResult, offsetVerified, offsetReadbackError =
			Util.TrySetHiddenProperty(joint, "ReplicateCurrentOffset6D", transform.Position)
		local angleSuccess, angleResult, angleVerified, angleReadbackError =
			Util.TrySetHiddenProperty(joint, "ReplicateCurrentAngle6D", axis * angle)
		if not transportOnly then
			local displayed = pcall(function() joint.Transform = transform end)
			applied = displayed or applied
		end
		local stats = Util.CharacterJointReplicationStats
		local replicated = offsetSuccess and angleSuccess
		local verified = replicated and offsetVerified and angleVerified
		stats.Path = r15Path and "R15 + ReplicateCurrent" or "R6 ReplicateCurrent"
		stats.Attempts += 1
		if replicated then
			stats.State = "write-accepted"
			stats.Source = angleResult or offsetResult or stats.Source
			stats.LastError = nil
			stats.Successes += 1
			if verified then stats.VerifiedWrites += 1 else stats.UnverifiedWrites += 1 end
		else
			stats.State = "failed"
			stats.LastError = tostring(not offsetSuccess and offsetResult or angleResult)
			stats.Failures += 1
		end
		stats.Joints[joint] = {
			State = stats.State, Path = stats.Path, LastError = stats.LastError,
			WriteAccepted = replicated, ReadbackVerified = verified,
			ObserverVerified = false,
			TransportOnly = transportOnly,
			RequestedOffset = transform.Position, RequestedAngle = axis * angle,
			OffsetAccepted = offsetSuccess, AngleAccepted = angleSuccess,
			OffsetReadbackVerified = offsetVerified, AngleReadbackVerified = angleVerified,
			OffsetReadbackError = offsetReadbackError, AngleReadbackError = angleReadbackError,
			OffsetSource = offsetResult, AngleSource = angleResult,
			WrittenAt = os.clock(),
		}
		-- DesiredAngle and a local Transform are not confirmation that either
		-- hidden replication channel accepted this pose.
		return replicated, applied
	else
		if not transportOnly then
			applied = pcall(function()
				joint.Transform = transform
				joint.IsKinematic = true
			end)
		end
		local stats = Util.CharacterJointReplicationStats
		stats.State, stats.Path = "local-only", "AnimationConstraint display"
		stats.LastError = "AnimationConstraint.Transform is not a Motor6D replication channel"
		stats.Joints[joint] = {
			State = stats.State, Path = stats.Path, LastError = stats.LastError,
			WriteAccepted = false, ReadbackVerified = false, ObserverVerified = false,
		}
	end
	return false, applied
end
Util.SetCharacterJointOffset = function(joint, offset, legacyMotorReplication, preserveLocalDisplay)
	if not FiniteJointPose(offset) then return false end
	local c0, c1 = Util.GetCharacterJointFrames(joint)
	if not FiniteJointPose(c0) or not FiniteJointPose(c1) then
		return false
	end
	return Util.SetCharacterJointTransform(joint, c0:Inverse() * offset * c1, legacyMotorReplication, preserveLocalDisplay)
end
Util.SetCharacterJointLocalOffset = function(joint, offset)
	-- Display never submits a replication write or claims observer success.
	if Util.CharacterJointTransportOnly[joint] then return false, "joint is reserved for replication transport" end
	if not Util.IsCharacterJoint(joint) or not FiniteJointPose(offset) then return false end
	local c0, c1 = Util.GetCharacterJointFrames(joint)
	if not FiniteJointPose(c0) or not FiniteJointPose(c1) then return false end
	local transform = c0:Inverse() * offset * c1
	if not FiniteJointPose(transform) then return false end
	return pcall(function()
		joint.Transform = transform
		if joint.ClassName == "AnimationConstraint" then joint.IsKinematic = true end
	end)
end
-- Backward-compatible aliases for community modules written before R15's
-- AnimationConstraint-based Avatar Joint Upgrade.
Util.SetMotor6DTransform = Util.SetCharacterJointTransform
Util.SetMotor6DOffset = Util.SetCharacterJointOffset

Util.ShowPartHitbox = function(part, color, lifetime)
	local w = Instance.new("WireframeHandleAdornment")
	w.Name = "_Uhhhhhh_ReanimateHitbox"
	w.Adornee = part
	w.Color3 = color or Color3.new(0, 1, 0)
	w.Transparency = 0
	w.ZIndex = 10
	w.AlwaysOnTop = true
	w.Thickness = 1
	w.Parent = SCREENGUI
	local hs = part.Size / 2
	local verts = {
		Vector3.new(-hs.X, -hs.Y, -hs.Z),
		Vector3.new(hs.X, -hs.Y, -hs.Z),
		Vector3.new(hs.X, hs.Y, -hs.Z),
		Vector3.new(-hs.X, hs.Y, -hs.Z),
		Vector3.new(-hs.X, -hs.Y, hs.Z),
		Vector3.new(hs.X, -hs.Y, hs.Z),
		Vector3.new(hs.X, hs.Y, hs.Z),
		Vector3.new(-hs.X, hs.Y, hs.Z),
	}
	w:AddLine(verts[1], verts[2])
	w:AddLine(verts[2], verts[3])
	w:AddLine(verts[3], verts[4])
	w:AddLine(verts[4], verts[1])
	w:AddLine(verts[5], verts[6])
	w:AddLine(verts[6], verts[7])
	w:AddLine(verts[7], verts[8])
	w:AddLine(verts[8], verts[5])
	w:AddLine(verts[1], verts[5])
	w:AddLine(verts[2], verts[6])
	w:AddLine(verts[3], verts[7])
	w:AddLine(verts[4], verts[8])
	if lifetime == nil then
		lifetime = 1
	end
	if lifetime > 0 then
		Debris:AddItem(w, lifetime)
	end
	return w
end

-- Gelatek's ownership display is a separate visual system from the thin
-- wireframe hitboxes above: it puts one thick outline on each body part.  Hat
-- reanimation uses the same per-limb presentation for its controller targets,
-- without touching the physical hats or the controller's transparency.
Util.GetAssemblyOwnership = function(part)
	if typeof(part) ~= "Instance" or not part:IsA("BasePart") or not part.Parent then
		return false, "missing part", nil
	end
	local root = part
	pcall(function() root = part.AssemblyRootPart or part end)
	if part.Anchored or root.Anchored then return false, "anchored assembly", root end
	-- The assembly root's answer is authoritative for this compatibility API.
	-- ReceiveAge is a fallback only when the API cannot answer, not a way to
	-- turn an explicit ownership rejection into success.
	if type(isnetworkowner) == "function" then
		local ok, owned = pcall(isnetworkowner, root)
		if ok and type(owned) == "boolean" then return owned, "isnetworkowner assembly", root end
		if root ~= part then
			local partOk, partOwned = pcall(isnetworkowner, part)
			if partOk and type(partOwned) == "boolean" then return partOwned, "isnetworkowner part", root end
		end
	end
	local ok, age = pcall(function() return root.ReceiveAge end)
	if ok and type(age) == "number" then return age == 0, "ReceiveAge inference (unverified)", root end
	return false, "ownership unavailable", root
end
Util.IsNetworkOwner = function(part)
	local owned = Util.GetAssemblyOwnership(part)
	return owned == true
end

-- Read-only capture: no test poses, hidden setters, simulated ownership or
-- observer confirmation. Late values can be consumed/overwritten by the engine;
-- they are reported separately from immediate read-back at the write boundary.
Util.GetJointReplicationReport = function(physical, controller)
	local function read(fn)
		local ok, value = pcall(fn)
		return ok and tostring(value) or "unavailable"
	end
	local lines = {"=== JOINT REPLICATION DIAGNOSTICS v16 ===",
		"observer=NOT VERIFIED; local values do not establish another client's pose"}
	table.insert(lines, "engine=" .. read(function() return version() end))
	table.insert(lines, "executor=" .. read(function() return identifyexecutor() end))
	table.insert(lines, "clock=" .. tostring(os.clock()))
	local stats = Util.CharacterJointReplicationStats
	for _, entry in ipairs({{Name="physical", Rig=physical}, {Name="controller", Rig=controller}}) do
		local rig = entry.Rig
		table.insert(lines, "--- " .. entry.Name .. " ---")
		if not rig or not rig.Parent then
			table.insert(lines, "rig=missing")
			continue
		end
		local humanoid = rig:FindFirstChildOfClass("Humanoid")
		table.insert(lines, "humanoid=" .. read(function() return humanoid.RigType.Name .. "/" .. humanoid:GetState().Name end))
		local descendants = rig:GetDescendants()
		local animatorCount = 0
		for _, child in ipairs(descendants) do if child:IsA("Animator") then animatorCount += 1 end end
		table.insert(lines, "Animators=" .. tostring(animatorCount))
		local count = 0
		for _, joint in ipairs(descendants) do
			if not Util.IsCharacterJoint(joint) then continue end
			count += 1
			if count > 32 then table.insert(lines, "joint limit=32") break end
			local part0, part1 = Util.GetCharacterJointParts(joint)
			local owned, ownershipSource, root = Util.GetAssemblyOwnership(part0 or part1)
			local sample = stats.Joints[joint]
			table.insert(lines, tostring(joint.Name) .. "/" .. joint.ClassName
				.. " parts=" .. tostring(part0 and part0.Name) .. "->" .. tostring(part1 and part1.Name)
				.. " enabled=" .. read(function() return joint.Enabled end)
				.. " assembly=" .. tostring(root and root.Name)
				.. " owned=" .. tostring(owned) .. " via=" .. ownershipSource
				.. " receiveAge=" .. read(function() return root.ReceiveAge end))
			table.insert(lines, "  local Transform=" .. read(function() return joint.Transform end)
				.. " CurrentAngle=" .. read(function() return joint.CurrentAngle end)
				.. " DesiredAngle=" .. read(function() return joint.DesiredAngle end))
			if sample then
				table.insert(lines, "  write=" .. tostring(sample.WriteAccepted)
					.. " immediateReadback=" .. tostring(sample.ReadbackVerified)
					.. " at=" .. tostring(sample.WrittenAt) .. " error=" .. tostring(sample.LastError)
					.. " requestedOffset=" .. tostring(sample.RequestedOffset)
					.. " requestedAngle=" .. tostring(sample.RequestedAngle))
				table.insert(lines, "  offsetSource=" .. tostring(sample.OffsetSource)
					.. " angleSource=" .. tostring(sample.AngleSource))
			else table.insert(lines, "  no shared-writer sample") end
			if joint:IsA("Motor6D") then
				table.insert(lines, "  lateOffset=" .. read(function() return Util.HiddenPropertyGetter(joint,"ReplicateCurrentOffset6D") end)
					.. " lateAngle=" .. read(function() return Util.HiddenPropertyGetter(joint,"ReplicateCurrentAngle6D") end))
			end
		end
	end
	return table.concat(lines,"\n")
end

Util.ShowPartLimbOutline = function(part, color, lifetime)
