function AnimLib.GetStudioWorkspace()
    if not AnimLib.StudioWorkspace then
        local pointer=Steve110.Require("main/studio_pointer")({IgnoreInset=SCREENGUI.IgnoreGuiInset,
            Camera=function()return workspace.CurrentCamera end,Mouse=function()return UserInputService:GetMouseLocation()end,
            Inset=function()local inset=GuiService:GetGuiInset()return inset end})
        AnimLib.StudioWorkspace=Steve110.Require("main/studio_workspace")({
            Util=Util,Theme=DevTheme,Font=Steve110.Require("main/data").TextFont,
            ScreenGui=SCREENGUI,MainWindow=SteveWindow,Input=UserInputService,Heartbeat=RunService.Heartbeat,
            MeasureText=function(text,size,width)
                return game:GetService("TextService"):GetTextSize(text,size,Steve110.Require("main/data").TextFont,Vector2.new(math.max(1,width),100000))
            end,
            Require=Steve110.Require,Files=AnimLib.GetFileTools(),Makers=AnimLib.GetMakerTools,
            CanPlay=function()return Reanimate.Character~=nil end,
            Play=function(module)CurrentDance=module end,Stop=function()CurrentDance=nil end,
            IsSelected=function(module)return module~=nil and CurrentDance==module end,
            Sources=function()return AnimLib.StudioSources end,
            ResolveAuthor=function(module)
                local api=AnimLib.StudioSources
                return api and api.Author and api.Author(module)
            end,
            Camera=function()return workspace.CurrentCamera end,
            GizmoParent=SCREENGUI,GizmoWorld=workspace,RenderSignal=RunService.PreRender,
            Pointer=pointer.Point,PointerRay=pointer.Ray,ProjectPoint=pointer.Project,
            EditorInput=function(enabled)
                if Reanimate.EditorInputCaptured==enabled then return end
                Reanimate.EditorInputCaptured=enabled
                Reanimate.Control.Inputs:Reset()Reanimate.Control.Move=Vector3.zero Reanimate.Control.Jump=false
                Reanimate.Camera.Inputs:Reset()Reanimate.Camera.Input=Vector3.zero
            end,
            SelectedModules=function()
                local modules={}
                if CurrentDance then table.insert(modules,CurrentDance)end
                local movement=MovementStyles[MovementStyleIndex]
                if movement and movement~=CurrentDance then table.insert(modules,movement)end
                return modules
            end,
            ActiveTracks=function()
                local rows,seen={},{}
                for animator in pairs(AnimLib.ActiveAnimators)do
                    if not animator._destroyed and animator.track and animator.playing then
                        local owner=animator._UhhhhhhModuleOwner
                        table.insert(rows,{Name=animator.track.Name or (owner and owner.Name)or "Playing animation",
                            Track=animator.track,Time=animator.timePosition,Module=owner,
                            Source=owner and owner.Name or "AnimLib playback",Playing=animator:IsPlaying()})
                    end
                end
                for _,rig in pairs({Reanimate.Character,Player.Character})do
                    if rig and not seen[rig]then
                        seen[rig]=true
                        for _,object in ipairs(rig:GetDescendants())do if object:IsA("Animator")then
                            local ok,tracks=pcall(function()return object:GetPlayingAnimationTracks()end)
                            if ok then for _,track in ipairs(tracks)do
                                local animation=track.Animation
                                local id=animation and animation.AnimationId
                                if id and id~=""then
                                    table.insert(rows,{Name=(animation.Name~="Animation"and animation.Name or track.Name).." / "..id,
                                        AssetId=id,Time=track.TimePosition,Source="Roblox Animator / "..rig.Name,Playing=track.IsPlaying})
                                end
                            end end
                        end end
                    end
                end
                return rows
            end,
            FetchTracks=function()
                local rows={}
                for _,player in ipairs(Players:GetPlayers())do
                    local character=player.Character
                    if character and player~=Player then
                        for _,object in ipairs(character:GetDescendants())do if object:IsA("Animator")then
                            local ok,tracks=pcall(function()return object:GetPlayingAnimationTracks()end)
                            if ok then for _,track in ipairs(tracks)do
                                local animation=track.Animation local id=animation and animation.AnimationId
                                if id and id~=""then table.insert(rows,{Id="character/"..player.UserId.."/"..id,
                                    Name=player.DisplayName.." / "..animation.Name.." / "..id,
                                    AssetId=id,Source="Roblox Animator / "..player.Name,Playing=track.IsPlaying})end
                            end end
                        end end
                    end
                    if #rows>=512 then break end
                end
                return rows
            end,
            ReadAsset=function(reference,cancelled)
                local path=AssetGetPathFromFilename(reference)
                local deadline=os.clock()+25
                repeat
                    assert(not cancelled or not cancelled(),"clip loading cancelled")
                    if AssetDownload(reference,"editor")then return readfile(path)end
                    local failure=_Assetretry[path]
                    if failure and not _Assetdownloading[path]then error(failure.LastError,0)end
                    task.wait(.05)
                until os.clock()>=deadline
                error("the animation download timed out; try again from Assets",0)
            end,
            FrameRegion=function(region)
                if not region then
                    Reanimate.EditorFrameRegion=nil
                    if Reanimate.EditorSavedZoom then Reanimate.Camera.Zoom=Reanimate.EditorSavedZoom Reanimate.EditorSavedZoom=nil end
                    return
                end
                Reanimate.EditorFrameRegion=region
                if not Reanimate.EditorSavedZoom then Reanimate.EditorSavedZoom=Reanimate.Camera.Zoom end
                local screen=region.Screen local scale=Reanimate.CharacterScale or 1
                local tan=math.tan(math.rad(35))
                local vertical=7*scale/(2*tan*math.max(.05,region.H/screen.Y)*.8)
                local horizontal=5*scale/(2*tan*(screen.X/screen.Y)*math.max(.05,region.W/screen.X)*.8)
                Reanimate.Camera.Zoom=math.max(vertical,horizontal,4)
            end,
            RigInfo=function(track)
                local editor=AnimLib.Files and AnimLib.Files.Editor
                local rig=editor and editor.Animator and editor.Animator._requestedRig==Reanimate.Character and editor.Animator.rig
                if not rig and Reanimate.Character then rig=Reanimate.ControllerRigAdapter.RigForTrack(Reanimate.Character,track)end
                if not rig then return nil end
                local root=rig:FindFirstChild("HumanoidRootPart")
                local result={Rig=rig,Root=root and root.CFrame or rig:GetPivot(),Scale=rig:GetScale(),Joints={}}
                for _,joint in ipairs(rig:GetDescendants())do if Util.IsCharacterJoint(joint)then
                    local p0,p1=Util.GetCharacterJointParts(joint)
                    if p0 and p1 then local c0,c1=Util.GetCharacterJointFrames(joint)
                        table.insert(result.Joints,{Name=p1.Name,Parent=p0.Name,ParentWorld=p0.CFrame,C0=c0,C1=c1,Size=p1.Size,Transform=joint.Transform})
                    end
                end end
                return result
            end,
            TransformFrame=function(name,track)
                local editor=AnimLib.Files and AnimLib.Files.Editor
                local rig=editor and editor.Animator and editor.Animator._requestedRig==Reanimate.Character and editor.Animator.rig
                if not rig and Reanimate.Character then rig=Reanimate.ControllerRigAdapter.RigForTrack(Reanimate.Character,track)end
                if not rig then return nil end
                for _,joint in ipairs(rig:GetDescendants())do
                    if Util.IsCharacterJoint(joint)then
                        local p0,p1=Util.GetCharacterJointParts(joint)
                        if p0 and p1 and p1.Name==name then
                            local c0=Util.GetCharacterJointFrames(joint)
                            return {Base=p0.CFrame*c0,Part=p1,Rig=rig,Scale=rig:GetScale()}
                        end
                    end
                end
            end,
            SelectionParts=function(kind)
                if Reanimate.Current and Reanimate.Current.SelectionParts then return Reanimate.Current.SelectionParts()end
                local rig=Reanimate.GetActiveRealCharacter and Reanimate.GetActiveRealCharacter()or Reanimate.Character
                if not rig then return {}end
                local aliases=kind=="R6"and {
                    UpperTorso="Torso",LowerTorso="Torso",
                    LeftUpperArm="Left Arm",LeftLowerArm="Left Arm",LeftHand="Left Arm",
                    RightUpperArm="Right Arm",RightLowerArm="Right Arm",RightHand="Right Arm",
                    LeftUpperLeg="Left Leg",LeftLowerLeg="Left Leg",LeftFoot="Left Leg",
                    RightUpperLeg="Right Leg",RightLowerLeg="Right Leg",RightFoot="Right Leg",
                }or {}
                local entries={}
                for _,part in ipairs(rig:GetChildren())do
                    if part:IsA("BasePart")and part.Name~="HumanoidRootPart"then
                        table.insert(entries,{Name=aliases[part.Name]or part.Name,Part=part})
                    end
                end
                return entries
            end,
        })
    end
    return AnimLib.StudioWorkspace
end
