local function RefreshBodyPartPickers()
	-- Hide Body Parts controls the replicated physical shell. Reanimate.Character
	-- is the invisible animation controller under Limb/Hats/Gelatek, so using it
	-- here can produce an empty/wrong list (especially after Gelatek handoff).
	local figure = type(Reanimate.GetActiveRealCharacter) == "function"
		and Reanimate.GetActiveRealCharacter()
		or nil
	if not figure and not Reanimate.Current then
		figure = Player.Character
	end
	local partNames = GetDetectedDanceEffectBodyParts(figure)
	HiddenBodyPartPicker:Refresh(partNames)
    AnimLib.NormalizePartSelections(Reanimate.Character)
    DisabledBodyPartPicker:Refresh(GetDetectedDanceEffectBodyParts(Reanimate.Character))
end

RefreshBodyPartPickers()
