end)

-- Module loading is the last large subsystem in this runtime. Keep all of its
-- registries, validators, browser controllers, and reload helpers in a fresh
-- register frame so both optimized and -O0 executor compilers stay below
-- Luau's 200-local limit. Event callbacks retain this scope as upvalues.
;(function()
if type(SaveData.ModuleConfigs) ~= "table" then
	SaveData.ModuleConfigs = {}
end
if type(SaveData.FavoriteModules) ~= "table" then
	SaveData.FavoriteModules = {}
end
if type(SaveData.HiddenModules) ~= "table" then
	SaveData.HiddenModules = {}
end
local RegisteredModuleKeys = {}
local MarketCatalog = Steve110.Require("main/market_catalog")({
    Require=Steve110.Require,Saved=SaveData,Save=SaveSettingsNow,
    Recovery=Steve110.Require("main/market_recovery"),
    Snapshots=function() return Steve110.Require("main/market_manifest") end,
    Fetch=HttpFetchBody, Decode=function(body) return HttpService:JSONDecode(body) end,
})
local StreamRuntime
local InitLogsText
local UserPacks = Steve110.Require("main/user_pack_assets").new({
    List=listfiles,IsFolder=isfolder,IsFile=isfile,Read=readfile,Write=writefile,Delete=delfile,
    Folders=EnsureAssetFolders,Path=AssetGetPathFromFilename,Yield=task.wait,
    Invalidate=function(path)
        ContentCache.Invalidate(path) _AssetContentIds[path]=nil _Assetretry[path]=nil
        AnimLib.Track.clearfilecache(path)
    end,
    Report=function(message)InitLogsText.Text..="\n[WARN] "..message end,
})
local function ResolveModuleAsset(context, filename)
    if context and context.LocalPack then return UserPacks.Resolve(context,filename) end
    local missing
    filename, missing = MarketCatalog.Remap(context, filename)
    if missing then return filename, true end
    if context and context.StreamScope then return StreamCache.Reference(context.StreamScope, filename) end
    return filename
end
local function ResolveModuleAssets(m, context, sourceLabel)
    m._UhhhhhhSource=sourceLabel or context and context.SourceLabel or m._UhhhhhhSource
    m._UhhhhhhMissingAssets = nil
    for _,list in ipairs({m.Assets,m.OptionalAssets or {}}) do
        for i,filename in ipairs(list) do
            local mapped,missing=ResolveModuleAsset(context,filename)
            if missing and list==m.Assets then
                m._UhhhhhhMissingAssets=m._UhhhhhhMissingAssets or {}
                table.insert(m._UhhhhhhMissingAssets,filename)
            elseif not missing then list[i]=mapped end
        end
    end
end
local function RetryAnimationAssets(m)
    m._UhhhhhhAssetFailure,m._UhhhhhhAssetFailureNotice=nil,nil
    m._UhhhhhhRuntimeFailure,m._UhhhhhhRandomUnavailable=nil,nil
    local active=StreamRuntime and StreamRuntime.Active[m]
    m._UhhhhhhOptionalNotices=nil
    for _,list in ipairs({active and active.Assets or m.Assets,active and active.OptionalAssets or m.OptionalAssets or {}}) do
        for _,filename in ipairs(list) do
            local retry=_Assetretry[AssetGetPathFromFilename(filename)]
            if retry then retry.NextAttempt,retry.Failures=0,0 end
        end
    end
end
local function CompileAnimationModule(source, name)
    source=RepairCommunitySource(source)
    -- Moveset Creator V6 packs can omit their optional jump track while still
    -- indexing it. Repair the generator pattern when loading, including cached
    -- installs; keep other scripts and their asset choices unchanged.
    if source:find("Created with Moveset Creator V6",1,true)
        and source:find("animJump = baseAnims.jump",1,true) then
        source=source:gsub('currentBase%s*=%s*"idle"','currentBase = nil')
        source=source:gsub('animJump%.weight%s*=%s*([01])','if animJump then animJump.weight = %1 end')
        source=source:gsub('actionStart%[animJump%]%s*=%s*os%.clock%(%)','if animJump then actionStart[animJump] = os.clock() end')
    end
    return loadstring(source,name)
end
local function ReadMarketContext(source,moduleFile)
    local key=source:match("^%-%- UHH_MARKET_CONTEXT ([^\r\n]+)")
    if not key or not MarketCatalog.SafePath(key) then return nil end
    local ok,context=pcall(function()
        return HttpService:JSONDecode(readfile("UhhhhhhReanim/MarketContexts/"..key..".json"))
    end)
    assert(ok and type(context)=="table" and type(context.Assets)=="table", "Missing pack asset context; redownload this pack")
    context.SourceLabel="Installed: "..key
    context.ModuleFile=moduleFile
    context.Directory=context.Directories and context.Directories[moduleFile]or context.Directory
    return context
end
local function GiveFunctionsToFunction(func, marketContext)
	local env = setmetatable({}, {__index = b_getfenv(func)})
    local moduleOwner
    local created=setmetatable({}, {__mode="k"})
    local declared=marketContext and {} or nil
    setfenv(func, env) -- each module keeps its own asset context when another pack loads
	env.warn = function(...)
        local parts = {}
        for i = 1, select("#", ...) do parts[i] = tostring(select(i, ...)) end
        Util.CommunityDiagnostics.Report("addon-warning", moduleOwner and moduleOwner.Name or "Addon",
            moduleOwner and moduleOwner._UhhhhhhSource or marketContext and marketContext.SourceLabel or "User module",
            table.concat(parts, " "))
    end
    -- Nested helper chunks (e.g. an installed ToolDance audio loader) must
    -- inherit this addon's asset context and quiet diagnostic sink too.
    -- The application/executor's global warn/loadstring are never changed.
    env.loadstring = function(source, name)
        local chunk, reason = loadstring(source, name)
        if chunk then setfenv(chunk, env) end
        return chunk, reason
    end
	env.RandomString = Util.RandomString
	-- Keep community modules on the same replicated joint writer as the core.
	-- These aliases preserve the BlaaBlaa module API without duplicating writers.
	env.Util_SetMotor6DTransform = Util.SetMotor6DTransform
	env.Util_SetMotor6DOffset = Util.SetMotor6DOffset
	env.Util_CreateText = UI.CreateText
	env.Util_CreateButton = UI.CreateButton
	env.Util_CreateSwitch = UI.CreateSwitch
	env.Util_CreateTextbox = UI.CreateTextbox
	env.Util_CreateSlider = UI.CreateSlider
	env.Util_CreateDropdown = UI.CreateDropdown
	env.Util_CreateCanvas = UI.CreateCanvas
	env.Util_CreateScrollCanvas = UI.CreateScrollCanvas
	env.Util_CreateSeparator = UI.CreateSeparator
	env.ReanimCamera = Reanimate.Camera
	env.LimbReanimator = LimbReanimator
	env.HatReanimator = HatReanimator
	env.ReanimateShowHitboxes = ReanimateShowHitboxes
	env.ReanimateFling = ReanimateFling
	env.SetOverrideMovesetMusic = SetOverrideMovesetMusic
	env.GetOverrideMovesetMusicTime = GetOverrideMovesetMusicTime
	env.SetOverrideMovesetMusicTime = SetOverrideMovesetMusicTime
	env.SetOverrideMovesetMusicSpeed = SetOverrideMovesetMusicSpeed
	env.SetOverrideDanceMusic = SetOverrideDanceMusic
	env.GetOverrideDanceMusicTime = GetOverrideDanceMusicTime
	env.SetOverrideDanceMusicTime = SetOverrideDanceMusicTime
	env.SetOverrideDanceMusicSpeed = SetOverrideDanceMusicSpeed
    -- Remember the factory's owner for delayed callbacks as well as Init/Update.
    -- fromfile/fromjson helpers still use the protected runtime owner context.
    env.AnimLib=setmetatable({Animator=setmetatable({new=function(...)
        local animator=AnimLib.Animator.new(...)
        created[animator]=true
        if moduleOwner then animator._UhhhhhhModuleOwner=moduleOwner end
        return animator
    end},{__index=AnimLib.Animator})},{__index=AnimLib})
	env.ContextActions = ContextActions
	env.AssetGetPathFromFilename = AssetGetPathFromFilename
	env.AssetGetContentId = AssetGetContentId
    env.AssetIsCached=function(filename) return HasCachedAsset(AssetGetPathFromFilename(filename)) end
    if marketContext then
        local function resolve(filename)
            assert(declared[filename]~=false,"Ambiguous declared asset: "..tostring(filename))
            -- Shared chunk helpers execute under the runtime's current owner;
            -- factory-local callbacks retain their owner for delayed work.
            local owner=moduleOwner or AnimLib.ModuleOwner
            local entry=owner and owner._UhhhhhhStream
            local context=entry and entry.Context or marketContext
            local mapped, missing = ResolveModuleAsset(context, declared[filename] or filename)
            assert(not missing, "Asset missing or ambiguous in " .. tostring(marketContext.Provider) .. " pack: " .. tostring(filename))
            return mapped
        end
        env.AssetGetPathFromFilename=function(filename) return AssetGetPathFromFilename(resolve(filename)) end
        env.AssetGetContentId=function(filename) return AssetGetContentId(resolve(filename)) end
        env.AssetIsCached=function(filename) return HasCachedAsset(AssetGetPathFromFilename(resolve(filename))) end
    end
	env.ProtectedChat = ProtectedChat
	env.OnPlayerChatted = OnPlayerChatted
	env.HiddenGui = SCREENGUI
	env.FallenPartsDestroyHeight = FallenPartsDestroyHeight
	env.RegisterServerReanimAdapter = _G_Uhhhhhh.RegisterServerReanimAdapter
    return function(owner)
        moduleOwner=owner
        if declared then
            for _,reference in ipairs(owner.Assets) do
                local name=reference:match("^([^@]+)@")
                if name then
                    for _,alias in ipairs({name,name:match("([^/]+)$")}) do
                        if declared[alias]~=nil and declared[alias]~=reference then declared[alias]=false
                        else declared[alias]=reference end
                    end
                end
            end
        end
        for animator in pairs(created) do animator._UhhhhhhModuleOwner=owner end
    end
end
