	end

	for _, m in favorites do
		local item = UI.CreateItemListItem(page.List)
		UI.CreateText(item, "[*] " .. m.Name .. " &gt;", 19, Enum.TextXAlignment.Left)
		UI.CreateText(
			item,
			string.split(m.Description, "\n")[1],
			11,
			Enum.TextXAlignment.Left
