InitLogsText = Steve110.Require("main/bounded_log")(
    UI.CreateText(InitLogsPage, "Loading...", 12, Enum.TextXAlignment.Left))
local STEVE110_BUILTIN_ROOT = STEVE110_ROOT .. "/main/addldata/"
local STEVE110_BUILTINS = {v_moveset1 = true, v_moveset2 = true, v_moveset3 = true,
    v_dance1 = true, v_dance2 = true, d_limbmap = true, d_hatsmap = true}
local function _contentgetgithubraw(path)
    local name = tostring(path):gsub("%.lua$", "")
    if STEVE110_BUILTINS[name] then
        local ok, body = pcall(readfile, STEVE110_BUILTIN_ROOT .. name .. ".lua")
        if ok and HttpBodyIsUsable(body) then return body end
    end
	local rawUrl =
		"https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/"
		.. STEVE_AUDITED_REVISION
		.. "/content/"
		.. path

	InitLogsText.Text ..= "\n[LOG] [GitGET] GET raw./" .. path
	local body, rawError = HttpFetchBody(rawUrl, nil, 3)
	if body then
		return body
	end
	InitLogsText.Text ..=
		"\n[WARN] [GitGET] raw./"
		.. path
		.. " failed: "
		.. tostring(rawError)

	local apiUrl =
		"https://api.github.com/repos/STEVE-916-create/Uhhhhhh/contents/content/"
		.. path
		.. "?ref="
		.. STEVE_AUDITED_REVISION
	InitLogsText.Text ..= "\n[LOG] [GitGET] GET api./" .. path
	local apiBody, apiError =
		HttpFetchBody(
			apiUrl,
			{ Accept = "application/vnd.github.VERSION.raw" },
			2
		)
	if apiBody then
		return apiBody
	end

	InitLogsText.Text ..=
		"\n[ERROR] [GitGET] api./"
		.. path
		.. " failed: "
		.. tostring(apiError)
	RecordContentFailure(
		"builtin-download",
		path,
		rawUrl .. " | " .. apiUrl,
		tostring(rawError) .. " | " .. tostring(apiError)
	)
	return nil
end

local UserModulesListor = {}
local USER_MODULE_ROOT = "UhhhhhhReanim/Modules/"
local function NormalizeUserPath(path)
	return tostring(path):gsub("\\", "/")
end
local function UserModuleRelativePath(path)
	path = NormalizeUserPath(path)
	local start = path:find(USER_MODULE_ROOT, 1, true)
	return start and path:sub(start + #USER_MODULE_ROOT) or path:match("([^/]+)$") or path
end
local function IsUserModuleScript(path)
    path = path:lower()
    return path:sub(-4) == ".lua" or path:sub(-5) == ".luau"
        or path:sub(-8) == ".lua.txt" or path:sub(-9) == ".luau.txt"
end
local function ForceModuleReload(force)
	IsUhhhhhhFullyLoaded = false
	InitLogsText.Reset("Init Logs -- This is where you check what happened.")
	ClearModules()
	table.clear(UserModulesListor)
	Util.UINotify("Checking hashes...", 0.05)
	InitLogsText.Text ..= "\n[LOG] Checking SHA1 hashes..."
	local filesofbuiltins = {
		"v_moveset1.lua",
		"v_moveset2.lua",
		"v_moveset3.lua",
		"v_dance1.lua",
		"v_dance2.lua",
		"d_limbmap.lua",
		"d_hatsmap.lua",
	}
	local filesofbuiltins_m = { "v_moveset1.lua", "v_moveset2.lua", "v_moveset3.lua", "v_dance1.lua", "v_dance2.lua" }
	local filesofbuiltins_d = { "d_limbmap.lua", "d_hatsmap.lua" }
    local upgradeBuiltins = SaveData.SteveBuiltinPayload ~= Steve110.PayloadSHA256
	SaveData.ContentHash = SaveData.ContentHash or {}
	local staleBuiltins = {}
	local staleBuiltinHashes = {}
	local hasCachedBuiltin = false
	for _, filename in filesofbuiltins do
		if HasCachedAsset("UhhhhhhReanim/BuiltinModules/" .. filename) then
			hasCachedBuiltin = true
			break
		end
	end
	if force ~= "SKIPHASH" and hasCachedBuiltin and not upgradeBuiltins then
		xpcall(function()
			local metadataUrl = "https://api.github.com/repos/STEVE-916-create/Uhhhhhh/contents/content/?ref="
				.. STEVE_AUDITED_REVISION
			local responseBody, fetchFailure = HttpFetchBody(metadataUrl, nil, 2)
			if responseBody then
				local decoded, files = pcall(HttpService.JSONDecode, HttpService, responseBody)
				if decoded and type(files) == "table" then
					for _, file in files do
						if file.name and file.sha then
							local oldHash = SaveData.ContentHash[file.name]
							if oldHash ~= file.sha then
								if oldHash and table.find(filesofbuiltins, file.name) then
									staleBuiltins[file.name] = true
									staleBuiltinHashes[file.name] = file.sha
									InitLogsText.Text ..= "\n[LOG] BuiltinModules/" .. file.name .. " has an update."
								else
									SaveData.ContentHash[file.name] = file.sha
									if oldHash then
										local path = AssetGetPathFromFilename(file.name)
										if isfile(path) then
											InitLogsText.Text ..= "\n[LOG] Downloaded Asset " .. file.name .. " removed because outdated."
											delfile(path)
											ContentCache.Invalidate(path)
										end
									end
								end
							end
						end
					end
				end
			else
				InitLogsText.Text ..= "\n[WARN] Content hash check failed: " .. tostring(fetchFailure)
			end
			InitLogsText.Text ..= "\n[LOG] Checked all SHA1 hashes..."
		end, function()
			InitLogsText.Text ..= "\n[WARN] SHA1 hashes check failed!"
		end)
	elseif force == "SKIPHASH" then
		InitLogsText.Text ..= "\n[WARN] Chill. We are just reloading user modules."
		InitLogsText.Text ..= "\n[LOG] Checked all SHA1 hashes..."
	else
		InitLogsText.Text ..= "\n[LOG] Fresh cache; skipped the update metadata request."
	end
	local wasold = false
	if SaveData.VanillaModuleCache then
		wasold = true
		SaveData.VanillaModuleCache = nil
	end
	local function validateBuiltinSource(filename, content)
		if not HttpBodyIsUsable(content) then
			return false, "empty or HTML response"
		end
		local chunk, compileFailure = loadstring(content, "Uhhhhhh :: DOWNLOAD CHECK " .. filename)
		if type(chunk) ~= "function" then
			return false, tostring(compileFailure)
		end
		return true
	end
	InitLogsText.Text ..= "\n[LOG] Loading maps..."
	for i, x in filesofbuiltins_d do
		Util.UINotify("Loading maps...", 0.15 + (i / #filesofbuiltins_d) * 0.15)
		local path = "UhhhhhhReanim/BuiltinModules/" .. x
		local exist = HasCachedAsset(path)
		local cached = exist and readfile(path) or nil
		if force == "ALL" or staleBuiltins[x] or upgradeBuiltins then
			exist = false
		end
		if exist then
			InitLogsText.Text ..= "\n[LOG] " .. x .. " already downloaded :D"
		else
			InitLogsText.Text ..= "\n[LOG] Downloading MAP " .. x .. "..."
			local content = _contentgetgithubraw(x)
			local valid, invalidReason = validateBuiltinSource(x, content)
			if valid then
				local wrote, writeFailure = pcall(writefile, path, content)
				if not wrote then
					InitLogsText.Text ..= "\n[WARN] Could not cache MAP " .. x .. ": " .. tostring(writeFailure)
				elseif staleBuiltinHashes[x] then
					SaveData.ContentHash[x] = staleBuiltinHashes[x]
				end
			elseif cached then
				InitLogsText.Text ..= "\n[WARN] MAP fetch failed validation; keeping cached " .. x
				pcall(writefile, path, cached)
			else
				InitLogsText.Text ..= "\n[ERROR] Failed to load MAP " .. x .. ": " .. tostring(invalidReason)
				SaveData.ContentHash[x] = nil
			end
		end
	end
	InitLogsText.Text ..= "\n[LOG] Loading builtin (also called vanilla) modules..."
	for i, x in filesofbuiltins_m do
		Util.UINotify("Loading modules...", 0.325 + (i / #filesofbuiltins_m) * 0.475)
		local path = "UhhhhhhReanim/BuiltinModules/" .. x
		local exist = HasCachedAsset(path)
		local cached = exist and readfile(path) or nil
		if wasold then
			exist = false
		end
		if force == "ALL" or staleBuiltins[x] or upgradeBuiltins then
			exist = false
		end
		local data = ""
		if exist then
			InitLogsText.Text ..= "\n[LOG] Reading local VANILLA " .. x .. "..."
			data = readfile(path)
			task.wait()
		else
			InitLogsText.Text ..= "\n[LOG] Downloading VANILLA " .. x .. "..."
			local content = _contentgetgithubraw(x)
			local valid, invalidReason = validateBuiltinSource(x, content)
			if valid then
				local wrote, writeFailure = pcall(writefile, path, content)
				if not wrote then
					InitLogsText.Text ..= "\n[WARN] Could not cache VANILLA " .. x .. ": " .. tostring(writeFailure)
				elseif staleBuiltinHashes[x] then
					SaveData.ContentHash[x] = staleBuiltinHashes[x]
				end
				data = content
			elseif cached then
				InitLogsText.Text ..= "\n[WARN] VANILLA fetch failed validation; using cached " .. x
				data = cached
				pcall(writefile, path, cached)
			else
				InitLogsText.Text ..= "\n[ERROR] Failed to load VANILLA " .. x .. ": " .. tostring(invalidReason)
				SaveData.ContentHash[x] = nil
			end
		end
		task.wait()
		InitLogsText.Text ..= "\n[LOG] Loadstringing VANILLA " .. x .. "..."
		xpcall(function()
			local func, comperr = loadstring(data, "Uhhhhhh :: VANILLA " .. x)
			if func then
				GiveFunctionsToFunction(func)
				local names, logging = AddModules(func())
				InitLogsText.Text ..= logging
			elseif comperr then
				error("COMPILE FAILED: " .. comperr)
			end
		end, function(msg)
			local traceback = debug.traceback("VANILLA " .. x .. ": " .. msg)
			RecordContentFailure("builtin-module", x, path, traceback)
			InitLogsText.Text ..= "\n[ERROR] Failed to load VANILLA " .. x .. ": See traceback below."
			InitLogsText.Text ..= "\n[ERROR] " .. table.concat(
				string.split(traceback, "\n"),
				"\n[ERROR] "
			)
		end)
	end
	Util.UINotify("Loading modules...", 0.8)
	InitLogsText.Text ..= "\n[LOG] Loading user modules..."
	local userFiles = {}
	userFiles=UserPacks.Scan()
	UserPacks.Stage(userFiles)
    local packCounts, deferred = {}, {}
    for _, path in ipairs(userFiles) do
        local relative = UserModuleRelativePath(path)
        local pack = relative:match("^(Market/[^/]+/[^/]+/)")
        if pack and IsUserModuleScript(relative) then packCounts[pack] = (packCounts[pack] or 0) + 1 end
    end
	for _, path in userFiles do
		local x = UserModuleRelativePath(path)
        local pack = x:match("^(Market/[^/]+/[^/]+/)")
        local mode = pack and SaveData.MarketPackModes and SaveData.MarketPackModes[pack]
        if pack and (mode == "stream" or (mode == nil and (packCounts[pack] or 0) >= 64)) then
            if not deferred[pack] then
                deferred[pack] = true
                InitLogsText.Text ..= "\n[LOG] Deferred installed pack " .. pack .. "; browse it with Stream Pack."
            end
            continue
        end
		local lower = string.lower(NormalizeUserPath(path))
		local isScript = IsUserModuleScript(lower)
        local replacement = MarketCatalog.LegacyReplacement(x)
        if replacement and isfile(USER_MODULE_ROOT .. replacement) then
            InitLogsText.Text ..= "\n[LOG] Superseded legacy module "..x.." by "..replacement
        elseif isScript then
			xpcall(function()
				InitLogsText.Text ..= "\n[LOG] Reading local USER " .. x .. "..."
				local data = readfile(path)
				InitLogsText.Text ..= "\n[LOG] Loadstringing USER " .. x .. "..."
				local func, comperr = CompileAnimationModule(data, "Uhhhhhh :: " .. x)
				if func then
                    local context = ReadMarketContext(data,x) or UserPacks.Context(path)
                    GiveFunctionsToFunction(func, context)
					local names, logging = AddModules(func(), context,"Installed: "..x)
					UserModulesListor[x] = names
					InitLogsText.Text ..= logging
				elseif comperr then
					error("COMPILE FAILED: " .. comperr)
				end
			end, function(msg)
				local traceback = debug.traceback("USER " .. x .. ": " .. msg)
				RecordContentFailure("user-module", x, path, traceback)
				InitLogsText.Text ..= "\n[ERROR] Failed to load USER " .. x .. ": See traceback below."
				InitLogsText.Text ..= "\n[ERROR] " .. table.concat(
					string.split(traceback, "\n"),
					"\n[ERROR] "
				)
			end)
		end
	end
	SaveData.SteveBuiltinPayload = Steve110.PayloadSHA256
	InitLogsText.Text ..= "\n[LOG] Refreshing Dance keybinds..."
	RefreshKeybinds()
	FavoriteSystem.Refresh()
	InitLogsText.Text ..= "\n[LOG] Loaded " .. (#MovementStyles + #DanceableDances) .. " modules - " .. #MovementStyles .. " Movesets, " .. #DanceableDances .. " Dances."
	InitLogsText.Text ..= "\n[LOG] Init complete!"
	Util.UINotify("Init complete" .. (InitLogsText.HasErrors() and " with errors" or ""))
	IsUhhhhhhFullyLoaded = true
	if not MovementStyles[MovementStyleIndex] then MovementStyleIndex = math.min(2, math.max(1, #MovementStyles)) end
	CurrentDance = nil
    if StreamRuntime then StreamRuntime.Restore(SaveData.StreamedModules) end
	if not Reanimate.Character then
		return
	end
	__TheoManualRefreshSerial += 1
end
