local MarketInstaller=Steve110.Require("main/market_install")({
    Task=task, Notify=Util.UINotify,
    IsInstalled=function(item)
        if item.Type~="folder" then return isfile("UhhhhhhReanim/Modules/"..item.File) end
        return SaveData.MarketPackModes and SaveData.MarketPackModes[item.File:gsub("/*$", "").."/"]=="installed"
    end,
    Prepare=function(item,targetPath)
        if item.Type~="folder" and not item.NeedsContext then
            return {{Source=item.Source,File=item.File,Path=targetPath or ("UhhhhhhReanim/Modules/"..item.File)}}
        end
        local modules, context, key = MarketCatalog.Folder(item)
        context.Directories={}
        for _,module in ipairs(modules)do context.Directories[module.File]=(module.Relative or ""):match("^(.*)/[^/]+$")end
        local contextPath="UhhhhhhReanim/MarketContexts/"..key..".json"
        local data=HttpService:JSONEncode(context)
        EnsureAssetFolders(contextPath)
        writefile(contextPath,data)
        assert(readfile(contextPath)==data,"Pack context write failed")
        local records={}
        for _,module in ipairs(modules) do
            table.insert(records,{Source=module.Source,File=module.File,Path="UhhhhhhReanim/Modules/"..module.File,
                Transform=function(body)return "-- UHH_MARKET_CONTEXT "..key.."\n"..body end})
        end
        return records
    end,
    Download=function(record,force,done)
        AssetDownloadAgent(record.Source,record.File,record.Path,force,record.Transform,nil,nil,done)
    end,
    Commit=function(item)
        if item.Type=="folder" then
            SaveData.MarketPackModes=SaveData.MarketPackModes or {}
            SaveData.MarketPackModes[item.File:gsub("/*$", "").."/"]="installed"
            SaveSettingsNow()
        end
    end,
    Apply=function()ForceModuleReload("SKIPHASH")end,
    CheckLoaded=function(records)
        for _,record in ipairs(records) do
            local names=UserModulesListor[record.File]
            if not names or #names==0 then return false,"Check Addon error details for "..record.File end
        end
        return true
    end,
})
SCREENGUI.Destroying:Connect(MarketInstaller.Dispose)
local function InstallMarketItem(item, force, targetPath)return MarketInstaller.Install(item,force,targetPath)end
local function AddMarketInstallControls(page,item,targetPath)
